    end

    -- ---- clipboard / files ----------------------------------------------
    -- the "Job ID" action calls (setclipboard or toclipboard or writeclipboard)
    alias("setclipboard", "toclipboard", "writeclipboard", "set_clipboard",
          fromNamespace("syn", "write_clipboard"))
    alias("toclipboard", "setclipboard")
    alias("writeclipboard", "setclipboard")

    -- ---- one-line capability report --------------------------------------
    -- Printed once, always. Everything in this hub degrades quietly rather
    -- than erroring, which is the right behaviour but leaves "it doesn't work
    -- on my executor" with nothing to go on. This is the first thing to read:
    -- if a feature is dead, the name it needs is almost always on this line.
    do
        local missing = {}
        for _, n in ipairs({ "getgc", "getconnections", "firesignal", "fireproximityprompt",
                             "getsenv", "getrenv", "loadstring", "setfenv", "hookfunction",
                             "writefile", "readfile", "isfile", "getcustomasset",
                             "request", "setclipboard", "setfpscap", "gethui" }) do
            if type(get(n)) ~= "function" then missing[#missing + 1] = n end
        end
        print(("[skyr0] executor: %s%s"):format(
            execName,
