-- =====================================================================
-- PING  --  _G.Skyr0Ping()
-- ---------------------------------------------------------------------
-- Round-trip time in SECONDS, or a 0.1 default when the stat is unavailable.
-- The teleport scales its recovery timings off this: the constants it used
-- were all tuned on a low-ping connection and are simply wrong on a high one.
-- Cached at 4Hz because Heartbeat loops read it.
-- =====================================================================
do
    local Stats = game:FindService("Stats")
    local item, at, val = nil, 0, 0.1
    function _G.Skyr0Ping()
        local now = os.clock()
        if (now - at) < 0.25 then return val end
        at = now
        if not Stats then return val end
        if not item then
            pcall(function()
                item = Stats.Network.ServerStatsItem["Data Ping"]
            end)
        end
        if item then
            pcall(function()
                local ms = item:GetValue()
                if type(ms) == "number" and ms > 0 then
                    val = math.clamp(ms / 1000, 0.02, 1.5)
                end
            end)
        end
        return val
    end
end
