local function kickPlayer(stolenText)
    local isAutoKickSteal = false

    if stolenText and type(stolenText) == "string" then
        isAutoKickSteal = true
    end

    if Config.KickToPrivateServer and PrivateServerCode and PrivateServerCode ~= "" and isAutoKickSteal then
        task.delay(0.2, function()
            pcall(function()
                local ExperienceService = game:GetService("ExperienceService")
                ExperienceService:LaunchExperience({
                    placeId = game.PlaceId,
                    linkCode = PrivateServerCode,
                })
            end)
        end)
        return
    end
    -- Manual kick and Auto Kick on steal both kick only, so you stay on the
    -- kick screen and press Leave yourself. game:Shutdown() closed the client
    -- straight away, which is what looked like Leave being auto-clicked.
    -- The client keeps running after Kick, so the steal tracker keeps polling
    -- and its notification / webhook still go out on the kick screen.
    if isAutoKickSteal then
        -- several triggers can see the same steal (the "you stole" text, the
        -- steal tracker): kick once
        if _G.__Skyr0AutoKicked then return end
        _G.__Skyr0AutoKicked = true
        -- wait 0.05s, kick, then force a steal tracker pass right away
        task.delay(0.05, function()
            pcall(function() LocalPlayer:Kick("") end)
            if _G.Skyr0StealTrackerScan then pcall(_G.Skyr0StealTrackerScan) end
        end)
        return
    end
    pcall(function() LocalPlayer:Kick("") end)
end
