-- =====================================================================
-- ANTI TRAP (always on). A placed trap stays VISIBLE but can't catch you:
-- its touch triggers are removed and its own parts stop colliding, and a
-- invisible block encloses it (twice its height, so you stand above its
-- reach) and you step / fly OVER it. The block is the trap's footprint +
-- _G.Skyr0TrapPad (1.5) studs a side. It is solid and
-- queryable, so the TP pathfinding sees it like any obstacle (and the trap's
-- own parts drop out of the pathfinding). Traps can be a Model OR a single
-- part, anchored or not ("Trap", "Cake Trap"...).
-- Event-driven: one scan at start, then only newly added instances are checked.
do
    local done = setmetatable({}, { __mode = "k" })
    local guards = {}   -- live guard blocks (for the lift below)
    local function isTrapName(n)
        n = tostring(n):lower()
        return n:find("trap", 1, true) ~= nil and n:sub(1, 5) ~= "skyr0"
    end
    local function skipIt(obj)
        if obj:IsA("Tool") then return true end
        local a = obj.Parent
        while a and a ~= workspace do
            if a:IsA("Tool") or a:FindFirstChildOfClass("Humanoid") then return true end   -- held / equipped
            if isTrapName(a.Name) and (a:IsA("Model") or a:IsA("BasePart")) then return true end   -- the outer one is guarded
            a = a.Parent
        end
        return a ~= workspace
    end
    local function box(obj)
        if obj:IsA("BasePart") then return obj.CFrame, obj.Size end
        local ok, cf, size = pcall(function() return obj:GetBoundingBox() end)
        if ok then return cf, size end
    end
    local function guard(obj)
        if done[obj] or not obj.Parent or skipIt(obj) then return end
        local cf, size = box(obj)
        if not cf then return end
        done[obj] = true
        local parts = obj:IsA("BasePart") and { obj } or obj:GetDescendants()
        for _, d in ipairs(parts) do
            if d:IsA("TouchTransmitter") then
                pcall(function() d:Destroy() end)
            elseif d:IsA("BasePart") then
                pcall(function() d.CanCollide = false; d.CanTouch = false; d.CanQuery = false end)
                for _, t in ipairs(d:GetChildren()) do
                    if t:IsA("TouchTransmitter") then pcall(function() t:Destroy() end) end
                end
            end
        end
        -- same height as the anti trap that works (twice the trap's height,
        -- centred on it: you stand half a trap-height ABOVE its top, out of
        -- its reach), with half its padding (_G.Skyr0TrapPad, 1.5 a side)
        local pad = tonumber(_G.Skyr0TrapPad) or 1.5
        local blk = Instance.new("Part")
        blk.Name = "Skyr0TrapGuard"
        blk.Size = Vector3.new(size.X + pad * 2, math.max(size.Y * 2, size.Y + 1.5), size.Z + pad * 2)
        local look = cf.LookVector
        local flat = Vector3.new(look.X, 0, look.Z)
        local rot = (flat.Magnitude > 0.05) and CFrame.lookAt(Vector3.zero, flat.Unit) or CFrame.new()
        blk.CFrame = CFrame.new(cf.Position) * rot
        blk.Anchored = true
        blk.CanCollide = true
        blk.CanTouch = false
        blk.CanQuery = true
        blk.CastShadow = false
        blk.Transparency = 1
        blk.Parent = workspace
        guards[blk] = true
        obj.AncestryChanged:Connect(function(_, parent)
            if not parent then guards[blk] = nil; pcall(function() blk:Destroy() end) end
        end)
    end
    local function consider(obj)
        -- fires for every part that streams in: reject on the name first, with
        -- no allocation ("Trap" / "trap" both contain "rap")
        if not string.find(obj.Name, "rap", 1, true) then return end
        if not ((obj:IsA("Model") or obj:IsA("BasePart")) and isTrapName(obj.Name)) then return end
        -- give a freshly placed trap a moment to settle (anchor / land), then
        -- guard it; re-checked for ~3s while it is still moving
        task.spawn(function()
            for i = 1, 6 do
                task.wait(0.5)
                if done[obj] or not obj.Parent then return end
                local pp = obj:IsA("BasePart") and obj or (obj.PrimaryPart or obj:FindFirstChildWhichIsA("BasePart", true))
                local still = pp and (pp.Anchored or pp.AssemblyLinearVelocity.Magnitude < 0.5)
                if still or i == 6 then pcall(guard, obj) end
            end
        end)
    end
    task.delay(3, function()   -- after the load, and spread over frames
        for i, obj in ipairs(workspace:GetDescendants()) do
            if string.find(obj.Name, "rap", 1, true) and (obj:IsA("Model") or obj:IsA("BasePart")) and isTrapName(obj.Name) then pcall(guard, obj) end
            if i % 4000 == 0 then task.wait() end
        end
    end)
    if _G.__Skyr0TrapConn then pcall(function() _G.__Skyr0TrapConn:Disconnect() end) end
    _G.__Skyr0TrapConn = workspace.DescendantAdded:Connect(consider)
    -- NEVER INTO A TRAP, EVEN MID-TP. A flight can clip through the guard
    -- (no-collide legs, a short straight leg the planner never checked). So
    -- whenever your root is over a guard's footprint and lower than standing
    -- on top of it, you are lifted onto it -- keeping your sideways speed,
    -- dropping only the downward part. Costs nothing while no trap is placed.
    if _G.__Skyr0TrapLift then pcall(function() _G.__Skyr0TrapLift:Disconnect() end) end
    _G.__Skyr0TrapLift = game:GetService("RunService").Heartbeat:Connect(function()
        if next(guards) == nil then return end
        local ch = game:GetService("Players").LocalPlayer.Character
        local hrp = ch and ch:FindFirstChild("HumanoidRootPart")
        if not hrp then return end
        local hum = ch:FindFirstChildOfClass("Humanoid")
        local rootH = 3
        if hum then
            if hum.RigType == Enum.HumanoidRigType.R6 then rootH = 3
            else rootH = hum.HipHeight + hrp.Size.Y / 2 end
        end
        local p = hrp.Position
        for blk in pairs(guards) do
            if blk.Parent then
                local lp = blk.CFrame:PointToObjectSpace(p)
                local hx, hz = blk.Size.X / 2 + 0.5, blk.Size.Z / 2 + 0.5
                if math.abs(lp.X) <= hx and math.abs(lp.Z) <= hz then
                    local top = blk.Position.Y + blk.Size.Y / 2
                    local want = top + rootH + 0.1
                    if p.Y < want and p.Y > blk.Position.Y - blk.Size.Y / 2 - rootH - 2 then
                        hrp.CFrame = hrp.CFrame + Vector3.new(0, want - p.Y, 0)
                        local v = hrp.AssemblyLinearVelocity
                        if v.Y < 0 then hrp.AssemblyLinearVelocity = Vector3.new(v.X, 0, v.Z) end
                    end
                    break
                end
            else
                guards[blk] = nil
            end
        end
    end)
end
-- INSTA WALK TO BRAINROT (rose.lua's Insta TP Brainrot). The last leg, from
-- the landing to the brainrot, is one CFrame snap with the velocity zeroed,
-- checked 0.05s later; pulled back -> one more snap, then the rest on a short
-- tween. OFF by default (its snap/re-snap/tween fought the server and lagged
-- you back): _G.Skyr0RoseWalkOn = true turns it on.
do
    local RS_ = game:GetService("RunService")
    local TS_ = game:GetService("TweenService")
    local function zero(hrp)
        hrp.AssemblyLinearVelocity = Vector3.zero
        hrp.AssemblyAngularVelocity = Vector3.zero
    end
    _G.Skyr0RoseWalk = function(hrp, dst, rotCF)
        local T = Config and Config.TpSettings
        if _G.Skyr0RoseWalkOn ~= true or _G.Skyr0RoseWalkOff == true then return false end
        if not (hrp and hrp.Parent and dst) then return true end
        rotCF = rotCF or CFrame.new()
        if _G.Skyr0TPCancel then zero(hrp); return true end
        local tries = math.max(1, math.floor(tonumber(_G.Skyr0RoseSnapTries) or 2))
        local verify = tonumber(_G.Skyr0RoseSnapVerify) or 0.05
        local tol = tonumber(_G.Skyr0RoseSnapTol) or 3
        for _ = 1, tries do
            zero(hrp); hrp.CFrame = CFrame.new(dst) * rotCF; zero(hrp)
            if verify <= 0 then return true end
            local v0 = os.clock()
            repeat
                RS_.Heartbeat:Wait()
                if _G.Skyr0TPCancel or not hrp.Parent then return true end
            until os.clock() - v0 >= verify
            if (hrp.Position - dst).Magnitude <= tol then return true end
        end
        local d = (hrp.Position - dst).Magnitude
        if d > 0.5 then
            local speed = math.max(tonumber(_G.Skyr0RoseWalkSpeed) or 175, 50)
            local tw_ = TS_:Create(hrp, TweenInfo.new(math.clamp(d / speed, 0.05, 0.6),
                Enum.EasingStyle.Quad, Enum.EasingDirection.Out), { CFrame = CFrame.new(dst) * rotCF })
            local done = false
            local c = tw_.Completed:Connect(function() done = true end)
            tw_:Play()
            local t0 = os.clock()
            while not done and os.clock() - t0 < 1 do
                RS_.Heartbeat:Wait()
                if not hrp.Parent or _G.Skyr0TPCancel then tw_:Cancel(); break end
                hrp.AssemblyLinearVelocity = Vector3.zero
            end
            c:Disconnect()
        end
        return true
    end
end
-- FLASH TP -- the wall-clone swap, done with the Flash Teleport instead.
-- ---------------------------------------------------------------------
-- The TP engine flies to the same wall spot it uses for the clone (any plot,
-- any floor -- MV.spots picks it), backs off a little, then calls this instead
-- of the Quantum Cloner. The flash goes where you aim, so the aim is written
-- the same way the grapple does it: camera turned so the cursor ray points at
-- the brainrot, and every PlayerMouse table's Hit/Target set to it, for the
-- frames around Activate(). Returns true once the character actually moved.
-- Wrapped in do..end: the main chunk is at the local limit.
-- =====================================================================
do
    local function findFlash(char)
        for _, where in ipairs({ char, player:FindFirstChild("Backpack") }) do
            if where then
                for _, t in ipairs(where:GetChildren()) do
                    if t:IsA("Tool") and t.Name:lower():find("flash", 1, true) then return t end
                end
            end
        end
        return nil
    end
    _G.Skyr0HasFlash = function()
        return findFlash(player.Character) ~= nil
    end
    -- Flash mode for THIS TP: the Auto TP toggle, or a one-shot from the Flash TP key
    -- the Auto TP tab's flash settings live in Config.TpSettings; the engine
    -- reads the _G names, so they are copied over at the start of every TP
    local FLASH_CFG = {
        FlashInstant = "Skyr0FlashInstant", FlashUseFixed = "Skyr0FlashUseFixed",
        FlashMargin = "Skyr0FlashMargin", FlashSideRight = "Skyr0FlashSideRight",
        FlashInside = "Skyr0FlashInside", FlashFireWindow = "Skyr0FlashInstantWait",
        FlashCooldown = "Skyr0FlashCooldown",
        FlashF2Delay = "Skyr0FlashF2Delay", FlashF2Walk = "Skyr0FlashF2Walk",
    }
    _G.Skyr0FlashApplyConfig = function()
        local t = Config and Config.TpSettings
        if not t then return end
        for k, g in pairs(FLASH_CFG) do
            if t[k] ~= nil then _G[g] = t[k] end
        end
    end
    _G.Skyr0FlashWanted = function()
        pcall(_G.Skyr0FlashApplyConfig)
        local once = _G.Skyr0FlashOnce
        if type(once) == "number" and os.clock() - once < 15 then return true end
        return Config and Config.TpSettings and Config.TpSettings.FlashTP == true
    end
    -- READY = not cooling down. Three signals: our own timer (set after every
    -- flash -- Auto TP "Flash Cooldown" seconds after a hit, at least 3s after
    -- a miss), the tool being disabled, or a cooldown-ish attribute on it
    -- that is true / an end-time still in the future. Not ready -> the TP is
    -- the old grapple TP (hook, carpet, wall clone) from the start.
    _G.Skyr0FlashCdUntil = _G.Skyr0FlashCdUntil or 0
    _G.Skyr0FlashReady = function()
        if os.clock() < (tonumber(_G.Skyr0FlashCdUntil) or 0) then return false end
        local f = findFlash(player.Character)
        if not f then return false end
        if f.Enabled == false then return false end
        local okA, attrs = pcall(function() return f:GetAttributes() end)
        if okA and type(attrs) == "table" then
            local now = os.time()
            for k, v in pairs(attrs) do
                local lk = tostring(k):lower()
                if lk:find("cool", 1, true) then
                    if v == true then return false end
                    if type(v) == "number" and v > now and v < now + 3600 then return false end
                end
            end
        end
        return true
    end
    -- workspace.Ghost is the game's own landing preview while the flash is out:
    -- Head cyan (0,200,255) = you can flash there, red (255,0,0) = you can't.
    local FLASH_RANGE = 39.87
    local function ghostRead()
        local g = workspace:FindFirstChild("Ghost")
        local head = g and (g:FindFirstChild("Head") or g:FindFirstChild("Head", true))
        if not (head and head:IsA("BasePart")) then return nil end
        local c = head.Color
        local can = c.B > 0.75 and c.R < 0.35
        return can, head.Position
    end
    _G.Skyr0FlashGhost = ghostRead
    -- WINDOWS: plot.Decorations["Side N"].Folder["Side N"] holds the side walls;
    -- the window panes are the parts at Transparency ~0.6. Picks the pane on the
    -- brainrot's floor, on nearPos's side of the base, closest to the brainrot.
    -- Returns its position and the flat outward direction (away from the base).
    _G.Skyr0FlashWindow = function(plot, petPos, nearPos)
        local deco = plot and plot:FindFirstChild("Decorations")
        if not deco then return nil end
        local center = plot:GetPivot().Position
        local maxDy = tonumber(_G.Skyr0FlashWindowY) or 10
        local best, bestS
        for _, d in ipairs(deco:GetDescendants()) do
            if d:IsA("BasePart") and math.abs(d.Transparency - 0.6) < 0.05
               and math.abs(d.Position.Y - petPos.Y) < maxDy then
                local inSide, a = false, d.Parent
                while a and a ~= deco do
                    if a.Name:find("Side", 1, true) then inSide = true; break end
                    a = a.Parent
                end
                if inSide and (not nearPos or (d.Position.Z - center.Z) * (nearPos.Z - center.Z) > 0) then
                    local s = Vector3.new(d.Position.X - petPos.X, 0, d.Position.Z - petPos.Z).Magnitude
                    if not bestS or s < bestS then best, bestS = d, s end
                end
            end
        end
        if not best then return nil end
        -- outward = the pane's thin axis, flattened, pointing away from the base
        local sz, cf = best.Size, best.CFrame
        local axis = (sz.X <= sz.Y and sz.X <= sz.Z) and cf.RightVector
            or ((sz.Y <= sz.Z) and cf.UpVector or cf.LookVector)
        axis = Vector3.new(axis.X, 0, axis.Z)
        if axis.Magnitude < 0.1 then
            axis = Vector3.new(0, 0, (best.Position.Z - center.Z) >= 0 and 1 or -1)
        else
            axis = axis.Unit
        end
        if axis:Dot(best.Position - center) < 0 then axis = -axis end
        return best.Position, axis
    end
    -- =================================================================
    -- FIXED FLASH SPOTS (measured by hand on plot 6, mapped to every plot)
    -- -----------------------------------------------------------------
    -- Plot layout (plot mapper): 2 columns x 4 rows, rows 107 studs apart;
    -- the west column is the east column turned 180 degrees. So a spot is
    -- stored as an offset from plot 6's pivot and, on a west plot, turned 180
    -- (x and z flipped). pos = where the root stands, look = the camera
    -- LookVector, cam = the camera position. Floor 1 looks a bit down, floor 2
    -- looks up from the ground (no climb needed).
    -- =================================================================
    local FIX_REF = Vector3.new(-316.94, -10.01, 113.61)   -- plot 6 pivot
    local FIX_SPOTS = {
