    local character = player.Character
    local humanoid = character and character:FindFirstChildOfClass("Humanoid")
    local hrp = character and (character.PrimaryPart or character:FindFirstChild("HumanoidRootPart"))
    if character then
        pcall(function() for _, p in ipairs(character:GetDescendants()) do if p:IsA("BasePart") then p.Anchored = false end end end)
    end
    if hrp then
        pcall(function()
            local pos = hrp.Position
            hrp.CFrame = CFrame.new(pos.X, pos.Y, pos.Z) * CFrame.Angles(0, math.rad(hrp.Orientation.Y), 0)
