local function invisTurnOn()
    if animPlaying then return end
    local character = player.Character
    if not character then return end
    local humanoid = character:FindFirstChildOfClass("Humanoid")
    if not humanoid then return end
    animPlaying = true; _G.invisibleStealEnabled = true
    setToggle("Invisible Steal", true)
    if _G.updateMovementPanelInvisVisual then pcall(_G.updateMovementPanelInvisVisual, true) end
    tracks = {}; removeFolders()
    local success = doClone()
    if not success then
        -- don't leave the flags saying "on" with no clone behind them: every
        -- later toggle (and auto recover) would read that as on and turn it off
        animPlaying = false; _G.invisibleStealEnabled = false
        setToggle("Invisible Steal", false)
        if _G.updateMovementPanelInvisVisual then pcall(_G.updateMovementPanelInvisVisual, false) end
        return
    end
    if _G.JAF_InvisFreezeOnEngage ~= false then
        pcall(function()
            local pm = player:FindFirstChild("PlayerScripts")
            pm = pm and pm:FindFirstChild("PlayerModule")
            if pm then require(pm):GetControls():Enable() end
        end)
        local _froot = character.PrimaryPart or character:FindFirstChild("HumanoidRootPart")
        if _froot then pcall(function() _froot.AssemblyLinearVelocity = Vector3.zero; _froot.AssemblyAngularVelocity = Vector3.zero; _froot.Anchored = false end) end
        if oldRoot then pcall(function() oldRoot.AssemblyLinearVelocity = Vector3.zero; oldRoot.AssemblyAngularVelocity = Vector3.zero end) end
        pcall(function() humanoid:Move(Vector3.zero, false) end)
        pcall(function() if humanoid.PlatformStand then humanoid.PlatformStand = false end end)
        pcall(function() if humanoid.Sit then humanoid.Sit = false end end)
        pcall(function() if humanoid.WalkSpeed <= 0 then humanoid.WalkSpeed = 16 end end)
    end
    if _G.JAF_InvisFold ~= false then task.wait(0.05); animationTrickery() end
    task.defer(function()
        if _G.resetBrainrotBeam then pcall(_G.resetBrainrotBeam) end
        if _G.resetPlotBeam then pcall(_G.resetPlotBeam) end
        task.wait(0.1)
        if _G.updateBrainrotBeam then pcall(_G.updateBrainrotBeam) end
        if _G.createPlotBeam then pcall(_G.createPlotBeam) end
    end)
    -- Enable walkspeed 1 second after invis steal activates
    task.delay(1, function()
        if _G.invisibleStealEnabled and not WalkSpeedState.enabled then
            setWalkSpeedEnabled(true)
        end
    end)
    local lastSetPosition = nil; local skipFrames = 5
    local _invisFastMode = false; local _invisSlowAccum = 0
    local function _invisRagGuard(_char, _hum)
        if (player:GetAttribute("RagdollEndTime") or 0) > 0 then player:SetAttribute("RagdollEndTime", 0) end
        if _hum then
            if _hum.PlatformStand then _hum.PlatformStand = false end
            local _s = _hum:GetState()
            if _s == Enum.HumanoidStateType.Physics or _s == Enum.HumanoidStateType.Ragdoll or _s == Enum.HumanoidStateType.FallingDown then
                _hum:ChangeState(Enum.HumanoidStateType.GettingUp)
            end
        end
        if invisRagdollACChar ~= _char then
            invisRagdollACChar = _char; invisRagdollACs = {}
            for _, d in ipairs(_char:GetDescendants()) do if d:IsA("AnimationConstraint") then table.insert(invisRagdollACs, d) end end
        end
        for _, ac in ipairs(invisRagdollACs) do if ac.Parent and not ac.Enabled then ac.Enabled = true end end
    end
    connection = RunService.PreSimulation:Connect(function(_psDt)
        local _invHum = character and character:FindFirstChildOfClass("Humanoid")
        if not (_invHum and _invHum.Health > 0 and oldRoot) then return end
        local root = character.PrimaryPart or character:FindFirstChild("HumanoidRootPart")
        if not root then return end
        if _G.JAF_InvisRagdollGuard ~= false then pcall(_invisRagGuard, character, _invHum) end
        if _G.JAF_InvisPoseFix ~= false and _invisPoseAtt and _invisPoseAtt.Parent and _invisPoseBase and _invisPoseRestDY then
            local _plt = character:FindFirstChild("LowerTorso")
            if _plt then
                local _appl = _invisPoseBase.Position.Y - _invisPoseAtt.CFrame.Position.Y
                local _lift = (_plt.Position.Y - root.Position.Y) + _appl - _invisPoseRestDY
                _lift = math.clamp(_lift, 0, tonumber(_G.JAF_InvisPoseMaxLift) or 8)
