-- AUTO BUY (walking carpet).
--   1. LOCK  -- picks the single nearest buy prompt inside the radius and
--               keeps it: no switching to a closer one, the lock only lets go
--               once that brainrot is bought, gone or its prompt shuts off.
--   2. GLIDE -- tweens over to it at Auto Buy Speed (studs/s). The target is
--               walking, so the tween re-aims at its live position every frame
--               instead of flying to where it USED to be.
--   3. STICK -- once there, rides HOVER_Y above it and fires the prompt.
-- The radius is drawn as a ring around you while Auto Buy is on, and the
-- locked brainrot gets a highlight, so you can see what it will take.
-- Prompts are tracked by tag add/remove instead of rescanning Debris. It
-- stands down while a TP or a steal is running.
-- Fast mode replays the purchase remote straight from the prompt's own
-- Triggered handler (needs getconnections + debug.getupvalues) and falls back
-- to fireproximityprompt when that cannot be resolved.
-- Its own function scope: the main chunk is near Luau's register limit.
AutoBuyState = { enabled = false, fast = false };
(function()
    local CS = game:GetService("CollectionService")
    local TAG = "AnimalPurchasePrompt"
    local HOVER_Y, NATURAL_RATE, LOCK_RATE, ARRIVE = 5, 0.08, 0.1, 1.5
    if Config.AutoBuyRange == nil then Config.AutoBuyRange = 17 end
    if Config.AutoBuyFastRate == nil then Config.AutoBuyFastRate = 12 end
    if Config.AutoBuyTweenSpeed == nil then Config.AutoBuyTweenSpeed = 70 end

    -- live prompt set, kept by the tag signals
    local prompts = {}
    local function isBuyPrompt(p)
        if not (p and p:IsA("ProximityPrompt")) then return false end
        local t = string.lower(p.ActionText or "")
        return t:find("purchase", 1, true) or t:find("buy", 1, true) or t:find("comprar", 1, true)
    end
    for _, p in ipairs(CS:GetTagged(TAG)) do prompts[p] = true end
    CS:GetInstanceAddedSignal(TAG):Connect(function(p) prompts[p] = true end)
    CS:GetInstanceRemovedSignal(TAG):Connect(function(p) prompts[p] = nil end)

    local function promptPart(p)
        local par = p.Parent
        if par and par:IsA("Attachment") then par = par.Parent end
        return (par and par:IsA("BasePart")) and par or nil
    end

    -- LOCK BY UID, NOT BY PROMPT INSTANCE. The prompt on a walking brainrot
    -- flickers Enabled and can be re-created as the walker streams; locking the
    -- instance dropped the lock on every flicker and the picker grabbed
    -- whatever was nearest that frame -- the "keeps switching". The UID is the
    -- brainrot itself, so the lock follows it through prompt swaps, and only a
    -- UID that has been gone for LOST_GRACE seconds releases it.
    -- HELD UNTIL AUTO BUY IS TURNED OFF. The lock used to let go after the
    -- prompt had been switched off for 2.5s or missing for 1.25s -- and a
    -- walking brainrot's prompt does both all the time, so the lock dropped a
    -- few seconds in. Now a prompt that is off or missing changes nothing: you
    -- stay on that brainrot (by its prompt part, else its model). Only a
    -- brainrot that is gone from the game entirely for LOST_GRACE seconds is
    -- let go, since there is nothing left to lock on to.
    local LOST_GRACE = 3
    local lock = { uid = nil, prompt = nil, part = nil, model = nil, arrived = false, lostAt = nil }
    local function uidOf(p)
        local u = p and p:GetAttribute("UID")
        return u ~= nil and tostring(u) or nil
    end
    local highlight   -- defined with the visuals below
    -- re-resolve the locked brainrot's prompt; true while it is still around
    local function lockAlive()
        if not lock.uid then return false end
        local p = lock.prompt
        if not (p and p.Parent and uidOf(p) == lock.uid) then
            p = nil
            for q in pairs(prompts) do
                if q.Parent and uidOf(q) == lock.uid then p = q; break end
            end
            lock.prompt = p
            if p then
                lock.part = promptPart(p) or lock.part
                local m = p:FindFirstAncestorWhichIsA("Model")
                if m and m ~= lock.model then lock.model = m; if highlight then highlight(m) end end
            end
        end
        if (lock.part and lock.part.Parent) or (lock.model and lock.model.Parent) then
            lock.lostAt = nil
            return true
        end
        lock.lostAt = lock.lostAt or os.clock()
        return (os.clock() - lock.lostAt) < LOST_GRACE
    end
    -- the old name, kept for the buyer: alive AND the prompt is live right now
    local function lockValid()
        return lockAlive() and lock.prompt and lock.prompt.Enabled and lock.part ~= nil
    end

    -- visuals: radius ring + highlight on the locked brainrot
    local vis = { ring = nil, hl = nil }
    local function ring()
        if vis.ring and vis.ring.Parent then return vis.ring end
        local r = Instance.new("Part")
        r.Name = "Skyr0BuyRadius"; r.Shape = Enum.PartType.Cylinder
        r.Anchored = true; r.CanCollide = false; r.CanQuery = false; r.CanTouch = false
        r.CastShadow = false; r.Material = Enum.Material.ForceField
        r.Color = Color3.fromRGB(170, 110, 255); r.Transparency = 0.15
        r.Parent = workspace
        vis.ring = r
        return r
    end
    function highlight(model)   -- assigns the forward-declared local above
        if vis.hl and vis.hl.Parent and vis.hl.Adornee == model then return end
        if vis.hl then pcall(function() vis.hl:Destroy() end) end
        vis.hl = nil
        if not model then return end
        local h = Instance.new("Highlight")
        h.Name = "Skyr0BuyLock"; h.FillTransparency = 0.6; h.OutlineTransparency = 0
        h.FillColor = Color3.fromRGB(170, 110, 255); h.OutlineColor = Color3.fromRGB(255, 255, 255)
        h.Adornee = model; h.Parent = model
        vis.hl = h
    end
    local function hideVisuals()
        if vis.ring then pcall(function() vis.ring:Destroy() end); vis.ring = nil end
        highlight(nil)
    end

    local function release()
        lock.uid, lock.prompt, lock.part, lock.model, lock.arrived, lock.lostAt, lock.offAt = nil, nil, nil, nil, false, nil, nil
        highlight(nil)
    end

    local function paused()
        return (_G.Skyr0TPActive and _G.Skyr0TPActive())
            or (_G.Skyr0IsStealing and _G.Skyr0IsStealing())
    end

    local function equipCarpetTool()
        local c = player.Character
        local hum = c and c:FindFirstChildOfClass("Humanoid")
        if not hum then return end
        local names = { (Config.TpSettings and Config.TpSettings.Tool) or "Flying Carpet",
            "Flying Carpet", "Magic Carpet", "Cupid's Wings", "Santa's Sleigh", "Witch's Broom", "Waverider" }
        for _, n in ipairs(names) do if c:FindFirstChild(n) then return end end
        local bp = player:FindFirstChild("Backpack")
        for _, n in ipairs(names) do
            local t = bp and bp:FindFirstChild(n)
            if t then pcall(function() hum:EquipTool(t) end); return end
        end
    end

    -- fast path: pull the raw sender + remote out of the prompt's handler
    local fast = { fire = nil, remote = nil, a = nil, b = nil, off = nil }
    local function resolveFast()
        if fast.remote and fast.remote.Parent then return true end
        local gu, gc = debug and debug.getupvalues, debug and debug.getconstants
        if not (gu and typeof(getconnections) == "function") then return false end
        for p in pairs(prompts) do
            local okC, conns = pcall(getconnections, p.Triggered)
            for _, cn in ipairs((okC and conns) or {}) do
                local fn = cn.Function
                if typeof(fn) == "function" then
                    local okU, ups = pcall(gu, fn)
                    local f, re
                    for _, v in pairs((okU and ups) or {}) do
                        if typeof(v) == "function" then f = f or v
                        elseif typeof(v) == "Instance" and v:IsA("RemoteEvent") then re = re or v end
                    end
                    if f and re and re.Parent then
                        local guids, nums = {}, {}
                        local okK, ks = pcall(gc or function() return {} end, fn)
                        for _, v in pairs((okK and ks) or {}) do
                            if type(v) == "string" and #v == 36 and v:find("^%x+%-%x+%-%x+%-%x+%-%x+$") then guids[#guids + 1] = v
                            elseif type(v) == "number" then nums[#nums + 1] = v end
                        end
                        fast.fire, fast.remote = f, re
                        fast.a = guids[1] or "3d3ab689-343b-4632-8337-3ee5eb6e505e"
                        fast.b = guids[2] or "3ce04c41-b21f-4b2a-b93a-037427eac16d"
                        fast.off = nums[1] or 43
                        return true
                    end
                end
            end
        end
        return false
    end
    local function buyFast(p)
        local uid = p:GetAttribute("UID")
        if not uid or not resolveFast() then return false end
        return (pcall(function()
            local t, u = workspace:GetServerTimeNow() + fast.off, tostring(uid)
            fast.fire(fast.remote, t, fast.a, u)
            fast.remote:FireServer(t, fast.b, u)
        end))
    end
    local function buyNatural(p)
        if typeof(fireproximityprompt) ~= "function" then return end
        pcall(fireproximityprompt, p)
    end

    -- lock picker: only runs while NOTHING is locked
    task.spawn(function()
        while true do
            task.wait(AutoBuyState.enabled and LOCK_RATE or 0.4)
            if not AutoBuyState.enabled then
                if lock.prompt then release() end
            elseif not lockAlive() then
                if lock.uid then release() end
                local hrp = player.Character and player.Character:FindFirstChild("HumanoidRootPart")
                if hrp and not paused() then
                    local range = tonumber(Config.AutoBuyRange) or 17
                    local best, bestPart, bestD
                    for p in pairs(prompts) do
                        if p.Parent and p.Enabled and isBuyPrompt(p) and uidOf(p) then
                            local part = promptPart(p)
                            if part then
                                local d = (part.Position - hrp.Position).Magnitude
                                if d <= range and (not bestD or d < bestD) then best, bestPart, bestD = p, part, d end
                            end
                        end
                    end
                    if best then
                        lock.uid, lock.prompt, lock.part = uidOf(best), best, bestPart
                        lock.model = best:FindFirstAncestorWhichIsA("Model")
                        lock.arrived, lock.lostAt, lock.offAt = false, nil, nil
                        highlight(lock.model)
                    end
                end
            end
        end
    end)

    -- ring + glide + stick, every frame
    RunService.Heartbeat:Connect(function(dt)
        if not AutoBuyState.enabled then
            if vis.ring then hideVisuals() end
            return
        end
        local hrp = player.Character and player.Character:FindFirstChild("HumanoidRootPart")
        if not hrp then return end
        -- the radius you can see: a flat disc at your feet, sized to the range
        local d = (tonumber(Config.AutoBuyRange) or 17) * 2
        local r = ring()
        r.Size = Vector3.new(0.15, d, d)
        r.CFrame = CFrame.new(hrp.Position - Vector3.new(0, 3, 0)) * CFrame.Angles(0, 0, math.pi / 2)

        if paused() then return end
        -- carpet out the whole time Auto Buy is on, locked or not
        equipCarpetTool()
        -- hold position over the locked brainrot even through a prompt flicker;
        -- only a lock that is truly gone (past the grace) lets go of you
        if not lockAlive() then return end
        local anchor
        if lock.part and lock.part.Parent then anchor = lock.part.Position
        elseif lock.model and lock.model.Parent then
            local okP, pv = pcall(lock.model.GetPivot, lock.model)
            if okP and pv then anchor = pv.Position end
        end
        if not anchor then return end
        local goal = anchor + Vector3.new(0, HOVER_Y, 0)
        local look = hrp.CFrame - hrp.Position -- keep the facing, move only the position
        if lock.arrived then
            hrp.CFrame = CFrame.new(goal) * look
        else
            local delta = goal - hrp.Position
            local step = (tonumber(Config.AutoBuyTweenSpeed) or 70) * dt
            if delta.Magnitude <= math.max(step, ARRIVE) then
                lock.arrived = true
                hrp.CFrame = CFrame.new(goal) * look
            else
                hrp.CFrame = CFrame.new(hrp.Position + delta.Unit * step) * look
            end
        end
        hrp.AssemblyLinearVelocity = Vector3.zero
        hrp.AssemblyAngularVelocity = Vector3.zero
    end)

    -- buyer: fires only once the glide has arrived on the locked brainrot
    task.spawn(function()
        while true do
            local useFast = AutoBuyState.fast
            if useFast then
                task.wait(1 / math.clamp(tonumber(Config.AutoBuyFastRate) or 12, 1, 60))
            else
                task.wait(NATURAL_RATE)
            end
            if AutoBuyState.enabled and lock.arrived and not paused() and lockValid() then
                local p = lock.prompt
                if not (useFast and buyFast(p)) then buyNatural(p) end
            end
        end
    end)

    -- SWITCHED ITEMS BY ACCIDENT? While Auto Buy is on, any other tool you
    -- pull out is swapped straight back for the flying tool (next frame, not
    -- next heartbeat tick of the hover), and the lock is untouched -- you stay
    -- on the same brainrot. The TP and a steal own the tools while they run.
    local FLYING = { ["Flying Carpet"]=true, ["Magic Carpet"]=true, ["Cupid's Wings"]=true,
        ["Santa's Sleigh"]=true, ["Witch's Broom"]=true, ["Waverider"]=true }
    local function watchTools(char)
        char.ChildAdded:Connect(function(t)
            if not (AutoBuyState.enabled and t:IsA("Tool")) then return end
            if FLYING[t.Name] or t.Name == ((Config.TpSettings and Config.TpSettings.Tool) or "") then return end
            if paused() then return end
            task.defer(function()
                if AutoBuyState.enabled and t.Parent == char and not paused() then
                    local hum = char:FindFirstChildOfClass("Humanoid")
                    if hum then pcall(function() hum:UnequipTools() end) end
                    equipCarpetTool()
                end
            end)
        end)
    end
    if player.Character then watchTools(player.Character) end
    player.CharacterAdded:Connect(function(c) release(); watchTools(c) end)

    -- Never resumes on load: a saved ON would start gliding the instant you
    -- spawn, before you have chosen to be anywhere near the carpet.
    _G.Skyr0SetAutoBuy = function(on)
        AutoBuyState.enabled = on and true or false
        setToggle("Auto Buy", AutoBuyState.enabled)
        if not AutoBuyState.enabled then release(); hideVisuals() end
        return AutoBuyState.enabled
    end
    _G.Skyr0SetFastAutoBuy = function(on)
        AutoBuyState.fast = on and true or false
        Config.AutoBuyFast = AutoBuyState.fast
        setToggle("Fast Auto Buy", AutoBuyState.fast)
        if saveConfig then pcall(saveConfig) end
        return AutoBuyState.fast
    end
    AutoBuyState.fast = Config.AutoBuyFast == true
    setToggle("Fast Auto Buy", AutoBuyState.fast, true)
end)();

-- STEAL TRACKER. Watches YOUR plot only: every time a brainrot lands in it
-- (stolen, bought off the carpet, anything) you get its name, generation and
-- mutation as a notification. Secrets and OGs are also posted to the Discord
-- webhook, with the brainrot's wiki image as the embed thumbnail.
--
-- Reads the hub's own plot scanner cache (SharedState.AllAnimalsCache), so it
-- costs one pass over a table a second -- no extra plot walks. The first pass
-- after your plot is found is a BASELINE: what is already in your base on
-- join is never reported.
-- Own function scope: the main chunk is near Luau's register limit.
(function()
    local HttpService = game:GetService("HttpService")
    local WEBHOOK = "https://discord.com/api/webhooks/1557872068610232440/JnW5eVnXHR_CBjv9UiePhdQ1AwGZ7wx01nBCXeQ5d0ox0GSBCLSU9rbh_wYGGaTrFMc8"
    local WEBHOOK_RARITIES = { secret = true, og = true }

    local function getStealImageUrl(animalName)
        local filename = animalName:gsub(" ", "_")
        local result = nil
        pcall(function()
            local req = (syn and syn.request) or request or http_request
            if not req then return end

            local apiUrl = "https://stealabrainrot.fandom.com/api.php?action=query&titles="
                .. filename
                .. "&prop=pageimages&format=json&pithumbsize=420&pilicense=any"

            print("[Skyro Steal] Trying API:", apiUrl)

            local res = req({
                Url = apiUrl,
                Method = "GET",
                Headers = {
                    ["User-Agent"] = "Mozilla/5.0 (compatible; Googlebot/2.1; +http://www.google.com/bot.html)",
                    ["Accept"] = "application/json",
                },
            })

            print("[Skyro Steal] API status:", res and res.StatusCode or "nil")
            print("[Skyro Steal] API body:", res and res.Body or "nil")

            if res and res.StatusCode == 200 and res.Body then
                local ok, data = pcall(HttpService.JSONDecode, HttpService, res.Body)
                if ok and data and data.query and data.query.pages then
                    for _, page in pairs(data.query.pages) do
                        print("[Skyro Steal] Page data:", HttpService:JSONEncode(page))
                        if page.thumbnail and page.thumbnail.source then
                            local src = page.thumbnail.source
                            src = src:gsub("/revision/latest/scale%-to%-width%-down/%d+", "/revision/latest")
                            result = src
                            print("[Skyro Steal] Got image:", result)
                        end
                    end
                end
            end
        end)
        return result
    end

    local animals
    local function rarityOf(index)
        if not animals then
            pcall(function()
                animals = require(game:GetService("ReplicatedStorage"):WaitForChild("Datas"):WaitForChild("Animals"))
            end)
        end
        local info = animals and index and animals[index]
        return type(info) == "table" and info.Rarity or nil
    end

    -- Discord user ID to ping when something is stolen from your base.
    -- Set it in the GUI: Misc tab -> "Steal Ping Discord ID" (saved to config).
    -- Can also be set from script: getgenv().Skyr0DiscordId / _G.Skyr0DiscordId.
    -- Leave it empty to post without a ping. Right-click your own name in
    -- Discord -> Copy User ID (needs Developer Mode on) to get the number.
    local function resolveDiscordId()
        -- set in the GUI (Misc tab -> "Steal Ping Discord ID"), saved to config
        local id
        pcall(function()
            if type(Config) == "table" and Config.DiscordId and Config.DiscordId ~= "" then
                id = Config.DiscordId
            end
        end)
        if id == nil or id == "" then id = _G.Skyr0DiscordId end
        if (id == nil or id == "") and type(getgenv) == "function" then
            local ok, env = pcall(getgenv)
            if ok and type(env) == "table" then id = env.Skyr0DiscordId end
        end
        -- fall back to a linked loader account if one exists (auth builds)
        if id == nil or id == "" then
            pcall(function()
                if type(skyr0) == "table" and type(skyr0.getUser) == "function" then
                    local u = skyr0.getUser()
                    if type(u) == "table" and u.id then id = tostring(u.id) end
                end
            end)
        end
        if id == nil then return nil end
        id = tostring(id):gsub("[^%d]", "")   -- accept "<@123>" or raw digits
        if id == "" then return nil end
        return id
    end

    local function sendWebhook(e)
        local req = (syn and syn.request) or request or http_request
        if not req then warn("[Skyro Steal] no http request function -- webhook skipped"); return end
        local image = getStealImageUrl(e.index or e.name)
        if not image and e.name ~= e.index then image = getStealImageUrl(e.name) end
        local userId = resolveDiscordId()
        local stealer = userId and ("<@" .. userId .. ">") or "SRC BUYER (CANT READ DISCORD)"
        local embed = {
            title = "STOLEN",
            description = "**" .. tostring(e.name) .. "**",
            color = 0xAA6EFF,
            fields = {
                { name = "Generation", value = tostring(e.gen), inline = true },
                { name = "Mutation",   value = tostring(e.mutation), inline = true },
                { name = "Rarity",     value = tostring(e.rarity), inline = true },
				{name = "User who stole", value = stealer, inline = true},
            },
            footer = { text = "skyr0.wtf steal tracker" },
            timestamp = DateTime.now():ToIsoDate(),
        }
        if image then embed.thumbnail = { url = image } end
        -- mentions inside an embed never ping, so the ping goes in content
        local payload = { username = "skyr0", embeds = { embed } }
        if userId then
            payload.content = "<@" .. userId .. ">"
            payload.allowed_mentions = { users = { userId } }
        end
        local ok, err = pcall(function()
            req({
                Url = WEBHOOK,
                Method = "POST",
                Headers = { ["Content-Type"] = "application/json" },
                Body = HttpService:JSONEncode(payload),
            })
        end)
        if not ok then warn("[Skyro Steal] webhook failed: " .. tostring(err)) end
    end

    local function fmtGen(v)
        v = tonumber(v) or 0
        if v <= 0 then return "?" end
        for _, u in ipairs({ { 1e12, "T" }, { 1e9, "B" }, { 1e6, "M" }, { 1e3, "K" } }) do
            if v >= u[1] then return (("$%.1f%s/s"):format(v / u[1], u[2]):gsub("%.0(%a)", "%1")) end
        end
        return ("$%d/s"):format(math.floor(v))
    end

    -- name / gen / mutation for one slot: the scanner's entry when it has one
    -- (already priced, traits included), otherwise priced here
    local function describe(plotName, slot, data)
        local cache = (_G.SharedState and _G.SharedState.AllAnimalsCache)
            or (SharedState and SharedState.AllAnimalsCache)
        if type(cache) == "table" then
            for _, a in ipairs(cache) do
                if a.plot == plotName and tostring(a.slot) == slot and a.index == data.Index then
                    return { name = a.name or a.index, index = a.index, gen = a.genText or fmtGen(a.genValue),
                             mutation = a.mutation }
                end
            end
        end
        local gen = 0
        local shim = _G._xenAnimShim
        if shim and shim.GetGeneration then
            local ok, g = pcall(shim.GetGeneration, shim, data.Index, data.Mutation, data.Traits, nil)
            if ok then gen = tonumber(g) or 0 end
        end
        local info = (function() rarityOf(data.Index); return animals and animals[data.Index] end)()
        return { name = (type(info) == "table" and info.DisplayName) or data.Index, index = data.Index,
                 gen = fmtGen(gen), mutation = data.Mutation }
    end

    local function report(d)
        local e = {
            name = d.name or d.index or "?", index = d.index, gen = d.gen or "?",
            mutation = (d.mutation and d.mutation ~= "" and tostring(d.mutation)) or "None",
            rarity = rarityOf(d.index) or "?",
        }
        print(("[Skyro Steal] STOLEN %s | %s | %s | %s"):format(e.name, e.gen, e.mutation, e.rarity))
        -- Auto Kick backup: the "you stole" text watcher misses whenever the
        -- game words or formats the popup differently; a new pet landing in
        -- your base right after a carry is the steal itself
        if Config.AutoKickOnSteal and _G.Skyr0KickPlayer
           and (os.clock() - (_G.__Skyr0LastStealingAt or 0)) < 4 then
            pcall(_G.Skyr0KickPlayer, "stole " .. tostring(e.name))
        end
        pcall(ShowNotification, "STOLEN", e.name .. "  " .. e.gen .. "  [" .. e.mutation .. "]")
        if WEBHOOK_RARITIES[tostring(e.rarity):lower()] then task.spawn(sendWebhook, e) end
    end

    -- PER-SLOT DIFF, so it fires on every steal for the whole server:
    --   * a slot whose brainrot CHANGES (empty -> X, or X -> Y) is a new one
    --   * the same brainrot coming back into a slot it left counts again once
    --     the slot has been empty for GONE seconds (sold / stolen from you,
    --     then stolen again) -- a one-pass blink from the scanner does not
    -- Reads your plot's live channel AnimalList first (updates the moment the
    -- server writes it), the scanner cache as the fallback.
    local GONE = 2.5
    local myPlot, foundAt, baselined = nil, 0, false
    local slots = {} -- slot -> { key = "Index|Mutation", missingSince = t|nil }
    local function readMyPlot()
        local list
        if _G.XenSyncGet and _G.Skyr0ChanGet then
            local ok, l = pcall(function() return _G.Skyr0ChanGet(_G.XenSyncGet(myPlot), "AnimalList") end)
            if ok and type(l) == "table" then list = l end
        end
        if not list and _G.Skyr0CachedSlotsForPlot then list = _G.Skyr0CachedSlotsForPlot(myPlot) end
        return list
    end
    local function scan()
            pcall(function()
                if not myPlot then
                    local plots = workspace:FindFirstChild("Plots")
                    if plots and _G.Skyr0IsMyPlotCached then
                        for _, pl in ipairs(plots:GetChildren()) do
                            if _G.Skyr0IsMyPlotCached(pl.Name) then myPlot = pl.Name; foundAt = os.clock(); break end
                        end
                    end
                    if not myPlot then return end
                end
                local list = readMyPlot()
                if type(list) ~= "table" then return end
                local t = os.clock()
                local present = {}
                for slot, data in pairs(list) do
                    if type(data) == "table" and type(data.Index) == "string" then
                        local s = tostring(slot)
                        present[s] = true
                        local key = data.Index .. "|" .. tostring(data.Mutation)
                        local st = slots[s]
                        local isNew = not st or st.key ~= key
                            or (st.missingSince and t - st.missingSince >= GONE)
                        slots[s] = { key = key }
                        -- baseline: let the plot fill for a few seconds after it
                        -- is found, and never report what you joined with
                        if isNew and baselined then report(describe(myPlot, s, data)) end
                    end
                end
                for s, st in pairs(slots) do
                    if not present[s] and not st.missingSince then st.missingSince = t end
                end
                if not baselined and t - foundAt >= 5 then baselined = true end
            end)
    end
    -- Auto Kick on steal runs this right after kicking, so the steal is
    -- logged without waiting for the next 0.5s poll
    _G.Skyr0StealTrackerScan = scan
    task.spawn(function()
        while true do
            task.wait(0.5)
            scan()
        end
    end)
end)()
if _G.__LMARK then _G.__LMARK("L7830") end

-- INFINITE JUMP (0.1s cooldown, 55 velocity)
InfJumpState={enabled=false,conn=nil,lastJump=0}
local function setInfiniteJump(en) InfJumpState.enabled=en; Config.InfiniteJump=en; Config.TpSettings.InfiniteJump=en; setToggle("Infinite Jump",en); saveConfig()
    if InfJumpState.conn then InfJumpState.conn:Disconnect(); InfJumpState.conn=nil end; if not en then return end
    InfJumpState.conn=RunService.Heartbeat:Connect(function() if not UIS:IsKeyDown(Enum.KeyCode.Space) then return end
        local now=tick(); if now-InfJumpState.lastJump<0.1 then return end; local c=player.Character; if not c then return end
        local hrp=c:FindFirstChild("HumanoidRootPart"); local hum=c:FindFirstChild("Humanoid"); if not hrp or not hum or hum.Health<=0 then return end
        InfJumpState.lastJump=now; hrp.AssemblyLinearVelocity=Vector3.new(hrp.AssemblyLinearVelocity.X,55,hrp.AssemblyLinearVelocity.Z)
    end)
end
