RunService.RenderStepped:Connect(function()
    if not ((Config and Config.AutoStealEnabled) or (_G.Skyr0Camp and _G.Skyr0Camp.active)) then
        hudName.Text = "Disabled"
        hudProgressFill.Size = UDim2.new(0, 0, 1, 0)
        hudPercent.Text = "0%"
        return
    end

    if LocalPlayer:GetAttribute("Stealing") then
        hudProgressFill.Size = UDim2.new(1, 0, 1, 0)
        hudProgressFill.BackgroundColor3 = _fillColour(true)
        hudPercent.Text = "100%"
        hudName.Text = "Carrying Brainrot!"
        return
    end

    local status = _G.Skyr0_StealStatus or {}

    -- NEAREST GRAB OWNS THE STEAL: a normal progress bar -- empty with the target
    -- named, filling while a hold runs, full once you are carrying it. The
    -- name line carries the target, its gen and the mode.
    if _G.SKYR0_GRAB_ENABLED == true or (_G.Skyr0Camp and _G.Skyr0Camp.active == true) then
        local sel = SharedState and SharedState.SelectedPetData
        local t
        if _G.Skyr0Camp and _G.Skyr0Camp.active then
            -- the target the steal engine is actually holding, so the bar moves
            -- onto each new brainrot with the hold
            local a = status.target
            if a and a.plot == _G.Skyr0Camp.plotName then
                t = { name = (a.name or "Brainrot") .. " [Slot " .. tostring(a.slot) .. "]", mpsValue = a.mps or a.mpsValue }
            else
                t = _G.Skyr0Camp.grabEntry
                if t and _G.Skyr0Camp.grabSlot then
                    t = { name = (t.name or "Brainrot") .. " [Slot " .. tostring(_G.Skyr0Camp.grabSlot) .. "]", mpsValue = t.mpsValue }
                end
            end
        elseif stealNearestEnabled then t = sel or status.target else t = status.target or sel end
        local mode = (_G.Skyr0Camp and _G.Skyr0Camp.active == true) and "BASE CAMP"
            or (stealNearestEnabled and "NEAREST")
            or (stealPriorityEnabled and "PRIORITY")
            or "HIGHEST"
        if status.active then
            local p = math.clamp((tick() - (status.start or 0)) / (status.duration or 1.3), 0, 1)
            hudProgressFill.Size = UDim2.new(p, 0, 1, 0)
            hudProgressFill.BackgroundColor3 = _fillColour(p >= 1)
            hudPercent.Text = math.floor(p * 100) .. "%"
        else
            hudProgressFill.Size = UDim2.new(0, 0, 1, 0)
            hudProgressFill.BackgroundColor3 = _fillColour(false)
            hudPercent.Text = "0%"
        end
        if t then
            local vs = _pbFmtVal(t.mpsValue or t.mps or t.genValue or t.value)
            hudName.Text = (t.name or t.petName or "Brainrot")
                .. ((vs ~= "0") and (" - $" .. vs .. "/s") or "") .. "  |  " .. mode
        else
            hudName.Text = "Searching...  |  " .. mode
        end
        return
    end

    if status.active then
        local p = math.clamp((tick() - (status.start or 0)) / (status.duration or 1.3), 0, 1)
        hudProgressFill.Size = UDim2.new(p, 0, 1, 0)
        hudPercent.Text = math.floor(p * 100) .. "%"
        hudProgressFill.BackgroundColor3 = _fillColour(p >= 1)
        hudName.Text = "Stealing..."
    elseif status.target then
        hudProgressFill.Size = UDim2.new(0, 0, 1, 0)
        hudPercent.Text = "0%"
        hudProgressFill.BackgroundColor3 = _fillColour(false)
        local vs = _pbFmtVal(status.target.mps or status.target.value)
        hudName.Text = (status.target.name or "Brainrot") .. ((vs ~= "0") and (" - $" .. vs) or "")
    else
        hudProgressFill.Size = UDim2.new(0, 0, 1, 0)
        hudPercent.Text = "0%"
        hudProgressFill.BackgroundColor3 = _fillColour(false)
        hudName.Text = "Searching..."
    end
end)
