function waitUntilHeartbeat(predicate, timeoutSec)
    local t = 0
    while true do
        if predicate() then
            return true
        end
        local dt = RunService.Heartbeat:Wait()
        t += dt
        if timeoutSec and (t >= timeoutSec) then
            return false
        end
    end
end
