local MAX_CLIMB = 60

local function velMoveThrough(hrp, waypoints, speedOverride, allowJump, quickStart)
    if not hrp or not hrp.Parent or #waypoints == 0 then return end
    local _runSpeed = speedOverride or Config.TpSettings.GrabbleTPSpeed or (_G.Skyr0CarpetSpeed or CARPET_SPEED or 230)
    vizPath(hrp.Position, waypoints)
    local wpIdx = 1
    local done = false
    local conn
    local function finish()
        if done then return end
        done = true
        if hrp and hrp.Parent then
            hrp.AssemblyLinearVelocity = Vector3.zero
            hrp.AssemblyAngularVelocity = Vector3.zero
            local _, y = hrp.CFrame:ToEulerAnglesYXZ()
            hrp.CFrame = CFrame.new(waypoints[#waypoints]) * CFrame.Angles(0, y, 0)
        end
        if conn then conn:Disconnect() end
        clearViz()
    end
    local lastDist, stall = math.huge, 0
    -- anti-lagback state
    local lastPos, lagRecover, lagUntil = hrp.Position, 0, 0
    local stallStart = 0
    local MAX_RECOVER = 3

    if quickStart then
        local _hp = RaycastParams.new()
        _hp.FilterType = Enum.RaycastFilterType.Exclude
        _hp.IgnoreWater = true
        local _skip = {}
        for _, pl in ipairs(Players:GetPlayers()) do
            if pl.Character then _skip[#_skip + 1] = pl.Character end
        end
        _hp.FilterDescendantsInstances = _skip
        for _ = 1, 3 do
            local target = waypoints[wpIdx]
            if not target then break end
            local flat = Vector3.new(target.X - hrp.Position.X, 0, target.Z - hrp.Position.Z)
            local mag = flat.Magnitude
            if mag < 1 then break end
            local nextPos = hrp.Position + flat.Unit * math.min(20, mag)
            local _hit = Workspace:Raycast(hrp.Position, nextPos - hrp.Position, _hp)
            if _hit and _hit.Instance and _hit.Instance.CanCollide then break end
            hrp.CFrame = (hrp.CFrame - hrp.CFrame.Position) + nextPos
            hrp.AssemblyLinearVelocity = Vector3.zero
            hrp.AssemblyAngularVelocity = Vector3.zero
            RunService.Heartbeat:Wait()
            if not hrp or not hrp.Parent then return end
        end
    end

    conn = RunService.Heartbeat:Connect(function(dt)
        dt = dt or (1 / 60)
        if not hrp or not hrp.Parent or done then
            if conn then conn:Disconnect() end
            return
        end
        equipCarpet()
        local target = waypoints[wpIdx]
        local diff = target - hrp.Position
        local mag = diff.Magnitude
        if mag < ARRIVE then
            wpIdx = wpIdx + 1
            if wpIdx > #waypoints then finish() return end
            lastDist, stall = math.huge, 0
            target = waypoints[wpIdx]
            diff = target - hrp.Position
            mag = diff.Magnitude
        end
        -- ---- lagback detection ----
        -- The server put us somewhere we did not drive to. Past what one frame at
        -- our own speed could cover AND moving away from the target is a rejection;
        -- either condition alone is just a bounce off geometry.
        local moved = (hrp.Position - lastPos).Magnitude
        local _png = (_G.Skyr0Ping and _G.Skyr0Ping()) or 0.1
        -- The correction covers everything the server thinks you did during one
        -- round trip, so the "could we have moved this far" budget has to include
        -- it -- otherwise ordinary high-ping catch-up reads as a lagback and
        -- cancels a flight that was going fine.
        local budget = _runSpeed * (math.max(dt, 1 / 240) * 2 + _png) + 6
        if moved > budget and mag > lastDist + 4 then
            lastPos = hrp.Position
            if lagRecover < MAX_RECOVER then
                lagRecover = lagRecover + 1
                -- Stop pushing and let it settle. Driving into a rejection just gets
                -- rejected again, and finish()'s snap to the last waypoint is that
                -- same illegal move one more time.
                hrp.AssemblyLinearVelocity = Vector3.zero
                hrp.Velocity = Vector3.zero
                -- Settle for a full round trip plus a margin. A fixed 0.35s is shorter
                -- than the correction takes to even arrive on a 300ms connection, so the
                -- old code resumed straight back into the rejection and burnt all three
                -- recoveries inside half a second.
                lagUntil = os.clock() + math.clamp(_png * 2 + 0.2, 0.35, 1.5)
                lastDist, stall, stallStart = math.huge, 0, 0
                return
            end
            -- out of recoveries: end where the server actually has us
            finish() return
        end
        lastPos = hrp.Position
        -- hold off while a recovery settles, then resume from wherever the server
        -- left us, re-aimed at the same waypoint
        if os.clock() < lagUntil then
            hrp.AssemblyLinearVelocity = Vector3.zero
            return
        end
        -- ---- stall detector, on a clock rather than a frame count ----
        if mag > lastDist - 0.05 then
            if stallStart == 0 then stallStart = os.clock() end
        else
            stallStart = 0
        end
        lastDist = mag
        -- Same reason: a high-ping server can hold you still for most of a round
        -- trip while it catches up, and that is not being stuck.
        if stallStart ~= 0 and (os.clock() - stallStart) > (0.45 + _png * 2) then finish() return end
        if mag >= 0.1 then
            local dir = diff.Unit
            if allowJump and diff.Y > 5 and wpIdx < #waypoints then
                local hum = hrp.Parent and hrp.Parent:FindFirstChildOfClass("Humanoid")
