--
-- Delta and most mobile executors restrict it to nil. That is not an error --
-- the exact-source match below simply matches nothing, every call is a no-op,
-- and the anticheat's CFrame/Position watchers stay live for the whole
-- session with nothing said about it. Decided once, from the first real
-- connection actually seen, rather than assumed either way.
local _connFnUsable = nil   -- nil = not yet known
local _connFnWarned = false

local function Strip()
    local char = lp.Character
    local hrp = char and char:FindFirstChild("HumanoidRootPart")
    if not hrp then return end
    if type(getconnections) ~= "function" then return end
    for _, sig in ipairs({"CFrame", "Position"}) do
        local signal = hrp:GetPropertyChangedSignal(sig)
        if signal then
            local okc, conns = pcall(getconnections, signal)
            if okc and type(conns) == "table" then
                for _, c in ipairs(conns) do
                    local f
                    pcall(function() f = c.Function end)
                    if _connFnUsable == nil then _connFnUsable = (type(f) == "function") end

                    if type(f) == "function" and type(getinfo) == "function" then
                        -- Exact source was "=ReplicatedFirst.test". Executors
                        -- disagree about the chunkname prefix ("=", "@", or
                        -- none), so match on the two parts instead of the
                        -- whole string -- same connection, one less way to
                        -- miss it.
                        local oki, info = pcall(getinfo, f)
                        local src = oki and type(info) == "table" and info.source
                        if src and src:find("ReplicatedFirst", 1, true)
                               and src:find("test", 1, true) then
                            local en = true
                            pcall(function() en = c.Enabled end)
                            if en ~= false then pcall(function() c:Disable() end) end
