-- =====================================================================
-- skyr0.wtf  --  UI CORE (rewritten)
-- ---------------------------------------------------------------------
-- Same palette, same name, same public API as the old core: every builder
-- below keeps its exact signature and return shape, so nothing downstream --
-- loadTab, rebuildActions, the AP panel, applyTheme -- needed touching.
--
-- What is new:
--   * ONE shared widget spine. Every row (toggle, slider, dropdown, textbox,
--     keybind) is built from the same `shell()` primitive, so spacing, corner
--     radius, hover and press feedback are defined once instead of per widget.
--   * Pointer-agnostic input. Buttons react to InputBegan/InputEnded rather
--     than MouseButton1Click, so touch behaves exactly like mouse -- that plus
--     the sizing below is the mobile support.
--   * Touch-sized targets. Every interactive row is at least MIN_TAP tall on a
--     touch device, and the window itself scales to the viewport instead of
--     using fixed 560px numbers that fall off a phone screen.
--   * Springy, interruptible motion. Tweens are short, Quint, and always
--     replace the previous one on the same property, so dragging or spamming a
--     toggle never queues up a backlog of animations.
-- =====================================================================

-- ---------- environment ----------
local UIS_ = game:GetService("UserInputService")
local IS_TOUCH = false
IS_TOUCH = _G.Skyr0IsTouch == true   -- shared detector (see DEVICE DETECTION)
local MIN_TAP = IS_TOUCH and 40 or 0

local function viewport()
    local cam = workspace.CurrentCamera
    return (cam and cam.ViewportSize) or Vector2.new(1280, 720)
end
if _G.__LMARK then _G.__LMARK("L15092") end

-- Window size: fixed on desktop, viewport-relative on a phone so the panel can
-- never open larger than the screen it is drawn on.
local function windowSize()
    local vp = viewport()
    if not IS_TOUCH then return UDim2.fromOffset(520, 540) end
    -- A tablet has the room for the desktop window; only phones need shrinking.
    -- Sizing both the same is why an iPad got the cramped phone layout.
    if _G.Skyr0IsTablet then
        local w = math.clamp(vp.X * 0.62, 460, 620)
        local h = math.clamp(vp.Y * 0.72, 420, 640)
        return UDim2.fromOffset(math.floor(w), math.floor(h))
    end
    local w = math.clamp(vp.X * 0.92, 300, 560)
    local h = math.clamp(vp.Y * 0.80, 320, 560)
    return UDim2.fromOffset(math.floor(w), math.floor(h))
end
if _G.__LMARK then _G.__LMARK("L15110") end

-- ---------- primitives ----------
corner = function(o,r) local c=Instance.new("UICorner"); c.CornerRadius=UDim.new(0,r); c.Parent=o; return c end
stroke = function(o,col,th,tr) local s=Instance.new("UIStroke"); s.Color=col or Theme.Stroke; s.Thickness=th or 1; s.Transparency=tr or 0; s.ApplyStrokeMode=Enum.ApplyStrokeMode.Border; s.Parent=o; return s end
-- LITE UI: properties are set instantly instead of tweened, so a hover or a
-- toggle never creates a tween. _G.Skyr0UIAnim = true brings animations back.
tw = function(o,p,t)
    if _G.Skyr0UIAnim == true then TweenService:Create(o,TweenInfo.new(t or 0.14,Enum.EasingStyle.Quint,Enum.EasingDirection.Out),p):Play(); return end
    pcall(function() for k,v in pairs(p) do o[k]=v end end)
end
-- KAYA-style rim: 1.5px outline with a diagonal accent gradient
addOutline = function(f)   -- minimal: one thin plain outline, no gradient
    local o=Instance.new("UIStroke"); o.Color=Theme.Stroke; o.Thickness=1; o.Transparency=0.35
    o.ApplyStrokeMode=Enum.ApplyStrokeMode.Border; o.Parent=f
    return o
end
if _G.__LMARK then _G.__LMARK("L15124") end

-- KAYA-style card background: a diagonal gradient (lighter top-left, darker
-- bottom-right). It multiplies the panel colour, so theme switching still works.
-- SKYRO BACKGROUND: the same picture duels.lua uses (its "Skyro" background),
-- stretched under every panel. Roblox cannot show a web image directly, so it
-- is downloaded ONCE on its own thread (never on the load frame), cached as
-- skyr0_bg_1.jpg -- the file duels.lua already writes -- and handed to Roblox
-- through getcustomasset. Panels built before it lands get it the moment it does.
-- _G.Skyr0PanelBg = false turns it off; _G.Skyr0PanelBgTransparency fades it.
do   -- kept in a block: no new main-chunk locals
    -- CUSTOM PHOTO (UI tab): Config.CustomBg is the source -- "" = the default
    -- Skyro picture, an image URL (downloaded once, cached), an asset id /
    -- rbxassetid://, or a file name in the executor workspace.
    -- Config.CustomBgTransparency fades it, Config.CustomBgOn = false hides it.
    local DEFAULT_URL = "https://anondrop.net/1559336458769145906/skyr0_duels_bg.jpg?download=true"
    local _skyrBg = { asset = nil, src = nil, gen = 0, labels = setmetatable({}, { __mode = "k" }) }
    -- "jpg" / "png" for an image Roblox can show, the other format's name
    -- for one it can't (webp / gif / avif / html), nil for junk
    local function _fmt(data)
        if type(data) ~= "string" or #data < 64 then return nil end
        local b1, b2, b3 = data:byte(1, 3)
        if b1 == 0xFF and b2 == 0xD8 then return "jpg" end
        -- some executors mangle the 0x89 byte of the PNG signature
        if data:sub(2, 4) == "PNG" then return "png" end
        if data:sub(1, 4) == "RIFF" and data:sub(9, 12) == "WEBP" then return "webp" end
        if data:sub(1, 3) == "GIF" then return "gif" end
        if data:sub(5, 12) == "ftypavif" or data:sub(5, 12) == "ftypheic" then return "avif" end
        local head = data:sub(1, 200):lower()
        if head:find("<html", 1, true) or head:find("<!doctype", 1, true) then return "html" end
        return nil
    end
    local function _isImg(data)
        local f = _fmt(data)
        return (f == "jpg" or f == "png") and #data >= 1024
    end
    -- links that serve WEBP / a web page by default, asked for PNG/JPG instead
    local function _fixUrl(url)
        if url:find("discordapp%.") or url:find("discord%.com") then
            url = url:gsub("([?&])format=webp", "%1format=png")
        end
        local id = url:match("^https?://imgur%.com/([%w]+)$") or url:match("^https?://www%.imgur%.com/([%w]+)$")
        if id then url = "https://i.imgur.com/" .. id .. ".png" end
        return url
    end
    local function _fetch(url)
        local last
        local req = (syn and syn.request) or (http and http.request) or http_request or request
        if req then
            local okR, res = pcall(req, { Url = url, Method = "GET",
                Headers = { ["User-Agent"] = "Mozilla/5.0", ["Accept"] = "image/png,image/jpeg;q=0.9" } })
            if okR and res then
                if _isImg(res.Body) then return res.Body end
                last = _fmt(res.Body)
            end
        end
        local okH, body = pcall(function() return game:HttpGet(url) end)
        if okH then
            if _isImg(body) then return body end
            last = last or _fmt(body)
        end
        return nil, last
    end
    local function _resolve(src)
        if src:match("^%d+$") then return "rbxassetid://" .. src end
        if src:match("^rbxasset") then return src end
        if type(getcustomasset) ~= "function" then error("your executor has no getcustomasset") end
        if src == "" or src:match("^https?://") then
            local url, base = DEFAULT_URL, "skyr0_bg_1"
            if src ~= "" then
                url = _fixUrl(src)
                local h = 0
                for i = 1, #url do h = (h * 31 + url:byte(i)) % 2147483647 end
                base = "skyr0_bg_custom_" .. h
            end
            local file
            for _, ext in ipairs({ ".jpg", ".png" }) do
                local fn = base .. ext
                if isfile and isfile(fn) then
                    -- a cached file Roblox can't show (an old webp download) is thrown away
                    if _isImg(readfile(fn)) then file = fn; break end
                    pcall(delfile, fn)
                end
            end
            if not file then
                if type(writefile) ~= "function" then error("your executor has no writefile") end
                local data, got = _fetch(url)
                if not data then
                    if got == "webp" or got == "gif" or got == "avif" then
                        error("that link is a " .. got:upper() .. " -- Roblox only shows PNG/JPG. Use a .png/.jpg link")
                    elseif got == "html" then
                        error("that link is a web page, not the image -- right click the picture > Copy image address")
                    end
                    error("download failed -- use a direct .png/.jpg link")
                end
                -- a new name per download: Roblox remembers a failed load per path
                file = base .. "_" .. tostring(os.time()) .. ((_fmt(data) == "png") and ".png" or ".jpg")
                writefile(file, data)
                pcall(function()
                    if isfile(base .. ".jpg") then delfile(base .. ".jpg") end
                    if isfile(base .. ".png") then delfile(base .. ".png") end
                end)
                writefile(base .. ((_fmt(data) == "png") and ".png" or ".jpg"), data)
            end
            return getcustomasset(file)
        end
        if isfile and isfile(src) then
            local d = readfile(src)
            local f = _fmt(d)
            if f and f ~= "jpg" and f ~= "png" then error(src .. " is a " .. f:upper() .. " -- Roblox only shows PNG/JPG") end
            return getcustomasset(src)
        end
        error("not an image link, asset id or file name: " .. src)
    end
    local function _paint()
        local tr = tonumber(Config and Config.CustomBgTransparency) or tonumber(_G.Skyr0PanelBgTransparency) or 0.7
        local vis = not (Config and Config.CustomBgOn == false)
        for lbl in pairs(_skyrBg.labels) do
            if lbl.Parent then
                lbl.Image = _skyrBg.asset or ""
                lbl.ImageTransparency = tr
                lbl.Visible = vis
            end
        end
    end
    local function _say(msg)
        warn("[skyr0] custom photo: " .. msg)
        pcall(ShowNotification, "PHOTO", msg)
    end
    local function _load(src)
        src = tostring(src or "")
        _skyrBg.gen = _skyrBg.gen + 1
        _skyrBg.src = src
        local my = _skyrBg.gen
        task.spawn(function()
            local ok, res = pcall(_resolve, src)
            if my ~= _skyrBg.gen then return end   -- a newer photo was picked meanwhile
            if not (ok and res) then
                _say(tostring(res):gsub("^.-:%d+: ", ""))
                return
            end
            _skyrBg.asset = res
            _paint()
            -- make sure Roblox really shows it, and say so when it doesn't
            if src ~= "" then
                local lbl
                for l in pairs(_skyrBg.labels) do if l.Parent then lbl = l; break end end
                if lbl then
                    local t0 = os.clock()
                    while not lbl.IsLoaded and os.clock() - t0 < 6 and my == _skyrBg.gen do task.wait(0.2) end
                    if my ~= _skyrBg.gen then return end
                    if lbl.IsLoaded then _say("photo loaded")
                    else _say("downloaded, but Roblox could not show it -- try a smaller .png/.jpg") end
                end
            end
        end)
    end
    _G.Skyr0SetPanelBg = function(src) _load(src) end
    _G.Skyr0SetPanelBgTransparency = function() _paint() end
    _G.Skyr0SetPanelBgVisible = function() _paint() end
    _G.Skyr0ApplyPanelBg = function(f)
        if _G.Skyr0PanelBg == false or not f or f:FindFirstChild("SkyroBackground") then return nil end
        local img = Instance.new("ImageLabel")
        img.Name = "SkyroBackground"
        img.Size = UDim2.fromScale(1, 1)
        img.BackgroundTransparency = 1
        img.BorderSizePixel = 0
        img.Image = _skyrBg.asset or ""
        img.ImageTransparency = tonumber(Config and Config.CustomBgTransparency) or tonumber(_G.Skyr0PanelBgTransparency) or 0.7
        img.Visible = not (Config and Config.CustomBgOn == false)
        img.ScaleType = Enum.ScaleType.Stretch   -- whole picture, stretched to fit the panel
        img.ZIndex = f.ZIndex
        local fc = f:FindFirstChildOfClass("UICorner")
        local c = Instance.new("UICorner"); c.CornerRadius = fc and fc.CornerRadius or UDim.new(0, 14); c.Parent = img
        img.Parent = f
        _skyrBg.labels[img] = true
        return img
    end
    -- start loading the moment the hub runs, on its own thread
    _load(Config and Config.CustomBg or "")
end
