-- Pointer press/release that works for mouse AND touch. Returns the button so
-- callers can keep chaining. `press` fires on release inside the widget only,
-- which is what makes a drag off a button cancel it the way a phone user
-- expects.
-- MOBILE TAP vs SCROLL (phone / tablet only -- PC is untouched).
-- A finger that lands on a toggle and then scrolls the list still ends on that
-- toggle, and a release used to count as a press -- so scrolling through the
-- settings flipped whatever you happened to let go on. On touch devices a
-- release is only a tap when the finger moved less than TAP_SLOP pixels AND the
-- scrolling list it sits in did not move. Each touch is tracked by its own
-- InputObject, so a thumb on the move joystick never affects a tap.
local _tapTracker
do
local TAP_SLOP = 12
local function _scrollerOf(g)
    local p = g and g.Parent
    while p do
        if p:IsA("ScrollingFrame") then return p end
        p = p.Parent
    end
    return nil
end
if _G.__LMARK then _G.__LMARK("L15225") end
_tapTracker = function(btn)
    local starts = setmetatable({}, { __mode = "k" })
    local function xy(i) return Vector2.new(i.Position.X, i.Position.Y) end
    local function began(i)
        local sf = _scrollerOf(btn)
        starts[i] = { pos = xy(i), sf = sf, canvas = sf and sf.CanvasPosition, moved = false }
    end
    local function changed(i)
        local s = starts[i]
        if s and not s.moved and (xy(i) - s.pos).Magnitude > TAP_SLOP then s.moved = true end
    end
    local function ended(i)
        local s = starts[i]
        starts[i] = nil
        if not s or s.moved then return false end
        if (xy(i) - s.pos).Magnitude > TAP_SLOP then return false end
        if s.sf and s.canvas and s.sf.Parent and (s.sf.CanvasPosition - s.canvas).Magnitude > 4 then return false end
        return true
    end
    return began, changed, ended
end
if _G.__LMARK then _G.__LMARK("L15247") end
end
if _G.__LMARK then _G.__LMARK("L15249") end

local function bindPress(btn, onPress, hoverIn, hoverOut)
    local inside, down = false, false
    local tBegan, tChanged, tEnded
    if IS_TOUCH then tBegan, tChanged, tEnded = _tapTracker(btn) end
    btn.InputBegan:Connect(function(i)
        if i.UserInputType == Enum.UserInputType.MouseButton1 or i.UserInputType == Enum.UserInputType.Touch then
            down = true
            if tBegan and i.UserInputType == Enum.UserInputType.Touch then tBegan(i) end
            if hoverIn then hoverIn(true) end
        elseif i.UserInputType == Enum.UserInputType.MouseMovement then
            inside = true; if hoverIn then hoverIn(false) end
        end
    end)
    if tChanged then
        btn.InputChanged:Connect(function(i)
            if i.UserInputType == Enum.UserInputType.Touch then tChanged(i) end
        end)
    end
    btn.InputEnded:Connect(function(i)
        if i.UserInputType == Enum.UserInputType.MouseButton1 or i.UserInputType == Enum.UserInputType.Touch then
            local tap = true
            if tEnded and i.UserInputType == Enum.UserInputType.Touch then tap = tEnded(i) end
            if down and tap and onPress then task.spawn(onPress) end
            down = false
            if hoverOut then hoverOut() end
        elseif i.UserInputType == Enum.UserInputType.MouseMovement then
            inside = false; if hoverOut then hoverOut() end
        end
    end)
    return btn
end
if _G.__LMARK then _G.__LMARK("L15282") end
_G.Skyr0BindPress = bindPress

-- Drop-in for btn.MouseButton1Click:Connect(fn). PC: exactly that. Phone /
-- tablet: fires only on a real tap (see the tap tracker above).
_G.Skyr0OnTap = function(btn, fn)
    if not IS_TOUCH then return btn.MouseButton1Click:Connect(fn) end
    local tBegan, tChanged, tEnded = _tapTracker(btn)
    local mdown = false
    btn.InputBegan:Connect(function(i)
        if i.UserInputType == Enum.UserInputType.Touch then tBegan(i)
        elseif i.UserInputType == Enum.UserInputType.MouseButton1 then mdown = true end
    end)
    btn.InputChanged:Connect(function(i)
        if i.UserInputType == Enum.UserInputType.Touch then tChanged(i) end
    end)
    return btn.InputEnded:Connect(function(i)
        if i.UserInputType == Enum.UserInputType.Touch then
            if tEnded(i) then task.spawn(fn) end
        elseif i.UserInputType == Enum.UserInputType.MouseButton1 then
            if mdown then mdown = false; task.spawn(fn) end
        end
    end)
end
