    row.BackgroundColor3 = opts.bg or Theme.Row
    row.BackgroundTransparency = opts.transparent and 1 or 0.2
    row.BorderSizePixel = 0
    row.Parent = parent
    if not opts.transparent then corner(row, 6) end   -- minimal: no outline per row
    return row
end
