-- KAYA-style toggle: the whole row is the button. It reads "NAME: ON" / "NAME: OFF",
-- and the text, the outline and the status dot light up in the accent when on.
local function cardToggle(parent, text, getVal, onPress)
    local title = string.upper((tostring(text):gsub(":%s*$", "")))
    local card = shell(parent, 34)
    local st = card:FindFirstChildOfClass("UIStroke")
    local lbl=Instance.new("TextLabel")
    lbl.Size=UDim2.new(1,-40,1,0); lbl.Position=UDim2.new(0,12,0,0); lbl.BackgroundTransparency=1
    lbl.Font=Enum.Font.GothamBold; lbl.TextSize=11; lbl.TextXAlignment=Enum.TextXAlignment.Left
    lbl.TextTruncate=Enum.TextTruncate.AtEnd; lbl.Parent=card
    local dot=Instance.new("Frame"); dot.Size=UDim2.fromOffset(8,8); dot.Position=UDim2.new(1,-20,0.5,-4)
    dot.BorderSizePixel=0; dot.Parent=card; corner(dot,4)
    local hit=Instance.new("TextButton"); hit.Name="WhiteTextBtn"
    hit.Size=UDim2.fromScale(1,1); hit.BackgroundTransparency=1; hit.Text=""; hit.AutoButtonColor=false; hit.ZIndex=3; hit.Parent=card
    local function paint(v)
        v = v and true or false
        lbl.Text = title .. (v and ": ON" or ": OFF")
        tw(lbl,{TextColor3 = v and Theme.Accent or Theme.Dim},0.14)
        tw(dot,{BackgroundColor3 = v and Theme.Accent or Theme.ToggleOff},0.14)
        if st then tw(st,{Color = v and Theme.Accent or Theme.Stroke, Transparency = v and 0.1 or 0.35},0.14) end
    end
    paint(getVal())
    bindPress(hit, onPress,
        function() tw(card,{BackgroundColor3=Theme.RowHover},0.10) end,
        function() tw(card,{BackgroundColor3=Theme.Row},0.12) end)
    return paint
end
