            local newKey
            if input.UserInputType==Enum.UserInputType.Keyboard then
                if input.KeyCode==Enum.KeyCode.Escape then
                    stop(); key.Text=Keybinds[nameText] or "NONE"
                    tw(key,{BackgroundColor3=Theme.Accent},0.12); return
