    -- built after the load TP (see MAIN GUI LOADS AFTER THE TP), one piece per frame
    while _G.__Skyr0GuiAfterTP do task.wait(0.1) end
    loadTab("Auto TP")
    task.wait()
    rebuildActions()
    task.wait()
    rebuildActionSettings()
end)
