            local Shared = RS:WaitForChild("Shared", 5)
            local Utils = RS:WaitForChild("Utils", 5)
            Synchronizer = _G.Skyr0SyncModuleBlocking and _G.Skyr0SyncModuleBlocking() or nil
            AnimalsData = require(Datas:WaitForChild("Animals"))
            AnimalsShared = _G._xenAnimShim
            NumberUtils = require(Utils:WaitForChild("NumberUtils"))
        end)
        return ok and Synchronizer ~= nil
    end

    local NetModule
    local function loadNet()
        if NetModule then return true end
        local ok, mod = pcall(function()
            return _G.Net
        end)
        if not ok or type(mod) ~= "table" then return false end
        NetModule = mod
        return true
    end

    local function fireGrapple()
        local char = LP.Character
        if not char then return end
        if not char:FindFirstChild("Grapple Hook") then
            -- TP-on-load now fires very early (warmed during the load), so it can
            -- get here before the server has finished handing you the Grapple
            -- Hook in the Backpack. Wait a moment -- bounded, and it does not
            -- block the rest of the hub -- instead of giving up instantly.
            local bp = LP:FindFirstChild("Backpack") or LP:WaitForChild("Backpack", 2)
            local tool = bp and bp:FindFirstChild("Grapple Hook")
            if not tool and bp then
                local _t0 = os.clock()
                while not tool and os.clock() - _t0 < 1.5 do
                    task.wait(0.05)
                    tool = bp:FindFirstChild("Grapple Hook")
                end
            end
            local hum = char:FindFirstChildOfClass("Humanoid")
            if tool and hum then pcall(function() hum:EquipTool(tool) end) end
        end
        if not char:FindFirstChild("Grapple Hook") then return end
        -- Same for the remote resolver: if it has not finished scanning yet,
        -- wait an instant rather than silently failing the first time.
        if not _G.Skyr0FireGrapple2 then
            local _t0 = os.clock()
            while not _G.Skyr0FireGrapple2 and os.clock() - _t0 < 1.5 do
                task.wait(0.05)
            end
        end
        -- Fire via the TOOL, not the remote: the aim goes into every live
        -- PlayerMouse table and the item's own Activated signal is driven, so
        -- the obfuscated HookScript builds the call itself.
        if not (_G.Skyr0FireGrapple2 and _G.Skyr0FireGrapple2()) then
            warn("[skyr0] fireGrapple: could not aim or activate the Grapple Hook")
        end
    end
    _G.Skyr0FireGrapple = fireGrapple

    -- ===== Speed config (live-settable) =====
    local Skyr0Speed = { CARPET = 400, INBASE = 250 }
    _G.Skyr0SetCarpetSpeed = function(v) v = tonumber(v); if v and v > 0 then Skyr0Speed.CARPET = v end end
    _G.Skyr0SetInbaseSpeed = function(v) v = tonumber(v); if v and v > 0 then Skyr0Speed.INBASE = v end end
    _G.Skyr0GetCarpetSpeed = function() return Skyr0Speed.CARPET end
    if Config and Config.TpSettings then
        if tonumber(Config.TpSettings.GrabbleTPSpeed) then Skyr0Speed.CARPET = tonumber(Config.TpSettings.GrabbleTPSpeed) end
    end

    -- ===== Tools =====
    local CARPET_NAMES = { "Flying Carpet", "Carpet", "Cloud", "Witch's Broom", "Cupid's Wings", "Santa's Sleigh", "Magic Carpet" }
    local GRAPPLE_NAMES = { "Grapple Hook", "Grappling Hook", "Grapple", "Hook", "Web Slinger", "Grapple Gun", "GrappleHook" }
    local function findTool(name)
        local char = LP.Character
        local bp = LP:FindFirstChild("Backpack")
        return (char and char:FindFirstChild(name)) or (bp and bp:FindFirstChild(name))
    end
    local function findGrapple()
        for _, n in ipairs(GRAPPLE_NAMES) do
            local t = findTool(n); if t then return t end
        end
        return nil
    end
    local function equipCarpet()
        local char = LP.Character
        local hum = char and char:FindFirstChildOfClass("Humanoid")
        if not hum then return nil end
        local preferred = Config and Config.TpSettings and Config.TpSettings.Tool
        if preferred then
            local pt = findTool(preferred)
            if pt and pt:IsA("Tool") then
                if pt.Parent ~= char then pcall(function() hum:EquipTool(pt) end) end
                return preferred
            end
        end
        for _, n in ipairs(CARPET_NAMES) do
            local t = findTool(n)
            if t and t:IsA("Tool") then
                if t.Parent ~= char then pcall(function() hum:EquipTool(t) end) end
                return n
            end
        end
        return nil
    end
local function carpetEngage()
        if not NetModule then pcall(loadNet) end
        local char = LP.Character
        local hum = char and char:FindFirstChildOfClass("Humanoid")
        if not char or not hum then return nil end
        -- Wait up to 3s for the grapple to replicate into backpack/character AND
        -- for _G.Net to come online. (Was 1s -- too short on a fresh join, so the
        -- very first TP silently skipped the grapple fire.)
        local _t0 = os.clock()
        while not findTool("Grapple Hook") and os.clock() - _t0 < 3 do
            if not NetModule then pcall(loadNet) end
            RunService.Heartbeat:Wait()
        end
        local g = findTool("Grapple Hook")
        if g and g.Parent ~= char then
            pcall(function() hum:EquipTool(g) end)
            -- Wait until the equip actually registers (tool becomes a child of the
            -- character) instead of a fixed 0.05s that lost the race on start.
            local _te = os.clock()
            while not (LP.Character and LP.Character:FindFirstChild("Grapple Hook"))
                  and os.clock() - _te < 0.5 do
                RunService.Heartbeat:Wait()
            end
        end
        -- The cycle (Skyr0CicloTP) has usually ALREADY fired the hook a moment
        -- ago. Firing it again here was a second shot, a second aim/cancel pass
        -- and -- worse -- a fresh fixed wait before the carpet, all of it sitting
        -- between the remote going out and the flight starting.
        local _firedAt = _G.Skyr0GrappleFiredAt
        local _justFired = _firedAt ~= nil and (os.clock() - _firedAt) < 2
        -- the cycle attempted the hook for THIS teleport (even if its shot did not
        -- register): never add an aimless second one on top
        local _cyc = _G.Skyr0CycleHookAt
        if _cyc ~= nil and (os.clock() - _cyc) < 8 then _justFired = true end
        if LP.Character and LP.Character:FindFirstChild("Grapple Hook") then
            if not _justFired then
                -- Fire via the TOOL, not the remote (see Skyr0FireGrapple2): aim is
                -- written into the live PlayerMouse tables, then Activated is driven
                -- and held for 4 frames because SignalBehavior is Deferred.
                if not (_G.Skyr0FireGrapple2 and _G.Skyr0FireGrapple2()) then
                    warn("[skyr0] carpetEngage: could not aim or activate the Grapple Hook")
                end
                _firedAt = _G.Skyr0GrappleFiredAt
            end
        else
            -- Diagnostic: say exactly WHY, so a load-time failure is identifiable
            -- instead of ambiguous (tool missing vs. equip race vs. no remote).
            local _bp = LP:FindFirstChild("Backpack")
            local _names = {}
            if _bp then for _, t in ipairs(_bp:GetChildren()) do _names[#_names+1] = t.Name end end
            warn(("[skyr0] carpetEngage: grapple skipped -- inBackpack=%s inChar=%s remote=%s | backpack: %s")
                :format(
                    tostring(_bp ~= nil and _bp:FindFirstChild("Grapple Hook") ~= nil),
                    tostring(LP.Character ~= nil and LP.Character:FindFirstChild("Grapple Hook") ~= nil),
                    tostring(_G.Skyr0GrappleReady and _G.Skyr0GrappleReady() or false),
                    (#_names > 0 and table.concat(_names, ", ") or "(empty)")))
        end
        -- Leave the hook in hand only until the item's handler has been dequeued
        -- (Activate() only QUEUES it; two frames is enough), measured from the
        -- moment the shot actually went out -- not a blind 0.08s before AND after
        -- the unequip. The carpet goes on the very next frame.
        do
            local _f = _firedAt or os.clock()
            while os.clock() - _f < (tonumber(_G.Skyr0HookHandlerWait) or 0.034) do RunService.Heartbeat:Wait() end
        end
        -- EquipTool swaps whatever is in hand, so there is no separate unequip and
        -- no frame spent waiting for one: the carpet goes on immediately.
        local cn
        local _tc = os.clock()
        repeat
            cn = equipCarpet()
            local c = LP.Character
            if cn and c and c:FindFirstChild(cn) then break end
            RunService.Heartbeat:Wait()
        until os.clock() - _tc > 1
        return cn
    end

    -- ===== Priority system =====
    local PET_PRIORITY_TIERS = {
        [1]  = { pets = {"Headless Horseman"}, threshold = 0 },
        [2]  = { pets = {"Signore Carapace"}, threshold = 0 },
        [3]  = { pets = {"Strawberry Elephant"}, threshold = 0 },
        [4]  = { pets = {"Arcadragon"}, threshold = 0 },
        [5]  = { pets = {"Elefanto Frigo"}, threshold = 5e9 },
        [6]  = { pets = {"John Pork"}, threshold = 10e9 },
        [7]  = { pets = {"Meowl"}, threshold = 5e9 },
        [8]  = { pets = {"Skibidi Toilet"}, threshold = 5e9 },
        [9]  = { pets = {"Love Love Bear"}, threshold = 0 },
        [10] = { pets = {"Antonio"}, threshold = 0 },
        [11] = { pets = {"Pancake and Syrup"}, threshold = 0 },
        [12] = { pets = {"Griffin"}, threshold = 0 },
        [13] = { pets = {"La Supreme Combinasion","Fishino Clownino","Dragon Gingerini","Tirilikalika Tirilikalako"}, threshold = 5e9 },
        [14] = { pets = {"Ginger Gerat","Pet"}, threshold = 10e9 },
        [15] = { pets = {"Hydra Bunny","Digi Narwhal","Kalika Bros"}, threshold = 3e9 },
        [16] = { pets = {"Hydra Dragon Cannelloni","Dragon Cannelloni","Bunny and Eggy"}, threshold = 3e9 },
        [17] = { pets = {"Globa Steppa","Ketupat Bros","Rosey and Teddy","La Casa Boo","Fragola la la"}, threshold = 3e9 },
        [18] = { pets = {"Fragola La La La","Cerberus","Guest 666","Los Hackers"}, threshold = 1e9 },
        [19] = { pets = {"Garama and Madundung","Spooky and Pumpky","Reinito Sleighito","Burguro And Fryuro","Cooki and Milki","Fragrama and Chocrama","La Food Combinasion","Los Amigos","Foxini Lanternini","Capitano Moby","Fortunu and Cashuru","Los Sekolahs","Celestial Pegasus"}, threshold = 750e6 },
        [20] = { pets = {"La Secret Combinasion","Sammyni Fattini","Cloverat Clapat","Popcuru and Fizzuru"}, threshold = 1e9 },
    }
    local TIER_LOOKUP = {}
    for tier, data in pairs(PET_PRIORITY_TIERS) do
        for _, name in ipairs(data.pets) do TIER_LOOKUP[name] = tier end
    end
    local LOCKED_TIERS = { [1]=true,[2]=true,[3]=true,[4]=true }
    local DIRECT_THRESHOLDS = {
        [3] = { [4] = 10e9 },
        [4] = {},
        [5] = { [6] = math.huge },
        [6] = { [9] = math.huge, [10] = math.huge, [12] = 15e9 },
        [10] = { [12] = 20e9 },
        [11] = { [12] = 10e9 },
    }
    local MUTATION_PRIORITY = {
        ["Galaxy"]=1,["Candy"]=1,["Yin Yang"]=1,["YinYang"]=1,["Divine"]=1,
        ["Cursed"]=1,["Lava"]=1,["Radioactive"]=1,["Cyber"]=1,["Rainbow"]=1,["Bloodrot"]=2,
    }
    local MUTATED_BEATS_GRIFFIN = {
        ["Fishino Clownino"]=true,["Globa Steppa"]=true,
        ["La Supreme Combinasion"]=true,["Tirilikalika Tirilikalako"]=true,
    }
    local function getMutPrio(m)
        if not m or m == "" or m == "None" then return 0 end
        if MUTATION_PRIORITY[m] then return MUTATION_PRIORITY[m] end
        local n = tostring(m):lower():gsub("[%s%-_]","")
        if n == "bloodrot" then return 2 end
        if n == "yinyang" or n == "galaxy" or n == "candy" or n == "divine"
            or n == "cursed" or n == "lava" or n == "radioactive" or n == "cyber"
            or n == "rainbow" then return 1 end
        return 0
    end
    local function getCumThreshold(hi, lo)
        if DIRECT_THRESHOLDS[hi] and DIRECT_THRESHOLDS[hi][lo] then return DIRECT_THRESHOLDS[hi][lo] end
        if LOCKED_TIERS[hi] then return math.huge end
        local total = 0
        for t = hi + 1, lo do
            local td = PET_PRIORITY_TIERS[t]
            if td and td.threshold > 0 then total = total + td.threshold end
        end
        return total
    end
    local function petOutranks(aName, bName, aMut, bMut, aMPS, bMPS)
        if aName == "Strawberry Elephant" and bName == "John Pork" then return true end
        if aName == "John Pork" and bName == "Strawberry Elephant" then return false end
        if MUTATED_BEATS_GRIFFIN[aName] and bName == "Griffin" and getMutPrio(aMut) >= 1 then return true end
        if aName == "Griffin" and MUTATED_BEATS_GRIFFIN[bName] and getMutPrio(bMut) >= 1 then return false end
        if aName == "Antonio" and bName == "Elefanto Frigo" and getMutPrio(aMut) >= 1 then return true end
        if aName == "Elefanto Frigo" and bName == "Antonio" and getMutPrio(bMut) >= 1 then return false end
        local tA = TIER_LOOKUP[aName] or 99
        local tB = TIER_LOOKUP[bName] or 99
        if not (TIER_LOOKUP[aName] and TIER_LOOKUP[bName]) then
            if tA == tB then return (aMPS or 0) > (bMPS or 0) end
            return tA < tB
        end
        if tA == tB then
            local pA, pB = getMutPrio(aMut), getMutPrio(bMut)
            if pA ~= pB then return pA > pB end
            return (aMPS or 0) > (bMPS or 0)
        end
        if tA == 4 and tB == 3 then return true end
        if tA == 3 and tB == 4 then return false end
        local hi = math.min(tA, tB)
        local lo = math.max(tA, tB)
        local hiMPS = tA < tB and aMPS or bMPS
        local loMPS = tA < tB and bMPS or aMPS
        local cum = getCumThreshold(hi, lo)
        if cum > 0 and cum ~= math.huge then
            if (loMPS or 0) - (hiMPS or 0) > cum then return tA > tB end
        end
        return tA < tB
    end

    -- ===== Plot/Channel helpers =====
    local function getPlotChannel(plotName)
        if not Synchronizer then return nil end
        local channel
        pcall(function() channel = _G.Skyr0_GetPlotChannel(plotName) end)
        -- NO BLOCKING RETRY HERE. This used to be:
    --     repeat channel=_G.XenSyncGet(plotName) ... task.wait(0.05)
    --     until os.clock()-_t0>3
    --
    -- i.e. up to THREE SECONDS of spinning, PER PLOT, inside the scan loop.
    -- On a server where the channels never register (the scan line reports
    -- sync=0), every plot paid the full three seconds and nothing was ever
    -- found: eight plots = a 24-SECOND teleport, which is exactly what the
    -- timing trace showed. isPlotUnlocked calls this too, which was the
    -- separate ~3s gap before carpetEngage.
    --
    -- The retry was also redundant: XenSyncGet -> _chans() ALREADY retries on
    -- its own rate-limited schedule (with the bounded deep scan), without
    -- yielding. Calling it once per scan gives exactly the same recovery over
    -- time, because the scanners run continuously.
    --
    -- And a missing channel is no longer fatal: the plot scanner falls back to
    -- rendered Models, and the TP scanners fall back to Skyr0CachedSlotsForPlot.
    if not channel then channel = _G.XenSyncGet and _G.XenSyncGet(plotName) or nil end
        return channel
    end
    local function channelGet(channel, key)
        if not channel then return nil end
        local v
        pcall(function() if type(channel.Get) == "function" then v = channel:Get(key) end end)
        if v == nil then pcall(function() v = channel.CacheTable and channel.CacheTable[key] end) end
        return v
    end
    local function isMyPlot(channel)
        if not channel then return false end
        local owner = channelGet(channel, "Owner")
        if not owner then return false end
        local result = false
        pcall(function()
            if typeof(owner) == "Instance" and owner:IsA("Player") then
                result = owner.UserId == LP.UserId
            elseif type(owner) == "table" and owner.UserId then
                result = owner.UserId == LP.UserId
            elseif typeof(owner) == "Instance" then
                result = owner == LP
            -- THREE SHAPES WERE MISSING, and they are exactly the ones that put
            -- your own base back in the target list.
            --
            -- The other copy of this function (the panel scanner's, further up)
            -- already handles a string or a number owner; this one -- the TELEPORT
            -- engine's -- did not, so on any server that reports Owner as a name
            -- or a UserId, scanAllPets kept your own plot and the flight could
            -- pick it. ownerInGame right below already reads `owner.Name`, which
            -- is proof that shape occurs here too.
            elseif type(owner) == "string" then
                result = (owner:lower() == LP.Name:lower() or owner:lower() == LP.DisplayName:lower())
            elseif type(owner) == "number" then
                result = owner == LP.UserId
            elseif type(owner) == "table" and owner.Name then
                local n = tostring(owner.Name):lower()
                result = (n == LP.Name:lower() or n == LP.DisplayName:lower())
            end
        end)
        return result
    end
    local function ownerInGame(channel)
        if not channel then return false end
        local owner = channelGet(channel, "Owner")
        if not owner then return false end
        local inGame = false
        pcall(function()
            if typeof(owner) == "Instance" and owner:IsA("Player") then
                inGame = Players:FindFirstChild(owner.Name) ~= nil
            elseif type(owner) == "number" then
                inGame = Players:GetPlayerByUserId(owner) ~= nil
            elseif type(owner) == "table" and owner.Name then
                inGame = Players:FindFirstChild(tostring(owner.Name)) ~= nil
            elseif typeof(owner) == "Instance" and owner.Name then
                inGame = Players:FindFirstChild(owner.Name) ~= nil
            end
        end)
        return inGame
    end
    -- A first-floor base is only really open when the game says so AND no laser
    -- is physically solid in the way. The channel flag alone said "unlocked" for
    -- a door with lasers still up, and the TP walked into them.
    local function _floor1LaserSolid(plotName)
        local solid = false
        pcall(function()
            local plots = workspace:FindFirstChild("Plots")
            local plot = plots and plots:FindFirstChild(plotName)
            if not plot then return end
            for _, d in ipairs(plot:GetDescendants()) do
                if d:IsA("BasePart") and (d.Name == "LaserHitbox" or d.Name == "Laser")
                   and d.CanCollide and d.Position.Y <= 9 then
                    solid = true
                    break
                end
            end
        end)
        return solid
    end
    local function isPlotUnlocked(plotName)
        local ok, res = pcall(function()
            local channel = getPlotChannel(plotName)
            if not channel then return false end
            if channelGet(channel, "BlockEndTimeFirstFloor") ~= nil then return false end
            return not _floor1LaserSolid(plotName)
        end)
        return ok and (res == true)
    end

    -- ===== Pet position =====
    -- =====================================================================
    -- PODIUM POSITION  --  MEMOISED. THIS IS THE PERIODIC-FREEZE FIX.
    -- ---------------------------------------------------------------------
    -- The body of this used to walk podium:GetDescendants() and then, for every
    -- candidate Model it found, walk THAT model's descendants again hunting for
    -- a MeshPart. GetDescendants ALLOCATES a fresh table holding every
    -- descendant, and a podium with a brainrot on it is 50-300 instances.
    --
    -- scanAllPets calls this once per pet, and the auto-steal Heartbeat calls
    -- scanAllPets ten times a second. On a busy server -- 8 bases, ~8 occupied
    -- podiums each -- that is tens of thousands of instance references
    -- allocated EVERY SECOND, for an answer that does not change: a pet
    -- standing on a podium does not move. Luau's collector pays that bill back
    -- in one visible pause every couple of seconds, which is exactly the
    -- "freezes every ~3 seconds", and only on servers with enough brainrots on
    -- enough bases to generate the garbage. An empty server never stutters.
    --
    -- The memo is keyed by podium and holds the RESOLVED MODEL, not a position:
    --   * the entry is dropped the instant that model stops being a descendant
    --     of the podium (stolen, swapped, streamed out), so a stale coordinate
    --     cannot outlive the pet it belonged to;
    --   * the bounding box is still read live on every call, so nothing that
    --     does move reports an old position;
    --   * an EMPTY podium is remembered too (model = nil) but only for
    --     POS_MEMO_TTL, so a pet arriving is picked up on the next second --
    --     and until it is, the fallback below still returns the podium's own
    --     position, which is what the old code returned for that case anyway.
    -- =====================================================================
    local _posMemo = setmetatable({}, { __mode = "k" })   -- podium -> {model=, at=}
    local POS_MEMO_TTL = 1.0
    local function _resolvePetModel(podium)
        for _, desc in ipairs(podium:GetDescendants()) do
            if desc:IsA("Model") and desc.Name ~= "Claim" and desc.Name ~= "Base" and desc.Name ~= "Decorations" then
                for _, c in ipairs(desc:GetDescendants()) do
                    if c:IsA("MeshPart") then return desc end
                end
            end
        end
        return nil
    end
    local function getPetPosition(plot, slot)
        local podiums = plot:FindFirstChild("AnimalPodiums")
        if not podiums then return nil end
        local podium = podiums:FindFirstChild(tostring(slot))
        if not podium then return nil end

        local memo = _posMemo[podium]
        local model = memo and memo.model
        -- the remembered model has to still BE on this podium
        if model and not model:IsDescendantOf(podium) then model, memo = nil, nil end
        if not model and (not memo or (os.clock() - memo.at) > POS_MEMO_TTL) then
            model = _resolvePetModel(podium)
            _posMemo[podium] = { model = model, at = os.clock() }
        end
        if model then
            -- pcall(f, self) rather than pcall(function() ... end): the closure
            -- form allocated one function object per pet per scan, ~600 a
            -- second on a full server, all of it immediate garbage.
            local ok, cf = pcall(model.GetBoundingBox, model)
            if ok and cf then return cf.Position end
        end
        local ok, cf = pcall(podium.GetPivot, podium)
        if ok and cf then return cf.Position end
        return podium.Position
    end

    -- ===== Fusing check =====
    local _BLOCKING_MACHINE_TYPES = { Fuse=true, Duel=true, Trade=true, Crafting=true }
    local function _Skyr0IsFusing(animalData)
        if type(animalData) ~= "table" then return false end
        local m = animalData.Machine
        if type(m) ~= "table" then return false end
        if _G.Skyr0IsInFuse and _G.Skyr0IsInFuse(animalData) then return true end
        return _BLOCKING_MACHINE_TYPES[m.Type] == true and m.Active == true
    end

    -- ===== Scanner =====
    -- SHORT RESULT CACHE. The auto-steal Heartbeat asks for a full scan TEN
    -- TIMES A SECOND, and every ask rebuilt the whole list -- a fresh table per
    -- pet -- and re-sorted it. Nothing on a podium changes ten times a second,
    -- so a result up to _SCAN_TTL old is the same result, at a tenth of the
    -- garbage.
    --
    -- Callers that must not be even 0.2s behind (the teleport, which decides
    -- where to fly from this) pass force=true and always get a live scan.
    -- Nothing mutates the returned list -- every consumer either reads it or
    -- copies out of it -- so handing the same table to several callers is safe.
    local _scanCache, _scanAt = nil, 0
    local _SCAN_TTL = 0.2
    -- Hoisted out of scanAllPets: a comparator closure and (below) a conveyor
    -- reader that used to be re-created on every scan.
    local function _petSortCmp(a, b)
        return petOutranks(a.name, b.name, a.mutation, b.mutation, a.mps, b.mps)
    end
    -- WALKING CARPET SCAN. Three locals on purpose (this block is close to the
    -- register limit): _convOut is the scanner's state table, _convGen resolves
    -- a name to an AnimalsData index + gen, _scanConveyorModel does the scan.
    --
    -- Two sources, deduped by model:
    --   1. every Model anywhere under RenderedMovingAnimals (not just direct
    --      children -- the walkers are often nested in a holder), matched by
    --      index OR display name, case/space-insensitive. Nested trait/accessory
    --      models inside a walker are skipped.
    --   2. every AnimalPurchasePrompt -- a walking brainrot is by definition
    --      buyable, so its prompt is the most reliable "it is on the carpet"
    --      signal there is. Index comes from the nearest ancestor carrying an
    --      Index attribute, or a model whose name resolves.
    -- A gen of 0 (unresolved) is no longer dropped: Min Gen decides that.
    local _convOut = { map = nil, out = nil, seen = nil }
    local function _convGen(name, mutation)
        if not AnimalsData or type(name) ~= "string" then return nil end
        local idx = AnimalsData[name] and name
        if not idx then
            if not _convOut.map then
                local m = {}
                for k, d in pairs(AnimalsData) do
                    m[(tostring(k):lower():gsub("%s+", ""))] = k
                    if type(d) == "table" and d.DisplayName then
                        m[(tostring(d.DisplayName):lower():gsub("%s+", ""))] = k
                    end
                end
                _convOut.map = m
            end
            idx = _convOut.map[(name:lower():gsub("%s+", ""))]
        end
        if not idx then return nil end
        local gen = 0
        if AnimalsShared then
            local ok, g = pcall(AnimalsShared.GetGeneration, AnimalsShared, idx, mutation, nil, nil)
            gen = (ok and tonumber(g)) or 0
        end
        if gen <= 0 and type(AnimalsData[idx]) == "table" then
            gen = tonumber(AnimalsData[idx].Generation) or 0
        end
        return idx, gen
    end
    local function _scanConveyorModel(pets)
        local st = _convOut
        st.seen = {}
        local function add(model, part, idx, gen, prompt)
            if st.seen[model] then return end
            st.seen[model] = true
            local info = AnimalsData[idx]
            local mut = (model.GetAttribute and model:GetAttribute("Mutation")) or "None"
            pets[#pets + 1] = {
                name = (type(info) == "table" and info.DisplayName) or idx, index = idx,
                mps = gen or 0, mutation = mut, position = part.Position,
                plot = nil, slot = nil, conveyor = true, model = model, prompt = prompt,
            }
        end
        local folder = workspace:FindFirstChild("RenderedMovingAnimals")
        if folder then
            for _, m in ipairs(folder:GetDescendants()) do
                if m:IsA("Model") and not Players:GetPlayerFromCharacter(m) then
                    local idx, gen = _convGen(m.Name, m:GetAttribute("Mutation"))
                    if idx then
                        -- skip a model nested inside another walker
                        local nested, anc = false, m.Parent
                        while anc and anc ~= folder do
                            if anc:IsA("Model") and _convGen(anc.Name) then nested = true; break end
                            anc = anc.Parent
                        end
                        local part = m.PrimaryPart or m:FindFirstChild("HumanoidRootPart", true) or m:FindFirstChildWhichIsA("BasePart", true)
                        if not nested and part then add(m, part, idx, gen, nil) end
                    end
                end
            end
        end
        for _, pr in ipairs(game:GetService("CollectionService"):GetTagged("AnimalPurchasePrompt")) do
            if pr:IsA("ProximityPrompt") and pr.Parent then
                local part = pr.Parent:IsA("Attachment") and pr.Parent.Parent or pr.Parent
                local _plots = workspace:FindFirstChild("Plots")
                if part and part:IsA("BasePart") and not (_plots and part:IsDescendantOf(_plots)) then
                    local idx, gen, holder
                    local m = pr:FindFirstAncestorWhichIsA("Model")
                    while m and not idx do
                        local ia = m:GetAttribute("Index")
                        idx, gen = _convGen(type(ia) == "string" and ia or m.Name, m:GetAttribute("Mutation"))
                        if idx then holder = m else m = m.Parent and m.Parent:FindFirstAncestorWhichIsA("Model") end
                    end
                    -- already listed from the folder walk (same walker, or one
                    -- standing on the prompt's part)?
                    local dup = holder and st.seen[holder]
                    if not dup then
                        for _, p in ipairs(pets) do
                            if p.conveyor and (p.position - part.Position).Magnitude < 8 then
                                p.prompt = p.prompt or pr; dup = true; break
                            end
                        end
                    end
                    if not dup and idx then add(holder or part, part, idx, gen, pr) end
                end
            end
        end
    end
    local function scanAllPets(force)
        -- the cache is only reused while the plots have NOT changed: the plot
        -- scanner bumps SharedState.CacheVersion on every real change, and the
        -- next call rebuilds instead of serving a list from before it
        local _ver = SharedState and SharedState.CacheVersion or 0
        if not force and _scanCache and (os.clock() - _scanAt) < _SCAN_TTL and _G.__Skyr0ScanVer == _ver then
            return _scanCache
        end
        _G.__Skyr0ScanVer = _ver
        local pets = {}
        if not loadModules() then return pets end
        local Plots = workspace:FindFirstChild("Plots")
        if not Plots then return pets end
        for _, plot in ipairs(Plots:GetChildren()) do
            local channel = getPlotChannel(plot.Name)
            -- see the note on the other scanner: neither "no channel" nor
            -- "owner offline" is a reason to skip a base
            -- YOUR OWN BASE, ALWAYS. The channel test only runs when there IS a
        -- channel, and on servers that key channels as PlotN there never is --
        -- which is exactly how your own brainrots ended up as TP targets. The
        -- instant check reads the PlotSign / YourBase billboard instead, so it
        -- answers with or without a channel.
        if (channel and isMyPlot(channel))
            or (_G.Skyr0IsMyPlotCached and _G.Skyr0IsMyPlotCached(plot.Name)) then continue end
            -- a base whose owner just joined: not a target yet
            if channel and _G.Skyr0NoteBaseOwner then pcall(_G.Skyr0NoteBaseOwner, plot.Name, channelGet(channel, "Owner")) end
            if _G.Skyr0IsNewBase and _G.Skyr0IsNewBase(plot.Name) then continue end
            -- server first (see the note on the other scanner); falls back to
            -- the client cache when Synchronizer.RequestData is unavailable
            local animalList = (_G.Skyr0GetAnimalList and _G.Skyr0GetAnimalList(plot.Name, channel))
                            or channelGet(channel, "AnimalList")
                            or (_G.Skyr0CachedSlotsForPlot and _G.Skyr0CachedSlotsForPlot(plot.Name))
            if not animalList then continue end
            for slot, animalData in pairs(animalList) do
                if type(animalData) ~= "table" then continue end
                local animalName = animalData.Index
                if not animalName then continue end
                local animalInfo = AnimalsData and AnimalsData[animalName]
                if not animalInfo then continue end
                if _Skyr0IsFusing(animalData) then continue end
                local mutation = animalData.Mutation or "None"
                -- pcall(method, self, ...) instead of wrapping it in a closure:
                -- the closure form allocated a function object per pet per scan.
                local genValue = 0
                if AnimalsShared then
                    local okg, g = pcall(AnimalsShared.GetGeneration, AnimalsShared, animalName, animalData.Mutation,
                        (_G.Skyr0NormTraits and _G.Skyr0NormTraits(animalData.Traits) or animalData.Traits), nil)
                    if okg then genValue = tonumber(g) or 0 end
                end
                local displayName = (animalInfo and animalInfo.DisplayName) or animalName
                local pos = getPetPosition(plot, slot)
                if pos then
                    pets[#pets + 1] = {
                        name = displayName, index = animalName, mps = genValue,
                        mutation = mutation, position = pos, plot = plot.Name, slot = tostring(slot),
                    }
                end
            end
        end
        -- walking carpet brainrots (see _scanConveyorModel)
        pcall(_scanConveyorModel, pets)
        -- one pet (or none) has nothing to order
        if #pets > 1 then table.sort(pets, _petSortCmp) end
        _scanCache, _scanAt = pets, os.clock()
        return pets
    end

    -- FRESH-ENOUGH READ -- for callers that need current data but do not need a
    -- guaranteed rebuild.
    --
    -- This exists for the teleport. doVelocityTP ran scanAllPets(true) -- an
    -- unconditional full rebuild -- synchronously on the keypress, before it
    -- could do anything else. On a full server that is ~12 plots and ~100 pets,
    -- each pet costing a GetGeneration call and a getPetPosition that ends in
    -- model:GetBoundingBox(), then the whole list re-sorted. That is the hitch
    -- between pressing the key and moving.
    --
    -- And it was almost always redundant work: the auto-steal Heartbeat runs the
    -- same scan TEN TIMES A SECOND, so when you press the key the cache is
    -- typically 0-100ms old. Nothing the teleport reads from a pet -- podium
    -- position, gen, mutation -- changes in 150ms; pets do not move on podiums.
    -- So reuse a genuinely fresh cache and only pay for a live scan when the
    -- cache really is stale (auto-steal off, or the hub just loaded).
    --
    -- force=true is still there and still means "rebuild now" -- the cold-join
    -- poll below uses it, because that one is waiting for data it does NOT have.
    local function scanAllPetsFresh(maxAge)
        if _scanCache and (os.clock() - _scanAt) < (tonumber(maxAge) or 0.15)
           and _G.__Skyr0ScanVer == (SharedState and SharedState.CacheVersion or 0) then
            return _scanCache
        end
        return scanAllPets(true)
    end

    -- ===== Sky coordinates =====
    local UPPER = {
        B = {{coord=Vector3.new(-487.921448,16.850713,-75.768013),facing="NORTH"},{coord=Vector3.new(-332.379730,16.850722,-75.762100),facing="NORTH"},{coord=Vector3.new(-487.134918,16.850713,-18.094154),facing="SOUTH"},{coord=Vector3.new(-316.300171,16.850713,-17.845898),facing="SOUTH"}},
        C = {{coord=Vector3.new(-330.765381,16.850713,31.424425),facing="NORTH"},{coord=Vector3.new(-502.989349,16.850713,31.172430),facing="NORTH"},{coord=Vector3.new(-489.077087,16.850713,89.010147),facing="SOUTH"},{coord=Vector3.new(-330.908936,16.850713,88.930145),facing="SOUTH"}},
        D = {{coord=Vector3.new(-331.264893,16.850713,138.209167),facing="NORTH"},{coord=Vector3.new(-487.935181,16.850713,138.026321),facing="NORTH"},{coord=Vector3.new(-487.774933,16.850713,195.882538),facing="SOUTH"},{coord=Vector3.new(-330.799133,16.850575,196.022354),facing="SOUTH"}},
    }
    local LOWER = {
        B = {{coord=Vector3.new(-335.725586,-3.048217,-74.984589),facing="NORTH"},{coord=Vector3.new(-503.214233,-3.048217,-75.043137),facing="NORTH"},{coord=Vector3.new(-483.619385,-3.718430,-18.844337),facing="SOUTH"},{coord=Vector3.new(-316.147095,-3.048218,-18.818844),facing="SOUTH"}},
        C = {{coord=Vector3.new(-335.985413,-3.048218,32.051426),facing="NORTH"},{coord=Vector3.new(-503.277008,-3.048217,31.956175),facing="NORTH"},{coord=Vector3.new(-483.749390,-3.048218,88.147003),facing="SOUTH"},{coord=Vector3.new(-315.793823,-3.048217,88.163979),facing="SOUTH"}},
        D = {{coord=Vector3.new(-335.476654,-3.048218,139.001083),facing="NORTH"},{coord=Vector3.new(-503.710083,-3.048218,138.989883),facing="NORTH"},{coord=Vector3.new(-315.654938,-3.048218,195.302444),facing="SOUTH"},{coord=Vector3.new(-483.859253,-3.048218,195.269043),facing="SOUTH"}},
    }
    local UPPER_Y_THRESHOLD = 7
    local TALL_PETS = { ["La Secret Combinasion"]=true, ["La Jolly Grande"]=true }
    local TALL_OFFSET = 3
    local BASES_LOW = {
        [1]=Vector3.new(-476.52,-2,220.94),[2]=Vector3.new(-476.52,-2,113.77),
        [3]=Vector3.new(-476.52,-2,6.18),[4]=Vector3.new(-476.52,-2,-101.07),
        [5]=Vector3.new(-342.66,-2,221.45),[6]=Vector3.new(-342.66,-2,113.41),
        [7]=Vector3.new(-342.66,-2,6.25),[8]=Vector3.new(-342.66,-2,-99.73),
    }
    local BASES_HIGH = {
        [1]=Vector3.new(-479.51,18,220.94),[2]=Vector3.new(-479.51,18,113.77),
        [3]=Vector3.new(-479.51,18,6.18),[4]=Vector3.new(-479.51,18,-101.07),
        [5]=Vector3.new(-339.48,18,221.45),[6]=Vector3.new(-339.48,18,113.41),
        [7]=Vector3.new(-339.48,18,6.25),[8]=Vector3.new(-339.48,18,-99.73),
    }
    local FRONT_Y_LOW = -3.048217
    local FRONT_Y_HIGH = 16.850713
    local COLUMN_SPLIT_X = -410
    local FRONT_Z_CLAMP = 18
    local SIDE_NEAR_Z = 45

    local function getClosestBaseIdx(pos)
        local closest, dist = 1, math.huge
        for i = 1, 8 do
            local b = BASES_LOW[i]
            local d = (pos.X - b.X)^2 + (pos.Z - b.Z)^2
            if d < dist then dist = d; closest = i end
        end
        return closest
    end
    local function buildFrontCandidate(idx, isUpper, playerZ)
        local base = isUpper and BASES_HIGH[idx] or BASES_LOW[idx]
        local frontY = isUpper and FRONT_Y_HIGH or FRONT_Y_LOW
        local frontZ = math.clamp(playerZ - base.Z, -FRONT_Z_CLAMP, FRONT_Z_CLAMP) + base.Z
        local coord = Vector3.new(base.X, frontY, frontZ)
        local faceDir = (idx <= 4) and Vector3.new(-1, 0, 0) or Vector3.new(1, 0, 0)
        return coord, faceDir
    end
    local function plotSides(coordTable, idx)
        local base = BASES_LOW[idx]
        local isWest = idx <= 4
        local out = {}
        for _, coords in pairs(coordTable) do
            for _, data in ipairs(coords) do
                if ((data.coord.X < COLUMN_SPLIT_X) == isWest)
                   and math.abs(data.coord.Z - base.Z) < SIDE_NEAR_Z then
                    out[#out + 1] = data
                end
            end
        end
        return out
    end
    -- =====================================================================
    -- ONE CLONE SPOT -- FRONT *or* SIDE, NEVER BOTH
    -- ---------------------------------------------------------------------
    -- A base can be entered from its FRONT lane or from a SIDE pad. The hook
    -- (Skyr0CicloTP) and the flight (doVelocityTP) each decided which, on their
    -- own, at different moments and from different data -- the hook aimed at the
    -- base's centre, the flight then picked front/side from wherever the pull
    -- had left you -- so the two could head for different spots and the TP
    -- looked like it was doing a side clone and a front clone at once.
    --
    -- This is the ONE place that decides. It measures every candidate (the
    -- front spot and each side pad of that base) from `fromPos`, keeps the
    -- CLOSEST, and returns it. The cycle calls it before the hook and stashes
    -- the answer in _G.Skyr0TPCloneSpot; doVelocityTP takes that stash instead
    -- of deciding again. Ties go to the front.
    -- =====================================================================
    local function coordTableFor(petPos, petName)
        local adjY = petPos.Y
        if TALL_PETS[petName] then adjY = adjY - TALL_OFFSET end
        local f2 = _G.Skyr0IsF2FromF1 and _G.Skyr0IsF2FromF1(petPos.Y) or false
        if f2 then adjY = math.min(adjY, UPPER_Y_THRESHOLD) end
        return adjY > UPPER_Y_THRESHOLD and UPPER or LOWER
    end
    local function pickCloneSpot(petPos, petName, fromPos)
        local _S = _G.Skyr0Spots
        if _S then
            local _c = _S.candidates(petPos, petName, fromPos)
            if _c[1] then return _c[1].coord, _c[1].face, _c[1].kind end
        end
        local coordTable = coordTableFor(petPos, petName)
        local isUpper = (coordTable == UPPER)
        local idx = getClosestBaseIdx(petPos)
        local frontCoord, frontFace = buildFrontCandidate(idx, isUpper, fromPos.Z)
        local bestCoord, bestFace, kind = frontCoord, frontFace, "front"
        local bestDist = (fromPos - frontCoord).Magnitude
        for _, d in ipairs(plotSides(coordTable, idx)) do
            local dd = (fromPos - d.coord).Magnitude
            if dd < bestDist then
                bestDist = dd
                bestCoord = d.coord
                bestFace = d.facing == "NORTH" and Vector3.new(0, 0, -1) or Vector3.new(0, 0, 1)
                kind = "side"
            end
        end
        return bestCoord, bestFace, kind
    end
    _G.Skyr0PickCloneSpot = pickCloneSpot

    local function findClosest(petPos, coordTable)
        local best, bestKey, bestDist = nil, nil, math.huge
        for skyKey, coords in pairs(coordTable) do
            for _, data in ipairs(coords) do
                local c = data.coord
                local d = math.sqrt((petPos.X - c.X)^2 + (petPos.Z - c.Z)^2)
                if d < bestDist then bestDist = d; best = data; bestKey = skyKey end
            end
        end
        return best, bestKey
    end

    -- ===== Viz =====
    local _vizParts = {}
    local function clearViz()
        for _, p in ipairs(_vizParts) do if p and p.Parent then p:Destroy() end end
        table.clear(_vizParts)
    end
    local function vizPath(fromPos, waypoints)
        -- Pathfinder lines/dots disabled (user request: no lines).
        return
    end

    -- ===== Movement =====
    local SPEED = 200
    local ARRIVE = 3
    local MAX_CLIMB = 60
    -- routing helpers the mover needs (filled in by ROUTING v2 below): MV.clear
    -- is the planner's own clearance test, used to pick a clear sidestep
    local MV = {}

    -- =====================================================================
    -- CLONE SPOTS -- FRONT, LEFT and RIGHT, best first
    -- ---------------------------------------------------------------------
    -- A base can be cloned from its FRONT lane (by the sign) or from either SIDE
    -- pad -- the LEFT and the RIGHT one, as seen standing at the front. The
    -- CLOSEST one to where you are ALWAYS wins (a tie goes to the front). The only
    -- thing that ever overrules that is a spot that got you STUCK earlier in this
    -- same TP: the flight marks it bad and takes the next-closest instead.
    -- (End bases only have the ONE side pad in the coordinate tables: the other
    -- side is the edge of the map.)
    -- =====================================================================
    MV.spots = (function()
        local S = {}
        _G.Skyr0BadSpots = _G.Skyr0BadSpots or {}
        function S.key(c)
            return string.format("%d,%d,%d", math.floor(c.X + 0.5), math.floor(c.Y + 0.5), math.floor(c.Z + 0.5))
        end
        function S.markBad(c) _G.Skyr0BadSpots[S.key(c)] = os.clock() end
        function S.isBad(c)
            local at = _G.Skyr0BadSpots[S.key(c)]
            return at ~= nil and (os.clock() - at) < (tonumber(_G.Skyr0TpBadSpotTTL) or 90)
        end
        -- right = facing x up. The west column's front faces -X (right = -Z), the
        -- east column's faces +X (right = +Z).
        function S.label(idx, dz)
            if math.abs(dz) < 0.5 then return "side" end
            local rightIsPlusZ = idx > 4
            return ((dz > 0) == rightIsPlusZ) and "right" or "left"
        end
        function S.candidates(petPos, petName, fromPos, coordTable)
            coordTable = coordTable or coordTableFor(petPos, petName)
            local isUpper = (coordTable == UPPER)
            local idx = getClosestBaseIdx(petPos)
            local base = BASES_LOW[idx]
            local frontCoord, frontFace = buildFrontCandidate(idx, isUpper, fromPos.Z)
            local list = { { coord = frontCoord, face = frontFace, kind = "front" } }
            for _, d in ipairs(plotSides(coordTable, idx)) do
                list[#list + 1] = {
                    coord = d.coord,
                    face = (d.facing == "NORTH") and Vector3.new(0, 0, -1) or Vector3.new(0, 0, 1),
                    kind = S.label(idx, d.coord.Z - base.Z),
                }
            end
            for _, c in ipairs(list) do
                c.score = (fromPos - c.coord).Magnitude
                if S.isBad(c.coord) then c.score = c.score + 20000 end
            end
            table.sort(list, function(a, b)
                if a.score ~= b.score then return a.score < b.score end
                return a.kind == "front" and b.kind ~= "front"
            end)
            return list, idx
        end
        return S
    end)()
    _G.Skyr0Spots = MV.spots

    local function vZero(hrp)
        if hrp then hrp.AssemblyLinearVelocity = Vector3.zero; hrp.AssemblyAngularVelocity = Vector3.zero end
    end

    -- =====================================================================
    -- AUTO-JUMP  (one helper for the flight AND the after-landing hops)
    -- ---------------------------------------------------------------------
    -- Two kinds of jump lived in this engine and both were wrong in the same
    -- way: they wrote Humanoid.Jump = true on a blind 0.1s timer, for 5-8
    -- SECONDS, whether or not the character was on the ground. Jump=true while
    -- already airborne just queues the next jump for the instant you land, so
    -- the character bounced in place -- "spam jump" -- and with the carpet still
    -- equipped it hung in the air on top of it -- "float".
    --
    -- Now a jump is issued only when the humanoid is actually able to jump:
    -- not Jumping, not Freefall, not Seated, not dead. That is what makes the jumps line up with landings.
    -- =====================================================================
    -- (The auto-jump helpers that used to live here are GONE: jumping during the
    -- flight could leave the character airborne at the clone pad, and the clone
    -- step anchors the root -- so it cloned differently and hung in the air.)
    -- Take the carpet off (it is a hover tool: while it is in hand, jumping does
    -- nothing useful and the character stays floating).
    local function dropCarpet()
        if _G.Skyr0KeepCarpet then return end
        local c = LP.Character
        local hum = c and c:FindFirstChildOfClass("Humanoid")
        if not c or not hum then return end
        for _, n in ipairs(CARPET_NAMES) do
            local t = c:FindFirstChild(n)
            if t and t:IsA("Tool") then pcall(function() hum:UnequipTools() end); return end
        end
    end
    -- After the TP: no velocity left over, no stuck jump flag, no hover tool.
    local function settleAfterTP()
        local c = LP.Character
        local hrp = c and c:FindFirstChild("HumanoidRootPart")
        local hum = c and c:FindFirstChildOfClass("Humanoid")
        if hrp then vZero(hrp) end
        if hum then
            pcall(function() hum.Jump = false end)
            pcall(function() hum.PlatformStand = false end)
        end
        if not (Config and Config.TpSettings and Config.TpSettings.BrainrotCarpet) then dropCarpet() end
    end

    local function velMoveThrough(hrp, waypoints, speedOverride, allowJump, quickStart)
        if not hrp or not hrp.Parent or #waypoints == 0 then return end
        local _runSpeed = speedOverride or Skyr0Speed.CARPET
        vizPath(hrp.Position, waypoints)
        local wpIdx = 1
        local done = false
        local conn
        local function finish()
            if done then return end
            done = true
            if hrp and hrp.Parent then
                hrp.AssemblyLinearVelocity = Vector3.zero
                hrp.AssemblyAngularVelocity = Vector3.zero
                -- Snap onto the last waypoint ONLY when we actually got there
                -- (within 12 studs). A flight that stalled or was rejected far
                -- from the end used to be snapped across the map anyway -- an
                -- illegal move the server answers with a lagback.
                local _last = waypoints[#waypoints]
                if (hrp.Position - _last).Magnitude <= 12 then
                    local _, y = hrp.CFrame:ToEulerAnglesYXZ()
                    hrp.CFrame = CFrame.new(_last) * CFrame.Angles(0, y, 0)
                end
                -- a jump queued by the last frame would carry straight on into
                -- the landing -- clear it so the flight ends standing still
                local _hh = hrp.Parent and hrp.Parent:FindFirstChildOfClass("Humanoid")
                if _hh then pcall(function() _hh.Jump = false end) end
            end
            if conn then conn:Disconnect() end
            clearViz()
        end
        local lastDist, stall = math.huge, 0
        -- anti-lagback state
        local lastPos, lagRecover, lagUntil = hrp.Position, 0, 0
        local stallStart = 0
        local unstick = 0
        local MAX_RECOVER = 3
        -- The 3 x 20-stud CFrame hops at the start are OFF by default now: 20
        -- studs in one frame is ~1200 studs/s, which the server reads as a
        -- speed hack and rolls back. _G.Skyr0QuickStart = true brings them back.
        if quickStart and _G.Skyr0QuickStart == true then
            local _hp = RaycastParams.new()
            _hp.FilterType = Enum.RaycastFilterType.Exclude
            _hp.IgnoreWater = true
            local _skip = {}
            for _, pl in ipairs(Players:GetPlayers()) do
                if pl.Character then _skip[#_skip + 1] = pl.Character end
            end
            _hp.FilterDescendantsInstances = _skip
            for _ = 1, 3 do
                local target = waypoints[wpIdx]
                if not target then break end
                local flat = Vector3.new(target.X - hrp.Position.X, 0, target.Z - hrp.Position.Z)
                local mag = flat.Magnitude
                if mag < 1 then break end
                local nextPos = hrp.Position + flat.Unit * math.min(20, mag)
                local _hit = workspace:Raycast(hrp.Position, nextPos - hrp.Position, _hp)
                if _hit and _hit.Instance and _hit.Instance.CanCollide then break end
                hrp.CFrame = (hrp.CFrame - hrp.CFrame.Position) + nextPos
                hrp.AssemblyLinearVelocity = Vector3.zero
                hrp.AssemblyAngularVelocity = Vector3.zero
                RunService.Heartbeat:Wait()
                if not hrp or not hrp.Parent then return end
            end
        end
        conn = RunService.Heartbeat:Connect(function(dt)
            dt = dt or (1 / 60)
            if not hrp or not hrp.Parent or done then
                if conn then conn:Disconnect() end; return
            end
            equipCarpet()
            local target = waypoints[wpIdx]
            local diff = target - hrp.Position
            local mag = diff.Magnitude
            if mag < ARRIVE then
                wpIdx = wpIdx + 1
                if wpIdx > #waypoints then finish(); return end
                lastDist, stall = math.huge, 0
                target = waypoints[wpIdx]
                diff = target - hrp.Position
                mag = diff.Magnitude
            end
            -- ---- lagback detection ----
            -- The server put us somewhere we did not drive to. Past what one frame at
            -- our own speed could cover AND moving away from the target is a rejection;
            -- either condition alone is just a bounce off geometry.
            local moved = (hrp.Position - lastPos).Magnitude
            local _png = (_G.Skyr0Ping and _G.Skyr0Ping()) or 0.1
            -- The correction covers everything the server thinks you did during one
            -- round trip, so the "could we have moved this far" budget has to include
            -- it -- otherwise ordinary high-ping catch-up reads as a lagback and
            -- cancels a flight that was going fine.
            local budget = _runSpeed * (math.max(dt, 1 / 240) * 2 + _png) + 6
            if moved > budget and mag > lastDist + 4 then
                lastPos = hrp.Position
                if lagRecover < MAX_RECOVER then
                    lagRecover = lagRecover + 1
                    -- Stop pushing and let it settle. Driving into a rejection just gets
                    -- rejected again, and finish()'s snap to the last waypoint is that
                    -- same illegal move one more time.
                    hrp.AssemblyLinearVelocity = Vector3.zero
                    hrp.Velocity = Vector3.zero
                    -- Settle for a full round trip plus a margin. A fixed 0.35s is shorter
                    -- than the correction takes to even arrive on a 300ms connection, so the
                    -- old code resumed straight back into the rejection and burnt all three
                    -- recoveries inside half a second.
                    lagUntil = os.clock() + math.clamp(_png * 2 + 0.2, 0.35, 1.5)
                    lastDist, stall, stallStart = math.huge, 0, 0
                    return
                end
                -- out of recoveries: end where the server actually has us
                finish(); return
            end
            lastPos = hrp.Position
            -- hold off while a recovery settles, then resume from wherever the server
            -- left us, re-aimed at the same waypoint
            if os.clock() < lagUntil then
                hrp.AssemblyLinearVelocity = Vector3.zero
                return
            end
            -- ---- stall detector, on a clock rather than a frame count ----
            if mag > lastDist - 0.05 then
                if stallStart == 0 then stallStart = os.clock() end
            else
                stallStart = 0
            end
            lastDist = mag
            -- Same reason: a high-ping server can hold you still for most of a round
            -- trip while it catches up, and that is not being stuck.
            if stallStart ~= 0 and (os.clock() - stallStart) > (0.45 + _png * 2) then
                -- STUCK (a wall, usually). Before giving up, sidestep: drop a
                -- waypoint 18 studs to whichever side is clear (or 16 studs up),
                -- fly there, then carry on to the target. Twice per leg at most;
                -- after that the leg ends and the flight sequence re-plans the
                -- whole route from where we are.
                if unstick < 2 and MV.clear then
                    unstick = unstick + 1
                    local flat = Vector3.new(diff.X, 0, diff.Z)
                    if flat.Magnitude > 0.1 then
                        local perp = Vector3.new(-flat.Z, 0, flat.X).Unit
                        local here = hrp.Position
                        local pick
                        for _, off in ipairs({ perp * 18, perp * -18, Vector3.new(0, 16, 0),
                                               perp * 18 + Vector3.new(0, 10, 0),
                                               perp * -18 + Vector3.new(0, 10, 0) }) do
                            if MV.clear(here, here + off) then pick = here + off; break end
                        end
                        if pick then
                            table.insert(waypoints, wpIdx, pick)
                            lastDist, stall, stallStart = math.huge, 0, 0
                            return
                        end
                    end
                end
                finish(); return
            end
            if mag >= 0.1 then
                local dir = diff.Unit
                if allowJump and diff.Y > 5 and wpIdx < #waypoints then
                    local hum = hrp.Parent and hrp.Parent:FindFirstChildOfClass("Humanoid")
                    if hum then
                        local st = hum:GetState()
                        if st ~= Enum.HumanoidStateType.Jumping and st ~= Enum.HumanoidStateType.Freefall then
                            pcall(function() hum:ChangeState(Enum.HumanoidStateType.Jumping) end)
                            pcall(function() hum.Jump = true end)
                        end
                    end
                end
                local _vy = dir.Y * _runSpeed
                if _vy > MAX_CLIMB then _vy = MAX_CLIMB end
                hrp.Velocity = Vector3.new(dir.X * _runSpeed, _vy, dir.Z * _runSpeed)
            end
        end)
        local totalDist = 0
        local prev = hrp.Position
        for _, wp in ipairs(waypoints) do totalDist = totalDist + (prev - wp).Magnitude; prev = wp end
        -- + the recovery budget: a flight that had to sit out three lagbacks
        -- was still held to the no-lagback timeout and cut off mid-route.
        local timeout = totalDist / math.min(SPEED, _runSpeed) + 2
            + 3 * math.clamp(((_G.Skyr0Ping and _G.Skyr0Ping()) or 0.1) * 2 + 0.2, 0.35, 1.5)
        local elapsed = 0
        while not done and elapsed < timeout do task.wait(0.05); elapsed = elapsed + 0.05 end
        finish()
        vZero(hrp)
    end

    -- ===== Routing =====
    local _DIRS = { Vector3.new(1,0,0), Vector3.new(-1,0,0), Vector3.new(0,0,1), Vector3.new(0,0,-1) }
    local _STRUCT = { ["structure base home"]=true, ["Wall"]=true, ["Floor"]=true, ["Roof"]=true }
    local _SKIP_NAME = { ["DeliveryHitbox"]=true, ["StealHitbox"]=true, ["LaserHitbox"]=true,
        ["AnimalTarget"]=true, ["Multiplier"]=true, ["Laser"]=true, ["Hitbox"]=true,
        ["Spawn"]=true, ["MainRoot"]=true, ["SecondFloor"]=true, ["ThirdFloor"]=true, ["Slope"]=true,
        -- pads other players' scripts drop under themselves (clone pads, temp
        -- platforms): they are somebody standing there, not a wall
        ["Skyr0ClonePlatform"]=true, ["Skyr0TempPlatform"]=true, ["ANGVELSTempPlatform"]=true,
        ["XiTempPlatform"]=true, ["Skyr0TPClonePlatform"]=true }
    local function _blocks(inst)
        if not inst then return false end
        if _SKIP_NAME[inst.Name] then return false end
        if inst.CanCollide then return true end
        if _STRUCT[inst.Name] then return true end
        local s = inst.Size
        if s and math.max(s.X * s.Y, s.X * s.Z, s.Y * s.Z) > 150 then return true end
        return false
    end
    local function _blocksWide(inst)
        if not inst then return false end
        if _SKIP_NAME[inst.Name] then return false end
        if inst.CanCollide then return true end
        if _STRUCT[inst.Name] then return true end
        local s = inst.Size
        if s and math.max(s.X * s.Y, s.X * s.Z, s.Y * s.Z) > 30 then return true end
        return false
    end
    -- ONE RaycastParams, ONE cached player-skip list, and AddToFilter instead of
    -- a whole-array reassignment per bounce.
    --
    -- This is the single hottest function on the teleport path, and it rebuilt
    -- its entire world on EVERY call: a fresh RaycastParams, a full
    -- Players:GetPlayers() walk to collect characters, and then -- inside a loop
    -- that runs up to 16 times -- a reassignment of FilterDescendantsInstances,
    -- which revalidates the whole instance array each time. So one _clear() cost
    -- up to 16 raycasts AND 16 array revalidations AND a player scan.
    --
    -- Multiply that by the callers: _clearWide is FIVE _blocks, and _pullWide
    -- called it in an O(N^2) loop. That burst is the freeze right before the TP.
    local _rp = RaycastParams.new()
    _rp.FilterType = Enum.RaycastFilterType.Exclude
    _rp.IgnoreWater = true
    local _charSkip, _charSkipAt = {}, 0
    local function _charList()
        -- 1s TTL instead of per-raycast: someone spawning mid-solve is not a
        -- correctness concern for a path that takes milliseconds to compute.
        if _charSkipAt ~= 0 and (os.clock() - _charSkipAt) < 1 then return _charSkip end
        local t = {}
        for _, pl in ipairs(Players:GetPlayers()) do if pl.Character then t[#t + 1] = pl.Character end end
        _charSkip, _charSkipAt = t, os.clock()
        return t
    end
    -- AddToFilter appends without revalidating the array. Probed once; the
    -- copy-and-reassign path below is the fallback for older clients.
    local _hasAddToFilter = pcall(function() return RaycastParams.new().AddToFilter end)
    local function _block(origin, target, blockFn)
        blockFn = blockFn or _blocks
        local skip = _charList()
        -- Resets the shared params for this call (and drops whatever the last
        -- call appended). The cached list itself is never mutated -- growing it
        -- would poison the cache -- so a copy is made only if we actually bounce
        -- and AddToFilter is unavailable.
        _rp.FilterDescendantsInstances = skip
        local grown = nil
        local o = origin
        for _ = 1, 16 do
            local d = target - o; if d.Magnitude < 0.05 then return nil end
            local res = workspace:Raycast(o, d, _rp)
            if not res then return nil end
            if blockFn(res.Instance) then return res end
            if _hasAddToFilter then
                _rp:AddToFilter(res.Instance)
            else
                if not grown then
                    grown = table.create and table.create(#skip + 4) or {}
                    table.move(skip, 1, #skip, 1, grown)
                end
                grown[#grown + 1] = res.Instance
                _rp.FilterDescendantsInstances = grown
            end
            o = res.Position + d.Unit * 0.3
        end
        return nil
    end
    local function _clear(a, b) return _block(a, b) == nil end
    local function _clearDist(origin, dir, maxD)
        local res = _block(origin, origin + dir.Unit * maxD)
        if not res then return maxD end
        return (res.Position - origin).Magnitude
    end
    local function _pull(pts)
        if #pts <= 2 then return pts end
        local out = { pts[1] }; local i = 1
        while i < #pts do
            local j = #pts
            while j > i + 1 and not _clear(out[#out], pts[j]) do j = j - 1 end
            out[#out + 1] = pts[j]; i = j
        end
        return out
    end
    local function _clearWideRay(a, b) return _block(a, b, _blocksWide) == nil end
    local function _clearWide(a, b)
        if not _clear(a, b) then return false end
        local d = Vector3.new(b.X - a.X, 0, b.Z - a.Z)
        if d.Magnitude < 0.1 then return true end
        local _CLEARANCE = 10
        local perp = Vector3.new(-d.Z, 0, d.X).Unit * _CLEARANCE
        local up = Vector3.new(0, _CLEARANCE, 0)
        return _clearWideRay(a + perp, b + perp) and _clearWideRay(a - perp, b - perp)
            and _clearWideRay(a + up, b + up) and _clearWideRay(a - up, b - up)
    end
    -- BOUNDED SMOOTHING.
    --
    -- The old loop scanned backwards from the END of the route for every point
    -- it kept -- O(N^2) calls to _clearWide, and _clearWide is FIVE _blocks of
    -- up to 16 raycasts each. On a 20-waypoint route that is tens of thousands
    -- of raycasts in ONE frame, with nothing yielding in between. That is the
    -- freeze immediately before the teleport.
    --
    -- Two bounds. The LOOKAHEAD cap costs almost nothing in route quality: a
    -- shortcut worth taking is nearly always a few waypoints ahead, not twenty,
    -- and the only penalty for missing one is a route with an extra corner in
    -- it. The DEADLINE is the hard guarantee -- whatever the map geometry does,
    -- past the budget the pass stops refining and hands back what it has, which
    -- is still a perfectly flyable path.
    local _PULL_LOOKAHEAD = 6
    local function _pullWide(pts, deadline)
        if #pts <= 2 then return pts end
        local out = { pts[1] }; local i = 1
        while i < #pts do
            if deadline and os.clock() > deadline then
                for k = i + 1, #pts do out[#out + 1] = pts[k] end
                return out
            end
            local j = math.min(#pts, i + _PULL_LOOKAHEAD)
            while j > i + 1 and not _clearWide(out[#out], pts[j]) do j = j - 1 end
            out[#out + 1] = pts[j]; i = j
        end
        return out
    end
    -- Linear in the waypoint count (4 _blocks each), so far less dangerous than
    -- _pullWide -- but it shares the same budget so a pathological route cannot
    -- spend it all here and leave nothing for the caller.
    local function _pushOffWalls(pts, deadline)
        if #pts <= 2 then return pts end
        local MARGIN = 10; local MAX_PUSH = 14
        local out = { pts[1] }
        for i = 2, #pts - 1 do
            if deadline and os.clock() > deadline then
                for k = i, #pts do out[#out + 1] = pts[k] end
                return out
            end
            local p = pts[i]; local shift = Vector3.zero
            for _, dr in ipairs(_DIRS) do
                local res = _block(p, p + dr * MARGIN, _blocks)
                if res then
                    local dist = (res.Position - p).Magnitude
                    if dist < MARGIN then shift = shift - dr * (MARGIN - dist) end
                end
            end
            if shift.Magnitude > 0.1 then
                if shift.Magnitude > MAX_PUSH then shift = shift.Unit * MAX_PUSH end
                local moved = p + shift
                if _clear(out[#out], moved) then out[#out + 1] = moved else out[#out + 1] = p end
            else
                out[#out + 1] = p
            end
        end
        out[#out + 1] = pts[#pts]
        return out
    end
    local PathfindingService = game:GetService("PathfindingService")
    -- (the previous, simpler router; superseded by ROUTING v2 below and unused)
    function MV.legacyRoute(fromPos, toPos, facingDir)
        if _clear(fromPos, toPos) then return { toPos } end
        local entry = facingDir and (toPos - facingDir * 14) or toPos
        local groundTo = Vector3.new(entry.X, fromPos.Y, entry.Z)
        local path = PathfindingService:CreatePath({
            AgentRadius = 12, AgentHeight = 5, AgentCanJump = true, AgentJumpHeight = 10, AgentMaxSlope = 89,
        })
        local FLOAT = 3
        local nav = { fromPos }
        local ok = pcall(function()
            path:ComputeAsync(Vector3.new(fromPos.X, fromPos.Y, fromPos.Z), groundTo)
        end)
        if ok and path.Status == Enum.PathStatus.Success then
            local last = fromPos
            for _, wp in ipairs(path:GetWaypoints()) do
                if (wp.Position - last).Magnitude >= 8 then
                    nav[#nav + 1] = wp.Position + Vector3.new(0, FLOAT, 0); last = wp.Position
                end
            end
        end
        nav[#nav + 1] = entry + Vector3.new(0, FLOAT, 0)
        -- HARD BUDGET for the two smoothing passes, shared between them.
        --
        -- Whatever geometry the map throws at these, the raycasting cannot cost
        -- more than this before they bail and return what they have. Both passes
        -- degrade gracefully: an unsmoothed route just has more corners in it,
        -- and velMoveThrough flies whatever it is given.
        --
        -- ~30ms is about two frames -- noticeable if you look for it, nowhere
        -- near the multi-second stall the unbounded version could produce.
        -- _G.Skyr0RouteBudget overrides it.
        local deadline = os.clock() + (tonumber(_G.Skyr0RouteBudget) or 0.03)
        nav = _pushOffWalls(nav, deadline)
        local route = _pullWide(nav, deadline)
        route[#route + 1] = toPos
        return route
    end
    -- =====================================================================
    -- ROUTING v2
    -- ---------------------------------------------------------------------
    -- WRAP AROUND EVERYTHING, EXCEPT THE TARGET PLOT.
    --
    -- Every collidable part -- other bases, walls, floors, roofs, props -- is
    -- solid to the route planner and is given a wide berth (a sphere sweep of
    -- radius 4, plus side/vertical rays 16 studs out). The ONE thing left out
    -- of the blocking checks is the plot the destination sits in: the clone spot
    -- is right at its wall, so counting that plot as an obstacle made the planner
    -- refuse or detour the final approach (and the flight then nosed into the
    -- wall). _G.Skyr0WrapTargetPlotOnly = false makes the target plot solid too.
    --
    -- Planner order (first that works):
    --   1. a wide-clear straight line
    --   2. a local hop over the centre block (when only that blocks the line)
    --   3. a lane around the rows of bases in between
    --   4. an optional crest route (_G.Skyr0CrestRoute = true)
    --   5. a 3D voxel A* (4-stud cells, inflated 2.5, 5 tall) -- time-sliced so
    --      it never freezes a frame, hard-capped at _G.Skyr0VoxelBudget (1.5s)
    --   6. candidate detours + Roblox pathfinding, pushed off walls and smoothed
    -- Everything is skipped through a sphere-swept, both-directions clearance
    -- check, so a route that squeezes past a corner is rejected, not flown.
    -- =====================================================================
    -- The whole planner lives inside ONE function (called immediately) so its
    -- ~100 locals sit in that function's own register file: declared in this
    -- scope directly they overflowed Lua's 200-local limit ("out of local
    -- registers"). Only `computeRoute` itself is visible outside.
    local computeRoute
    computeRoute = (function()
        local _OBST_PARENT = { ObstacleVolumes = true, ObstacleVolume = true }
        local function _blk(inst)
            if not inst then return false end
            if _SKIP_NAME[inst.Name] then return false end
            if inst.CanCollide then return true end
            local par = inst.Parent
            if par and _OBST_PARENT[par.Name] then return false end
            if _STRUCT[inst.Name] then return true end
            local s = inst.Size
            if s and math.max(s.X * s.Y, s.X * s.Z, s.Y * s.Z) > 150 then return true end
            return false
        end
        local function _blkWide(inst)
            if not inst then return false end
            if _SKIP_NAME[inst.Name] then return false end
            if inst.CanCollide then return true end
            local par = inst.Parent
            if par and _OBST_PARENT[par.Name] then return false end
            if _STRUCT[inst.Name] then return true end
            local s = inst.Size
            if s and math.max(s.X * s.Y, s.X * s.Z, s.Y * s.Z) > 30 then return true end
            return false
        end

        -- everything the raycasts must look straight through: every player's
        -- character, other players' clones, and (unless disabled) the TARGET PLOT
        local _skip = {}
        -- Another player's CLONE body: "<userid>_Clone", or any Model with
        -- "lone" in its name that has a Humanoid + root and is nobody's character.
        -- Exported: the no-collision module at the end of the file uses the same test.
        local function _otherClone(c)
            local n = c.Name
            if n == tostring(LP.UserId) .. "_Clone" then return false end
            if n:match("^%d+_Clone$") then return true end
            if not c:IsA("Model") or not n:find("lone", 1, true) or c == LP.Character then return false end
            if not (c:FindFirstChild("HumanoidRootPart") and c:FindFirstChildOfClass("Humanoid")) then return false end
            for _, pl in ipairs(Players:GetPlayers()) do
                if pl.Character == c then return false end
            end
            return true
        end
        _G.Skyr0IsOtherClone = _otherClone
        local function _rebuildSkip(toPos, fromPos)
            local t = {}
            for _, pl in ipairs(Players:GetPlayers()) do
                if pl.Character then t[#t + 1] = pl.Character end
            end
            for _, c in ipairs(workspace:GetChildren()) do
                if _otherClone(c) then t[#t + 1] = c end
            end
            if toPos and _G.Skyr0WrapTargetPlotOnly ~= false then
                local plots = workspace:FindFirstChild("Plots")
                if plots then
                    -- NEVER YOUR OWN BASE, NEVER THE ONE YOU ARE STANDING IN.
                    -- "Nearest pivot to the destination" is a coin flip for a side
                    -- clone spot facing your own base, and when it landed on yours
                    -- every wall of your base went invisible to the planner -- the
                    -- route left your base straight through its walls.
                    local under = fromPos and _G.Skyr0PlotUnderMe and _G.Skyr0PlotUnderMe(fromPos)
                    local best, bd = nil, math.huge
                    for _, p in ipairs(plots:GetChildren()) do
                        if p.Name ~= under
                           and not (_G.Skyr0IsMyPlotCached and _G.Skyr0IsMyPlotCached(p.Name)) then
                            local ok, pv = pcall(p.GetPivot, p)
                            if ok and pv then
                                local dx, dz = pv.Position.X - toPos.X, pv.Position.Z - toPos.Z
                                local d = math.sqrt(dx * dx + dz * dz)
                                if d < bd then bd, best = d, p end
                            end
                        end
                    end
                    if best and bd <= (tonumber(_G.Skyr0TargetPlotRange) or 90) then t[#t + 1] = best end
                end
            end
            _skip = t
        end

        local _rp2 = RaycastParams.new()
        _rp2.FilterType = Enum.RaycastFilterType.Exclude
        _rp2.IgnoreWater = true
        local function _block(origin, target, blockFn)
            blockFn = blockFn or _blk
            _rp2.FilterDescendantsInstances = _skip
            local grown = nil
            local o = origin
            for _ = 1, 16 do
                local d = target - o
                if d.Magnitude < 0.05 then return nil end
                local res = workspace:Raycast(o, d, _rp2)
                if not res then return nil end
                if blockFn(res.Instance) then return res end
                if _hasAddToFilter then
                    _rp2:AddToFilter(res.Instance)
                else
                    if not grown then grown = table.move(_skip, 1, #_skip, 1, {}) end
                    grown[#grown + 1] = res.Instance
                    _rp2.FilterDescendantsInstances = grown
                end
                o = res.Position + d.Unit * 0.3
            end
            return nil
        end
        local function _clear(a, b) return _block(a, b) == nil end
        MV.clear = _clear     -- the mover's unstick step uses the same clearance test
        local function _lenOf(pts)
            local s, prev = 0, pts[1]
            for k = 2, #pts do s = s + (pts[k] - prev).Magnitude; prev = pts[k] end
            return s
        end

        local _CLEARANCE = 16
        local _SWEEP_R = 4
        local _ENDPOINT_SLACK = 6
        local _canSphere = nil
        local function _clearWideRay(a, b) return _block(a, b, _blkWide) == nil end
        local function _sweepBlockFn(inst)
            if _G.Skyr0StrictSweep == false then return _blk(inst) end
            return _blkWide(inst)
        end
        local function _sweepDir(a, b)
            local rp = RaycastParams.new()
            rp.FilterType = Enum.RaycastFilterType.Exclude
            rp.IgnoreWater = true
            local skip = table.move(_skip, 1, #_skip, 1, {})
            local o = a
            for _ = 1, 24 do
                rp.FilterDescendantsInstances = skip
                local d = b - o
                if d.Magnitude < 0.05 then return false end
                local res
                local ok = pcall(function() res = workspace:Spherecast(o, _SWEEP_R, d, rp) end)
                if not ok then _canSphere = false; return nil end
                if not res then return false end
                if _sweepBlockFn(res.Instance) then return true end
                skip[#skip + 1] = res.Instance
                local adv = (res.Distance or 0) - 0.05
                if adv > 0 then o = o + d.Unit * math.min(adv, d.Magnitude) end
            end
            return true
        end
        local function _sweepBlocked(a, b, slackA, slackB)
            if _canSphere == nil then
                _canSphere = pcall(function()
                    workspace:Spherecast(Vector3.new(0, 10000, 0), 1, Vector3.new(0, -1, 0), RaycastParams.new())
                end)
            end
            if not _canSphere then return nil end
            local d = b - a
            local len = d.Magnitude
            if len < 0.1 then return false end
            local u = d / len
            local a2 = a + u * math.min(slackA or _ENDPOINT_SLACK, len * 0.4)
            local b2 = b - u * math.min(slackB or _ENDPOINT_SLACK, len * 0.4)
            local fwd = _sweepDir(a2, b2)
            if fwd == nil then return nil end
            if fwd then return true end
            local rev = _sweepDir(b2, a2)   -- and back: catches one-sided geometry
            if rev == nil then return nil end
            return rev
        end
        local function _clearWide(a, b, slackA, slackB)
            if not _clear(a, b) then return false end
            local sw = _sweepBlocked(a, b, slackA, slackB)
            if sw ~= nil then return not sw end
            -- no Spherecast on this executor: side + vertical rays instead
            local d = Vector3.new(b.X - a.X, 0, b.Z - a.Z)
            if d.Magnitude < 0.1 then
                local ox = Vector3.new(_CLEARANCE, 0, 0)
                local oz = Vector3.new(0, 0, _CLEARANCE)
                return _clearWideRay(a + ox, b + ox) and _clearWideRay(a - ox, b - ox)
                    and _clearWideRay(a + oz, b + oz) and _clearWideRay(a - oz, b - oz)
            end
            local perp = Vector3.new(-d.Z, 0, d.X).Unit * _CLEARANCE
            local up = Vector3.new(0, _CLEARANCE, 0)
            return _clearWideRay(a + perp, b + perp) and _clearWideRay(a - perp, b - perp)
                and _clearWideRay(a + up, b + up) and _clearWideRay(a - up, b - up)
        end
        MV.clearWide = _clearWide

        local function _pullWide(pts)
            if #pts <= 2 then return pts end
            local out = { pts[1] }
            local i = 1
            local n = #pts
            while i < n do
                local j = n
                while j > i + 1 do
                    local a, b = out[#out], pts[j]
                    local sA = (i == 1) and _ENDPOINT_SLACK or 0
                    local sB = (j == n) and _ENDPOINT_SLACK or 0
                    if _clearWide(a, b, sA, sB) then break end
                    j = j - 1
                end
                out[#out + 1] = pts[j]
                i = j
            end
            return out
        end

        local function _pushOffWalls(pts)
            if #pts <= 2 then return pts end
            local MARGIN, MAX_PUSH = 8, 12
            local out = { pts[1] }
            for i = 2, #pts - 1 do
                local p = pts[i]
                local shift = Vector3.zero
                for _, dr in ipairs(_DIRS) do
                    local res = _block(p, p + dr * MARGIN, _blk)
                    if res then
                        local dist = (res.Position - p).Magnitude
                        if dist < MARGIN then shift = shift - dr * (MARGIN - dist) end
                    end
                end
                do
                    local resUp = _block(p, p + Vector3.new(0, MARGIN, 0), _blk)
                    if resUp then
                        local dist = (resUp.Position - p).Magnitude
                        if dist < 4 then shift = shift + Vector3.new(0, -(4 - dist), 0) end
                    end
                end
                if shift.Magnitude > 0.1 then
                    if shift.Magnitude > MAX_PUSH then shift = shift.Unit * MAX_PUSH end
                    local moved = p + shift
                    if _clear(out[#out], moved) then out[#out + 1] = moved else out[#out + 1] = p end
                else
                    out[#out + 1] = p
                end
            end
            out[#out + 1] = pts[#pts]
            return out
        end

        -- ---------------------------------------------------------------
        -- 3D voxel A*
        -- ---------------------------------------------------------------
        local _vxFloor, _vxSqrt = math.floor, math.sqrt
        local _vxMin, _vxMax = math.min, math.max
        local function _vxAbs(n) return n < 0 and -n or n end
        local _vxOverlap = OverlapParams.new()
        _vxOverlap.FilterType = Enum.RaycastFilterType.Exclude
        _vxOverlap.RespectCanCollide = true
        local _vxCast = RaycastParams.new()
        _vxCast.FilterType = Enum.RaycastFilterType.Exclude
        _vxCast.RespectCanCollide = true
        _vxCast.IgnoreWater = true
        local _vxOrigin
        local _vxDimX, _vxDimY, _vxDimZ = 0, 0, 0
        local _vxSz, _vxInflate = 4, 2.5
        local _vxSolid = {}
        local _vxSolidGen, _vxSolidAt = "", 0
        local _vxOX, _vxOY, _vxOZ = 0, 0, 0
        local _vxHeight = 5
        local _vxHeurW = 2.5

        local function _vxWorld(sz, x, y, z)
            local h = sz * 0.5
            return Vector3.new(_vxOrigin.X + x * sz + h, _vxOrigin.Y + y * sz + h, _vxOrigin.Z + z * sz + h)
        end
        local function _vxKey(x, y, z) return x + y * 1024 + z * 1048576 end
        local function _vxGKey(x, y, z)
            return (x + _vxOX + 8192) + (y + _vxOY + 8192) * 16384 + (z + _vxOZ + 8192) * 268435456
        end
        local function _vxIsSolid(x, y, z)
            if x < 0 or y < 0 or z < 0 or x >= _vxDimX or y >= _vxDimY or z >= _vxDimZ then return true end
            local k = _vxGKey(x, y, z)
            local c = _vxSolid[k]
            if c ~= nil then return c end
            local h = _vxSz * 0.5
            local cx = _vxOrigin.X + x * _vxSz + h
            local cy = _vxOrigin.Y + y * _vxSz + h
            local cz = _vxOrigin.Z + z * _vxSz + h
            local sxz = _vxSz + _vxInflate
            local vy = _vxHeight > _vxSz and _vxHeight or _vxSz
            local vcy = cy - h + vy * 0.5
            local parts = workspace:GetPartBoundsInBox(CFrame.new(cx, vcy, cz), Vector3.new(sxz, vy, sxz), _vxOverlap)
            local solid = #parts > 0
            _vxSolid[k] = solid
            return solid
        end
        local function _vxSegClear(from, to, radius, height, sample)
            local dir = to - from
            local mag = dir.Magnitude
            if mag < 0.05 then return true end
            if workspace:Raycast(from, dir, _vxCast) then return false end
            local r = radius > 1 and radius or 1
            if workspace:Blockcast(CFrame.new(from), Vector3.new(r * 2, height, r * 2), dir, _vxCast) ~= nil then return false end
            local n = _vxFloor(mag)
            if sample ~= false and n >= 2 then
                local step = dir / n
                local torso = Vector3.new(r * 2, 3, r * 2)
                for i = 1, n - 1 do
                    local pt = from + step * i
                    if #workspace:GetPartBoundsInBox(CFrame.new(pt), torso, _vxOverlap) > 0 then return false end
                end
            end
            return true
        end
        local _vxNeigh = {}
        do
            for dx = -1, 1 do
                for dy = -1, 1 do
                    for dz = -1, 1 do
                        if dx ~= 0 or dy ~= 0 or dz ~= 0 then
                            local nz = (dx ~= 0 and 1 or 0) + (dy ~= 0 and 1 or 0) + (dz ~= 0 and 1 or 0)
                            _vxNeigh[#_vxNeigh + 1] = {
                                dx, dy, dz, _vxSqrt(dx * dx + dy * dy + dz * dz), nz,
                                dx + dy * 1024 + dz * 1048576,
                            }
                        end
                    end
                end
            end
        end
        local function _vxNoCorner(cx, cy, cz, off)
            if off[5] < 2 then return true end
            if off[1] ~= 0 and _vxIsSolid(cx + off[1], cy, cz) then return false end
            if off[2] ~= 0 and _vxIsSolid(cx, cy + off[2], cz) then return false end
            if off[3] ~= 0 and _vxIsSolid(cx, cy, cz + off[3]) then return false end
            return true
        end
        local function _vxSnapGoal(goalPos, x, y, z)
            if not _vxIsSolid(x, y, z) then return x, y, z end
            for r = 1, 16 do
                for dx = -r, r do
                    for dy = -r, r do
                        for dz = -r, r do
                            if _vxMax(_vxAbs(dx), _vxAbs(dy), _vxAbs(dz)) == r then
                                local nx, ny, nz = x + dx, y + dy, z + dz
                                if not _vxIsSolid(nx, ny, nz)
                                   and (_vxWorld(_vxSz, nx, ny, nz) - goalPos).Magnitude <= 8 then
                                    return nx, ny, nz
                                end
                            end
                        end
                    end
                end
            end
            return x, y, z
        end
        local function _vxSnapStart(pos, x, y, z)
            if not _vxIsSolid(x, y, z) then return x, y, z end
            for r = 1, 16 do
                for dx = -r, r do
                    for dy = -r, r do
                        for dz = -r, r do
                            if _vxMax(_vxAbs(dx), _vxAbs(dy), _vxAbs(dz)) == r then
                                local nx, ny, nz = x + dx, y + dy, z + dz
                                if not _vxIsSolid(nx, ny, nz)
                                   and not workspace:Raycast(pos, _vxWorld(_vxSz, nx, ny, nz) - pos, _vxCast) then
                                    return nx, ny, nz
                                end
                            end
                        end
                    end
                end
            end
            return x, y, z
        end
        local function _vxPush(h, f, key)
            local i = #h + 1
            h[i] = { f, key }
            while i > 1 do
                local p = _vxFloor(i * 0.5)
                if h[p][1] <= h[i][1] then break end
                h[p], h[i] = h[i], h[p]
                i = p
            end
        end
        local function _vxPop(h)
            local n = #h
            if n == 0 then return nil end
            local top = h[1]
            h[1] = h[n]
            h[n] = nil
            n = n - 1
            local i = 1
            while true do
                local l, r, s = i + i, i + i + 1, i
                if l <= n and h[l][1] < h[s][1] then s = l end
                if r <= n and h[r][1] < h[s][1] then s = r end
                if s == i then break end
                h[i], h[s] = h[s], h[i]
                i = s
            end
            return top[2]
        end
        local function _vxAStar(sz, startCell, goalCell, startPos, goalPos)
            local sx, sy, sz2 = _vxSnapStart(startPos, startCell.x, startCell.y, startCell.z)
            local gx, gy, gz = _vxSnapGoal(goalPos, goalCell.x, goalCell.y, goalCell.z)
            local goalKey = _vxKey(gx, gy, gz)
            local startKey = _vxKey(sx, sy, sz2)
            local nodes = { [startKey] = { x = sx, y = sy, z = sz2, g = 0, parent = nil } }
            local closed = {}
            local heap = {}
            _vxPush(heap, 0, startKey)
            local function Heur(x, y, z)
                local ax, ay, az = x - gx, y - gy, z - gz
                return _vxSqrt(ax * ax + ay * ay + az * az)
            end
            -- TIME-SLICED: every 48 pops it checks the clock; past ~6ms of work it
            -- yields a frame, and past the total budget it gives up (nil).
            local budget = _vxBudgetOverride or tonumber(_G.Skyr0VoxelBudget) or 1.5
            local t0, sliceT = os.clock(), os.clock()
            local pops = 0
            while #heap > 0 do
                local curKey = _vxPop(heap)
                if not closed[curKey] then
                    closed[curKey] = true
                    pops = pops + 1
                    if pops > 300000 then break end
                    if pops % 48 == 0 then
                        local nowc = os.clock()
                        if nowc - t0 > budget then return nil end
                        if nowc - sliceT > 0.006 then
                            RunService.Heartbeat:Wait()
                            sliceT = os.clock()
                        end
                    end
                    local cur = nodes[curKey]
                    if curKey == goalKey then
                        local path = {}
                        local n = cur
                        while n do
                            path[#path + 1] = _vxWorld(sz, n.x, n.y, n.z)
                            n = n.parent and nodes[n.parent]
                        end
                        local rev = {}
                        for i = #path, 1, -1 do rev[#rev + 1] = path[i] end
                        return rev
                    end
                    local cx, cy, cz = cur.x, cur.y, cur.z
                    local cg = cur.g
                    for _, off in ipairs(_vxNeigh) do
                        local nk = curKey + off[6]
                        if not closed[nk] then
                            local nx, ny, nz = cx + off[1], cy + off[2], cz + off[3]
                            if not _vxIsSolid(nx, ny, nz) and _vxNoCorner(cx, cy, cz, off) then
                                local tg = cg + off[4]
                                local ex = nodes[nk]
                                if not ex or tg < ex.g then
                                    if ex then
                                        ex.g, ex.parent, ex.x, ex.y, ex.z = tg, curKey, nx, ny, nz
                                    else
                                        nodes[nk] = { x = nx, y = ny, z = nz, g = tg, parent = curKey }
                                    end
                                    _vxPush(heap, tg + _vxHeurW * Heur(nx, ny, nz), nk)
                                end
                            end
                        end
                    end
                end
            end
            return nil
        end
        local function _vxSimplify(path, radius, height)
            if not path or #path < 3 then return path end
            local out = { path[1] }
            local anchor = 1
            local i = 2
            while i <= #path do
                if not _vxSegClear(path[anchor], path[i + 1] or path[i], radius, height, false) then
                    out[#out + 1] = path[i]
                    anchor = i
                end
                i = i + 1
            end
            out[#out + 1] = path[#path]
            return out
        end
        -- wide = the last-resort pass: a much bigger search box (6-stud cells so
        -- it still fits the cell cap) and a longer budget, so a route that has
        -- to swing far around something is still found instead of flying
        -- straight through it.
        local _vxBudgetOverride = nil
        local function voxelRoute(fromPos, toPos, wide)
            local flt = table.move(_skip, 1, #_skip, 1, {})
            _vxOverlap.FilterDescendantsInstances = flt
            _vxCast.FilterDescendantsInstances = flt

            local sz      = wide and 6 or (tonumber(_G.Skyr0PathCell) or 4)
            local inflate = tonumber(_G.Skyr0PathRadius) or 3
            local height  = tonumber(_G.Skyr0PathHeight) or 5
            local pad     = wide and (tonumber(_G.Skyr0PathPadWide) or 80) or (tonumber(_G.Skyr0PathPad) or 40)
            local padY    = wide and 30 or pad
            _vxBudgetOverride = wide and (tonumber(_G.Skyr0VoxelBudgetWide) or 3) or nil
            _vxHeurW = tonumber(_G.Skyr0PathWeight) or 2.5
            local _gen = sz .. "|" .. inflate .. "|" .. height
            local _now = os.clock()
            if _gen ~= _vxSolidGen or (_now - _vxSolidAt) > (tonumber(_G.Skyr0PathCacheTTL) or 3) then
                table.clear(_vxSolid)
                _vxSolidGen = _gen
            end
            _vxSolidAt = _now
            _vxSz, _vxInflate, _vxHeight = sz, inflate, height

            local mn = Vector3.new(_vxMin(fromPos.X, toPos.X), _vxMin(fromPos.Y, toPos.Y), _vxMin(fromPos.Z, toPos.Z)) - Vector3.new(pad, padY, pad)
            local mx = Vector3.new(_vxMax(fromPos.X, toPos.X), _vxMax(fromPos.Y, toPos.Y), _vxMax(fromPos.Z, toPos.Z)) + Vector3.new(pad, padY, pad)
            mn = Vector3.new(_vxFloor(mn.X / sz) * sz, _vxFloor(mn.Y / sz) * sz, _vxFloor(mn.Z / sz) * sz)
            _vxOrigin = mn
            _vxOX, _vxOY, _vxOZ = _vxFloor(mn.X / sz), _vxFloor(mn.Y / sz), _vxFloor(mn.Z / sz)
            local size = mx - mn
            _vxDimX = _vxFloor(size.X / sz) + 1
            _vxDimY = _vxFloor(size.Y / sz) + 1
            _vxDimZ = _vxFloor(size.Z / sz) + 1
            if _vxDimX * _vxDimY * _vxDimZ > 200000 then return nil end

            local startCell = {
                x = _vxFloor((fromPos.X - _vxOrigin.X) / sz),
                y = _vxFloor((fromPos.Y - _vxOrigin.Y) / sz),
                z = _vxFloor((fromPos.Z - _vxOrigin.Z) / sz),
            }
            local goalCell = {
                x = _vxFloor((toPos.X - _vxOrigin.X) / sz),
                y = _vxFloor((toPos.Y - _vxOrigin.Y) / sz),
                z = _vxFloor((toPos.Z - _vxOrigin.Z) / sz),
            }
            local path = _vxAStar(sz, startCell, goalCell, fromPos, toPos)
            if not path then return nil end
            path = _vxSimplify(path, inflate, height)
            if not path or #path == 0 then return nil end
            local route = {}
            for idx = 2, #path do route[#route + 1] = path[idx] end
            if #route == 0 or (route[#route] - toPos).Magnitude > 0.5 then
                route[#route + 1] = toPos
            end
            return route
        end

        -- ---------------------------------------------------------------
        -- centre block, base rows, hop-over
        -- ---------------------------------------------------------------
        local _MAP_CENTER = { minX = -458, maxX = -362, minZ = -40, maxZ = 185 }
        local function _inCenterZone(x, z)
            return x >= _MAP_CENTER.minX and x <= _MAP_CENTER.maxX
               and z >= _MAP_CENTER.minZ and z <= _MAP_CENTER.maxZ
        end
        local function _segmentCrossesCenter(a, b)
            if _inCenterZone(a.X, a.Z) or _inCenterZone(b.X, b.Z) then return true end
            for i = 1, 10 do
                local t = i / 11
                if _inCenterZone(a.X + (b.X - a.X) * t, a.Z + (b.Z - a.Z) * t) then return true end
            end
            return false
        end
        local function _centerSpanT(a, b)
            local t0, t1 = nil, nil
            for i = 0, 40 do
                local t = i / 40
                local x = a.X + (b.X - a.X) * t
                local z = a.Z + (b.Z - a.Z) * t
                if _inCenterZone(x, z) then
                    if not t0 then t0 = t end
                    t1 = t
                end
            end
            return t0, t1
        end
        local function _hitSpanT(a, b)
            local rp = RaycastParams.new()
            rp.FilterType = Enum.RaycastFilterType.Exclude
            rp.IgnoreWater = true
            rp.FilterDescendantsInstances = table.move(_skip, 1, #_skip, 1, {})
            local t0, t1 = nil, nil
            local n, edge = 28, 0.1
            for i = 0, n - 1 do
                local tA, tB = i / n, (i + 1) / n
                if tB > edge and tA < (1 - edge) then
                    local pA, pB = a:Lerp(b, tA), a:Lerp(b, tB)
                    local d = pB - pA
                    if d.Magnitude > 0.05 then
                        local hit = workspace:Raycast(pA, d, rp)
                        if hit and _blkWide(hit.Instance) then
                            if not t0 then t0 = math.max(tA, edge) end
                            t1 = math.min(tB, 1 - edge)
                        end
                    end
                end
            end
            return t0, t1
        end
        local function _localHopOver(fromPos, toPos, tBlock0, tBlock1)
            local lift = tonumber(_G.Skyr0CenterFly) or 10
            local pad = tonumber(_G.Skyr0HopPad) or 0.12
            local t0 = math.clamp(tBlock0 or 0.35, 0.08, 0.85)
            local t1 = math.clamp(tBlock1 or 0.65, t0 + 0.04, 0.92)
            local tRise0 = math.max(0.04, t0 - pad)
            local tRise1, tFall0, tFall1 = t0, t1, math.min(0.94, t1 + pad)
            local function at(t, yAdd)
                local p = fromPos:Lerp(toPos, t)
                local gy = fromPos.Y + (toPos.Y - fromPos.Y) * t
                return Vector3.new(p.X, gy + (yAdd or 0), p.Z)
            end
            local route = { fromPos }
            local function push(p)
                if (route[#route] - p).Magnitude > 0.6 then route[#route + 1] = p end
            end
            push(at(tRise0, 0))
            push(at((tRise0 + tRise1) * 0.5, lift * 0.5))
            push(at(tRise1, lift))
            push(at((tRise1 + tFall0) * 0.5, lift))
            push(at(tFall0, lift))
            push(at((tFall0 + tFall1) * 0.5, lift * 0.5))
            push(at(tFall1, 0))
            push(toPos)
            return route
        end

        local function _rowBoxX() return tonumber(_G.Skyr0RowBoxX) or 26 end
        local function _rowBoxZ() return tonumber(_G.Skyr0RowBoxZ) or 30 end
        local function _rowLane() return tonumber(_G.Skyr0RowLane) or 30 end
        local function _nearestBase(p)
            local bi, bd = nil, math.huge
            for i = 1, 8 do
                local b = BASES_LOW[i]
                local d = (p.X - b.X) ^ 2 + (p.Z - b.Z) ^ 2
                if d < bd then bd = d; bi = i end
            end
            if bd > 70 * 70 then return nil end
            return bi
        end
        local function _segmentHitsOtherBase(a, b, ignA, ignB)
            local hx, hz = _rowBoxX(), _rowBoxZ()
            for i = 0, 24 do
                local t = i / 24
                local px = a.X + (b.X - a.X) * t
                local pz = a.Z + (b.Z - a.Z) * t
                for k = 1, 8 do
                    if k ~= ignA and k ~= ignB then
                        local bs = BASES_LOW[k]
                        if math.abs(px - bs.X) <= hx and math.abs(pz - bs.Z) <= hz then return true end
                    end
                end
            end
            return false
        end
        local function _findRowDetour(fromPos, toPos, y)
            local iFrom, iTo = _nearestBase(fromPos), _nearestBase(toPos)
            if not _segmentHitsOtherBase(fromPos, toPos, iFrom, iTo) then return nil end
            local colX = BASES_LOW[iTo or 1].X
            local off = _rowLane()
            local lanes = {}
            lanes[#lanes + 1] = (colX < COLUMN_SPLIT_X) and (colX - off) or (colX + off)
            local inner = (colX < COLUMN_SPLIT_X) and (colX + off) or (colX - off)
            if not _inCenterZone(inner, (fromPos.Z + toPos.Z) * 0.5) then lanes[#lanes + 1] = inner end
            local best, bestLen = nil, math.huge
            for _, laneX in ipairs(lanes) do
                local w1 = Vector3.new(laneX, y, fromPos.Z)
                local w2 = Vector3.new(laneX, y, toPos.Z)
                if _clearWide(fromPos, w1) and _clearWide(w1, w2) and _clearWide(w2, toPos)
                   and not _segmentHitsOtherBase(w1, w2, iFrom, iTo) then
                    local len = (fromPos - w1).Magnitude + (w1 - w2).Magnitude + (w2 - toPos).Magnitude
                    if len < bestLen then bestLen = len; best = { w1, w2 } end
                end
            end
            return best
        end

        -- ---------------------------------------------------------------
        -- PLOT HULLS -- wrap AROUND bases, never through their walls
        -- ---------------------------------------------------------------
        -- The raycast planner below cannot be trusted with base walls on its own:
        --   * the target base is deliberately invisible to it (_skip), so a
        --     clone spot on the far side was reached straight through the
        --     target's back wall;
        --   * from INSIDE your own base the first ray starts next to (or inside)
        --     a wall and the sphere sweep skips its first 6 studs, so the way
        --     out was planned through the wall instead of the doorway;
        --   * a base the Plot Cleaner stashed is not in the workspace at all,
        --     yet the SERVER still has its walls.
        -- So every base is reduced to a box (its collidable parts' bounds), and:
        --   1. starting inside a base -> leave through its DOORWAY (the lasers,
        --      or the face toward the middle lane) before going anywhere;
        --   2. ending inside a base (walk-in) -> enter through its doorway;
        --   3. clone spot at a wall -> approach along the spot's facing line from
        --      outside the box;
        --   4. in between, a shortest path around the box corners (visibility
        --      graph, margin _G.Skyr0HullMargin = 6) whenever the straight line
        --      would cross a box -- your own base, the target, or any other.
        -- Each leg between those anchors still goes through the normal planner
        -- when something else (centre block, props) is in the way.
        -- _G.Skyr0PlotWrap = false turns this off.
        local _hull = (function()
            local H = {}
            local cache = setmetatable({}, { __mode = "k" })
            local MIN_PARTS = 12
            local abs, huge = math.abs, math.huge

            function H.of(plot, force)
                if not plot then return nil end
                local c = cache[plot]
                if c and not force and c.ready and (os.clock() - c.at) < 20 then return c end
                local okp, pv = pcall(plot.GetPivot, plot)
                if not okp or not pv then return c end
                local px, pz = pv.Position.X, pv.Position.Z
                local REACH = tonumber(_G.Skyr0HullReach) or 70
                local minX, maxX, minZ, maxZ, minY, maxY = huge, -huge, huge, -huge, huge, -huge
                local n = 0
                local lsum, ln, lminY = Vector3.zero, 0, huge
                for _, d in ipairs(plot:GetDescendants()) do
                    if d:IsA("BasePart") then
                        local nm = d.Name
                        if nm == "LaserHitbox" or nm == "Laser" then
                            -- the doorway; the LOWEST floor's lasers win
                            local p = d.Position
                            if p.Y < lminY - 3 then lsum, ln, lminY = p, 1, p.Y
                            elseif abs(p.Y - lminY) <= 3 then lsum, ln = lsum + p, ln + 1 end
                        elseif not _SKIP_NAME[nm] and (d.CanCollide or _STRUCT[nm]) then
                            local p, s = d.Position, d.Size
                            if s.X < 160 and s.Y < 160 and s.Z < 160
                               and abs(p.X - px) < REACH and abs(p.Z - pz) < REACH then
                                local cf = d.CFrame
                                local r, u, l = cf.RightVector, cf.UpVector, cf.LookVector
                                local hx = (abs(r.X) * s.X + abs(u.X) * s.Y + abs(l.X) * s.Z) * 0.5
                                local hy = (abs(r.Y) * s.X + abs(u.Y) * s.Y + abs(l.Y) * s.Z) * 0.5
                                local hz = (abs(r.Z) * s.X + abs(u.Z) * s.Y + abs(l.Z) * s.Z) * 0.5
                                -- footprint from UPRIGHT parts only (walls, pillars): a flat
                                -- ground tile under a base would swell the box over the
                                -- corridor next to it and leave no way around
                                if hy >= 2 then
                                if p.X - hx < minX then minX = p.X - hx end
                                if p.X + hx > maxX then maxX = p.X + hx end
                                if p.Y - hy < minY then minY = p.Y - hy end
                                if p.Y + hy > maxY then maxY = p.Y + hy end
                                if p.Z - hz < minZ then minZ = p.Z - hz end
                                if p.Z + hz > maxZ then maxZ = p.Z + hz end
                                n = n + 1
                                end
                            end
                        end
                    end
                end
                if n == 0 then
                    cache[plot] = { ready = false, n = 0, at = os.clock() }
                    return cache[plot]
                end
                -- bases sit ~107 studs apart; never let one box eat the corridor
                local MAXH = tonumber(_G.Skyr0HullMaxHalf) or 45
                minX, maxX = math.max(minX, px - MAXH), math.min(maxX, px + MAXH)
                minZ, maxZ = math.max(minZ, pz - MAXH), math.min(maxZ, pz + MAXH)
                local h = {
                    name = plot.Name, n = n, at = os.clock(), ready = n >= MIN_PARTS,
                    minX = minX, maxX = maxX, minZ = minZ, maxZ = maxZ, bottom = minY, top = maxY,
                    cx = (minX + maxX) * 0.5, cz = (minZ + maxZ) * 0.5,
                }
                if ln > 0 then
                    local door = lsum / ln
                    local dx, dz = door.X - h.cx, door.Z - h.cz
                    local wx, wz = math.max((maxX - minX) * 0.5, 1), math.max((maxZ - minZ) * 0.5, 1)
                    if abs(dx) / wx >= abs(dz) / wz then
                        h.nrm = Vector3.new(dx >= 0 and 1 or -1, 0, 0)
                    else
                        h.nrm = Vector3.new(0, 0, dz >= 0 and 1 or -1)
                    end
                    h.door = door
                else
                    -- no lasers streamed: bases open toward the middle lane
                    h.nrm = Vector3.new(h.cx < COLUMN_SPLIT_X and 1 or -1, 0, 0)
                    h.door = Vector3.new(h.nrm.X > 0 and maxX or minX, minY + 3, h.cz)
                end
                cache[plot] = h
                return h
            end

            function H.contains(h, p, pad)
                pad = pad or 0
                return p.X > h.minX - pad and p.X < h.maxX + pad
                   and p.Z > h.minZ - pad and p.Z < h.maxZ + pad
                   and p.Y < h.top + 2 and p.Y > h.bottom - 8
            end

            -- 2D segment vs box (Liang-Barsky); touching an edge is not a hit
            local function segHits(a, b, x0, x1, z0, z1)
                local t0, t1 = 0, 1
                local dx, dz = b.X - a.X, b.Z - a.Z
                local P = { -dx, dx, -dz, dz }
                local Q = { a.X - x0, x1 - a.X, a.Z - z0, z1 - a.Z }
                for i = 1, 4 do
                    local p, q = P[i], Q[i]
                    if p == 0 then
                        if q <= 0 then return false end
                    else
                        local t = q / p
                        if p < 0 then
                            if t > t1 then return false end
                            if t > t0 then t0 = t end
                        else
                            if t < t0 then return false end
                            if t < t1 then t1 = t end
                        end
                    end
                end
                return (t1 - t0) > 1e-4
            end

            -- every base, including the ones the Plot Cleaner took out of the world
            local function allHulls()
                local list, seen = {}, {}
                local plots = workspace:FindFirstChild("Plots")
                if plots then
                    for _, p in ipairs(plots:GetChildren()) do
                        seen[p] = true
                        local h = H.of(p)
                        if h and h.n and h.n > 0 and h.minX then list[#list + 1] = h end
                    end
                end
                if type(_G.Skyr0StashedPlots) == "function" then
                    local ok, st = pcall(_G.Skyr0StashedPlots)
                    if ok and type(st) == "table" then
                        for _, p in ipairs(st) do
                            if not seen[p] then
                                local h = H.of(p)
                                if h and h.n and h.n > 0 and h.minX then list[#list + 1] = h end
                            end
                        end
                    end
                end
                return list
            end

            -- inside -> outside points through a base's doorway, at height y
            local function doorPair(h, y, M)
                local n, d = h.nrm, h.door
                local inner, outer
                if n.X ~= 0 then
                    local face = n.X > 0 and h.maxX or h.minX
                    inner = Vector3.new(face - n.X * 8, y, d.Z)
                    outer = Vector3.new(face + n.X * (M + 4), y, d.Z)
                else
                    local face = n.Z > 0 and h.maxZ or h.minZ
                    inner = Vector3.new(d.X, y, face - n.Z * 8)
                    outer = Vector3.new(d.X, y, face + n.Z * (M + 4))
                end
                return inner, outer
            end

            -- Anchors from fromPos to toPos (fromPos excluded, toPos last), or nil
            -- when no base is in the way and the normal planner should decide alone.
            function H.plan(fromPos, toPos, facingDir)
                if _G.Skyr0PlotWrap == false then return nil end
                local hulls = allHulls()
                if #hulls == 0 then return nil end
                local M = tonumber(_G.Skyr0HullMargin) or 6

                local startH, endH
                for _, h in ipairs(hulls) do
                    if not startH and H.contains(h, fromPos, 0) then startH = h end
                    if not endH and H.contains(h, toPos, 0) then endH = h end
                end
                if startH and startH == endH then return nil end   -- moving inside one base

                local pre, post = {}, {}
                local S, E = fromPos, toPos

                -- 1. leave the base we are in through its doorway
                if startH then
                    local inner, outer = doorPair(startH, fromPos.Y, M)
                    if not _clear(fromPos, outer) then pre[#pre + 1] = inner end
                    pre[#pre + 1] = outer
                    S = outer
                end

                -- 2./3. how we arrive
                if facingDir and facingDir.Magnitude > 0.1 then
                    -- clone spot: come in along its facing line, from outside every box
                    local f = Vector3.new(facingDir.X, 0, facingDir.Z).Unit
                    local q = toPos - f * 14
                    for k = 0, 60, 2 do
                        q = toPos - f * (14 + k)
                        local inside = false
                        for _, h in ipairs(hulls) do
                            if H.contains(h, q, M - 0.5) then inside = true; break end
                        end
                        if not inside then break end
                    end
                    E = q
                elseif endH then
                    -- walk-in: through the target's doorway
                    local inner, outer = doorPair(endH, toPos.Y, M)
                    E = outer
                    post[#post + 1] = inner
                end

                -- 4. around every box between S and E
                local function blocked(a, b)
                    for _, h in ipairs(hulls) do
                        if segHits(a, b, h.minX - M + 0.5, h.maxX + M - 0.5, h.minZ - M + 0.5, h.maxZ + M - 0.5) then
                            return true
                        end
                    end
                    return false
                end
                local mid = {}
                if blocked(S, E) then
                    local nodes = { S }
                    for _, h in ipairs(hulls) do
                        for _, c in ipairs({
                            Vector3.new(h.minX - M, 0, h.minZ - M), Vector3.new(h.maxX + M, 0, h.minZ - M),
                            Vector3.new(h.maxX + M, 0, h.maxZ + M), Vector3.new(h.minX - M, 0, h.maxZ + M),
                        }) do
                            local free = true
                            for _, o in ipairs(hulls) do
                                if c.X > o.minX - M + 0.5 and c.X < o.maxX + M - 0.5
                                   and c.Z > o.minZ - M + 0.5 and c.Z < o.maxZ + M - 0.5 then
                                    free = false; break
                                end
                            end
                            if free then nodes[#nodes + 1] = c end
                        end
                    end
                    nodes[#nodes + 1] = E
                    local N = #nodes
                    -- Dijkstra over <= 34 nodes; edges tested lazily
                    local dist, prev, done = {}, {}, {}
                    for i = 1, N do dist[i] = huge end
                    dist[1] = 0
                    local flat = function(v) return Vector3.new(v.X, 0, v.Z) end
                    for _ = 1, N do
                        local u, best = nil, huge
                        for i = 1, N do
                            if not done[i] and dist[i] < best then u, best = i, dist[i] end
                        end
                        if not u or u == N then break end
                        done[u] = true
                        for v = 2, N do
                            if not done[v] then
                                local w = (flat(nodes[u]) - flat(nodes[v])).Magnitude
                                if dist[u] + w < dist[v] and not blocked(nodes[u], nodes[v]) then
                                    dist[v] = dist[u] + w
                                    prev[v] = u
                                end
                            end
                        end
                    end
                    if dist[N] < huge then
                        local chain, k = {}, prev[N]
                        while k and k ~= 1 do table.insert(chain, 1, k); k = prev[k] end
                        -- heights: ease from the start height to the arrival height
                        local total = dist[N]
                        for _, idx in ipairs(chain) do
                            local t = total > 0 and (dist[idx] / total) or 1
                            local c = nodes[idx]
                            mid[#mid + 1] = Vector3.new(c.X, S.Y + (E.Y - S.Y) * t, c.Z)
                        end
                    else
                        warn("[skyr0] route: no way around the bases found -- flying the normal route")
                        if #pre == 0 and #post == 0 then return nil end
                    end
                elseif #pre == 0 and #post == 0 and (E - toPos).Magnitude < 0.5 then
                    return nil   -- nothing in the way, nothing to leave or enter
                end

                local out = {}
                for _, p in ipairs(pre) do out[#out + 1] = p end
                for _, p in ipairs(mid) do out[#out + 1] = p end
                if (E - toPos).Magnitude > 0.5 then out[#out + 1] = E end
                for _, p in ipairs(post) do out[#out + 1] = p end
                out[#out + 1] = toPos
                return out
            end

            return H
        end)()
        MV.plotHull = function(plot, force) return _hull.of(plot, force) end
        _G.Skyr0PlotHulls = function()
            local out = {}
            local plots = workspace:FindFirstChild("Plots")
            if plots then
                for _, p in ipairs(plots:GetChildren()) do
                    local h = _hull.of(p)
                    if h and h.minX then
                        out[#out + 1] = string.format("%s  x[%.0f..%.0f] z[%.0f..%.0f] y[%.0f..%.0f]  door %s  parts %d",
                            p.Name, h.minX, h.maxX, h.minZ, h.maxZ, h.bottom, h.top, tostring(h.nrm), h.n)
                    end
                end
            end
            for _, l in ipairs(out) do print("[skyr0] hull " .. l) end
            return out
        end

        -- ---------------------------------------------------------------
        -- the planner
        -- ---------------------------------------------------------------
        local function _planLeg(fromPos, toPos, facingDir, maxLift, preferCrest)

            if _clearWide(fromPos, toPos) then return { toPos } end

            if _segmentCrossesCenter(fromPos, toPos) then
                local c0, c1 = _centerSpanT(fromPos, toPos)
                local h0, h1 = _hitSpanT(fromPos, toPos)
                if c0 and h0 and h1 and h1 >= c0 and h0 <= (c1 or 1) then
                    local t0 = math.max(h0, c0)
                    local t1 = math.min(h1, c1 or h1)
                    if (t1 - t0) > 0.02 then return _localHopOver(fromPos, toPos, t0, t1) end
                end
            end

            local rowPatch = _findRowDetour(fromPos, toPos, fromPos.Y)
            if rowPatch and #rowPatch > 0 then fromPos = rowPatch[#rowPatch] end
            local function _withPatch(route)
                if not rowPatch or #rowPatch == 0 then return route end
                local merged = {}
                for _, p in ipairs(rowPatch) do merged[#merged + 1] = p end
                for _, p in ipairs(route) do merged[#merged + 1] = p end
                return merged
            end
            if _clearWide(fromPos, toPos) then return _withPatch({ toPos }) end

            if preferCrest or _G.Skyr0CrestRoute == true then
                local cruiseY = math.max(fromPos.Y, toPos.Y, 26) + 12
                local up = Vector3.new(fromPos.X, cruiseY, fromPos.Z)
                local over = Vector3.new(toPos.X, cruiseY, toPos.Z)
                local crest = { fromPos, up, over, toPos }
                local ok = true
                for i = 1, #crest - 1 do
                    local a, b = crest[i], crest[i + 1]
                    if (a - b).Magnitude > 0.5 then
                        local sA = (i == 1) and _ENDPOINT_SLACK or 0
                        local sB = (i == #crest - 1) and _ENDPOINT_SLACK or 0
                        if not _clearWide(a, b, sA, sB) then ok = false; break end
                    end
                end
                if ok then return _withPatch(crest) end
            end

            do
                local vr = voxelRoute(fromPos, toPos)
                if vr and #vr > 0 then return _withPatch(vr) end
            end

            local entry = facingDir and (toPos - facingDir * 14) or toPos
            local best, bestLen = nil, math.huge
            local function consider(pts)
                if not pts or #pts < 2 then return end
                local n = #pts
                for i = 1, n - 1 do
                    local a, b = pts[i], pts[i + 1]
                    if (a - b).Magnitude > 0.5 then
                        local sA = (i == 1) and _ENDPOINT_SLACK or 0
                        local sB = (i == n - 1) and _ENDPOINT_SLACK or 0
                        if not _clearWide(a, b, sA, sB) then return end
                    end
                end
                local pulled = _pullWide(pts)
                local L = _lenOf(pulled)
                if L < bestLen then best, bestLen = pulled, L end
            end
            do
                local dirF = Vector3.new(entry.X - fromPos.X, 0, entry.Z - fromPos.Z)
                if dirF.Magnitude > 0.1 then
                    dirF = dirF.Unit
                    local perp = Vector3.new(-dirF.Z, 0, dirF.X)
                    local midBase = (fromPos + entry) * 0.5
                    for _, off in ipairs({ 14, -14, 24, -24, 38, -38, 56, -56, 76, -76 }) do
                        consider({ fromPos, midBase + perp * off, entry })
                        consider({ fromPos, fromPos + perp * off, entry + perp * off, entry })
                    end
                end
            end

            local navRaw
            if not best then
                local groundTo = Vector3.new(entry.X, fromPos.Y, entry.Z)
                local path = PathfindingService:CreatePath({
                    AgentRadius = 16, AgentHeight = 5, AgentCanJump = true, AgentJumpHeight = 10, AgentMaxSlope = 89,
                })
                local FLOAT = 5
                local nav = { fromPos }
                local ok = pcall(function()
                    path:ComputeAsync(Vector3.new(fromPos.X, fromPos.Y, fromPos.Z), groundTo)
                end)
                if ok and path.Status == Enum.PathStatus.Success then
                    local last = fromPos
                    for _, wp in ipairs(path:GetWaypoints()) do
                        if (wp.Position - last).Magnitude >= 8 then
                            nav[#nav + 1] = wp.Position + Vector3.new(0, FLOAT, 0)
                            last = wp.Position
                        end
                    end
                end
                nav[#nav + 1] = entry + Vector3.new(0, FLOAT, 0)
                nav = _pushOffWalls(nav)
                navRaw = nav
                consider(nav)
            end

            -- NEVER STRAIGHT THROUGH. Nothing above found a wide-clear route:
            -- before falling back, run the voxel A* again over a much bigger
            -- box so it can swing all the way around whatever is in the way.
            -- The old fallback was a thin-ray straight line, then a blind
            -- straight line -- which is how it clipped through things.
            local route = best
            if not route then
                local vr = voxelRoute(fromPos, toPos, true)
                if vr and #vr > 0 then route = vr end
            end
            if not route and navRaw then route = _pullWide(navRaw) end
            if not route and _clearWide(fromPos, toPos, _ENDPOINT_SLACK, _ENDPOINT_SLACK) then route = { toPos } end
            if not route then
                warn("[skyr0] route: no way around found -- flying straight (last resort)")
                route = { toPos }
            end
            if (route[#route] - toPos).Magnitude > 0.5 then route[#route + 1] = toPos end
            return _withPatch(route)
        end

        return function(fromPos, toPos, facingDir, maxLift, preferCrest)
            -- escape hatch back to the old ground-pathfinding router
            if _G.Skyr0RouterLegacy == true then return MV.legacyRoute(fromPos, toPos, facingDir) end
            _rebuildSkip(toPos, fromPos)

            local okH, anchors = pcall(_hull.plan, fromPos, toPos, facingDir)
            if not okH then
                warn("[skyr0] route: base wrap failed (" .. tostring(anchors) .. ") -- normal route")
                anchors = nil
            end
            if not anchors then return _planLeg(fromPos, toPos, facingDir, maxLift, preferCrest) end

            -- Fly anchor to anchor. A leg with a clear line is taken as is; one with
            -- something else in the way (centre block, props) gets the normal
            -- planner for just that leg. The final approach keeps the facing.
            local out, cur = {}, fromPos
            for i, a in ipairs(anchors) do
                local last = (i == #anchors)
                local leg
                if (a - cur).Magnitude < 0.5 then
                    leg = {}
                elseif _clearWide(cur, a, (i == 1) and _ENDPOINT_SLACK or 0, last and _ENDPOINT_SLACK or 0) then
                    -- wide-clear only (sphere sweep both ways + side rays): a
                    -- thin ray let legs scrape corners and clip edges
                    leg = { a }
                else
                    leg = _planLeg(cur, a, last and facingDir or nil, maxLift, preferCrest)
                    if not leg or #leg == 0 then leg = { a } end
                end
                for _, p in ipairs(leg) do out[#out + 1] = p end
                cur = a
            end
            if #out == 0 or (out[#out] - toPos).Magnitude > 0.5 then out[#out + 1] = toPos end
            return out
        end
    end)()

    -- ===== Clone / goToBrainrot =====
    local function doClone()
        local char = LP.Character or LP.CharacterAdded:Wait()
        local hum = char and char:FindFirstChildOfClass("Humanoid")
        if not char or not hum then return false end
        local cloner = (LP:FindFirstChild("Backpack") and LP.Backpack:FindFirstChild("Quantum Cloner"))
                    or char:FindFirstChild("Quantum Cloner")
        if not cloner then
            warn("[skyr0] doClone: Quantum Cloner not found in Backpack or Character")
            return false
        end
        -- Use the EXACT manual-clone method: equip the cloner, Activate() it, then
        -- firesignal the game's own TeleportToClone button so the GAME performs the
        -- switch through its legitimate code path. Firing QuantumCloner/OnTeleport
        -- directly stopped switching after the update -- this doesn't.
        if _G.Skyr0InstantClone then
            -- instantClone returns false when the fire did NOT happen (no cloner
            -- UI in time). This used to be ignored and reported as a success --
            -- a silent miss. Retry the fire up to 3 times; only a real fire counts.
            for _attempt = 1, 3 do
                if _G.Skyr0InstantClone() then return true end
                task.wait(0.1)
            end
            warn("[skyr0] doClone: the clone never fired (no Quantum Cloner UI)")
            return false
        end
        warn("[skyr0] doClone: manual clone method (_G.Skyr0InstantClone) unavailable")
        return false
    end

    -- CARPET GLIDE: fly straight to the pet on the equipped carpet at FULL 3D speed
    -- (same pace as velMoveThrough -- WalkTPSpeed in the actual direction, vertical
    -- included). The carpet is already equipped by goToBrainrot, so no extra equip
    -- wait. Used as the FINAL approach after the clone/grabble TP.
    local function carpetGlideTo(targetPos)
        if not targetPos then return end
        local char = LP.Character
        local hrp = char and char:FindFirstChild("HumanoidRootPart")
        if not hrp then return end
        pcall(function() hrp.Anchored = false end)
        pcall(equipCarpet)
        local FLOAT_OFFSET = (targetPos.Y > 20) and -4 or 0
        local goal = Vector3.new(targetPos.X, targetPos.Y + FLOAT_OFFSET, targetPos.Z)
        -- instant CFrame to the pet (was a velocity glide at Walk To Brainrot Speed)
        if hrp.Parent and not LP:GetAttribute("Stealing") and (goal - hrp.Position).Magnitude >= 3 then
            hrp.AssemblyLinearVelocity = Vector3.zero
            hrp.AssemblyAngularVelocity = Vector3.zero
            hrp.CFrame = CFrame.new(goal)
        end
        if hrp and hrp.Parent then
            hrp.AssemblyLinearVelocity = Vector3.zero
            hrp.AssemblyAngularVelocity = Vector3.zero
        end
    end

    local function goToBrainrot(petPos)
        if not petPos then return end
        local char, hrp, hum
        local _t0 = os.clock()
        repeat
            char = LP.Character
            hrp = char and char:FindFirstChild("HumanoidRootPart")
            hum = char and char:FindFirstChildOfClass("Humanoid")
            if hrp and hum then break end
            RunService.Heartbeat:Wait()
        until os.clock() - _t0 > 3
        if not hrp or not hum then return end
        pcall(function() hrp.Anchored = false end)
        local _equipped = false
        do
            local _e0 = os.clock()
            repeat
                char = LP.Character
                for _, _cn in ipairs(CARPET_NAMES) do
                    if char and char:FindFirstChild(_cn) then _equipped = true; break end
                end
                if _equipped then break end
                equipCarpet()
                RunService.Heartbeat:Wait()
            until _equipped or os.clock() - _e0 > 1.5
            if _equipped then task.wait(0.2) end
        end
        char = LP.Character
        hrp = char and char:FindFirstChild("HumanoidRootPart")
        hum = char and char:FindFirstChildOfClass("Humanoid")
        if not hrp then return end
        pcall(function() hrp.Anchored = false end)
        local _plotRad = (petPos.Y <= 8.9) and 26 or 25
        do
            local _t0b = os.clock()
            repeat
                local p = hrp.Position
                local inRad = false
                local plotsFolder = workspace:FindFirstChild("Plots")
                if plotsFolder then
                    for _, plot in ipairs(plotsFolder:GetChildren()) do
                        pcall(function()
                            local pp = plot:GetPivot().Position
                            if math.abs(p.X - pp.X) < _plotRad and math.abs(p.Z - pp.Z) < _plotRad then inRad = true end
                        end)
                        if inRad then break end
                    end
                end
                if inRad then break end
                RunService.Heartbeat:Wait()
            until os.clock() - _t0b > 1.5
        end
        local h = petPos.Y
        -- one band, shared with doVelocityTP's coord clamp and its _forceGo
        local _isF2FromF1Case = _G.Skyr0IsF2FromF1 and _G.Skyr0IsF2FromF1(h) or false
        local targetY = hrp.Position.Y
        if h > 23.15 then targetY = 21
        elseif h >= 11 and h <= 23.15 then
            -- V3 Floor 2 from Floor 1: use the runAutoSnipe F3-from-F2 pattern
            -- literally -- character ends up at petY - 8 (8 studs below the pet)
            -- and the platform below settles at petY - 11 (3 studs below the
            -- character). Same relative offsets the F3 case uses, just applied
            -- to the F2 pet Y.
            targetY = (_isF2FromF1Case and (h - 8)) or 14.5
        elseif h >= -6.9 and h <= 8.9 then targetY = -4 end
        local _to = Vector3.new(petPos.X, targetY, petPos.Z)
        -- V3 Floor 2 from Floor 1: after the clone lands us inside the base on
        -- floor 1, spam Humanoid.Jump so we bounce up toward the 2nd floor pet
        -- instead of moving to under it with a lerp+platform.
        if _isF2FromF1Case then
            -- no hopping any more (was: a blind Jump=true every 0.1s for 8s)
        elseif Config.TpSettings and Config.TpSettings.BrainrotCarpet then
            -- Carpet to Brainrot: after the clone/grabble TP into the base, glide on
            -- the carpet straight to the pet (uses live Walk To Brainrot Speed).
            carpetGlideTo(petPos)
        else
            -- walk to brainrot = instant CFrame straight under it (was a
            -- pathfinding velocity walk at Walk To Brainrot Speed)
            if hrp and hrp.Parent and not LP:GetAttribute("Stealing") then
                hrp.AssemblyLinearVelocity = Vector3.zero
                hrp.AssemblyAngularVelocity = Vector3.zero
                hrp.CFrame = CFrame.new(_to)
            end
        end
        if hrp and hrp.Parent and not _isF2FromF1Case then
            hrp.AssemblyLinearVelocity = Vector3.zero
            hrp.AssemblyAngularVelocity = Vector3.zero
        end
        if not _isF2FromF1Case then
            do
                local _platPos = (hrp and hrp.Parent and hrp.Position) or _to
                local _feetY = _platPos.Y - 3
                local _plat = Instance.new("Part")
                _plat.Name = "Skyr0TempPlatform"; _plat.Size = Vector3.new(8, 1, 8)
                _plat.Position = Vector3.new(petPos.X, _feetY - 1.5, petPos.Z)
                _plat.Anchored = true; _plat.CanCollide = false; pcall(makeOneWay, _plat); _plat.Transparency = 1
                _plat.Material = Enum.Material.SmoothPlastic; _plat.Parent = workspace
                task.spawn(function()
                    local _s = tick()
                    while tick() - _s < 20 do
                        if LP:GetAttribute("Stealing") then break end
                        task.wait(0.1)
                    end
                    if _plat and _plat.Parent then _plat:Destroy() end
                end)
            end
        end
    end

    -- ===== Steal engine =====
    local InternalStealCache = {}
    local STEAL_HOLD_DURATION = 1.3
    local _stealHoldStart = 0
    local _stealHoldActive = false

    local function buildStealCallbacks(prompt)
        local cached = InternalStealCache[prompt]
        if cached then
            -- real callbacks: done. An EMPTY grab (made before the game's own
            -- client hooked this prompt -- right after execute) is retried, at
            -- most every 0.2s and never mid-hold, instead of being kept forever.
            if #cached.holdCallbacks > 0 or not cached.ready then return end
            if type(getconnections) ~= "function" then return end
            if os.clock() - (cached.builtAt or 0) < 0.2 then return end
            InternalStealCache[prompt] = nil
        end
        if not prompt or not prompt.Parent then return end
        local data = { holdCallbacks = {}, triggerCallbacks = {}, holdEndCallbacks = {}, ready = true, builtAt = os.clock() }
        local _seenConns = 0
        local function grab(sig, into)
            local ok, conns = pcall(getconnections, sig)
            if ok and type(conns) == "table" then
                _seenConns = _seenConns + #conns
                for _, c in ipairs(conns) do
                    if type(c.Function) == "function" then table.insert(into, c.Function) end
                end
            end
        end
        grab(prompt.PromptButtonHoldBegan, data.holdCallbacks)
        grab(prompt.Triggered, data.triggerCallbacks)
        grab(prompt.PromptButtonHoldEnded, data.holdEndCallbacks)

        -- THE FIRST GRAB FAILED. The game hooks a steal prompt's signals only once
        -- the prompt has been SHOWN to you, so the first build after execute (or
        -- for a base you just arrived at) often finds NO connections at all.
        -- That used to be read as "this executor hides .Function" and sent the
        -- steal down the direct fireproximityprompt path -- which fails the
        -- forced hold -- and only the next loop, with the real callbacks, worked.
        -- No connections at all = not hooked YET: wait for them (re-asked every
        -- loop tick) for _G.Skyr0StealHookWait (1.5s) before falling back. Hooked
        -- but .Function hidden (Delta, mobile) still goes direct at once.
        local _empty = _G.__Skyr0StealEmpty
        if not _empty then
            _empty = setmetatable({}, { __mode = "k" })
            _G.__Skyr0StealEmpty = _empty
        end
        if #data.holdCallbacks == 0 and #data.triggerCallbacks == 0 and #data.holdEndCallbacks == 0
           and _seenConns == 0 and type(getconnections) == "function" then
            local since = _empty[prompt]
            if not since then since = os.clock(); _empty[prompt] = since end
            if os.clock() - since < (tonumber(_G.Skyr0StealHookWait) or 1.5) then return end
        end
        _empty[prompt] = nil

        -- ALWAYS cache, with a flag for which path this prompt has to take.
        --
        -- Delta and most mobile executors hand back connections whose
        -- .Function is restricted to nil, so nothing above captures anything
        -- and the entry used to be skipped entirely -- which made the caller's
        -- `if InternalStealCache[prompt]` false forever and the steal silently
        -- never fire. That is the whole of "it doesn't work on Delta": no
        -- error, no message, just a feature that never happens.
        data.direct = not (#data.holdCallbacks > 0 or #data.triggerCallbacks > 0
                           or #data.holdEndCallbacks > 0)
        if data.direct and type(fireproximityprompt) ~= "function" then
            -- neither path available on this executor: say so once rather than
            -- failing silently every attempt
            if not _G.__Skyr0NoStealAPI then
                _G.__Skyr0NoStealAPI = true
                warn("[skyr0] this executor exposes neither getconnections(.Function) "
                     .. "nor fireproximityprompt -- auto steal cannot run")
            end
            return
        end
        InternalStealCache[prompt] = data
    end

    -- FORCED HOLD: the hold-began callbacks close over the game's anti-cheat
    -- table ({State=, ProximityPrompt=, ...}). Forcing its State to "Steal" for
    -- the duration of the call is what makes the hold count server side.
    -- Cached per prompt (false = none found).
    local function _apFromHold(data)
        if data.ap ~= nil then return data.ap or nil end
        if debug and debug.getupvalues then
            for _, f in ipairs(data.holdCallbacks) do
                local ok, ups = pcall(debug.getupvalues, f)
                if ok and type(ups) == "table" then
                    for _, v in pairs(ups) do
                        if type(v) == "table" and rawget(v, "State") ~= nil and rawget(v, "ProximityPrompt") ~= nil then
                            data.ap = v
                            return v
                        end
                    end
                end
            end
        end
        data.ap = false
        return nil
    end

    local function executeStealAsync(prompt)
        -- Runs alongside the nearest grab: this is the hold that fills the progress
        -- bar. The nearest grab may still finish the steal first with its instant fire -- both
        -- only ever touch the armed target, so they can never pick different pets.
        if _stealHoldActive then return false end
        local data = InternalStealCache[prompt]
        if not data or not data.ready then return false end
        data.ready = false
        _stealHoldStart = tick()
        _stealHoldActive = true
        _G.Skyr0_StealStatus = _G.Skyr0_StealStatus or {}
        _G.Skyr0_StealStatus.active = true
        _G.Skyr0_StealStatus.start = _stealHoldStart
        _G.Skyr0_StealStatus.duration = tonumber(_G.Skyr0StealHoldDuration) or STEAL_HOLD_DURATION

        task.spawn(function()
            -- DIRECT PATH (no usable callbacks -- Delta, most mobile).
            -- Hold the prompt the way a player does and let the game run its
            -- own logic start to finish. Same duration, so the HUD and the
            -- guard thresholds are unchanged.
            if data.direct then
                local _dur = tonumber(_G.Skyr0StealHoldDuration) or STEAL_HOLD_DURATION
                local _t0 = tick()
                -- ONE call, then retries -- not a flood.
                --
                -- fireproximityprompt(p, 0) completes the prompt instantly, so
                -- a "hold" built out of one every 0.05s is not a hold at all:
                -- it fires on the first call and then sends 25 more for
                -- nothing. That is pure noise to anticheat and it is the kind
                -- of thing that gets an executor flagged.
                --
                -- Fire once, then only retry if the game has not registered
                -- the steal, and stop the moment it does.
                pcall(fireproximityprompt, prompt)
                local _next = 0.25
                while prompt and prompt.Parent and (tick() - _t0) < _dur do
                    if LP:GetAttribute("Stealing") then break end
                    task.wait(_next)
                    if LP:GetAttribute("Stealing") then break end
                    if prompt and prompt.Parent then
                        pcall(fireproximityprompt, prompt, 0)
                    end
                    _next = math.min(_next * 1.6, 0.5)
                end
                _stealHoldActive = false
                if _G.Skyr0_StealStatus then _G.Skyr0_StealStatus.active = false end
                task.wait(0.05)
                data.ready = true
                return
            end

            -- HOLD: prompt HoldDuration to 0, hold-began fired with the
            -- anti-cheat State forced to "Steal", and a hold begun less than
            -- Skyr0StealCarryMax (1.25s) ago is carried instead of restarted.
            local _oldHoldDur
            pcall(function() _oldHoldDur = prompt.HoldDuration; prompt.HoldDuration = 0 end)
            local _epoch = tonumber(_G.__Skyr0HoldEpoch) or 0
            local _hAge = _epoch > 0 and (tick() - _epoch) or math.huge
            local _carried = _G.Skyr0StealHoldCarry ~= false and prompt.Enabled
                and _hAge <= (tonumber(_G.Skyr0StealCarryMax) or 1.25)
            local _ap = _apFromHold(data)
            if _carried then
                _stealHoldStart = _epoch
                if _G.Skyr0_StealStatus then _G.Skyr0_StealStatus.start = _epoch end
            elseif _ap and _ap.State ~= "Steal" then
                local _os = _ap.State
                _ap.State = "Steal"
                for _, fn in ipairs(data.holdCallbacks) do pcall(fn) end
                _ap.State = _os
                _G.__Skyr0HoldEpoch = tick()
            else
                for _, fn in ipairs(data.holdCallbacks) do task.spawn(fn) end
                if #data.holdCallbacks > 0 and prompt.Enabled then _G.__Skyr0HoldEpoch = tick() end
            end
            -- old remote nudge, now only a fallback when the anti-cheat table
            -- could not be found in the callbacks' upvalues
            if not _ap then pcall(function()
                local _st = prompt:GetAttribute("State")
                if _st ~= nil and _st ~= "Steal" then
                    -- Was `_net:RemoteEvent(<guid>)`, which hands back the DEAD
                    -- PLAINTEXT ALIAS -- the steal fires went nowhere. Resolve
                    -- through the hashed resolver (HERENEW's GetRemote-first
                    -- order) and only keep it if it is a real remote, so a miss
                    -- retries next steal instead of latching a stub forever.
                    -- THIS is the "lags every time a remote happens" site.
                    --
                    -- The name here is a GUID, which is the Net folder's own key,
                    -- so Skyr0GetRemote answers it with a plain FindFirstChild.
                    -- The _G.Net fallback underneath it did not: _G.Net resolves
                    -- lazily and runs build() -- a getgc(true) walk of the entire
                    -- Lua heap. And because a failed resolve leaves
                    -- _xenStealRemote nil, this whole block re-ran on EVERY
                    -- steal, so a name that never resolves meant a heap sweep
                    -- every 15s for the rest of the session.
                    --
                    -- The fallback is gone. A miss now costs three FindFirstChild
                    -- calls and retries on the next steal, which is what the
                    -- retry was always meant to be.
                    if not _G._xenStealRemote or not _G._xenStealRemote.Parent then
                        local _r, _real = nil, false
                        if _G.Skyr0GetRemote then
                            _r, _real = _G.Skyr0GetRemote("f40f7d9e-2f0d-4167-b250-899273f46874", "RemoteEvent")
                        end
                        if _r and _real then _G._xenStealRemote = _r end
                    end
                    local r = _G._xenStealRemote
                    if r then
                        local _t = workspace:GetServerTimeNow() + 124
                        r:FireServer(_t, "68c86eb7-eb7e-4b4d-96ae-cf7cd847c5b0")
                        r:FireServer(_t, "07b9cc25-2a1f-4a26-a0ec-f2fab578d8bd")
                    end
                end
            end) end
            -- Effective hold before firing the trigger that completes the steal.
            -- Live-tunable via _G.Skyr0StealHoldDuration (default 1.3 = the game's
            -- normal timing). Kept SEPARATE from STEAL_HOLD_DURATION so the
            -- guard/threshold logic below is unaffected by it. Lower is faster
            -- but far more detectable -- change it deliberately.
            local _holdDur = tonumber(_G.Skyr0StealHoldDuration) or STEAL_HOLD_DURATION
            local remain = _holdDur - (tick() - _stealHoldStart)
            if remain > 0 then task.wait(remain) end
            -- TRIGGER: fireproximityprompt completes the forced hold; the
            -- Triggered callbacks are the fallback (Skyr0StealUseFPP = false
            -- to prefer the callbacks)
            if prompt and prompt.Parent then
                if type(fireproximityprompt) == "function" and _G.Skyr0StealUseFPP ~= false then
                    pcall(fireproximityprompt, prompt)
                else
                    for _, fn in ipairs(data.triggerCallbacks) do task.spawn(fn) end
                    if #data.triggerCallbacks == 0 and type(fireproximityprompt) == "function" then
                        pcall(fireproximityprompt, prompt)
                    end
                end
            end
            for _, fn in ipairs(data.holdEndCallbacks) do task.spawn(fn) end
            pcall(function() if _oldHoldDur ~= nil and prompt.Parent then prompt.HoldDuration = _oldHoldDur end end)
            _stealHoldActive = false
            if _G.Skyr0_StealStatus then _G.Skyr0_StealStatus.active = false end
            task.wait(0.05)
            data.ready = true
        end)
        return true
    end

    local function findStealPrompt(pet)
        if pet.plot and pet.slot then
            local plots = workspace:FindFirstChild("Plots")
            local plot = plots and plots:FindFirstChild(pet.plot)
            local podiums = plot and plot:FindFirstChild("AnimalPodiums")
            local podium = podiums and podiums:FindFirstChild(tostring(pet.slot))
            if podium then
                local base = podium:FindFirstChild("Base")
                local spawn = base and base:FindFirstChild("Spawn")
                local attach = spawn and spawn:FindFirstChild("PromptAttachment")
                if attach then
                    for _, p in ipairs(attach:GetChildren()) do
                        if p:IsA("ProximityPrompt") then return p end
                    end
                end
                for _, d in ipairs(podium:GetDescendants()) do
                    if d:IsA("ProximityPrompt") then return d end
                end
            end
        end
        if pet.model and pet.model.Parent then
            for _, d in ipairs(pet.model:GetDescendants()) do
                if d:IsA("ProximityPrompt") then return d end
            end
        end
        return nil
    end

    local STEAL_PROXIMITY = 60
    -- Fraction of the hold to have elapsed on arrival. 0.95 -> the bar reads
    -- ~95% as you land. 1.0 would complete exactly on arrival; lower is safer
    -- because the trigger still has to happen in range. Live-tunable.
    local STEAL_PREARM    = 0.95
    local STEAL_ARM_TIMEOUT = 25
    local _stealTarget = nil
    local _stealArmedAt = 0

    local function timeUntilCanSteal()
        if LP:GetAttribute("Stealing") or LP:GetAttribute("IsTrading")
            or LP:GetAttribute("IsDuelSelecting") or LP:GetAttribute("Web") then
            return -1
        end
        return 0
    end

    local function _petKey(pet)
        if not pet then return nil end
        if pet.plot and pet.slot then return tostring(pet.plot) .. "|" .. tostring(pet.slot) end
        return "idx|" .. tostring(pet.index or pet.name)
    end
    local function _petStillExists(sel, pets)
        if not sel or not pets then return nil end
        local k = _petKey(sel)
        for _, p in ipairs(pets) do if _petKey(p) == k then return p end end
        return nil
    end
    -- forward declaration: _pickByMode's priority branch falls back to this, and
    -- it is defined further down (it needs getPetPosition)
    local _petPorUID

    -- The topmost priority-list entry present on the server, or nil.
    --
    -- Split out of _pickByMode so it can run BEFORE the mode branches instead of
    -- after them (see the note there), and so the "no min gen ever applies to a
    -- priority pet" rule lives in exactly one place: nothing in here filters on
    -- earnings at all. If it is on your list, it is a target, full stop.
    --
    -- Trimming/case-folding and the same-name tie-break are in
    -- _G.Skyr0PickPriority, shared with getTargetPetData and the Steal Target
    -- selector -- this used to take the FIRST scan-order match while
    -- getTargetPetData took the biggest earner of that name, and
    -- getTargetPetData's pick is what Skyr0CicloTP locks in as the teleport's
    -- destination. Two of the same priority pet on a server and the hook aimed
    -- at one base while the grab was armed on the other.
    local function _pickPriorityFrom(pets, hrp)
        if not (priorityList and #priorityList > 0 and _G.Skyr0PickPriority) then return nil end
        local _rp
        if typeof(hrp) == "Vector3" then _rp = hrp
        elseif typeof(hrp) == "Instance" then _rp = hrp.Position end

        if pets then
            local hit = _G.Skyr0PickPriority(
                pets,
                function(p) return p.mps or 0 end,
                function(p) return p.position end,
                function(p) return not p.conveyor end,
                _rp)
            if hit then return hit end
        end

        -- SECOND CHANCE: the PANEL's cache.
        --
        -- The panel (SharedState.AllAnimalsCache) and this teleport engine build
        -- two INDEPENDENT lists -- the file says so at _petPorUID -- and the panel
        -- deliberately sees pets the engine cannot: bases with no channel resolved
        -- yet, and rendered-Model entries. So a priority pet can be sitting right
        -- there in your list while `pets` above does not contain it, and the walk
        -- falls through to the biggest earner. That is the intermittent "it went
        -- to the wrong one": it depends on which bases have replicated, which is
        -- different every join.
        --
        -- _petPorUID rebuilds the entry from the uid, taking the position from the
        -- podium exactly as the engine would, so the result is a normal target and
        -- not a second-class one.
        local cache = (_G.SharedState and _G.SharedState.AllAnimalsCache)
                   or (SharedState and SharedState.AllAnimalsCache)
        if type(cache) == "table" and _petPorUID then
            local eu = LocalPlayer
            -- EVERY listed candidate, in list order -- not just the top one.
            --
            -- Taking only the best and giving up if _petPorUID could not rebuild
            -- it (no podium position yet, plot not streamed) threw away every
            -- OTHER priority pet on the server and fell straight through to the
            -- biggest earner. Walk down the list instead: #1 if it resolves, else
            -- #2, and so on. Only a completely unresolvable list falls through.
            local cands = {}
            for _, a in ipairs(cache) do
                if a and a.uid and a.plot
                   and a.owner ~= eu.Name and a.owner ~= eu.DisplayName
                   and not (_G.Skyr0IsMyPlotCached and _G.Skyr0IsMyPlotCached(a.plot)) then
                    local rank = _G.Skyr0PrioRank(a.name, a.index)
                    if rank then cands[#cands + 1] = { a = a, rank = rank, gen = a.genValue or 0 } end
                end
            end
            table.sort(cands, function(x, y)
                if x.rank ~= y.rank then return x.rank < y.rank end
                return x.gen > y.gen
            end)
            for _, c in ipairs(cands) do
                local rebuilt = _petPorUID(c.a.uid)
                if rebuilt and rebuilt.position then return rebuilt end
            end
        end
        return nil
    end

    -- autoGrab (3rd arg): the auto-grab's own picker. In Nearest mode it
    -- IGNORES the priority list and takes the nearest pet, full stop -- that is
    -- what the Steal Nearest keybind means. The teleport's callers do not pass
    -- it, so they keep the priority-first rule.
    local function _pickByMode(pets, hrp, autoGrab)
        if not pets or #pets == 0 then return nil end
        local C = Config or {}
        -- ============================================================
        --  THE PRIORITY LIST IS NOT A MODE. IT IS THE FIRST TIER.
        --
        --  This ran BELOW the mode branches, so `mode == "Highest"` and
        --  `mode == "Nearest"` both returned before the list was ever read.
        --  And the mode resolves to "Highest" for anyone whose saved config
        --  has StealMode = "Highest" in it -- one click on the Steal panel,
        --  ever, and the priority list was dead from then on, silently.
        --
        --  The list is the user's explicit "take THESE, in THIS order". It is
        --  checked first, always, whatever the mode says. The mode only
        --  decides what happens when NOTHING on the list is on the server --
        --  which is what the Highest/Nearest branches below now are.
        -- ============================================================
        -- The resolution lives in _G.Skyr0ResolveMode so that getTargetPetData
        -- -- whose pick is what actually locks the teleport's destination, see
        -- the note there -- answers this question with the SAME code. The two
        -- had drifted: this one read AutoTPHighestGen/Value and that one read
        -- nothing at all.
        local mode = _G.Skyr0ResolveMode and _G.Skyr0ResolveMode() or (C.StealMode or "Priority")

        if not (autoGrab and mode == "Nearest") then
            local hit = _pickPriorityFrom(pets, hrp)
            if hit then return hit end
        end

        if mode == "Nearest" then
            -- `hrp` may be an HRP instance (the usual case) OR a bare Vector3.
            -- The teleport passes a Vector3 while it is airborne so "nearest"
            -- is measured from the DESTINATION rather than from a root part
            -- that is still crossing the map -- see the call site.
            local rp
            if typeof(hrp) == "Vector3" then
                rp = hrp
            elseif typeof(hrp) == "Instance" then
                rp = hrp.Position
            else
                local c = LocalPlayer.Character
                local h = c and c:FindFirstChild("HumanoidRootPart")
                rp = h and h.Position
            end
            if rp then
                local best, bd = nil, math.huge
                for _, p in ipairs(pets) do
                    if p.position then
                        local d = (rp - p.position).Magnitude
                        if d < bd then bd, best = d, p end
                    end
                end
                if best then return best end
            end
            return pets[1]
        end

        if mode == "Highest" then
            local best, bv
            for _, p in ipairs(pets) do
                local v = p.mps or 0
                if not bv or v > bv then bv, best = v, p end
            end
            return best or pets[1]
        end

        -- Neither Highest nor Nearest, and nothing on the list is here: the
        -- biggest earner.
        local best, bv
        for _, p in ipairs(pets) do
            local v = p.mps or 0
            if not bv or v > bv then bv, best = v, p end
        end
        return best or pets[1]
    end
    local function _samePet(a, b)
        if not a or not b then return false end
        return a.plot == b.plot and tostring(a.slot) == tostring(b.slot)
    end

    -- ========================================================
    --  REBUILD A PET FROM ITS UID -- fixes "the TP goes to the wrong pet"
    --
    --  The PANEL (scanSinglePlot -> SharedState.AllAnimalsCache) and the TP
    --  ENGINE (scanAllPets, in this scope) build TWO INDEPENDENT lists. The
    --  only link between them is manuallySelectedUID = plot.."_"..slot.
    --
    --  When the clicked uid was not in the engine's list, the code fell
    --  through to `_pickByMode(allPets) or allPets[1]` -- silently, with no
    --  error: you clicked one pet and the TP flew to a different one. That is
    --  the "sometimes it works, sometimes it doesn't".
    --
    --  It became common with the new plot scanner, which deliberately sees
    --  pets the engine cannot: rendered-Model entries and bases with no
    --  channel at all. So the panel lists them and the engine does not.
    --
    --  Here the entry is rebuilt from the uid itself. The position comes from
    --  the usual getPetPosition (podium), never from the Model's pivot, so
    --  floor and slot still come from the old system.
    -- ========================================================
    -- assigns the forward-declared local above (so _pickByMode's priority
    -- second-chance can reach it); NOT a new local
    function _petPorUID(uid)
        if type(uid) ~= "string" then return nil end
        -- the plot UUID contains no "_", so the LAST one separates the slot
        local plotName, slot = uid:match("^(.+)_([^_]+)$")
        if not plotName or not slot then return nil end
        if _G.Skyr0SlotInFuse and _G.Skyr0SlotInFuse(plotName, slot) then return nil end

        local plots = workspace:FindFirstChild("Plots")
        local plot = plots and plots:FindFirstChild(plotName)
        if not plot then return nil end

        local pos = getPetPosition(plot, slot)
        if not pos then return nil end

        -- name/value come from what the panel already showed, for display only
        local nome, mps, mut = "Target", 0, "None"
        for _, a in ipairs(SharedState.AllAnimalsCache or {}) do
            if a.uid == uid then
                nome = a.name or nome
                mps  = a.genValue or 0
                mut  = a.mutation or mut
                break
            end
        end
        return {
            name = nome, index = nome, mps = mps, mutation = mut,
            position = pos, plot = plotName, slot = tostring(slot),
        }
    end

    local _stealTarget2 = nil
    local function armSteal(pet)
        if not pet then return end
        _stealTarget = pet; _stealArmedAt = os.clock()
        _stealTarget2 = pet
        _G.Skyr0_StealStatus = _G.Skyr0_StealStatus or {}
        _G.Skyr0_StealStatus.target = pet
    end
    local function disarmSteal()
        _stealTarget = nil
        _G.Skyr0_StealStatus = _G.Skyr0_StealStatus or {}
        _G.Skyr0_StealStatus.target = nil
        -- a hold in flight keeps its bar; it clears itself when it finishes
        if not _stealHoldActive then _G.Skyr0_StealStatus.active = false end
    end
    _G.Skyr0ArmSteal = armSteal
    _G.Skyr0DisarmSteal = disarmSteal

    local AUTO_STEAL = (Config and Config.AutoStealEnabled) and true or false
    _G.Skyr0AutoSteal = function(on) AUTO_STEAL = on ~= false end

    local _stealLastScan = 0
    local _autoLastScan = 0
    local isTeleporting = false
    local _tpStartedAt = 0
    local _cloneTP = false
    local _cloneFired = false
    local _started = false
    -- last plot-scanner cache version this loop acted on; a change means the
    -- plots really changed and the target should be re-decided (see the gate
    -- in the Heartbeat below)
    local _lastCacheVer = -1
    -- position the in-flight teleport committed to, used as the "nearest"
    -- reference while airborne so a mid-flight retarget cannot chase the HRP
    local _tpAnchor = nil
    -- THE TP'S TARGET STAYS THE GRAB TARGET. The re-picker used to resume the
    -- instant a flight ended and could re-pick a different pet (a duplicate, a
    -- tie on value, a new "nearest" from where you landed) before the grab
    -- fired. While this is live the re-picker keeps the TP's pet as long as it
    -- still exists. Held for the whole flight, then _G.Skyr0TpCommitHold (4s)
    -- after landing.
    local _tpCommit = { pet = nil, untilT = 0 }
    local function _commitTP(pet, landed)
        if not pet or pet.conveyor then return end
        _tpCommit.pet = pet
        _tpCommit.untilT = landed and (os.clock() + (tonumber(_G.Skyr0TpCommitHold) or 4)) or math.huge
    end

    -- =====================================================================
    -- AUTO-GRAB FINISHER
    -- ---------------------------------------------------------------------
    -- Called by the anti-ragdoll watchdog a short lead before a ragdoll
    -- recovery finishes, so the steal engine is already armed and clean the
    -- instant you are back on your feet instead of spending the first second
    -- upright sorting itself out.
    --
    -- A ragdoll interrupts a steal, so once you are back up the engine should
    -- be picking a target again rather than sitting on whatever it was reaching
    -- for when you got knocked over.
    --
    -- WHAT THIS MUST NOT DO: touch an in-flight hold.
    --
    -- The first version force-set data.ready = true on every cached prompt, on
    -- the theory that an interrupted hold could leave it stuck false. It cannot
    -- -- executeStealAsync's coroutine is just task.wait plus callbacks, it
    -- always runs to completion and always restores ready itself. What forcing
    -- it actually did was let a SECOND hold coroutine start on a prompt that
    -- already had one running. Both then raced: each finished, each set
    -- _stealHoldActive/Skyr0_StealStatus.active false and ready true again 0.05s
    -- later, and each of those re-opened the gate for another. The result was a
    -- permanent restart loop -- the bar climbing to 10% or 60% and snapping back
    -- to 0 forever, from a single ragdoll, until rejoin.
    --
    -- So: if a hold is genuinely running, leave it completely alone. It will
    -- finish on its own in at most STEAL_HOLD_DURATION and the normal path takes
    -- over from there. Only when nothing is in flight does this re-arm.
    -- =====================================================================
    _G.Skyr0GrabFinisher = function()
        -- Re-enable, but never turn on something the user switched off.
        if Config and Config.AutoStealEnabled then AUTO_STEAL = true end

        -- A hold is running: hands off. No ready flags, no status writes, no
        -- disarm -- every one of those is what created the overlapping
        -- coroutines. It completes by itself.
        if _stealHoldActive then return false end

        -- Nothing in flight: drop the stale progress and force the re-picker to
        -- re-evaluate on its next Heartbeat tick.
        --
        -- Deliberately NOT disarmSteal(). The re-picker already keeps the target
        -- when it is still the best one and swaps it when it is not, so a disarm
        -- buys nothing -- and it is actively harmful if the re-picker happens to
        -- be frozen for a teleport, which would leave nothing armed at all.
        _G.Skyr0_StealStatus = _G.Skyr0_StealStatus or {}
        _G.Skyr0_StealStatus.active = false
        _autoLastScan = 0
        return true
    end

    RunService.Heartbeat:Connect(function()
        local now = os.clock()
        -- FROZEN FOR THE WHOLE FLIGHT, not just the clone sub-case.
        --
        -- This is what made the TP and the auto-grab go to DIFFERENT pets. The
        -- teleport picks its destination ONCE, at the top of doVelocityTP, from
        -- a forced scan -- and then flies. This re-picker kept running for the
        -- entire flight, every 0.1s, off its own (0.2s-cached) scan, and
        -- re-armed _stealTarget the moment its answer differed.
        --
        -- In "Nearest" mode that divergence is guaranteed, not occasional: the
        -- reference point is the HRP and the HRP is crossing the map at ~400
        -- studs/s, so "nearest" is a different pet on almost every tick. You
        -- land where the TP aimed and auto-grab has already armed something
        -- else. Priority/Highest diverge too, just less often -- the TP reads a
        -- forced scan and this reads a stale one, so a pet that replicates in
        -- mid-flight flips the pick.
        --
        -- The destination is now the armed target (doVelocityTP calls armSteal
        -- on its own pick) and nothing is allowed to re-target until the flight
        -- ends. Same 30s reclaim as the doVelocityTP stale-guard, so a leaked
        -- isTeleporting can't freeze retargeting forever.
        --
        -- The cycle latch is checked as well as the engine's own flag. TP-on-load
        -- runs Skyr0CicloTP, which GRAPPLES AND CLIMBS before it ever reaches
        -- doVelocityTP -- so isTeleporting is still false for that whole first
        -- leg, and this loop was re-scanning every 0.1s (a full ~100-pet rebuild,
        -- GetBoundingBox per pet) right through it. That is load-time frames
        -- spent re-deciding a target that is about to be decided anyway.
        -- __Skyr0CicloRodando is set for the whole cycle; it holds os.clock() at
        -- start, so it carries the same 20s reclaim doVelocityTP gives it.
        local _ciclo = _G.__Skyr0CicloRodando
        local _cicloRunning = type(_ciclo) == "number" and (os.clock() - _ciclo) < 20
        local _tpInFlight = (isTeleporting and (now - _tpStartedAt) < 30) or _cicloRunning

        -- PLOT CHANGED -> RETARGET, even mid-flight.
        --
        -- The freeze above stops the TIMER-driven re-pick, which is the one that
        -- caused the TP and the grab to disagree: it re-decided ten times a
        -- second off data that had not changed, and in "Nearest" mode it chased
        -- the HRP across the map while the HRP was the thing moving.
        --
        -- What it must NOT stop is a retarget when the WORLD actually changes --
        -- someone steals the pet you were flying at, a base empties out, new pets
        -- land. Frozen through that, the engine sat on a target that no longer
        -- existed and never grabbed anything.
        --
        -- SharedState.CacheVersion is exactly that signal and nothing else: the
        -- plot scanner bumps it only after its content hash says the cache really
        -- changed, so this fires on real plot changes and not on a timer.
        local _ver = SharedState and SharedState.CacheVersion or 0
        local _plotChanged = (_ver ~= _lastCacheVer)
        if _plotChanged then _lastCacheVer = _ver end

        -- BASE CAMP: skyro's engine stands down completely while the camp is
        -- on -- the camp runs rose's own steal (see ROSE BASE CAMP STEAL), and
        -- a disarm from here every 0.1s would reset its progress bar.
        local _camp = _G.Skyr0Camp
        local _camping = _camp and _camp.active == true
        if AUTO_STEAL and not _camping and _started and not LP:GetAttribute("Stealing")
            and (_plotChanged or not _tpInFlight)
            and (now - _autoLastScan) >= 0.1 then
            _autoLastScan = now
            local char = LP.Character
            local hrp = char and char:FindFirstChild("HumanoidRootPart")
            if hrp then
                local ok, pets = pcall(scanAllPets)
                if ok and pets then
                    local best
                    -- Manual selection from Skyr0Hub
                    if manuallySelectedUID then
                        for _, pet in ipairs(pets) do
                            if not pet.conveyor and pet.plot and pet.slot then
                                local uid = pet.plot .. "_" .. tostring(pet.slot)
                                if uid == manuallySelectedUID then best = pet; break end
                            end
                        end
                        -- not in the engine's list: rebuild it from the uid
                        -- instead of silently switching to a different pet
                        if not best then best = _petPorUID(manuallySelectedUID) end
                    end
                    if not best then
                        -- One picker for every mode. Nearest used to be handled
                        -- separately here (measuring to the steal PROMPT rather
                        -- than the pet), so the auto-steal loop and the TP could
                        -- disagree about which pet is nearest and fight over the
                        -- target. Both go through _pickByMode now.
                        local nc = {}
                        for _, p in ipairs(pets) do if not p.conveyor then nc[#nc + 1] = p end end
                        -- MID-FLIGHT, MEASURE FROM WHERE WE ARE GOING.
                        --
                        -- Only relevant to "Nearest". Retargeting during a flight
                        -- is the right thing to do when the plot changed, but
                        -- measuring "nearest" from the LIVE HRP while it crosses
                        -- the map at ~400 studs/s is what made the TP and the grab
                        -- disagree in the first place -- the answer changes every
                        -- tick and none of those answers is where you will land.
                        --
                        -- _tpAnchor is the position the teleport committed to, so
                        -- during a flight the question becomes "which pet will be
                        -- nearest when I arrive" -- stable, and consistent with
                        -- the destination. On the ground it is nil and the live
                        -- HRP is used exactly as before.
                        -- STEAL NEAREST = nearest auto-grab, and NEW SPAWNS ARE
                        -- IGNORED. When Nearest is on, only the pets that already
                        -- existed at that moment (a snapshot taken on the first
                        -- tick, cleared by setStealMode) can be picked. A brainrot
                        -- that spawns in a plot later never becomes the target, so
                        -- nothing re-arms or moves you for it; the priority alert
                        -- is a separate loop and still fires for it.
                        local _nm = _G.Skyr0ResolveMode and _G.Skyr0ResolveMode() or "Priority"
                        if _nm == "Nearest" then
                            local base = _G.Skyr0NearBase
                            if not base then
                                if #nc > 0 then
                                    base = {}
                                    for _, p in ipairs(nc) do base[tostring(p.plot) .. "_" .. tostring(p.slot)] = true end
                                    _G.Skyr0NearBase = base
                                end
                            else
                                local kept = {}
                                for _, p in ipairs(nc) do
                                    if base[tostring(p.plot) .. "_" .. tostring(p.slot)] then kept[#kept + 1] = p end
                                end
                                nc = kept
                            end
                        else
                            _G.Skyr0NearBase = nil
                        end
                        best = _pickByMode(nc, (_tpInFlight and _tpAnchor) or hrp, true)
                    end
                    -- the TP's pet wins while the commit is live and it still exists
                    if _tpCommit.pet and os.clock() < _tpCommit.untilT and not manuallySelectedUID then
                        local kept
                        for _, p in ipairs(pets) do
                            if _samePet(p, _tpCommit.pet) then kept = p; break end
                        end
                        if kept then best = kept else _tpCommit.pet = nil end
                    end
                    if best then
                        if not _samePet(best, _stealTarget) then armSteal(best) end
                    elseif _stealTarget and not _stealHoldActive then
                        disarmSteal()
                    end
                end
            end
        end

        if _camping then return end
        local pet = _stealTarget
        if not pet then return end
        local STEAL_MODE = (Config and Config.StealMode) or "Priority"
        if STEAL_MODE == "Nearest" and now - _stealArmedAt > STEAL_ARM_TIMEOUT then
            disarmSteal(); return
        end
        if now - _stealLastScan < 0.067 then return end
        _stealLastScan = now
        local t = timeUntilCanSteal()
        if t == -1 then
            if LP:GetAttribute("Stealing") then disarmSteal() end
            return
        end
        if t > 0 and t > STEAL_HOLD_DURATION then return end
        local char = LP.Character
        local hrp = char and char:FindFirstChild("HumanoidRootPart")
        if not hrp then return end
        local prompt = findStealPrompt(pet)
        if not prompt or not prompt.Parent then return end
        local pp = prompt.Parent
        local ppPos = (pp and pp:IsA("BasePart") and pp.Position)
            or (pp and pp.Parent and pp.Parent:IsA("BasePart") and pp.Parent.Position)
        local _inCloneTP = isTeleporting and _cloneTP and _cloneFired

        -- (TP-timed holding removed: nothing starts while you are still flying)
        local _preArm = false
        -- still in the air: wait for the landing (a Clone TP has already put
        -- you on the pet, so it is allowed through)
        if isTeleporting then _G.__Skyr0LastFlightAt = os.clock() end
        local _pend = _G.__Skyr0TPPending
        local _pendBlocks = _pend ~= nil
            and not (type(_pend) == "number" and (tonumber(_G.__Skyr0LastFlightAt) or 0) > _pend)
        if (isTeleporting or _pendBlocks) and not _inCloneTP then return end

        local _reach = (_G.Skyr0GetGrabRadius and _G.Skyr0GetGrabRadius()) or STEAL_PROXIMITY
        if _G.Skyr0Camp and _G.Skyr0Camp.active == true and pet.plot == _G.Skyr0Camp.plotName then
            _reach = math.max(_reach, tonumber(_G.Skyr0CampStealRadius) or 95)
        end
        if not _inCloneTP and not _preArm and ppPos
           and (hrp.Position - ppPos).Magnitude > _reach then return end
        local oldMax
        pcall(function() oldMax = prompt.MaxActivationDistance end)
        pcall(function() prompt.MaxActivationDistance = math.huge end)
        buildStealCallbacks(prompt)
        if InternalStealCache[prompt] then executeStealAsync(prompt) end
        pcall(function() if oldMax ~= nil then prompt.MaxActivationDistance = oldMax end end)
    end)

    -- =====================================================================
    -- SKYR0 TP
    -- ---------------------------------------------------------------------
    -- velMoveThrough, carpetEngage(+Fast), goToBrainrot, the ping/straight-route
    -- helpers and the flight from the target on keep their original call order
    -- and timing. What is YOURS and plugged in:
    --   * the target (your priority / mode / manual pick, made just above)
    --   * computeRoute (your pathfinding), pickCloneSpot, isPlotUnlocked, doClone
    --   * your TP speed (GrabbleTPSpeed) and Clone Delay slider
    --   * the hook shot (a plain remote call -> your tool-activate method)
    --   * your steal engine's arm / disarm around the clone
    -- One bound added: a stalled leg's final CFrame snap is limited to 25 studs
    -- (_G.Skyr0TpSnapMax) -- unbounded, it teleports you across the map.
    -- =====================================================================
    MV.mk = (function()
        local SkyrTP = {}
        local LPH_NO_VIRTUALIZE = function(f) return f end
        local _STRIP_OK = (type(getconnections) == "function")
        local CARPET_SPEED = Skyr0Speed.CARPET
        local SKYR0_TP_ARRIVE = ARRIVE
        local SKYR0_TP_TIMEOUT_SPEED = 125                       -- a generous flight timeout
        local function _spd() return tonumber(Config and Config.TpSettings and Config.TpSettings.GrabbleTPSpeed) or 400 end
        local function _cloneDelay() return tonumber(Config and Config.TpSettings and Config.TpSettings.CloneDelayVal) or 0.12 end
        -- defaults for the settings below, unless you have already set them
        if _G.Skyr0TpNoZeroVel == nil then _G.Skyr0TpNoZeroVel = false end
        if _G.Skyr0TpClimb == nil then _G.Skyr0TpClimb = 100 end
        if _G.Skyr0TpCloseSpeed == nil then _G.Skyr0TpCloseSpeed = 300 end
        if _G.Skyr0TpGoSpeed == nil then _G.Skyr0TpGoSpeed = 220 end
        if _G.Skyr0TpCFrameSpeed == nil then _G.Skyr0TpCFrameSpeed = 450 end
        local function _vzOK()
            if _G.Skyr0TpNoZeroVel == true then return false end
            if _G.Skyr0TpZeroWhileStealing ~= true and LP:GetAttribute("Stealing") == true then return false end
            return true
        end
        local function _vzL(p) if p and _vzOK() then p.AssemblyLinearVelocity = Vector3.new(0, 0, 0) end end
        local function _vzA(p) if p and _vzOK() then p.AssemblyAngularVelocity = Vector3.new(0, 0, 0) end end

        -- The hook fires through this hub's working method (the tool's own Activate, aim
        -- written into the PlayerMouse tables), at the clone spot when it is known.
        local function _fireGrapple()
            -- the TP owns the hook: stop the hub's own carpetEngage adding an aimless second shot
            _G.Skyr0CycleHookAt = os.clock()
            local ok = false
            if _G.Skyr0FireGrapple2 then
                pcall(function() ok = _G.Skyr0FireGrapple2(SkyrTP.aim) and true or false end)
            end
            return ok
        end
        local function fireGrapple()
            local char = LP.Character
            if not char then return end
            if not char:FindFirstChild("Grapple Hook") then
                local bp = LP:FindFirstChild("Backpack")
                local tool = bp and bp:FindFirstChild("Grapple Hook")
                local hum = char:FindFirstChildOfClass("Humanoid")
                if tool and hum then pcall(function() hum:EquipTool(tool) end) end
            end
            if not char:FindFirstChild("Grapple Hook") then return end
            _fireGrapple()
        end

        local function _climbCap()
            local v = math.clamp(tonumber(_G.Skyr0TpClimb) or 200, 100, 250)
            if not _STRIP_OK then v = 55 end
            return v
        end

        local function vZero(hrp)
            if hrp then _vzL(hrp); _vzA(hrp) end
        end


        local function _setFlightVel(hrp, vel)
            local char = hrp and hrp.Parent
            local part = (char and (char:FindFirstChild("UpperTorso") or char:FindFirstChild("Torso"))) or hrp
            if part then part.AssemblyLinearVelocity = vel end
        end

        local function velMoveThrough(hrp, waypoints, speedOverride, allowJump, quickStart)
            if not hrp or not hrp.Parent or #waypoints == 0 then return end
            local _runSpeed = speedOverride or (_G.TPVelocity and math.clamp(_G.TPVelocity, 200, 750)) or CARPET_SPEED
            vizPath(hrp.Position, waypoints)
            local wpIdx = 1
            local done = false
            local conn
            -- why the leg ended: "arrived" | "lagback" | "stuck" | "cancel" | "timeout".
            -- run() reads it so a leg the SERVER cut short is retried at the same spot
            -- instead of the spot being marked bad and swapped -- that swap is the
            -- "TP keeps restarting somewhere else".
            local _reason = "timeout"
            local function finish(why)
                if done then return end
                done = true
                if why then _reason = why end
                if hrp and hrp.Parent then
                    _vzL(hrp)
                    _vzA(hrp)
                    local _, y = hrp.CFrame:ToEulerAnglesYXZ()
                    -- never snap after a lagback: the server just refused that ground
                    if _reason ~= "lagback"
                       and (hrp.Position - waypoints[#waypoints]).Magnitude <= (tonumber(_G.Skyr0TpSnapMax) or 25) then
                        hrp.CFrame = CFrame.new(waypoints[#waypoints]) * CFrame.Angles(0, y, 0)
                    end
                end
                if conn then conn:Disconnect() end
            end
            local lastDist, stallStart = math.huge, 0
            -- anti-lagback state
            local lastPos, lagRecover, lagUntil, unstick = hrp.Position, 0, 0, 0
            local MAX_RECOVER = tonumber(_G.Skyr0TpMaxRecover) or 5
            local _startPos = hrp.Position
            -- Speed back-off. A rejection is the server refusing the SPEED as often
            -- as the path, and re-flying at the same speed got the same answer --
            -- on a laggy join, every time. Each lagback costs 20% (floor 140 studs/s
            -- or the leg's own speed if lower); the factor carries over to the next
            -- leg and creeps back to full over ~15s.
            local _lagMul = 1
            do
                local m, at = tonumber(_G.Skyr0TpLagMul), tonumber(_G.Skyr0TpLagMulAt)
                if m and at then _lagMul = math.min(1, m + (os.clock() - at) * 0.04) end
            end
            -- multi-frame lagback: on high ping the server walks you back over several
            -- frames, no single one past the snap budget. Movement AGAINST the
            -- direction we are commanding (while that direction is steady, so a
            -- waypoint overshoot does not count) is accumulated over a 0.5s window.
            local _cmdDir, _prevCmd = nil, nil
            local _backSum, _backAt = 0, os.clock()
            -- After a lagback, resume on the ROUTE, not straight at the waypoint we
            -- were heading for. The server can throw you back past several corners,
            -- and the straight line from there to the old waypoint is exactly the
            -- line through the wall the route was going around -- so the resume got
            -- rejected again, three times, and the leg died.
            local function _resumeIdx(pos)
                local best, bestD, bestT = wpIdx, math.huge, 1
                local prev = _startPos
                for k = 1, #waypoints do
                    local a, b = prev, waypoints[k]
                    local ab = b - a
                    local L2 = ab:Dot(ab)
                    local t = (L2 > 1e-6) and math.clamp((pos - a):Dot(ab) / L2, 0, 1) or 1
                    local d = (a + ab * t - pos).Magnitude
                    if d < bestD - 0.01 then best, bestD, bestT = k, d, t end
                    prev = b
                end
                -- thrown back before the start of that segment: go to its start first
                if bestT < 0.02 and best > 1 then best = best - 1 end
                return best
            end

            local _stStart = os.clock()
            local _lastJump = 0

            local _routeLen = 0
            do
                local _p = hrp.Position
                for _, wp in ipairs(waypoints) do
                    _routeLen = _routeLen + (_p - wp).Magnitude
                    _p = wp
                end
            end
            local _mayJump = _routeLen >= (tonumber(_G.Skyr0TpJumpMinDist) or 100)

            local _ = quickStart

            conn = RunService.Heartbeat:Connect(LPH_NO_VIRTUALIZE(function(dt)
                dt = dt or (1 / 60)
                if not hrp or not hrp.Parent or done then
                    if conn then conn:Disconnect() end
                    return
                end
                if _G.Skyr0TPCancel then finish("cancel") return end
                equipCarpet()
                if _mayJump and _G.Skyr0TpJumpEachStep ~= false then
                    local _now = os.clock()
                    if _now - _lastJump >= (tonumber(_G.Skyr0TpJumpGap) or 0.2) then
                        _lastJump = _now
                        local _jh = hrp.Parent and hrp.Parent:FindFirstChildOfClass("Humanoid")
                        if _jh then
                            pcall(function() _jh:ChangeState(Enum.HumanoidStateType.Jumping) end)
                            pcall(function() _jh.Jump = true end)
                        end
                    end
                end
                local target = waypoints[wpIdx]
                local diff = target - hrp.Position
                local mag = diff.Magnitude
                local _spd = math.max(_runSpeed * _lagMul, math.min(_runSpeed, 140))
                if wpIdx < #waypoints and mag < 26 then
                    local nxt = waypoints[wpIdx + 1]
                    local b = nxt - target
                    if mag > 0.1 and b.Magnitude > 0.1 and diff.Unit:Dot(b.Unit) < 0.9 then
                        _spd = math.min(_spd, 240)
                    end
                end
                local _arr = math.max(SKYR0_TP_ARRIVE, _spd / 60 * 1.25)
                if mag < _arr then
                    wpIdx = wpIdx + 1
                    if wpIdx > #waypoints then finish("arrived") return end
                    lastDist, stallStart = math.huge, 0
                    if _G.Skyr0TpZeroEachStep ~= false and _vzOK() then
                        pcall(function()
                            local _v = hrp.AssemblyLinearVelocity
                            local _keepY = (_G.Skyr0TpZeroStepKeepY == false) and 0 or math.max(_v.Y, 0)
                            hrp.AssemblyLinearVelocity = Vector3.new(0, _keepY, 0)
                            hrp.AssemblyAngularVelocity = Vector3.new(0, 0, 0)
                        end)
                    end
                    if _mayJump and _G.Skyr0TpJumpEachStep ~= false then
                        local _wh = hrp.Parent and hrp.Parent:FindFirstChildOfClass("Humanoid")
                        if _wh then
                            _lastJump = os.clock()
                            pcall(function() _wh:ChangeState(Enum.HumanoidStateType.Jumping) end)
                            pcall(function() _wh.Jump = true end)
                        end
                    end
                    target = waypoints[wpIdx]
                    diff = target - hrp.Position
                    mag = diff.Magnitude
                end

                -- ---- lagback detection ----
                -- The server put us somewhere we did not drive to. Past what one
                -- frame at our own speed could cover AND moving away from the
                -- target is a rejection; either alone is just a bounce off geometry.
                local _delta = hrp.Position - lastPos
                local moved = _delta.Magnitude
                local _png = (_G.Skyr0Ping and _G.Skyr0Ping()) or 0.1
                local _budget = _spd * (math.max(dt, 1 / 240) * 2 + _png) + 6
                local _nowL = os.clock()
                if (_nowL - _backAt) > 0.5 then _backSum, _backAt = 0, _nowL end
                local _against = _cmdDir and -_delta:Dot(_cmdDir) or 0
                if _cmdDir and _prevCmd and _cmdDir:Dot(_prevCmd) > 0.7 and _against > 0.5
                   and _nowL >= lagUntil then
                    _backSum = _backSum + _against
                end
                -- one hard snap: past the frame budget AND either further from the
                -- target than last frame or flung against the commanded direction
                -- (the second catches a snap right after a waypoint advance, when
                -- lastDist has just been reset and the first test cannot fire)
                local _snapped = moved > _budget
                    and ((lastDist < math.huge and mag > lastDist + 4) or _against > moved * 0.3)
                local _drifted = _backSum > math.max(24, _spd * 0.12)
                if (_snapped or _drifted) and _nowL >= lagUntil then
                    lastPos = hrp.Position
                    _backSum, _backAt = 0, _nowL
                    _cmdDir, _prevCmd = nil, nil
                    if lagRecover < MAX_RECOVER then
                        lagRecover = lagRecover + 1
                        _lagMul = math.max(_lagMul * 0.8, 0.35)
                        _G.Skyr0TpLagMul, _G.Skyr0TpLagMulAt = _lagMul, _nowL
                        hrp.AssemblyLinearVelocity = Vector3.zero
                        -- settle for a couple of round trips before moving again
                        lagUntil = _nowL + math.clamp(_png * 2 + 0.2, 0.35, 1.5)
                        wpIdx = _resumeIdx(hrp.Position)
                        lastDist, stallStart = math.huge, 0
                        warn(string.format("[skyr0] TP: lagback %d/%d -- resuming on the route at waypoint %d/%d, speed x%.2f",
                            lagRecover, MAX_RECOVER, wpIdx, #waypoints, _lagMul))
                        return
                    end
                    finish("lagback") return   -- out of recoveries: end where the server has us
                end
                lastPos = hrp.Position
                if _nowL < lagUntil then
                    hrp.AssemblyLinearVelocity = Vector3.zero
                    return
                end
                -- ---- stall detector, on a clock rather than a frame count: a
                -- high-ping server can hold you still for most of a round trip
                -- while it catches up, and that must not read as stuck ----
                if mag > lastDist - 0.05 then
                    if stallStart == 0 then stallStart = os.clock() end
                else
                    stallStart = 0
                end
                lastDist = mag
                if stallStart ~= 0 and (os.clock() - stallStart) > (0.45 + _png * 2) then
                    -- STUCK (a wall, usually). Sidestep: drop a waypoint 18 studs to
                    -- whichever side is clear (or 16 studs up), fly there, then carry
                    -- on. Twice per leg at most; after that the leg ends.
                    if unstick < 2 and MV.clear then
                        unstick = unstick + 1
                        local flat = Vector3.new(diff.X, 0, diff.Z)
                        if flat.Magnitude > 0.1 then
                            local perp = Vector3.new(-flat.Z, 0, flat.X).Unit
                            local here = hrp.Position
                            local pick
                            for _, off in ipairs({ perp * 18, perp * -18, Vector3.new(0, 16, 0),
                                                   perp * 18 + Vector3.new(0, 10, 0),
                                                   perp * -18 + Vector3.new(0, 10, 0) }) do
                                if MV.clear(here, here + off) then pick = here + off; break end
                            end
                            if pick then
                                table.insert(waypoints, wpIdx, pick)
                                lastDist, stallStart = math.huge, 0
                                return
                            end
                        end
                    end
                    finish("stuck") return
                end

                if mag >= 0.1 then
                    local dir = diff.Unit
                    if (allowJump or diff.Y > 10) and diff.Y > 5 and wpIdx < #waypoints then
                        local hum = hrp.Parent and hrp.Parent:FindFirstChildOfClass("Humanoid")
                        if hum then
                            local st = hum:GetState()
                            if st ~= Enum.HumanoidStateType.Jumping and st ~= Enum.HumanoidStateType.Freefall then
                                pcall(function() hum:ChangeState(Enum.HumanoidStateType.Jumping) end)
                                pcall(function() hum.Jump = true end)
                            end
                        end
                    end
                    local _sp = _spd
                    local _mc = _climbCap()
                    if dir.Y > 0 and dir.Y * _sp > _mc then
                        _sp = _mc / dir.Y
                    end
                    _prevCmd, _cmdDir = _cmdDir, dir
                    _setFlightVel(hrp, Vector3.new(dir.X * _sp, dir.Y * _sp, dir.Z * _sp))
                end
            end))

            local totalDist = 0
            do
                local prev = hrp.Position
                for _, wp in ipairs(waypoints) do
                    totalDist = totalDist + (prev - wp).Magnitude
                    prev = wp
                end
            end
            -- real time, not 0.05 per tick (at load-screen fps a task.wait(0.05)
            -- is several times longer), and every lagback the leg sat out buys
            -- back its settle plus the re-flown distance at the reduced speed
            local _settle = math.clamp(((_G.Skyr0Ping and _G.Skyr0Ping()) or 0.1) * 2 + 0.2, 0.35, 1.5)
            local timeout = totalDist / math.min(SKYR0_TP_TIMEOUT_SPEED, _runSpeed) + (tonumber(_G.Skyr0TpFlightGrace) or 2)
            local _t0 = os.clock()
            while not done and (os.clock() - _t0) < timeout + lagRecover * (_settle + 1.5) do
                task.wait(0.05)
                if not (hrp and hrp.Parent) then break end
            end
            finish()
            vZero(hrp)
            SkyrTP.lastLeg = { reason = _reason, lagbacks = lagRecover }
            return _reason, lagRecover
        end
        local _carpetEngaging = false
        local function carpetEngage(force)
            if not force then
                local c = LP.Character
                if c then
                    for _, n in ipairs(CARPET_NAMES) do
                        local t = c:FindFirstChild(n)
                        if t and t:IsA("Tool") then
                            _G.TPEngage = "carpet=" .. tostring(n)
                            return n
                        end
                    end
                end
            end
            if _carpetEngaging then
                local _tw = os.clock()
                repeat RunService.Heartbeat:Wait() until (not _carpetEngaging) or os.clock() - _tw > 6
                local c = LP.Character
                if c then
                    for _, n in ipairs(CARPET_NAMES) do
                        local t = c:FindFirstChild(n)
                        if t and t:IsA("Tool") then return n end
                    end
                end
            end
            _carpetEngaging = true
            local _t0 = os.clock()
            while not findTool("Grapple Hook") and os.clock() - _t0 < (tonumber(_G.Skyr0TpGrappleToolWait) or 5) do
                RunService.Heartbeat:Wait()
            end
            local char = LP.Character
            local hum = char and char:FindFirstChildOfClass("Humanoid")
            if not char or not hum then _carpetEngaging = false; return nil end

            if not char:FindFirstChild("Grapple Hook") then
                local g = findTool("Grapple Hook")
                if g then pcall(function() hum:EquipTool(g) end) end
            end
            local _te = os.clock()
            while not (LP.Character and LP.Character:FindFirstChild("Grapple Hook")) and os.clock() - _te < 1.5 do
                local c = LP.Character
                local h2 = c and c:FindFirstChildOfClass("Humanoid")
                local g = findTool("Grapple Hook")
                if g and h2 then pcall(function() h2:EquipTool(g) end) end
                RunService.Heartbeat:Wait()
            end
            if LP.Character and LP.Character:FindFirstChild("Grapple Hook") then
                _fireGrapple()
            end
            task.wait(0.06)
            local h = LP.Character and LP.Character:FindFirstChildOfClass("Humanoid")
            if h then pcall(function() h:UnequipTools() end) end
            task.wait(0.04)
            local cn
            local _tc = os.clock()
            repeat
                cn = equipCarpet()
                local c = LP.Character
                if cn and c and c:FindFirstChild(cn) then break end
                RunService.Heartbeat:Wait()
            until os.clock() - _tc > 0.5
            _G.TPEngage = "carpet=" .. tostring(cn)
            _carpetEngaging = false
            return cn
        end
        local function carpetEngageFast()
            local char = LP.Character
            local hum  = char and char:FindFirstChildOfClass("Humanoid")
            if not char or not hum then return nil end

            if not char:FindFirstChild("Grapple Hook") then
                local g = findTool("Grapple Hook")
                if g then pcall(function() hum:EquipTool(g) end) end
            end
            local _t = os.clock()
            while not (LP.Character and LP.Character:FindFirstChild("Grapple Hook"))
                and os.clock() - _t < (tonumber(_G.Skyr0TpGoGrappleWait) or 0.35) do
                local c = LP.Character
                local h = c and c:FindFirstChildOfClass("Humanoid")
                local g = findTool("Grapple Hook")
                if g and h then pcall(function() h:EquipTool(g) end) end
                RunService.Heartbeat:Wait()
            end
            if LP.Character and LP.Character:FindFirstChild("Grapple Hook") then
                _fireGrapple()
            end

            local h2 = LP.Character and LP.Character:FindFirstChildOfClass("Humanoid")
            if h2 then pcall(function() h2:UnequipTools() end) end
            RunService.Heartbeat:Wait()

            local cn
            local _t2 = os.clock()
            repeat
                cn = equipCarpet()
                local c = LP.Character
                if cn and c and c:FindFirstChild(cn) then break end
                RunService.Heartbeat:Wait()
            until os.clock() - _t2 > (tonumber(_G.Skyr0TpGoCarpetWait) or 2)
            return cn
        end
        local function goToBrainrot(petPos, slot)
            if not petPos then return end
            local char, hrp, hum
            local _t0 = os.clock()
            repeat
                char = LP.Character
                hrp = char and char:FindFirstChild("HumanoidRootPart")
                hum = char and char:FindFirstChildOfClass("Humanoid")
                if hrp and hum then break end
                RunService.Heartbeat:Wait()
            until os.clock() - _t0 > 3
            if not hrp or not hum then return end
            pcall(function() hrp.Anchored = false end)
            local _equipped = false
            do


                for _, _cn in ipairs(CARPET_NAMES) do
                    if char and char:FindFirstChild(_cn) then _equipped = true break end
                end
                local _gd = (petPos and hrp and hrp.Parent) and (petPos - hrp.Position).Magnitude or math.huge
                local _gmin = tonumber(_G.Skyr0TpGoGrappleMin) or 100
                if not _equipped and _G.Skyr0TpGoGrapple ~= false and _gd > _gmin then
                    pcall(carpetEngageFast)
                    char = LP.Character
                    for _, _cn in ipairs(CARPET_NAMES) do
                        if char and char:FindFirstChild(_cn) then _equipped = true break end
                    end
                end
                local _e0 = os.clock()
                while not _equipped and os.clock() - _e0 <= (tonumber(_G.Skyr0TpGoCarpetWait) or 3) do
                    char = LP.Character
                    for _, _cn in ipairs(CARPET_NAMES) do
                        if char and char:FindFirstChild(_cn) then _equipped = true break end
                    end
                    if _equipped then break end
                    equipCarpet()
                    RunService.Heartbeat:Wait()
                end
                if _equipped then task.wait(tonumber(_G.Skyr0TpGoCarpetSettle) or 0.02) end
            end
            char = LP.Character
            hrp = char and char:FindFirstChild("HumanoidRootPart")
            hum = char and char:FindFirstChildOfClass("Humanoid")
            if not hrp then return end
            pcall(function() hrp.Anchored = false end)
            local _plotRad = (petPos.Y <= 8.9) and 26 or 25
            do
                local _t0b = os.clock()
                repeat
                    local p = hrp.Position
                    local inRad = false
                    local plotsFolder = workspace:FindFirstChild("Plots")
                    if plotsFolder then
                        for _, plot in ipairs(plotsFolder:GetChildren()) do
                            pcall(function()
                                local pp = plot:GetPivot().Position
                                if math.abs(p.X - pp.X) < _plotRad and math.abs(p.Z - pp.Z) < _plotRad then inRad = true end
                            end)
                            if inRad then break end
                        end
                    end
                    if inRad then break end
                    RunService.Heartbeat:Wait()
                until os.clock() - _t0b > (tonumber(_G.Skyr0TpGoPlotWait) or 1)
            end
            local h = petPos.Y
            pcall(function()
                hrp.AssemblyLinearVelocity = Vector3.new(0, 0, 0)
                hrp.AssemblyAngularVelocity = Vector3.new(0, 0, 0)
            end)
            local _wentUnder = false
            local _slot = tonumber(slot)
            local _under = tonumber(_G.Skyr0TpUnderOffset) or 6
            local targetY = hrp.Position.Y
            if (_slot and _slot >= 19) or (not _slot and h > 23.15) then
                targetY = h - (tonumber(_G.Skyr0TpUnderOffset3) or 4)
                _wentUnder = true
            elseif (_slot and _slot >= 11) or (not _slot and h >= 11 and h <= 23.15) then


                targetY = h - (tonumber(_G.Skyr0TpUnderOffset2) or 3.5)
                _wentUnder = true
            elseif (_slot and _slot >= 1) or (not _slot and h >= -6.9 and h <= 8.9) then
                targetY = tonumber(_G.Skyr0TpFloor1Y) or -4
                if _G.Skyr0TpFloor1Platform ~= false then _wentUnder = true end
            else
                targetY = h - _under
                _wentUnder = true
            end
            -- after a 2nd-floor FLASH you are already standing on that floor:
            -- stay at your height (the "under the brainrot" Y dragged you down
            -- through the floor) and no platform
            if _G.Skyr0TpGoKeepY == true and hrp and hrp.Parent then
                targetY = hrp.Position.Y
                _wentUnder = false
            end
            local _to = Vector3.new(petPos.X, targetY, petPos.Z)
            if hrp and hrp.Parent then


                local _roseDone = false
                if _G.Skyr0RoseWalk then
                    local _okR, _r = pcall(_G.Skyr0RoseWalk, hrp, _to, hrp.CFrame - hrp.CFrame.Position)
                    _roseDone = _okR and _r == true
                end
                if not _roseDone then
                -- WALK TO BRAINROT = INSTANT CFRAME. The velocity glide below is
                -- skipped (opt back in with _G.Skyr0TpGoGlide = true); the snap
                -- right after it puts you straight under the brainrot.
                if _G.Skyr0TpGoGlide == true then
                    local _goSpeed = tonumber(_G.Skyr0TpGoSpeed) or 400
                    local _s1 = tonumber(_G.Skyr0TpGoGlideSpeed1) or (_goSpeed * 0.375)
                    local _t1 = tonumber(_G.Skyr0TpGoGlideTime1) or 0.03
                    local _s2 = tonumber(_G.Skyr0TpGoGlideSpeed2) or _goSpeed
                    local _cap = tonumber(_G.Skyr0TpGoGlideMax) or 2.5
                    local _g0 = os.clock()
                    local _lastJump = 0
                    while os.clock() - _g0 < _cap do
                        if not (hrp and hrp.Parent) then break end
                        if LP:GetAttribute("Stealing") or _G.Skyr0TPCancel then break end
                        local d = _to - hrp.Position
                        if d.Magnitude <= 3 then break end
                        equipCarpet()
                        if _G.Skyr0TpGoJump == true and d.Magnitude > 15 and (os.clock() - _lastJump) > 0.5 then
                            local _gh = hrp.Parent and hrp.Parent:FindFirstChildOfClass("Humanoid")
                            if _gh then
                                pcall(function() _gh:ChangeState(Enum.HumanoidStateType.Jumping) end)
                                pcall(function() _gh.Jump = true end)
                                _lastJump = os.clock()
                            end
                        end
                        if _G.Skyr0TpGoZeroEachFrame ~= false then
                            pcall(function()
                                hrp.AssemblyLinearVelocity = Vector3.new(0, 0, 0)
                                hrp.AssemblyAngularVelocity = Vector3.new(0, 0, 0)
                            end)
                        end
                        local _v = d.Unit * (((os.clock() - _g0) < _t1) and _s1 or _s2)
                        if _G.Skyr0TpGoNoRise ~= false and hrp.Position.Y >= _to.Y - 0.5 and _v.Y > 0 then
                            _v = Vector3.new(_v.X, 0, _v.Z)
                        end
                        _setFlightVel(hrp, _v)
                        RunService.Heartbeat:Wait()
                    end
                end
                local _snapCF = CFrame.new(_to) * (hrp.CFrame - hrp.CFrame.Position)
                pcall(function()
                    hrp.AssemblyLinearVelocity = Vector3.new(0, 0, 0)
                    hrp.AssemblyAngularVelocity = Vector3.new(0, 0, 0)
                    hrp.CFrame = _snapCF
                end)


                for _ = 1, (tonumber(_G.Skyr0TpSnapHoldFrames) or 8) do
                    RunService.Heartbeat:Wait()
                    if not (hrp and hrp.Parent) then break end
                    if (hrp.Position - _to).Magnitude > 4 then
                        pcall(function()
                            hrp.CFrame = _snapCF
                        end)
                    end
                end
                end   -- not _roseDone
            end
            if _wentUnder and _G.Skyr0TpPlatform ~= false then
                local _platPos = (hrp and hrp.Parent and hrp.Position) or _to
                local _feetY = _platPos.Y - 3
                local _sz = tonumber(_G.Skyr0TpPlatSize) or 10
                local _old = workspace:FindFirstChild("ANGVELSTempPlatform")
                if _old then pcall(function() _old:Destroy() end) end
                local _plat = Instance.new("Part")
                _plat.Name = "ANGVELSTempPlatform"; _plat.Size = Vector3.new(_sz, 1, _sz)
                _plat.Position = Vector3.new(petPos.X, _feetY - (tonumber(_G.Skyr0TpPlatDrop) or 1.5), petPos.Z)
                _plat.Anchored = true; _plat.CanCollide = false; pcall(makeOneWay, _plat); _plat.Transparency = 1
                _plat.Material = Enum.Material.SmoothPlastic; _plat.Parent = workspace
                task.spawn(function()
                    local _s = tick()
                    while tick() - _s < (tonumber(_G.Skyr0TpPlatLife) or 20) do
                        if LP:GetAttribute("Stealing") then break end
                        task.wait(0.1)
                    end
                    if _plat and _plat.Parent then _plat:Destroy() end
                end)
            end
        end
        local _Stats = game:GetService("Stats")
        local function _pingMs()
            local ok, p = pcall(function() return LP:GetNetworkPing() * 1000 end)
            if ok and type(p) == "number" and p > 0 then return p end
            local ok2, p2 = pcall(function()
                return _Stats.Network.ServerStatsItem["Data Ping"]:GetValue()
            end)
            if ok2 and type(p2) == "number" and p2 > 0 then return p2 end
            return 0
        end
        _G.Skyr0TpPingMs = _pingMs
        local function _pingAdjustSpeed(spd)
            local thresh = tonumber(_G.Skyr0TpPingThresh) or 170
            local capped = tonumber(_G.Skyr0TpHighPingSpeed) or 400
            if _pingMs() >= thresh and spd > capped then return capped end
            return spd
        end
        local function _isStraightRoute(fromPos, route)
            if not route or #route <= 1 then return true end
            local turns, lastDir, prev = 0, nil, fromPos
            for _, wp in ipairs(route) do
                local seg = wp - prev
                if seg.Magnitude > 1 then
                    local dir = seg.Unit
                    if lastDir and dir:Dot(lastDir) < 0.94 then turns = turns + 1 end
                    lastDir = dir
                end
                prev = wp
            end
            return turns <= (tonumber(_G.Skyr0TpStraightMaxTurns) or 1)
        end
        local function _inVoid(hrp)
            if not hrp or not hrp.Parent then return true end
            local voidY = tonumber(_G.Skyr0TpVoidY) or -50
            return hrp.Position.Y < voidY
        end
        local function run(pet, forceGrapple)
            -- (doVelocityTP has already done the guard, the scan and the pick; `pet` is its
            --  answer. Everything from here keeps its original call order and timing.)
            local char = LP.Character
            local hrp = char and char:FindFirstChild("HumanoidRootPart")
            local hum = char and char:FindFirstChildOfClass("Humanoid")
            if not hrp or not hum then isTeleporting = false; return end

            pcall(function()
                hrp.AssemblyLinearVelocity = Vector3.new(0, 0, 0)
                hrp.AssemblyAngularVelocity = Vector3.new(0, 0, 0)
            end)

            -- where the hook should point (the clone spot)
            SkyrTP.aim = nil
            pcall(function()
                local sd = pickCloneSpot(pet.position, pet.name, hrp.Position)
                if typeof(sd) == "Vector3" then SkyrTP.aim = sd end
            end)

            -- the hook goes out FIRST, before anything else
            if forceGrapple or _G.Skyr0TpAlwaysGrapple ~= false then
                pcall(fireGrapple)
            end

            if _inVoid(hrp) then
                if _G.Skyr0TPCancel then isTeleporting = false; return end
                char = LP.Character
                hrp = char and char:FindFirstChild("HumanoidRootPart")
                hum = char and char:FindFirstChildOfClass("Humanoid")
                if not hrp or not hum then isTeleporting = false; return end
            end

            local petPos = pet.position
            local petName = pet.name
            warn(string.format("[skyr0] TP: %s | Y %.1f | %.0f studs away", tostring(petName), petPos.Y,
                (petPos - hrp.Position).Magnitude))

            _G.Skyr0TpStealHold = true

            local _hasCarpet = false
            do
                local _c = LP.Character
                if _c then
                    for _, _n in ipairs(CARPET_NAMES) do
                        if _c:FindFirstChild(_n) then _hasCarpet = true break end
                    end
                end
            end
            if not _hasCarpet then
                pcall(fireGrapple)
            end

            local adjY = petPos.Y
            if TALL_PETS[petName] then adjY = petPos.Y - TALL_OFFSET end
            local coordTable = adjY > 23.15 and UPPER or LOWER

            -- The walk-in through the front door is OPT-IN (_G.Skyr0WalkInFirstFloor = true).
            -- It has no wall clone, and it is taken whenever the base happens to be
            -- unlocked -- which is mid-round (the keybind) but not at join (TP-on-load,
            -- where the bases are still locked). That is why on-load cloned at the wall
            -- and the keybind did not. Default: always the wall clone.
            if _G.Skyr0WalkInFirstFloor == true and petPos.Y <= 8.9 and isPlotUnlocked(pet.plot) then
                if not _hasCarpet then carpetEngage(forceGrapple) end
                vZero(hrp)
                local _to = Vector3.new(petPos.X, -4, petPos.Z)
                local route = computeRoute(hrp.Position, _to, nil)
                if not route or #route == 0 then route = { _to } end
                local _straight = _isStraightRoute(hrp.Position, route)
                local _obSpeed = math.clamp(_spd(), 60, 750)
                if _straight then
                    _obSpeed = math.clamp(tonumber(_G.Skyr0TpStraightSpeed) or 300, 100, 500)
                end
                do
                    local _len, _prev = 0, hrp.Position
                    for _, wp in ipairs(route) do _len = _len + (wp - _prev).Magnitude; _prev = wp end
                    if _len < 100 then
                        _obSpeed = math.clamp(tonumber(_G.Skyr0TpCloseSpeed) or 80, 20, 400)
                    end
                end
                _obSpeed = _pingAdjustSpeed(_obSpeed)
                velMoveThrough(hrp, route, _obSpeed, true, true)
                if hrp and hrp.Parent and not _G.Skyr0TPCancel
                   and (hrp.Position - _to).Magnitude > 12 then
                    local _rr2 = computeRoute(hrp.Position, _to, nil)
                    if not _rr2 or #_rr2 == 0 then _rr2 = { _to } end
                    velMoveThrough(hrp, _rr2, _obSpeed, true, true)
                end
                if hrp and hrp.Parent then
                    _vzL(hrp)
                    _vzA(hrp)
                end
                _G.Skyr0TpStealHold = false
                pcall(settleAfterTP)
                _tpAnchor = nil
                isTeleporting = false
                if _G.Skyr0TPCancel then return end
                return
            end

            -- FRONT / LEFT / RIGHT: every clone spot of this base, best first (a spot
            -- that got us stuck lately ranks last). See MV.spots.
            if _G.Skyr0BadSpots then table.clear(_G.Skyr0BadSpots) end
            local _cands = MV.spots.candidates(petPos, petName, hrp.Position, coordTable)
            if #_cands == 0 then _G.Skyr0TpStealHold = false; _tpAnchor = nil; isTeleporting = false; return end

            local destPos = _cands[1].coord

            local _carpet = _hasCarpet and (function()
                local _c = LP.Character
                if _c then
                    for _, _n in ipairs(CARPET_NAMES) do
                        if _c:FindFirstChild(_n) then return _n end
                    end
                end
                return nil
            end)() or carpetEngage(forceGrapple)
            vZero(hrp)
            _cloneTP = true
            disarmSteal()

            local facingDir = _cands[1].face
            local _frontApproach = false
            local _spotCoord, _spotKind = _cands[1].coord, _cands[1].kind
            -- FLASH TP: same wall spot, a little further off it, Flash Teleport
            -- instead of the clone. Needs the tool -- otherwise the clone as usual.
            SkyrTP.flash = _G.Skyr0FlashWanted and _G.Skyr0FlashWanted()
                and _G.Skyr0HasFlash and _G.Skyr0HasFlash() or false
            if SkyrTP.flash and _G.Skyr0FlashReady and not _G.Skyr0FlashReady() then
                SkyrTP.flash = false
                warn("[skyr0] Flash TP: flash on cooldown -- using the old grapple TP")
            end
            SkyrTP.frontX = nil
            for _, c in ipairs(_cands) do
                if c.kind == "front" then SkyrTP.frontX = c.coord.X; break end
            end
            _G.Skyr0FlashOnce = nil
            -- FIXED SPOTS first (hand-measured, every plot); none for this floor -> computed plan
            SkyrTP.fixed = nil
            if SkyrTP.flash and _G.Skyr0FlashFixed and _G.Skyr0FlashUseFixed ~= false then
                pcall(function()
                    local pl = workspace:FindFirstChild("Plots")
                    pl = pl and pet.plot and pl:FindFirstChild(tostring(pet.plot))
                    if pl then SkyrTP.fixed = _G.Skyr0FlashFixed(pl, petPos, hrp.Position) end
                end)
                if SkyrTP.fixed then
                    warn(("[skyr0] Flash TP: fixed spot '%s' (floor %d)"):format(SkyrTP.fixed.name, SkyrTP.fixed.floor))
                end
            end
            -- FLASH PLAN for one spot. entry = where you cross the wall (the side
            -- window, else the wall spot); out = which way is outside. The stand
            -- point is the point CLOSEST TO YOU that is still in flash range of the
            -- entry -- the shortest flight the range allows, none at all when you
            -- are already in range. Range is measured from the root with a LEVEL
            -- aim (looking up/down shortens it): 39.87 minus the landing depth past
            -- the entry (_G.Skyr0FlashInside, 5) and a margin (_G.Skyr0FlashMargin, 1.5).
            -- The stand stays within _G.Skyr0FlashMaxAngle (55) of straight out, so
            -- the line still goes through the entry and not along the wall.
            SkyrTP.flashPlan = function(c)
                local entry, out = c.coord, nil
                if c.kind ~= "front" then
                    pcall(function()
                        local pl = workspace:FindFirstChild("Plots")
                        pl = pl and pet.plot and pl:FindFirstChild(tostring(pet.plot))
                        if pl and _G.Skyr0FlashWindow then
                            local wp, wo = _G.Skyr0FlashWindow(pl, petPos, c.coord)
                            if wp then entry, out = Vector3.new(wp.X, c.coord.Y, wp.Z), wo end
                        end
                    end)
                end
                if not out then
                    local f = (c.face and c.face.Magnitude > 0.1) and Vector3.new(c.face.X, 0, c.face.Z).Unit
                        or Vector3.new(1, 0, 0)
                    out = (f:Dot(entry - petPos) >= 0) and f or -f
                end
                local inside = tonumber(_G.Skyr0FlashInside) or 5
                local reach = (tonumber(_G.Skyr0FlashRange) or 39.87) - (tonumber(_G.Skyr0FlashMargin) or 4) - inside
                local v = Vector3.new(hrp.Position.X - entry.X, 0, hrp.Position.Z - entry.Z)
                local dir = out
                if v.Magnitude > 0.5 then
                    local vu, maxA = v.Unit, math.rad(tonumber(_G.Skyr0FlashMaxAngle) or 55)
                    if vu:Dot(out) >= math.cos(maxA) then
                        dir = vu
                    else
                        local t = vu - out * vu:Dot(out)
                        if t.Magnitude > 0.01 then dir = out * math.cos(maxA) + t.Unit * math.sin(maxA) end
                    end
                end
                local dist = math.clamp(v.Magnitude, 2.5, math.max(reach, 2.5))
                -- something outside in the way (sign, the next base): stop short of it
                pcall(function()
                    local rp = RaycastParams.new()
                    rp.FilterType = Enum.RaycastFilterType.Exclude
                    rp.FilterDescendantsInstances = { LP.Character }
                    local o = entry + dir * 0.5
                    local hit = workspace:Raycast(o, dir * dist, rp)
                    if hit then dist = math.max(2.5, (hit.Position - o).Magnitude - 2) end
                end)
                return { entry = entry, out = out, dir = dir,
                         stand = entry + dir * dist, land = entry - dir * inside }
            end
            -- the spot the plain clone TP would use (before the flash re-sort):
            -- the fallback clone spot when the flash turns out to be on cooldown
            SkyrTP.cloneCand = _cands[1]
            -- flash mode: the spot with the SHORTEST flight to its stand point wins
            if SkyrTP.flash then
                for _, c in ipairs(_cands) do
                    local okP, fp = pcall(SkyrTP.flashPlan, c)
                    c.fscore = (okP and fp and (hrp.Position - fp.stand).Magnitude or math.huge)
                        + (MV.spots.isBad(c.coord) and 20000 or 0)
                end
                table.sort(_cands, function(a, b) return a.fscore < b.fscore end)
            end
            -- the chosen spot -> destPos / facingDir, backed off the wall on the side
            -- you arrive from. Used for the first pick AND any later switch.
            local function useSpot(c)
                _spotCoord, _spotKind = c.coord, c.kind
                destPos, facingDir = c.coord, c.face
                _frontApproach = (c.kind == "front")
                if facingDir and facingDir.Magnitude > 0.1 then
                    local axis = facingDir.Unit
                    local toPlayer = hrp.Position - destPos
                    local sign = (axis:Dot(toPlayer) >= 0) and 1 or -1
                    destPos = destPos + axis * sign * (SkyrTP.flash and (tonumber(_G.Skyr0FlashBackoff) or 2)
                        or (tonumber(_G.Skyr0TpCloneBackoff) or 0.5))
                end
                -- this side's wall CLONE spot, kept for the fallback when the flash
                -- turns out to be on cooldown mid-TP (same backoff the clone TP uses)
                do
                    local _cc = (SkyrTP.flash and SkyrTP.cloneCand) or c
                    local _cp = _cc.coord
                    if _cc.face and _cc.face.Magnitude > 0.1 then
                        local _ax = _cc.face.Unit
                        local _sg = (_ax:Dot(hrp.Position - _cp) >= 0) and 1 or -1
                        _cp = _cp + _ax * _sg * (tonumber(_G.Skyr0TpCloneBackoff) or 0.5)
                    end
                    SkyrTP.cloneSpot = { pos = _cp, face = _cc.face }
                end
                -- FLASH: stand at the plan's point (see SkyrTP.flashPlan), facing the entry
                SkyrTP.flashNear, SkyrTP.flashYaw, SkyrTP.flashAim = nil, 0, nil
                SkyrTP.flashEntry, SkyrTP.flashOut, SkyrTP.flashCam = nil, nil, nil
                if SkyrTP.flash and SkyrTP.fixed then
                    local fs = SkyrTP.fixed
                    destPos = fs.pos
                    facingDir = Vector3.new(fs.look.X, 0, fs.look.Z).Unit
                    SkyrTP.flashCam, SkyrTP.flashAim = fs, fs.pos + fs.look * 39
                elseif SkyrTP.flash then
                    local fp = SkyrTP.flashPlan(c)
                    destPos, facingDir = fp.stand, -fp.dir
                    SkyrTP.flashNear = fp.entry + fp.out * 2
                    SkyrTP.flashAim, SkyrTP.flashEntry, SkyrTP.flashOut = fp.land, fp.entry, fp.out
                    -- side TP: aim a little to the right by default
                    SkyrTP.flashYaw = (c.kind ~= "front") and (tonumber(_G.Skyr0FlashSideRight) or 12) or 0
                end
            end
            useSpot(_cands[1])

            -- ============================================================
            --  STREAM THE TARGET BASE IN BEFORE PLANNING.  (TP-on-load)
            --
            --  Every launch now goes Skyr0LaunchTP -> dispatcher -> here, which
            --  skips the grapple cycle -- and the cycle was the only place that
            --  asked for the destination region. So on a fresh join the router
            --  planned against a target base whose walls had not streamed in:
            --  as far as the client knew there was nothing there, the route went
            --  straight through them, and the server answered with lagback after
            --  lagback. Asked for here, and the planner waits (bounded,
            --  _G.Skyr0TpStreamWait, 3s) until the base actually has its parts.
            --  Mid-game the base is already there and this costs nothing.
            -- ============================================================
            if workspace.StreamingEnabled then
                local _sp = destPos
                task.spawn(function() pcall(function() LP:RequestStreamAroundAsync(_sp) end) end)
                local _plotsF = workspace:FindFirstChild("Plots")
                local _tplot = _plotsF and pet.plot and _plotsF:FindFirstChild(tostring(pet.plot))
                if _tplot and MV.plotHull then
                    local _w0 = os.clock()
                    local _cap = tonumber(_G.Skyr0TpStreamWait) or 3
                    local _h = MV.plotHull(_tplot, true)
                    if not (_h and _h.ready) then
                        while os.clock() - _w0 < _cap and not _G.Skyr0TPCancel do
                            task.wait(0.1)
                            _h = MV.plotHull(_tplot, true)
                            if _h and _h.ready then break end
                        end
                        warn(string.format("[skyr0] TP: waited %.2fs for the target base to stream in (%s)",
                            os.clock() - _w0, (_h and _h.ready) and "loaded" or "gave up"))
                    end
                end
            end

            local _route = computeRoute(hrp.Position, destPos, facingDir, nil, _G.Skyr0TpCrestRoute == true)

            local ASCEND_STEP = 10
            local _stepped = {}
            do
                local prev = hrp.Position
                for _, wp in ipairs(_route) do
                    local dy = wp.Y - prev.Y
                    if dy > ASCEND_STEP * 1.5 then
                        local n = math.ceil(dy / ASCEND_STEP)
                        for s = 1, n - 1 do
                            local t = s / n
                            _stepped[#_stepped + 1] = Vector3.new(
                                prev.X + (wp.X - prev.X) * t,
                                prev.Y + dy * t,
                                prev.Z + (wp.Z - prev.Z) * t
                            )
                        end
                    end
                    _stepped[#_stepped + 1] = wp
                    prev = wp
                end
            end
            local _mainSpeed = math.clamp(_spd(), 60, 750)
            local _targetIdx = getClosestBaseIdx(petPos)
            local _targetIsWest = _targetIdx <= 4
            local _playerIsWest = hrp.Position.X < COLUMN_SPLIT_X
            local _crossRow = _targetIsWest ~= _playerIsWest
            local _isLower = coordTable == LOWER
            local _toTarget = (petPos - hrp.Position).Unit
            local _lookDir = hrp.CFrame.LookVector
            local _dot = _toTarget:Dot(_lookDir)
            local _isBehind = _dot < -0.3
            local _isProblemTP = _crossRow and _frontApproach and _isLower and _isBehind
            do
                local _len, _prev = 0, hrp.Position
                for _, wp in ipairs(_route) do _len = _len + (wp - _prev).Magnitude; _prev = wp end
                if _len < 100 then
                    _mainSpeed = math.clamp(tonumber(_G.Skyr0TpCloseSpeed) or 80, 20, 400)
                end
                if _isProblemTP and _G.Skyr0TpSlowCrossRow == true then
                    _mainSpeed = math.clamp(tonumber(_G.Skyr0TpProblemBaseSpeed) or 60, 20, 400)
                end
            end
            _mainSpeed = _pingAdjustSpeed(_mainSpeed)
            -- how far (flat) we are from the current spot
            local function flatOffNow()
                return Vector3.new(destPos.X - hrp.Position.X, 0, destPos.Z - hrp.Position.Z).Magnitude
            end
            -- a fresh, ascent-stepped route from where we ARE to the current spot
            local function routeHere()
                local r = computeRoute(hrp.Position, destPos, facingDir, nil, _G.Skyr0TpCrestRoute == true)
                if not r or #r == 0 then r = { destPos } end
                local out, prev = {}, hrp.Position
                for _, wp in ipairs(r) do
                    local dy = wp.Y - prev.Y
                    if dy > ASCEND_STEP * 1.5 then
                        local n = math.ceil(dy / ASCEND_STEP)
                        for s = 1, n - 1 do
                            local t = s / n
                            out[#out + 1] = Vector3.new(
                                prev.X + (wp.X - prev.X) * t,
                                prev.Y + dy * t,
                                prev.Z + (wp.Z - prev.Z) * t)
                        end
                    end
                    out[#out + 1] = wp
                    prev = wp
                end
                return out
            end
            -- this spot got us stuck: remember it and take the next-best one
            -- (front <-> left <-> right), ranked again from where we are now
            local function nextSpot()
                MV.spots.markBad(_spotCoord)
                for _, c in ipairs(MV.spots.candidates(petPos, petName, hrp.Position, coordTable)) do
                    if not MV.spots.isBad(c.coord) then useSpot(c); return true end
                end
                return false
            end
            local _legWhy = velMoveThrough(hrp, _stepped, _mainSpeed, true, true)
            if _G.Skyr0TPCancel then
                if hrp and hrp.Parent then vZero(hrp) end
                _G.Skyr0TpStealHold = false
                isTeleporting = false
                return
            end

            -- STUCK FAR FROM THE SPOT (the leg died on the sign, a wall, another base):
            -- do not spend the hop and run-in phases on a spot we can not reach --
            -- switch to the next one and fly there from where we are. At most 2 switches.
            --
            -- A leg the SERVER ended (lagbacks) is not a bad spot. Marking it bad
            -- and flying to a different side of the base is what made the TP look
            -- like it kept restarting: lag -> new spot -> lag -> another spot. Those
            -- legs re-plan from where the server left us and go to the SAME spot,
            -- after letting the connection settle (_G.Skyr0TpLagRetries, 2).
            do
                local _sw, _lagTries = 0, 0
                local _maxLag = tonumber(_G.Skyr0TpLagRetries) or 2
                while hrp and hrp.Parent and not _G.Skyr0TPCancel
                      and flatOffNow() > (tonumber(_G.Skyr0TpStuckDist) or 22) do
                    if _legWhy == "lagback" and _lagTries < _maxLag then
                        _lagTries = _lagTries + 1
                        warn(string.format("[skyr0] TP: leg ended on lagbacks -- same %s spot, re-planned from here (%d/%d)",
                            tostring(_spotKind), _lagTries, _maxLag))
                        local _png = (_G.Skyr0Ping and _G.Skyr0Ping()) or 0.1
                        task.wait(math.clamp(_png * 3 + 0.3, 0.5, 2))
                    else
                        if _sw >= (tonumber(_G.Skyr0TpAltSpots) or 2) then break end
                        if not nextSpot() then break end
                        _sw = _sw + 1
                    end
                    _legWhy = velMoveThrough(hrp, routeHere(), _mainSpeed, true, true)
                end
            end

            do
                local above = destPos + Vector3.new(0, 16, 0)
                local _t0 = os.clock()
                local _lastJump = 0
                while not SkyrTP.flash and os.clock() - _t0 < 1.5 do
                    if not hrp or not hrp.Parent then break end
                    if LP:GetAttribute("Stealing") or _G.Skyr0TPCancel then break end
                    equipCarpet()
                    local d = above - hrp.Position
                    local flat = Vector3.new(d.X, 0, d.Z).Magnitude
                    if flat <= 3 and hrp.Position.Y >= destPos.Y then break end
                    if d.Y > 3 and (os.clock() - _lastJump) > 0.5 then
                        local _hum = hrp.Parent and hrp.Parent:FindFirstChildOfClass("Humanoid")
                        if _hum then
                            local st = _hum:GetState()
                            if st ~= Enum.HumanoidStateType.Jumping and st ~= Enum.HumanoidStateType.Freefall then
                                pcall(function() _hum:ChangeState(Enum.HumanoidStateType.Jumping) end)
                                pcall(function() _hum.Jump = true end)
                                _lastJump = os.clock()
                            end
                        end
                    end
                    _setFlightVel(hrp, d.Unit * math.min(math.max(d.Magnitude * 8, 55), 320))
                    _vzA(hrp)
                    RunService.Heartbeat:Wait()
                end
            end

            do
                local _runCap = _frontApproach and (tonumber(_G.Skyr0TpFrontRunIn) or 130) or 400
                local _t0 = os.clock()
                local _bestMag, _bestT = math.huge, os.clock()
                local _lastJump = 0
                while os.clock() - _t0 < 4 do
                    if not hrp or not hrp.Parent then break end
                    if LP:GetAttribute("Stealing") or _G.Skyr0TPCancel then break end
                    equipCarpet()
                    local diff = destPos - hrp.Position
                    local mag = diff.Magnitude
                    if mag <= 3 then break end
                    if mag < _bestMag - 0.5 then _bestMag = mag; _bestT = os.clock()
                    elseif os.clock() - _bestT > 0.6 then break end
                    if diff.Y > 3 and mag > 15 and (os.clock() - _lastJump) > 0.5 then
                        local _hum = hrp.Parent and hrp.Parent:FindFirstChildOfClass("Humanoid")
                        if _hum then
                            local st = _hum:GetState()
                            if st ~= Enum.HumanoidStateType.Jumping and st ~= Enum.HumanoidStateType.Freefall then
                                pcall(function() _hum:ChangeState(Enum.HumanoidStateType.Jumping) end)
                                pcall(function() _hum.Jump = true end)
                                _lastJump = os.clock()
                            end
                        end
                    end
                    _setFlightVel(hrp, diff.Unit * math.min(math.max(mag * 8, 55), _runCap))
                    _vzA(hrp)
                    RunService.Heartbeat:Wait()
                end
            end

            if hrp and hrp.Parent and not _G.Skyr0TPCancel then
                local _flatOff = Vector3.new(destPos.X - hrp.Position.X, 0, destPos.Z - hrp.Position.Z).Magnitude
                if _flatOff > 10 then
                    -- REACH RECOVER: re-plan from where we ACTUALLY are, not the stale
                    -- route from the original launch point (that route's first leg can
                    -- point back toward where we took off from if we are now well past
                    -- it -- exactly the wrong direction on a long flight).
                    warn(string.format("[skyr0] TP: %.0f studs off the %s clone spot -- re-pathing from here", _flatOff, tostring(_spotKind)))
                    local _rrWhy = velMoveThrough(hrp, routeHere(), _mainSpeed, true, true)
                    if hrp and hrp.Parent and not _G.Skyr0TPCancel and flatOffNow() > 10
                       and _rrWhy ~= "lagback" and nextSpot() then
                        warn("[skyr0] TP: still stuck -> the " .. tostring(_spotKind) .. " spot instead")
                        velMoveThrough(hrp, routeHere(), _mainSpeed, true, true)
                    end
                    if hrp and hrp.Parent then
                        _vzL(hrp)
                        _vzA(hrp)
                    end
                end
            end

            if hrp and hrp.Parent then
                hrp.CFrame = CFrame.new(hrp.Position, hrp.Position + facingDir)
            end
            vZero(hrp)

            local syncFrames = 3
            local syncConn
            syncConn = RunService.Heartbeat:Connect(LPH_NO_VIRTUALIZE(function()
                if not hrp or not hrp.Parent then syncConn:Disconnect(); return end
                syncFrames = syncFrames - 1
                hrp.CFrame = CFrame.new(destPos, destPos + facingDir)
                _vzL(hrp)
                _vzA(hrp)
                if syncFrames <= 0 then syncConn:Disconnect() end
            end))

            local _landTries = SkyrTP.flash and 0 or (tonumber(_G.Skyr0TpMaxLandTries) or 3)
            local _landGap   = tonumber(_G.Skyr0TpLandCheckGap) or 0.03
            for _ = 1, _landTries do
                task.wait(_landGap)
                if hum.FloorMaterial ~= Enum.Material.Air then break end
            end

            do
                local stable, _st0 = 0, os.clock()
                local _cap = SkyrTP.flash and (tonumber(_G.Skyr0FlashStableWait) or 0.06)
                    or (tonumber(_G.Skyr0TpStableWait) or 0.3)
                while os.clock() - _st0 < _cap do
                    if _G.Skyr0TPCancel then break end
                    local _hrp = char and char:FindFirstChild("HumanoidRootPart")
                    if not _hrp or not _hrp.Parent then break end
                    local flat = (Vector3.new(_hrp.Position.X, 0, _hrp.Position.Z) - Vector3.new(destPos.X, 0, destPos.Z)).Magnitude
                    if flat <= 3.5 and math.abs(_hrp.Position.Y - destPos.Y) <= 4 then
                        stable = stable + 1
                        if stable >= 2 then break end
                    else
                        stable = 0
                        pcall(function() _hrp.CFrame = CFrame.new(destPos, destPos + facingDir) end)
                        _vzL(_hrp)
                        _vzA(_hrp)
                    end
                    RunService.Heartbeat:Wait()
                end
            end
            _cloneFired = true
            -- a Base Camp slot is a place to stand, not a pet to steal
            if not pet.campSlot then armSteal(pet); _commitTP(pet, true) end
            local _ahrp = LP.Character and LP.Character:FindFirstChild("HumanoidRootPart")
            local _clonePos = (_ahrp and _ahrp.Parent and _ahrp.Position) or destPos

            local _clonePlat = Instance.new("Part")
            _clonePlat.Name = "Skyr0TPClonePlatform"
            _clonePlat.Size = Vector3.new(12, 1, 12)
            _clonePlat.Position = Vector3.new(_clonePos.X, _clonePos.Y - 3, _clonePos.Z)
            _clonePlat.Anchored = true
            _clonePlat.CanCollide = true
            _clonePlat.Transparency = 1
            _clonePlat.Material = Enum.Material.SmoothPlastic
            _clonePlat.Parent = workspace

            if _ahrp and _ahrp.Parent then
                _vzL(_ahrp)
                _vzA(_ahrp)
            end

            local _preClonePos, _preCloneChar
            do
                _preCloneChar = LP.Character
                local _h = _preCloneChar and _preCloneChar:FindFirstChild("HumanoidRootPart")
                _preClonePos = _h and _h.Position or destPos
            end
            local _charAdded = false
            local _caConn = LP.CharacterAdded:Connect(function() _charAdded = true end)

            _G.Skyr0TpStealHold = false

            if not SkyrTP.flash then task.wait(_cloneDelay()) end

            if not SkyrTP.flash and facingDir and facingDir.Magnitude > 0.1 then
                local _pinHum = LP.Character and LP.Character:FindFirstChildOfClass("Humanoid")
                if _pinHum then pcall(function() _pinHum.AutoRotate = false end) end
                for _ = 1, 2 do
                    local _h = LP.Character and LP.Character:FindFirstChild("HumanoidRootPart")
                    if not _h or not _h.Parent then break end
                    pcall(function()
                        _h.CFrame = CFrame.new(_h.Position, _h.Position + facingDir)
                        _vzL(_h)
                        _vzA(_h)
                    end)
                    RunService.Heartbeat:Wait()
                end
            end

            local _cloneOk
            if SkyrTP.flash then
                warn("[skyr0] TP: Flash Teleport through the wall")
                local _okF, _movedF = pcall(_G.Skyr0DoFlash, SkyrTP.flashAim or petPos, SkyrTP.flashYaw,
                    SkyrTP.flashEntry, SkyrTP.flashOut, SkyrTP.flashCam)
                _cloneOk = _okF and _movedF
                local _cd = tonumber(_G.Skyr0FlashCooldown) or 0
                if _cloneOk and _G.Skyr0FlashCheckCloser ~= false then
                    local _h = LP.Character and LP.Character:FindFirstChild("HumanoidRootPart")
                    if _h and _preClonePos then
                        local _before = Vector3.new(_preClonePos.X - petPos.X, 0, _preClonePos.Z - petPos.Z).Magnitude
                        local _after = Vector3.new(_h.Position.X - petPos.X, 0, _h.Position.Z - petPos.Z).Magnitude
                        if _after > _before - 5 then
                            warn("[skyr0] Flash TP: flashed the wrong way -- grapple clone TP")
                            _cloneOk = false
                        end
                    end
                end
                SkyrTP.flashHit = _cloneOk and true or false
                if _cloneOk then
                    _G.Skyr0FlashCdUntil = os.clock() + _cd
                else
                    -- the flash did not move us: on cooldown (or blocked). Treat it as
                    -- cooling down for a bit and finish with the OLD GRAPPLE TP's
                    -- swap: carpet to this side's wall clone spot, face the wall, clone.
                    _G.Skyr0FlashCdUntil = os.clock() + math.max(_cd, 3)
                    local _cs = SkyrTP.cloneSpot
                    local _nh = LP.Character and LP.Character:FindFirstChild("HumanoidRootPart")
                    if _cs and _nh and not _G.Skyr0TPCancel then
                        warn("[skyr0] Flash TP: flash unavailable -- old grapple TP (wall clone)")
                        -- put the flash away first, then the carpet out
                        pcall(function()
                            local _uh = LP.Character and LP.Character:FindFirstChildOfClass("Humanoid")
                            if _uh then _uh:UnequipTools() end
                        end)
                        pcall(equipCarpet)
                        if (_cs.pos - _nh.Position).Magnitude > 3 then
                            local _r = computeRoute(_nh.Position, _cs.pos, _cs.face)
                            if not _r or #_r == 0 then _r = { _cs.pos } end
                            pcall(velMoveThrough, _nh, _r, _mainSpeed, true, true)
                        end
                        _nh = (LP.Character and LP.Character:FindFirstChild("HumanoidRootPart")) or _nh
                        -- SETTLE ON THE CLONE SPOT exactly like the clone TP: the
                        -- platform moves under it and you are pinned there, facing
                        -- the wall, until you are standing still on it.
                        if _clonePlat then
                            pcall(function() _clonePlat.Position = Vector3.new(_cs.pos.X, _cs.pos.Y - 3, _cs.pos.Z) end)
                        end
                        local _face = (_cs.face and _cs.face.Magnitude > 0.1) and _cs.face.Unit or nil
                        local _pinCF = _face and CFrame.new(_cs.pos, _cs.pos + _face) or CFrame.new(_cs.pos)
                        pcall(function()
                            local _ph = LP.Character and LP.Character:FindFirstChildOfClass("Humanoid")
                            if _ph then _ph.AutoRotate = false end
                        end)
                        do
                            local _stable, _s0 = 0, os.clock()
                            local _cap = (tonumber(_G.Skyr0TpStableWait) or 0.3) + 0.3
                            while os.clock() - _s0 < _cap do
                                if _G.Skyr0TPCancel or not (_nh and _nh.Parent) then break end
                                local _p = _nh.Position
                                local _flat = Vector3.new(_p.X - _cs.pos.X, 0, _p.Z - _cs.pos.Z).Magnitude
                                if _flat <= 3.5 and math.abs(_p.Y - _cs.pos.Y) <= 4 then
                                    _stable = _stable + 1
                                    if _stable >= 3 then break end
                                else
                                    _stable = 0
                                    pcall(function() _nh.CFrame = _pinCF end)
                                end
                                pcall(function() _vzL(_nh); _vzA(_nh) end)
                                RunService.Heartbeat:Wait()
                            end
                        end
                        if _face and _nh and _nh.Parent then
                            for _ = 1, 2 do
                                pcall(function()
                                    _nh.CFrame = CFrame.new(_nh.Position, _nh.Position + _face)
                                    _vzL(_nh); _vzA(_nh)
                                end)
                                RunService.Heartbeat:Wait()
                            end
                        end
                        -- the "did the clone move us" check below measures from
                        -- HERE -- from the flash spot it thought the clone had
                        -- already happened and went on before the swap finished
                        _preCloneChar = LP.Character
                        _preClonePos = (_nh and _nh.Parent and _nh.Position) or _cs.pos
                        task.wait(_cloneDelay())
                    end
                    if LP.Backpack:FindFirstChild("Quantum Cloner")
                        or (LP.Character and LP.Character:FindFirstChild("Quantum Cloner")) then
                        _cloneOk = doClone()
                    end
                    -- from here on this TP is the grapple clone TP
                    SkyrTP.flash = false
                end
            else
                _cloneOk = doClone()
            end
            if _clonePlat then pcall(function() _clonePlat:Destroy() end); _clonePlat = nil end
            -- CLONE IN FIRST, THEN WALK (rose.lua order). This used to wait 0.6s
            -- at most for ANY movement and then go to the brainrot whether the
            -- clone had swapped us in or not -- so it skipped the clone and went
            -- straight for the brainrot from outside the wall. Now: the clone must
            -- fire, its model must appear, we must actually land on it (and not
            -- get pulled back) BEFORE goToBrainrot runs; otherwise the TP stops.
            -- _G.Skyr0CloneFirst = false brings the old behaviour back.
            local _swapOk = true
            if not SkyrTP.flash and _G.Skyr0CloneFirst ~= false then
                _swapOk = false
                if not _cloneOk then
                    warn("[skyr0] TP: the clone did not fire -- not walking to the brainrot")
                else
                    local _ping = 0
                    pcall(function() _ping = LP:GetNetworkPing() end)
                    local _win = math.clamp(1.5 + _ping * 3, 1.5, tonumber(_G.Skyr0SwapWinMax) or 4)
                    local _cloneName = tostring(LP.UserId) .. "_Clone"
                    local _cs, _landPos
                    local _t0 = os.clock()
                    repeat
                        if _charAdded or LP.Character ~= _preCloneChar then break end
                        if not _cs then
                            local _cm = workspace:FindFirstChild(_cloneName)
                            if _cm then pcall(function() _cs = _cm:GetPivot().Position end) end
                        end
                        local _h = LP.Character and LP.Character:FindFirstChild("HumanoidRootPart")
                        if _h then
                            local _p = _h.Position
                            local _moved = Vector3.new(_p.X - _preClonePos.X, 0, _p.Z - _preClonePos.Z).Magnitude
                            if _cs then
                                -- swapped = standing on the clone's spot, not just nudged
                                local _gap = Vector3.new(_cs.X - _preClonePos.X, 0, _cs.Z - _preClonePos.Z).Magnitude
                                local _toCl = Vector3.new(_p.X - _cs.X, 0, _p.Z - _cs.Z).Magnitude
                                if _moved > 1 and _toCl <= math.max(_gap * 0.5, 2.5) then _landPos = _p; break end
                            elseif os.clock() - _t0 > 2 and _moved > 2 then
                                -- clone model never showed up: fall back to "we moved"
                                _landPos = _p; break
                            end
                        end
                        RunService.Heartbeat:Wait()
                    until os.clock() - _t0 > _win
                    if _landPos then
                        -- let the server commit the swap, then make sure it held
                        task.wait(math.max(tonumber(_G.Skyr0SwapCommit) or 0.05, 0))
                        local _h = LP.Character and LP.Character:FindFirstChild("HumanoidRootPart")
                        local _tol = tonumber(_G.Skyr0SwapRevertTol) or math.clamp(4 + _ping * 3, 4, 8)
                        if _h and LP.Character == _preCloneChar and not _charAdded
                           and Vector3.new(_h.Position.X - _landPos.X, 0, _h.Position.Z - _landPos.Z).Magnitude <= _tol then
                            _swapOk = true
                        else
                            warn("[skyr0] TP: the clone swap was pulled back -- not walking to the brainrot")
                        end
                    else
                        warn("[skyr0] TP: the clone never swapped us in -- not walking to the brainrot")
                    end
                end
            else
            do
                local _t0 = os.clock()
                repeat
                    if _charAdded then break end
                    if LP.Character ~= _preCloneChar then break end
                    local _h = LP.Character and LP.Character:FindFirstChild("HumanoidRootPart")
                    if _h then
                        local _dx = _h.Position.X - _preClonePos.X
                        local _dz = _h.Position.Z - _preClonePos.Z
                        local _dy = _h.Position.Y - _preClonePos.Y
                        if (_dx * _dx + _dz * _dz) > 4 then break end
                        if _dy * _dy > 1 then break end
                    end
                    RunService.Heartbeat:Wait()
                until os.clock() - _t0 > (tonumber(_G.Skyr0TpCloneSettle) or 0.6)
            end
            end
            if _caConn then _caConn:Disconnect() end

            pcall(function()
                local _rh = LP.Character and LP.Character:FindFirstChildOfClass("Humanoid")
                if _rh then _rh.AutoRotate = true end
            end)
            if not _swapOk then
                isTeleporting = false
                _tpAnchor = nil; _tpCommit.pet = nil
                return
            end

            if not SkyrTP.flash then task.wait(0.1) end
            -- THE NEW SCAN: the brainrot may have been taken while we flew; if so, go for the
            -- best one left in THIS base. A Base Camp slot is empty on purpose:
            -- never swap it for a brainrot.
            if _G.Skyr0Retarget ~= false and not pet.campSlot then
                pcall(function()
                    local fresh = scanAllPets(true)
                    if type(fresh) ~= "table" then return end
                    local still, cands = false, {}
                    for _, fp in ipairs(fresh) do
                        if not fp.conveyor and fp.plot == pet.plot then
                            cands[#cands + 1] = fp
                            if tostring(fp.slot) == tostring(pet.slot) and fp.index == pet.index then still = true end
                        end
                    end
                    if not still and #cands > 0 then
                        local _hr = LP.Character and LP.Character:FindFirstChild("HumanoidRootPart")
                        local np = _pickByMode(cands, _hr or hrp) or cands[1]
                        if np and np.position then
                            warn("[skyr0] TP: the target changed while flying -> " .. tostring(np.name))
                            pet, petPos = np, np.position
                            armSteal(np); _commitTP(np, false)
                        end
                    end
                end)
            end
            -- FLASH, 2ND FLOOR: the snap under the brainrot went out the instant
            -- the flash landed, before the server had settled the flash -- it
            -- rubber-banded and looked like lag. Wait a little (Auto TP "Flash 2F
            -- Delay", 0.15s), then GLIDE there on the carpet instead of snapping
            -- ("Flash 2F Walk"; off = the old snap).
            local _f2 = SkyrTP.flash and SkyrTP.flashHit and petPos and petPos.Y >= 10 and petPos.Y < 23.15
                and _G.Skyr0Flash2FFrom1 == false
            -- 3RD FLOOR: flashed onto floor 2, the brainrot is a floor up. A glide
            -- would hit the ceiling, so: same short wait, then the normal snap up
            -- under the brainrot with the platform (goToBrainrot's floor-3 path).
            -- (2nd floor flashed in on floor 1 takes this path too: wait, then the
            -- same lift under the brainrot the grapple clone TP ends with)
            local _f3 = SkyrTP.flash and SkyrTP.flashHit and petPos
                and petPos.Y >= ((_G.Skyr0Flash2FFrom1 ~= false) and 10 or 23.15)
            if _f3 then
                SkyrTP.flashHit = false
                task.wait(math.max(tonumber(_G.Skyr0FlashF2Delay) or 0.15, 0))
            end
            local _oldGlide = _G.Skyr0TpGoGlide
            if _f2 then
                SkyrTP.flashHit = false
                task.wait(math.max(tonumber(_G.Skyr0FlashF2Delay) or 0.15, 0))
                if _G.Skyr0FlashF2Walk ~= false then _G.Skyr0TpGoGlide = true end
                _G.Skyr0TpGoKeepY = true
            end
            pcall(goToBrainrot, petPos, pet and pet.slot)
            if _f2 then _G.Skyr0TpGoGlide = _oldGlide; _G.Skyr0TpGoKeepY = nil end
            isTeleporting = false
            if _G.Skyr0TPCancel then _tpAnchor = nil; _tpCommit.pet = nil; return end
            if pet.campSlot then
                -- land ON the open slot, not next to it
                pcall(function()
                    local _ch = LP.Character
                    if _ch and pet.position then
                        _ch:PivotTo(CFrame.new(pet.position + Vector3.new(0, 3, 0)))
                    end
                end)
                pcall(settleAfterTP)
                _tpAnchor = nil
                return
            end
            armSteal(pet); _commitTP(pet, true)
            pcall(settleAfterTP)
            _tpAnchor = nil
        end
        -- WALKING CARPET RUN -- the normal TP, pointed at a moving target.
        -- Same order as run(): hook out FIRST (aimed at the brainrot), carpet in
        -- hand, then the normal mover (velMoveThrough: lagback handling, climb
        -- cap, routing) to where the brainrot WILL be, then a short live chase
        -- for the last stretch because it kept walking during the flight.
        -- (assigned straight onto SkyrTP: no new local in this closure)
        SkyrTP.runCarpet = function(pet)
            local char = LP.Character
            local hrp = char and char:FindFirstChild("HumanoidRootPart")
            local hum = char and char:FindFirstChildOfClass("Humanoid")
            if not hrp or not hum or not pet then return end
            local model = pet.model
            local function livePos()
                if not model or not model.Parent then return nil end
                if model:IsA("BasePart") then return model.Position end
                local p = model.PrimaryPart or model:FindFirstChild("HumanoidRootPart", true) or model:FindFirstChildWhichIsA("BasePart", true)
                return p and p.Position or nil
            end
            local p0, t0 = livePos() or pet.position, os.clock()
            pcall(function()
                hrp.AssemblyLinearVelocity = Vector3.zero
                hrp.AssemblyAngularVelocity = Vector3.zero
            end)

            -- 1) hook first, aimed at the brainrot -- exactly like run()
            SkyrTP.aim = p0
            pcall(fireGrapple)
            local _hasCarpet = false
            for _, n in ipairs(CARPET_NAMES) do if char:FindFirstChild(n) then _hasCarpet = true; break end end
            if not _hasCarpet then pcall(carpetEngage, true) else equipCarpet() end
            if _G.Skyr0TPCancel then return end

            -- 2) where is it going? two samples taken across the hook/carpet step
            local p1 = livePos()
            if not p1 then warn("[skyr0] Carpet TP: the brainrot left the carpet."); return end
            local dt = math.max(os.clock() - t0, 0.05)
            local vel = (p1 - p0) / dt
            vel = Vector3.new(vel.X, 0, vel.Z)
            if vel.Magnitude > 40 then vel = vel.Unit * 40 end -- a teleporting sample is not a walk speed
            local spd = math.clamp(tonumber(_G.TPVelocity) or tonumber(Config.TpSettings.GrabbleTPSpeed) or 400, 200, 750)
            local eta = (p1 - hrp.Position).Magnitude / spd
            local lead = p1 + vel * eta + Vector3.new(0, 3, 0)
            warn(string.format("[skyr0] Carpet TP: %s | %.0f studs away", tostring(pet.name), (p1 - hrp.Position).Magnitude))

            -- 3) the normal mover to the lead point (skipped when already close)
            if (lead - hrp.Position).Magnitude > 25 then
                local route = computeRoute(hrp.Position, lead, nil)
                if not route or #route == 0 then route = { lead } end
                pcall(velMoveThrough, hrp, route, spd, false, true)
            end
            if _G.Skyr0TPCancel then return end

            -- 4) live chase for the last stretch
            local tc, stall, last = os.clock(), 0, math.huge
            while os.clock() - tc < 4 do
                if not hrp.Parent then break end
                local lp = livePos()
                if not lp then break end
                local diff = (lp + Vector3.new(0, 3, 0)) - hrp.Position
                local mag = diff.Magnitude
                if mag <= 5 then break end
                if mag > last - 0.05 then stall = stall + 1 else stall = 0 end
                last = mag
                if stall >= 30 then break end
                equipCarpet()
                local v = diff.Unit * math.min(spd, mag * 20)
                local cap = _climbCap()
                if v.Y > cap then v = Vector3.new(v.X, cap, v.Z) end
                _setFlightVel(hrp, v)
                RunService.Heartbeat:Wait()
            end
            vZero(hrp)
        end
        SkyrTP.run = run
        SkyrTP.carpetEngage = carpetEngage
        SkyrTP.fireGrapple = fireGrapple
        return SkyrTP
    end)()
    _G.Skyr0MK = MV.mk

    -- WALKING CARPET PICKER. Shared by the Carpet Brainrot TP button and the
    -- auto TP ("TP to Carpet Brainrots"). Same rules as a base target:
    --   * Min Gen for Auto TP filters the belt -- a priority pet is exempt,
    --     exactly as get_all_pets exempts it
    --   * the pick goes through _pickByMode, so the priority list is the first
    --     tier when it is in use and the mode decides otherwise
    -- On _G (not a local) to keep this block's register count where it is.
    -- allPets is optional; without it a live scan is taken.
    _G.Skyr0CarpetPick = function(allPets, hrp)
        if type(allPets) ~= "table" then
            local ok, r = pcall(scanAllPets, true)
            if not ok or type(r) ~= "table" then return nil end
            allPets = r
        end
        hrp = hrp or (LP.Character and LP.Character:FindFirstChild("HumanoidRootPart"))
        local minGen = parseMinGen(Config.TpSettings and Config.TpSettings.MinGenForTp) or 0
        local belt, seen = {}, 0
        for _, p in ipairs(allPets) do
            if p.conveyor and p.model and p.model.Parent then
                seen = seen + 1
                local prio = _G.Skyr0IsPriority and _G.Skyr0IsPriority(p.name, p.index, p.mutation)
                if prio or minGen <= 0 or (tonumber(p.mps) or 0) >= minGen then belt[#belt + 1] = p end
            end
        end
        _G.Skyr0CarpetCounts = { seen = seen, passed = #belt }
        if #belt == 0 then return nil end
        local okP, pick = pcall(_pickByMode, belt, hrp)
        if okP and type(pick) == "table" then return pick end
        pick = belt[1]
        for _, p in ipairs(belt) do if (p.mps or 0) > (pick.mps or 0) then pick = p end end
        return pick
    end
    -- Does the carpet pet beat the base pet the pickers settled on? A listed
    -- pet beats an unlisted one and a better rank beats a worse one; between
    -- two unlisted pets the usual tier/mutation/gen ordering decides.
    _G.Skyr0CarpetBeats = function(c, b)
        if type(c) ~= "table" then return false end
        if type(b) ~= "table" then return true end
        -- priority only counts when it is switched on (Priority mode / the
        -- Auto TP Priority toggle); otherwise it is purely the better gen
        local prioOn = Config.AutoTPPriority == true
            or (_G.Skyr0ResolveMode and _G.Skyr0ResolveMode() == "Priority")
        local rank = prioOn and _G.Skyr0PrioRank or nil
        local rc = rank and rank(c.name, c.index)
        local rb = rank and rank(b.name, b.index)
        if rc and not rb then return true end
        if rb and not rc then return false end
        if rc and rb then return rc < rb end
        -- neither listed: the higher gen is the better brainrot
        return (tonumber(c.mps) or 0) > (tonumber(b.mps) or 0)
    end

    -- ===== Main TP function (1:1 xentp.lua doVelocityTP) =====
    local function doVelocityTP(forcePet)
        if isTeleporting and (os.clock() - _tpStartedAt) < 30 then return end
        if _G.Skyr0CarpetOffForTP then pcall(_G.Skyr0CarpetOffForTP) end
        isTeleporting = true
        _tpStartedAt = os.clock()
        _cloneTP = false
        _cloneFired = false
        clearViz()
        if not NetModule then pcall(loadNet) end

        local char = LP.Character
        local hrp = char and char:FindFirstChild("HumanoidRootPart")
        local hum = char and char:FindFirstChildOfClass("Humanoid")
        if not hrp or not hum then isTeleporting = false; return end

        -- CLEAN START. TP-on-load begins from a fresh spawn; a KEYPRESS begins
        -- from whatever the last TP left behind, and that is the difference
        -- between the two. An anchored root (float / invisible-steal / a failed
        -- clone) can never fly; PlatformStand or Sit swallow the velocity; a
        -- stale _G.isCloning makes the clone pin let go on its first frame; the
        -- pad under the last pet sits in the router's way. Reset all of it first;
        -- the warn below says when something WAS stale.
        if hrp.Anchored or _G.isCloning == true or hum.PlatformStand or hum.Sit then
            warn("[skyr0] TP start: cleared a leftover state from the last TP ("
                .. (hrp.Anchored and "root ANCHORED " or "")
                .. (_G.isCloning == true and "cloning flag " or "")
                .. (hum.PlatformStand and "PlatformStand " or "")
                .. (hum.Sit and "Sit" or "") .. ")")
        end
        _G.isCloning = false
        pcall(function()
            hrp.Anchored = false
            hum.PlatformStand = false
            hum.Sit = false
            hum.Jump = false
            hum.AutoRotate = true
        end)
        for _, _pn in ipairs({ "Skyr0ClonePlatform", "Skyr0TempPlatform" }) do
            local _po = workspace:FindFirstChild(_pn)
            if _po then pcall(function() _po:Destroy() end) end
        end
        vZero(hrp)

        -- hub_Mata's scan gate. Three differences from a bare scanAllPets():
        --   * pcall + type check: a scan that throws used to take the whole TP
        --     down with it instead of just retrying.
        --   * _nBase counts NON-CONVEYOR pets. #allPets counted belt pets too,
        --     so a single brainrot riding the conveyor satisfied "found
        --     something" and the poll exited with no base target to fly to.
        --   * 6s at 0.05 instead of 4s at 0.15 -- more attempts, and the first
        --     success is caught ~100ms sooner on a cold join.
        -- Fresh-enough instead of forced. The teleport picks its destination
        -- from this, so it must not read stale data -- but a 150ms-old scan is
        -- not stale for a pet standing on a podium, and forcing a rebuild here
        -- put a full ~100-pet scan (each one a GetBoundingBox) directly on the
        -- keypress, duplicating what the auto-steal Heartbeat had just done
        -- milliseconds earlier. See scanAllPetsFresh. The cold-join poll below
        -- still forces, because it is waiting for data that does not exist yet.
        local _okScan, allPets = pcall(scanAllPetsFresh, 0.15)
        if not _okScan or type(allPets) ~= "table" then
            isTeleporting = false; return
        end
        local function _nBase(t)
            local n = 0
            for _, p in ipairs(t) do if not p.conveyor then n = n + 1 end end
            return n
        end
        -- a forced conveyor target (Carpet Brainrot TP) has nothing to wait for
        if _nBase(allPets) == 0 and not forcePet
           and not (Config.TpSettings.CarpetBrainrotTP and #allPets > 0) then
            local _t0 = os.clock()
            while _nBase(allPets) == 0 and os.clock() - _t0 < 6 do
                task.wait(0.05)
                local ok2, r = pcall(scanAllPets, true)
                if ok2 and type(r) == "table" then allPets = r end
            end
        end
        -- hub_Mata gates the FINAL check on #allPets, not _nBase: after the poll
        -- gives up, a conveyor-only result is still allowed through rather than
        -- aborting the teleport outright.
        if #allPets == 0 then isTeleporting = false; return end

        -- Respect Skyr0Hub manual selection, then fall back to priority/mode
        -- forcePet: an explicit target handed in by the caller (the walking
        -- carpet TP). It skips every picker below -- they all exclude the
        -- conveyor on purpose, which is exactly the pet being asked for.
        local pet = type(forcePet) == "table" and forcePet or nil
        if not pet and manuallySelectedUID then
            for _, p in ipairs(allPets) do
                if p.plot and p.slot and (p.plot .. "_" .. tostring(p.slot)) == manuallySelectedUID then pet = p; break end
            end
            -- not in the engine's list: rebuild from the uid rather than
            -- silently changing target (see _petPorUID)
            if not pet then pet = _petPorUID(manuallySelectedUID) end
            -- A MANUAL CHOICE IS ABSOLUTE. This used to fall through to
            -- _pickByMode below, which does NOT filter the conveyor -- which is
            -- how the TP ended up flying at RenderedMovingAnimals. If the
            -- clicked target cannot be resolved, better to not teleport at all
            -- than to go somewhere else.
            if not pet then isTeleporting = false; return end
        end
        -- ================================================================
        --  HONOUR THE CYCLE'S LOCKED TARGET.  <-- "it TPs to random things"
        --
        --  Skyr0CicloTP picks the base to GRAPPLE at using
        --  _G.Skyr0GetTargetPetData -- the PANEL's picker, over
        --  SharedState.AllAnimalsCache -- and then stashes that exact pet in
        --  _G.Skyr0TPLockedPet, with a comment saying "the TP reuses this exact
        --  pet instead".
        --
        --  It never did. NOTHING read that global. So the cycle grappled toward
        --  your priority brainrot's base, and then doVelocityTP -- reached a
        --  fraction of a second later -- ran a COMPLETELY DIFFERENT picker
        --  (_pickByMode, over this engine's own scanAllPets list) and flew
        --  wherever that one landed. Two pickers, two data sources, one flight.
        --  That is why the grapple went one way and the teleport another, and
        --  why it looked random rather than simply wrong.
        --
        --  The lock is honoured here, as intended, and consumed so a stale one
        --  can never steer a later teleport. The live entry from THIS scan is
        --  preferred when present (fresher position); _petPorUID rebuilds it
        --  when the engine cannot see that pet, which is the whole reason the
        --  two lists disagree in the first place.
        -- ================================================================
        if not pet then
            local locked   = _G.Skyr0TPLockedPet
            local lockedAt = tonumber(_G.Skyr0TPLockedAt) or 0
            _G.Skyr0TPLockedPet, _G.Skyr0TPLockedAt = nil, nil
            if type(locked) == "table" and locked.plot and locked.slot
               and (os.clock() - lockedAt) < 20
               and not (_G.Skyr0IsMyPlotCached and _G.Skyr0IsMyPlotCached(locked.plot)) then
                local uid = tostring(locked.plot) .. "_" .. tostring(locked.slot)
                for _, p in ipairs(allPets) do
                    if not p.conveyor and p.plot and p.slot
                       and (p.plot .. "_" .. tostring(p.slot)) == uid then
                        pet = p; break
                    end
                end
                if not pet then pet = _petPorUID(uid) end
            end
        end

        -- ================================================================
        --  GO WHERE AUTO-GRAB IS ALREADY GOING.  (fallback, not first choice)
        --
        --  ORDER MATTERS, AND GETTING IT WRONG PUT THE TELEPORT BACK ON RANDOM
        --  PETS. This block used to sit ABOVE the cycle lock, and that is a
        --  strictly worse source on the grapple path:
        --
        --    Skyr0CicloTP raises __Skyr0CicloRodando FIRST, which FREEZES the
        --    auto-steal re-picker, and only then calls getTargetPetData to aim
        --    the grapple and set the lock. So by the time doVelocityTP runs,
        --    _stealTarget is whatever happened to be armed BEFORE the cycle
        --    started -- frozen, possibly minutes old, possibly not on the
        --    priority list at all -- while the lock is a fresh, priority-first
        --    pick made moments ago. Reading the stale one first overrode the
        --    good one on every single grapple TP.
        --
        --  It stays, below the lock, because it is the right answer for a
        --  teleport that never went through the cycle (side TP, dispatcher,
        --  re-fire) -- there is no lock in those cases and the armed target is
        --  then the only live statement of intent.
        --
        --  The hub has THREE independent target pickers, each over its own data:
        --    * the beam/tracer  -- its own walk of SharedState.AllAnimalsCache
        --    * the steal engine -- _pickByMode over scanAllPets, result in
        --                          _stealTarget (this is what actually gets
        --                          grabbed)
        --    * this teleport    -- _pickByMode again, its own fresh scan
        --
        --  Two runs of _pickByMode are not the same answer. The steal loop and
        --  the teleport scan at different moments, and the priority pet may be
        --  visible to one list and not the other -- the panel scanner resolves
        --  bases the engine cannot (no channel yet, rendered-Model only), which
        --  is exactly why _petPorUID exists. So auto-grab arms the priority pet,
        --  the tracer draws to it, and the teleport independently decides on
        --  something else.
        --
        --  _stealTarget is what the engine will actually fire the prompt on, so
        --  on a lock-less teleport it is the best statement of intent there is.
        --
        --  BUT IT NEVER OUTRANKS THE LIST. If the armed pet is not on the
        --  priority list and the list is in use, this stands aside and lets
        --  _pickByMode run -- that path checks the list first, across BOTH the
        --  engine scan and the panel cache, so it can see a listed pet the
        --  auto-steal loop had not gotten to yet. Without this guard a stale
        --  non-priority armed target would win outright, which is the whole
        --  complaint: it goes to random stuff while a priority pet is sitting
        --  right there.
        -- ================================================================
        local _armedRanked = (type(_stealTarget) == "table" and _G.Skyr0PrioRank)
            and _G.Skyr0PrioRank(_stealTarget.name, _stealTarget.index) or nil
        local _listInUse = (type(priorityList) == "table" and #priorityList > 0)
        if not pet and type(_stealTarget) == "table"
           and (_armedRanked or not _listInUse)
           and _stealTarget.plot and _stealTarget.slot and not _stealTarget.conveyor
           and not (_G.Skyr0IsMyPlotCached and _G.Skyr0IsMyPlotCached(_stealTarget.plot)) then
            local uid = tostring(_stealTarget.plot) .. "_" .. tostring(_stealTarget.slot)
            for _, p in ipairs(allPets) do
                if not p.conveyor and p.plot and p.slot
                   and (p.plot .. "_" .. tostring(p.slot)) == uid then
                    pet = p; break
                end
            end
            -- armed against a pet this engine's scan cannot see: rebuild it from
            -- the uid rather than falling through to a different target
            if not pet then pet = _petPorUID(uid) end
        end

        if not pet then
            -- no manual choice: conveyor pets are out of the running. The
            -- auto-steal path already filtered this way; only doVelocityTP did not.
            local semEsteira = {}
            for _, p in ipairs(allPets) do
                if not p.conveyor then semEsteira[#semEsteira+1] = p end
            end
            -- with carpet TP on, an empty base list is not the end: the belt
            -- gets its turn just below
            if #semEsteira == 0 and not (Config.TpSettings and Config.TpSettings.CarpetBrainrotTP) then
                isTeleporting = false; return
            end
            -- hrp passed explicitly: in "Nearest" mode _pickByMode measures from
            -- this reference, and the auto-steal caller above already passes it.
            -- It fell back to LocalPlayer's HRP here, which is the same instance
            -- -- but leaving the two call sites asymmetric is how they drifted
            -- apart in the first place.
            if #semEsteira > 0 then pet = _pickByMode(semEsteira, hrp) or semEsteira[1] end
        end

        -- TP TO CARPET BRAINROTS. Never overrides a manual click or a forced
        -- target; otherwise the best qualifying belt pet (min gen + priority,
        -- see Skyr0CarpetPick) takes the flight when it outranks the base pick.
        if not forcePet and not manuallySelectedUID
           and Config.TpSettings and Config.TpSettings.CarpetBrainrotTP then
            local okC, belt = pcall(_G.Skyr0CarpetPick, allPets, hrp)
            if okC and belt and _G.Skyr0CarpetBeats(belt, pet) then pet = belt end
        end
        if not pet then isTeleporting = false; return end

        -- ================================================================
        --  LAST LINE OF DEFENCE AGAINST FLYING HOME.  <-- "it TPs to my own base"
        --
        --  Every picker above does filter your own plot -- but each one does it
        --  from a DIFFERENT snapshot, and the flight commits to whichever
        --  answered last:
        --    * the engine's scanAllPets list (its own isMyPlot + the cache)
        --    * a lock stashed by the grapple cycle up to 20 SECONDS earlier
        --    * _petPorUID, which resolves a uid straight off the plot with no
        --      ownership test at all -- and both the lock path and the manual
        --      path fall back to it
        --    * the bare `or semEsteira[1]` above, which is not filtered by
        --      anything except "not a conveyor pet"
        --
        --  One stale or cold answer anywhere in that chain and you fly home.
        --  Asked once more here, at the point of no return, against what the
        --  check knows NOW -- and a positive is latched for the session (see
        --  Skyr0IsMyPlotCached), so by this point it is as good as it gets.
        --
        --  Conveyor pets have no plot and are skipped, not rejected.
        -- ================================================================
        if pet and pet.plot and _G.Skyr0IsMyPlotCached and _G.Skyr0IsMyPlotCached(pet.plot) then
            warn("[skyr0] TP: target sits on YOUR OWN base -- re-picking.")
            local safe = {}
            for _, p in ipairs(allPets) do
                if not p.conveyor and p.plot and not _G.Skyr0IsMyPlotCached(p.plot) then
                    safe[#safe+1] = p
                end
            end
            if #safe == 0 then
                warn("[skyr0] TP aborted: nothing on this server but your own base.")
                isTeleporting = false
                return
            end
            -- re-picked through the mode, not just "the first survivor", so the
            -- replacement still obeys the priority list
            pet = _pickByMode(safe, hrp) or safe[1]
        end

        -- ================================================================
        --  SAY WHAT IT PICKED AND WHY.
        --
        --  Every "the TP went to the wrong thing" report so far has been a
        --  guess at which of five pickers answered, because the flight commits
        --  in silence. One line at the point of no return: the pet, its place
        --  in your priority list (or that it is not on it at all), how many
        --  listed pets were on the server, and the mode that would have decided
        --  if the list came up empty.
        --
        --  If this says "not on list" while the pet IS on your list, the names
        --  disagree -- the list entry and AnimalsData.DisplayName are not the
        --  same string -- and that is a matching problem, not a picker problem.
        -- ================================================================
        if pet then
            local _rank = _G.Skyr0PrioRank and _G.Skyr0PrioRank(pet.name, pet.index)
            local _onServer = 0
            for _, p in ipairs(allPets) do
                if not p.conveyor and _G.Skyr0PrioRank and _G.Skyr0PrioRank(p.name, p.index) then
                    _onServer = _onServer + 1
                end
            end
            warn(("[skyr0] TP target: %s -- %s | %d listed pet(s) on server | fallback mode: %s")
                :format(tostring(pet.name),
                        _rank and ("priority #" .. _rank) or "NOT ON LIST",
                        _onServer,
                        tostring(_G.Skyr0ResolveMode and _G.Skyr0ResolveMode() or "?")))
        end

        -- ONE TARGET FOR BOTH ENGINES.
        --
        -- The destination the TP just committed to IS the pet auto-grab will
        -- take. Previously the TP flew to `pet` and never told the steal engine
        -- anything -- the Heartbeat above kept picking its own target on its own
        -- schedule, so the two routinely disagreed and you arrived next to a pet
        -- auto-grab had no interest in. Arming it here, combined with the flight
        -- freeze on the re-picker, makes the destination and the grab target the
        -- same pet by construction rather than by coincidence.
        --
        -- Conveyor pets are excluded: they have no plot/slot, so findStealPrompt
        -- has nothing to resolve and arming one would just park the steal engine
        -- on a target it can never fire. (Both selection branches above already
        -- filter them out; this is a guard, not a live case.)
        if not pet.conveyor and not pet.campSlot then armSteal(pet); _commitTP(pet, false) end
        -- The "nearest" reference for the rest of the flight. A mid-flight
        -- retarget (plot changed) measures from HERE, not from the moving HRP.
        _tpAnchor = pet.position

        local _tpSpd = (Config and Config.TpSettings and Config.TpSettings.GrabbleTPSpeed) or 400
        local _cloneDelay = (Config and Config.TpSettings and Config.TpSettings.CloneDelayVal) or 0.35

        local petPos = pet.position
        local petName = pet.name

        local adjY = petPos.Y
        if TALL_PETS[petName] then adjY = petPos.Y - TALL_OFFSET end
        -- V3 Floor 2 from Floor 1: when the pet is on floor 2 and the toggle is on,
        -- clamp adjY down so coordTable picks LOWER (floor-1 wall) instead of UPPER.
        -- Same band as goToBrainrot's arrival half -- see _G.Skyr0IsF2FromF1.
        local _f2FromF1 = _G.Skyr0IsF2FromF1 and _G.Skyr0IsF2FromF1(petPos.Y) or false
        if _f2FromF1 then adjY = math.min(adjY, UPPER_Y_THRESHOLD) end
        local coordTable = adjY > UPPER_Y_THRESHOLD and UPPER or LOWER

        -- CONVEYOR -- the normal TP (hook, carpet, mover) via MV.mk.runCarpet
        if pet.conveyor then
            local maxHP = hum.MaxHealth
            local healConn = RunService.Heartbeat:Connect(function()
                if hum and hum.Parent then hum.Health = maxHP end
            end)
            local okR, errR = pcall(MV.mk.runCarpet, pet)
            if not okR then warn("[skyr0] Carpet TP error: " .. tostring(errR)) end
            healConn:Disconnect()
            -- landed on the carpet: Auto Buy takes it from here (locks the
            -- nearest walker -- the one we just flew to)
            if okR and not _G.Skyr0TPCancel and _G.Skyr0SetAutoBuy then
                pcall(_G.Skyr0SetAutoBuy, true)
            end
            _tpAnchor = nil
            isTeleporting = false
            return
        end

        -- =====================================================================
        -- THE FLIGHT: hook first, carpet, route, flight, clone, walk to the brainrot.
        -- pcall'd, so an error can never leave isTeleporting stuck for 30 seconds.
        -- =====================================================================
        local _okTp, _errTp = pcall(MV.mk.run, pet, true)
        if not _okTp then
            warn("[skyr0] TP error: " .. tostring(_errTp))
            _tpCommit.pet = nil
            _cloneTP = false
            pcall(settleAfterTP)
            _tpAnchor = nil
            isTeleporting = false
        end
    end

    doGrabbleVelocityTP = doVelocityTP
    _G.Skyr0StartSideTP = doVelocityTP
    -- Stashed on _G so the dispatcher at the very bottom of the file can point
    -- back at THIS function. doVelocityTP is a local inside this do-block, and
    -- the tail used to overwrite both names above with the V1 engine -- so this
    -- teleport, the one that matches hub_Mata, never actually ran.
    _G.Skyr0DoVelocityTP = doVelocityTP
    -- Escape hatch for _G.Skyr0TPReset. The V1 engine used to export this;
    -- with V1 gone the live engine has to, or a stuck isTeleporting can only
    -- be cleared by the 30s staleness check inside doVelocityTP.
    _G.Skyr0ForceIdleTP = function() isTeleporting = false end
    -- ONE FLIGHT AT A TIME. True from the moment doVelocityTP starts until it
    -- ends (30s stale-reclaim, same as its own guard). The launcher, the grapple
    -- cycle, the dispatcher and the lagback watcher all check it, because
    -- doVelocityTP's own guard only stopped a second FLIGHT: a second key press
    -- or a lagback retry still started a new grapple cycle -- a fresh hook shot
    -- and pull -- on top of the flight already running.
    _G.Skyr0TPActive = function()
        return isTeleporting and (os.clock() - _tpStartedAt) < 30
    end

    _G.Skyr0_ExecuteManualTP = function()
        task.spawn(function() pcall(doVelocityTP) end)
    end

    -- WALKING CARPET TP. Every normal picker drops conveyor pets on purpose, so
    -- this one asks for them explicitly: priority list / mode first (same
    -- _pickByMode the base TP uses), highest gen as the fallback, then hands
    -- the pet straight to doVelocityTP's conveyor chase. Pairs with Auto Buy:
    -- the chase ends inside the buy radius and the hover lock takes over.
    _G.Skyr0TPCarpetBrainrot = function()
        if _G.Skyr0TPActive and _G.Skyr0TPActive() then return false end
        local hrp = LP.Character and LP.Character:FindFirstChild("HumanoidRootPart")
        if not hrp then return false end
        local okP, pick = pcall(_G.Skyr0CarpetPick, nil, hrp)
        if not okP or type(pick) ~= "table" then
            local c = _G.Skyr0CarpetCounts or {}
            warn(("[skyr0] Carpet TP: %d brainrot(s) on the carpet, %d pass Min Gen / priority -- not teleporting.")
                :format(c.seen or 0, c.passed or 0))
            if ShowNotification then pcall(ShowNotification, "CARPET TP", "Nothing on the carpet qualifies") end
            return false
        end
        warn(("[skyr0] Carpet TP target: %s (%s)"):format(tostring(pick.name), tostring(pick.mutation)))
        task.spawn(function() pcall(doVelocityTP, pick) end)
        return true
    end

    -- (hardcoded T-key handler removed -- it fired this hub's OLD doVelocityTP in PARALLEL with
    -- the "Manual TP" keybind's runAutoSnipe -> _fxTpDispatch -> V1, so two TP engines fought and
    -- the character spun. T is now handled ONLY by the "Manual TP" keybind, exactly like the upstream hub.)

    -- Boot
    task.spawn(function() pcall(loadModules) pcall(loadNet) end)
    task.spawn(function()
        local char = LP.Character or LP.CharacterAdded:Wait()
        char:WaitForChild("HumanoidRootPart", 10)
        char:WaitForChild("Humanoid", 10)
        pcall(loadModules); pcall(loadNet)
        local _t0 = os.clock()
        repeat
            local ok, pets = pcall(scanAllPets)
            if ok and pets and #pets > 0 then break end
            task.wait(0.3)
        until os.clock() - _t0 > 12
        _started = true
    end)
end
if _G.__LMARK then _G.__LMARK("L23399") end

-- (The V1 teleport engine that used to sit here is GONE, along with the
--  _G.Skyr0_getNet / _G.Skyr0FireUseItem shims that existed only to feed it.
--  It was unreachable: _fxTpDispatch tries _G.Skyr0DoVelocityTP first and
--  that is always set, so the V1 branch never ran.)

-- Route this hub's TP through the upstream hub's V1 engine via a settings bridge (its _tpDispatch,
-- 1:1). This hub has the SAME Config keys, so this maps StealMode / PriorityList / manual
-- selection / speed onto the _G.* contract the V1 engine reads -- so the V1 TP flies to the
-- Highest/Priority/Nearest/manually-selected pet exactly like the upstream hub, not just allPets[1].
-- TP INTENT. A flight only takes off when something YOU did asked for it: a
-- keybind, an Actions button, a Steal Target click, or TP on Load at execute
-- (they all stamp _G.Skyr0TPIntent right before the dispatcher). Anything else
-- -- a base joining, a scanner update, a leftover loop -- is refused and the
-- console says where it came from. One press = one flight.
-- OFF by default: the grapple cycle's hand-off never stamped an intent, so the
-- hook pulled you and the flight was refused. _G.Skyr0RequireTPIntent = true
-- turns the gate on.
_G.Skyr0TPIntent = function(src)
    _G.__Skyr0TPIntentAt = os.clock()
    _G.__Skyr0TPIntentSrc = tostring(src or "?")
end
local function _fxTpDispatch()
    if _G.Skyr0RequireTPIntent == true then
        local _ia = tonumber(_G.__Skyr0TPIntentAt)
        if not (_ia and os.clock() - _ia < 10) then
            warn("[skyr0] TP blocked: automatic TP with no keybind/button press -- refused.")
            return false
        end
        _G.__Skyr0TPIntentAt = nil
    end
    if _G.Skyr0CarpetOffForTP then pcall(_G.Skyr0CarpetOffForTP) end
    -- Steal lockout (see Skyr0IsStealing): every "just teleport" path funnels
    -- through here, so one check covers the keybind, the Actions button and the
    -- side-TP dispatcher alike.
    if _G.Skyr0IsStealing and _G.Skyr0IsStealing() then
        warn("[skyr0] TP blocked: you are stealing.")
        return false
    end
    -- before anything below is touched: a second call must not reset the cancel
    -- flag or the speed of the flight that is already running
    if _G.Skyr0TPActive and _G.Skyr0TPActive() then return false end
    _G.TPVelocity        = math.max(tonumber(Config.TpSettings.GrabbleTPSpeed) or 400, 400)
    _G.TPCloneDelay      = tonumber(Config.TpSettings.CloneDelayVal) or 0.1
    _G.LandingDelay      = _G.LandingDelay or 0.4
    _G.Skyr0StealModeStr = (tostring(Config.StealMode or "")):lower()
    _G.Skyr0StealTargetUID = manuallySelectedUID and ((tostring(manuallySelectedUID):gsub("_", "|"))) or nil
    -- Always re-point at the LIVE priority list so UI reorders/adds/removes take effect on
    -- the very next TP (the old `x = x or Config.PriorityList` latched the first value and
    -- ignored later reorders, so TP would not follow the freshly-sorted list).
    _G.SHARED_PRIORITY_ITEMS = Config.PriorityList or _G.SHARED_PRIORITY_ITEMS
    _G.Skyr0TPCancel = false
    -- One engine, one branch. doVelocityTP, exported as _G.Skyr0DoVelocityTP:
    -- its velMoveThrough is the TP mover (SPEED 200, ARRIVE 3, quickStart
    -- hop, 18-frame stall detector, CFrame settle in finish()).
    if _G.Skyr0DoVelocityTP then return _G.Skyr0DoVelocityTP() end
    warn("[skyr0] TP engine missing -- did the engine block fail to load?")
end
if _G.__LMARK then _G.__LMARK("L23438") end
_G.Skyr0StartSideTP      = _fxTpDispatch
doGrabbleVelocityTP    = _fxTpDispatch
_G.Skyr0_ExecuteManualTP = function() task.spawn(function() pcall(_fxTpDispatch) end) end

-- =====================================================================
-- THE ONE MANUAL TP
-- ---------------------------------------------------------------------
-- Every "just teleport now" caller goes through here: the Manual TP keybind,
-- the Actions button, and TP-on-load.
--
-- They used to disagree. The keybind ran the dispatcher above, while
-- TP-on-load ran runAutoSnipe behind a getTargetPetData()/findAdorneeGlobal()
-- gate -- a different target picker AND a precondition the engine does not
-- need, since it polls for pets itself. So the two could pick different pets,
-- and on a slow join TP-on-load simply never fired.
--
-- One entry point means "TP on load" is now, by definition, the same thing as
-- pressing the Manual TP key.
-- =====================================================================
_G.Skyr0ManualTP = function()
    -- a press during a flight must not touch it (this used to reset the cancel
    -- flag of the flight already running)
    if _G.Skyr0TPActive and _G.Skyr0TPActive() then return end
    _G.Skyr0TPCancel = false
    -- THROUGH THE GRAPPLE CYCLE, same as TP-on-load and the Grapple TP key.
    --
    -- This called _fxTpDispatch directly, which goes straight to the teleport.
    -- The cycle is what fires the hook, turns you to face the plot and lets the
    -- pull drag you before the flight starts -- so Manual TP had no hook and no
    -- drag at all, it just started teleporting. TP-on-load looked completely
    -- different for that one reason.
    --
    -- 25 is the wait-for-a-target ceiling; it exits the moment one exists.
    -- The cycle hands off to _fxTpDispatch itself once the hook is away.
    if _G.Skyr0RunTPOnLoad then task.spawn(_G.Skyr0RunTPOnLoad, true); return end
    task.spawn(function()
        local ok, err = pcall(_fxTpDispatch)
        if not ok then warn("[skyr0] Manual TP error:", err) end
    end)
end
if _G.__LMARK then _G.__LMARK("L23479") end


-- =====================================================================
-- INSTA RESET  --  duels.lua's insta reset
-- ---------------------------------------------------------------------
-- HipHeight 1e30 + no-collide on every part, re-applied every 0.05s (up to
-- 40 times) so the character is flung out of the map and dies; Health = 0
-- as the fallback if it is still alive; HipHeight/collision restored when
-- the reset failed. The camera is held where it was until the new
-- character arrives. 0.75s request debounce.
--
-- skyro glue around it: the hub's anti-die (which heals Health back up) is
-- off for the duration and re-hooked onto the new body, invisible steal is
-- turned off first (it parks the real root in the camera), and
-- _G.__Skyr0Resetting is up while it runs so Anti Body Swap ignores it.
-- =====================================================================
do
    local Players = game:GetService("Players")
    local LP = Players.LocalPlayer

    local resetCooldown          = false
    local resetThread            = nil
    local resetSuccessful        = false
    local stopResetSequence      = false
    local cameraLocked           = false
    local lockedCameraCFrame     = nil
    local _lastInstaResetRequest = 0
    local prevAntiDie            = nil

    local function restoreAntiDie()
        if prevAntiDie == nil then return end
        local was = prevAntiDie
        prevAntiDie = nil
        _G.AntiDieDisabled = was
        if not was and _G.setupAntiDie then
            task.delay(0.6, function() pcall(_G.setupAntiDie) end)
        end
    end

    local function instaResetFast()
        if resetCooldown then return end
        resetCooldown     = true
        resetSuccessful   = false
        stopResetSequence = false
        cameraLocked      = false

        local character = LP.Character
        if not character then resetCooldown = false return end
        local humanoid = character:FindFirstChildOfClass("Humanoid")
        if not humanoid then resetCooldown = false return end

        _G.__Skyr0Resetting = true
        if prevAntiDie == nil then prevAntiDie = _G.AntiDieDisabled == true end
        _G.AntiDieDisabled = true
        if _G.AntiDieConnection then
            pcall(function() _G.AntiDieConnection:Disconnect() end)
            _G.AntiDieConnection = nil
        end
        if _G.invisibleStealEnabled and _G._forceInvisToggle then pcall(_G._forceInvisToggle) end

        local cam = workspace.CurrentCamera
        if cam then
            lockedCameraCFrame = cam.CFrame
            cameraLocked       = true
            cam.CFrame         = lockedCameraCFrame
        end

        local isRespawning = false

        resetThread = task.spawn(function()
            local attempts          = 0
            local maxAttempts       = 40
            local originalHipHeight = humanoid.HipHeight

            while character and character.Parent and humanoid and humanoid.Health > 0
                  and not isRespawning and not stopResetSequence do
                if LP.Character ~= character then
                    isRespawning = true
                    break
                end
                pcall(function()
                    humanoid.HipHeight  = 1e30
                    humanoid.AutoRotate = true
                    local rootPart = character:FindFirstChild("HumanoidRootPart")
                    if rootPart then rootPart.CanCollide = false end
                    for _, part in ipairs(character:GetChildren()) do
                        if part:IsA("BasePart") and part.Name ~= "HumanoidRootPart" then
                            part.CanCollide = false
                        end
                    end
                end)

                if not character or not character.Parent or not humanoid
                   or humanoid.Health <= 0 or LP.Character ~= character then
                    resetSuccessful = true
                    break
                end

                attempts = attempts + 1
                if attempts >= maxAttempts then break end
                task.wait(0.05)
            end

            if not resetSuccessful then
                if character and character.Parent and humanoid
                   and humanoid.Health > 0 and not isRespawning then
                    pcall(function() humanoid.Health = 0 end)
                    task.wait(0.1)
                    if not character.Parent or humanoid.Health <= 0 then
                        resetSuccessful = true
                    end
                end
            end

            if not resetSuccessful and character and character.Parent and humanoid then
                pcall(function()
                    humanoid.HipHeight = originalHipHeight
                    local rootPart = character:FindFirstChild("HumanoidRootPart")
                    if rootPart then rootPart.CanCollide = true end
                    for _, part in ipairs(character:GetChildren()) do
                        if part:IsA("BasePart") and part.Name ~= "HumanoidRootPart" then
                            part.CanCollide = true
                        end
                    end
                end)
                -- still alive: nothing is coming to put anti-die back, so do it here
                cameraLocked = false
                restoreAntiDie()
                _G.__Skyr0Resetting = nil
            end

            resetCooldown     = false
            resetThread       = nil
            stopResetSequence = false
        end)
    end

    local function instaReset()
        local now = os.clock()
        if now - _lastInstaResetRequest < 0.75 then return false end
        _lastInstaResetRequest = now
        instaResetFast()
        return true
    end

    LP.CharacterAdded:Connect(function()
        stopResetSequence = true
        if resetThread then pcall(task.cancel, resetThread); resetThread = nil end
        resetCooldown = false
        cameraLocked  = false
        restoreAntiDie()
        _G.__Skyr0Resetting = nil
    end)

    task.spawn(function()
        while true do
            task.wait(0.016)
            local cam = workspace.CurrentCamera
            if cameraLocked and lockedCameraCFrame and cam then
                cam.CFrame = lockedCameraCFrame
            end
        end
    end)

    _G.Skyr0InstaReset = instaReset
end
if _G.__LMARK then _G.__LMARK("L23646") end

-- =====================================================================
-- ANTI BODY SWAP
-- ---------------------------------------------------------------------
-- Detected without knowing the game's mechanism, because the definition of
-- being swapped IS the observable: LocalPlayer.Character is reassigned to a
-- different model WITHOUT you having died first.
--
-- A normal respawn always follows a death, so a CharacterAdded with no recent
-- Died is a swap. That holds however the potion is implemented, and it cannot
-- fire on an ordinary respawn.
--
-- The response is to use your own Body Swap Potion, which puts you back. If
-- you are not carrying one there is nothing to do but say so.
-- =====================================================================
do
    local LPx = game:GetService("Players").LocalPlayer
    local POTION = "Body Swap Potion"
    local GRACE  = 3          -- a respawn lands within this long of the death
    local lastDeath = -math.huge
    local lastSwap  = -math.huge
    local loadedAt  = os.clock()
    local ARM_DELAY = 8       -- seconds after load before this can fire
    -- The character we already believe is ours. A swap REPLACES one, so until
    -- this is set there is nothing to have been swapped out of -- which is
    -- exactly the state the load-time CharacterAdded arrives in.
    local knownChar = LPx.Character

    _G.Skyr0AntiBodySwap = (Config and Config.AntiBodySwap) or false

    local function watchDeath(char)
        local hum = char and char:FindFirstChildOfClass("Humanoid")
        if not hum then return end
        hum.Died:Connect(function() lastDeath = os.clock() end)
    end
    watchDeath(LPx.Character)

    local function swapBack()
        local char = LPx.Character
        local bp = LPx:FindFirstChildOfClass("Backpack")
        local hum = char and char:FindFirstChildOfClass("Humanoid")
        if not (char and hum) then return false end

        local tool = (bp and bp:FindFirstChild(POTION)) or char:FindFirstChild(POTION)
        if not tool then
            ShowNotification("BODY SWAP", "swapped -- no potion to swap back")
            return false
        end
        pcall(function() hum:EquipTool(tool) end)
        task.wait(0.1)
        pcall(function() tool:Activate() end)
        ShowNotification("BODY SWAP", "swapped back")
        return true
    end

    LPx.CharacterAdded:Connect(function(char)
        watchDeath(char)
        local prev = knownChar
        knownChar = char
        if not _G.Skyr0AntiBodySwap then return end

        local now = os.clock()
        -- NOT A SWAP ON LOAD.
        -- The first character we see is the one we already had; there was no
        -- previous body to be swapped out of. And nothing in the opening
        -- seconds of a session counts, because that is the join spawn.
        if prev == nil then return end
        if (now - loadedAt) < ARM_DELAY then return end
        -- Followed a death: ordinary respawn, not a swap.
        if (now - lastDeath) <= GRACE then return end
        -- An insta reset is a death we caused, so it must not read as a swap.
        -- Both reset implementations are covered: whichever this build
        -- ships, one of these flags is up while it runs.
        if _G.__meerkoResetBusy or _G.__Skyr0Resetting then return end
        -- One response per swap, not one per frame of a chain.
        if (now - lastSwap) < 5 then return end
        lastSwap = now

        task.spawn(function()
            task.wait(0.35)      -- let the swap settle before answering it
            swapBack()
        end)
    end)

    function _G.Skyr0SetAntiBodySwap(on)
        _G.Skyr0AntiBodySwap = on and true or false
        Config.AntiBodySwap = _G.Skyr0AntiBodySwap
        pcall(saveConfig)
    end
end
if _G.__LMARK then _G.__LMARK("L23737") end

-- =====================================================================
-- TP LAGBACK RECOVERY
-- ---------------------------------------------------------------------
-- The hub already recovers from lagbacks, but only inside the invisible-steal
-- loop and only while the Stealing attribute is set. A teleport that gets
-- rejected mid-flight is not covered at all: the server snaps you back toward
-- where you launched from, the flight thread carries on believing it arrived,
-- and you are left standing at your own base wondering why nothing happened.
--
-- Detection needs no knowledge of the destination, which is what makes it
-- cheap to bolt on: a lagback is a large BACKWARD jump -- toward where the
-- flight started -- inside a single frame, while a teleport is in flight.
-- Ordinary travel never does that, and neither does the flight's own
-- CFrame stepping, which always moves away from the origin.
--
-- _G.__Skyr0TPPending is the launcher's own in-flight latch, so this costs
-- nothing whenever a teleport is not running.
-- =====================================================================
do
    local LPx = game:GetService("Players").LocalPlayer
    local RSx = game:GetService("RunService")

    local JUMP_BACK   = 40     -- studs of instant backward travel that counts
    local DRIFT_BACK  = 60     -- ... or this much accumulated inside DRIFT_WIN
    local DRIFT_WIN   = 0.75
    local COOLDOWN    = 6      -- never retry more often than this
    local MAX_RETRIES = 3      -- per flight

    local lastPos, origin, retries, lastRetry = nil, nil, 0, -math.huge
    local wasPending = false
    -- Accumulated backward movement, and when the window started.
    --
    -- A single-frame threshold only catches a lagback delivered as one hard
    -- snap. On a high-ping connection the server frequently walks you back
    -- over several frames instead, and no single step is 40 studs -- so the
    -- flight was being rejected and nothing here ever noticed.
    local drift, driftAt = 0, 0

    local function hrp()
        local c = LPx.Character
        return c and c:FindFirstChild("HumanoidRootPart")
    end

    RSx.Heartbeat:Connect(function()
        if not _G.AutoRecoverLagback then lastPos = nil; return end

        local pending = _G.__Skyr0TPPending ~= nil
        if not pending then
            -- flight ended: reset the per-flight budget
            if wasPending then wasPending, retries, origin = false, 0, nil end
            lastPos = nil
            return
        end

        local root = hrp()
        if not root then lastPos = nil; return end
        local pos = root.Position

        if not wasPending then
            wasPending = true
            origin = pos
            lastPos = pos
            return
        end
        if not lastPos or not origin then lastPos = pos; return end

        -- A frame-sized jump that moves us back toward the launch point.
        local step = (pos - lastPos).Magnitude
        local wasAway = (lastPos - origin).Magnitude
        local nowAway = (pos - origin).Magnitude
        lastPos = pos

        local now = os.clock()
        local backwards = nowAway < wasAway

        -- accumulate backward movement inside a rolling window
        if (now - driftAt) > DRIFT_WIN then drift, driftAt = 0, now end
        if backwards then drift = drift + (wasAway - nowAway) end

        local snapped = (step >= JUMP_BACK) and backwards
        local drifted = drift >= DRIFT_BACK
        if not (snapped or drifted) then return end
        drift, driftAt = 0, now
        -- The flight's own mover already recovers from a lagback (settle, resume,
        -- re-plan). Launching a whole new grapple cycle on top of it is the
        -- "two TPs at once". Only retry once the flight is over.
        if _G.Skyr0TPActive and _G.Skyr0TPActive() then return end
        -- Skyr0LaunchTP refuses the `false` (retry) form unless Skyr0LagbackRetry
        -- is on, so without it this used to announce "retrying" and then do
        -- nothing. The mover inside the flight is what recovers a lagback now.
        if _G.Skyr0LagbackRetry ~= true then return end
        if retries >= MAX_RETRIES or (now - lastRetry) < COOLDOWN then return end
        retries = retries + 1
        lastRetry = now

        if ShowNotification then
            ShowNotification("LAGBACK", "teleport rejected -- retrying (" .. retries .. ")")
        end

        task.spawn(function()
            -- Let the server settle before asking again. Re-firing into the
            -- same rejection just burns the retry budget -- and "settled"
            -- means a couple of round trips, not a fixed 0.6s that is shorter
            -- than one of them on a bad connection.
            local png = (_G.Skyr0Ping and _G.Skyr0Ping()) or 0.1
            task.wait(math.clamp(png * 3 + 0.3, 0.6, 2.5))
            if _G.Skyr0TPActive and _G.Skyr0TPActive() then return end
            if _G.Skyr0LaunchTP then pcall(_G.Skyr0LaunchTP, false) end
        end)
    end)
end
if _G.__LMARK then _G.__LMARK("L23850") end

-- =====================================================================
-- NO COLLISION WITH OTHER PLAYERS  (phase through them)
-- ---------------------------------------------------------------------
-- Other players and their clone bodies are solid to your character, so a
-- player standing on the flight line -- or at the clone spot -- stalled the
-- flight like a wall. The router already looks straight through them (its
-- rays, sphere sweeps and voxel boxes skip every character and clone); this is
-- the PHYSICAL half: their parts are made non-collidable on YOUR client, so you
-- fly through them and clone where they stand.
--   * every part of every other player's character and of every other clone
--     is set CanCollide=false, and pinned (a Humanoid turns it back on)
--   * a NoCollisionConstraint from your root to their root/torso/head
--   * anyone within _G.Skyr0NoCollideRange (28) is swept every 0.1s
-- Client-side only. _G.Skyr0NoCollidePlayers = false turns it off.
-- Wrapped in a function so its locals never touch the chunk's 200-local limit.
-- =====================================================================
;(function()
    local Players    = game:GetService("Players")
    local RunService = game:GetService("RunService")
    local LP = Players.LocalPlayer
    if _G.Skyr0NoCollidePlayers == nil then _G.Skyr0NoCollidePlayers = true end
    local function on() return _G.Skyr0NoCollidePlayers ~= false end

    local pinned  = setmetatable({}, { __mode = "k" })   -- part  -> true
    local hooked  = setmetatable({}, { __mode = "k" })   -- model -> true
    local ncBag   = setmetatable({}, { __mode = "k" })   -- model -> { root=, [name]=constraint }
    local THEIRS  = { "HumanoidRootPart", "UpperTorso", "LowerTorso", "Torso", "Head" }

    local function pin(p)
        if not p:IsA("BasePart") then return end
        if p.CanCollide then p.CanCollide = false end
        if pinned[p] then return end
        pinned[p] = true
        pcall(function()
            p:GetPropertyChangedSignal("CanCollide"):Connect(function()
                if p.CanCollide and on() then p.CanCollide = false end
            end)
        end)
    end
    local function pinModel(m)
        if not m or not on() then return end
        for _, d in ipairs(m:GetDescendants()) do pin(d) end
        if not hooked[m] then
            hooked[m] = true
            m.DescendantAdded:Connect(function(d) task.defer(pin, d) end)
        end
    end
    local function constrain(m)
        if not on() or _G.Skyr0NoCollideConstraints == false or not m then return end
        local c = LP.Character
        local mine = c and c:FindFirstChild("HumanoidRootPart")
        if not mine then return end
        local bag = ncBag[m]
        if not bag or bag.root ~= mine then bag = { root = mine }; ncBag[m] = bag end
        for _, n in ipairs(THEIRS) do
            local part = m:FindFirstChild(n)
            if part and part:IsA("BasePart") then
                local k = bag[n]
                if not (k and k.Parent) then
                    pcall(function()
                        local nc = Instance.new("NoCollisionConstraint")
                        nc.Part0, nc.Part1 = mine, part
                        nc.Parent = mine
                        bag[n] = nc
                    end)
                end
            end
        end
    end
    local function handle(m)
        pinModel(m)
        constrain(m)
    end

    -- other players
    local function hookPlayer(pl)
        if pl == LP then return end
        if pl.Character then handle(pl.Character) end
        pl.CharacterAdded:Connect(function(ch)
            task.wait(0.05)
            handle(ch)
            task.wait(0.15)
            handle(ch)
        end)
    end
    for _, pl in ipairs(Players:GetPlayers()) do hookPlayer(pl) end
    Players.PlayerAdded:Connect(hookPlayer)

    -- other players' clone bodies (same test the router uses)
    local function isClone(inst)
        local f = _G.Skyr0IsOtherClone
        if f then return f(inst) end
        return inst.Name:match("^%d+_Clone$") ~= nil and inst.Name ~= tostring(LP.UserId) .. "_Clone"
    end
    local function scanClones()
        for _, c in ipairs(workspace:GetChildren()) do
            if isClone(c) then handle(c) end
        end
    end
    workspace.ChildAdded:Connect(function(c)
        task.defer(function()
            if c.Parent == workspace and isClone(c) then handle(c) end
        end)
        task.delay(0.2, function()          -- root/humanoid may not exist yet
            if c.Parent == workspace and isClone(c) then handle(c) end
        end)
    end)
    scanClones()

    -- your own respawn: the constraints hang off YOUR root, so redo them
    LP.CharacterAdded:Connect(function()
        task.wait(0.3)
        for _, pl in ipairs(Players:GetPlayers()) do
            if pl ~= LP and pl.Character then constrain(pl.Character) end
        end
        for _, c in ipairs(workspace:GetChildren()) do
            if isClone(c) then constrain(c) end
        end
    end)

    -- close-range sweep (every 0.1s) + a slow full re-check (every 1s)
    local acc = 0
    RunService.Stepped:Connect(function(_, dt)
        if not on() or _G.isCloning == true then return end
        acc = acc + (dt or 0.016)
        if acc < 0.1 then return end
        acc = 0
        local c = LP.Character
        local root = c and c:FindFirstChild("HumanoidRootPart")
        if not root then return end
        local mp = root.Position
        local rng = tonumber(_G.Skyr0NoCollideRange) or 28
        local function sweep(m)
            local h = m:FindFirstChild("HumanoidRootPart")
            if h and (h.Position - mp).Magnitude <= rng then
                for _, d in ipairs(m:GetDescendants()) do
                    if d:IsA("BasePart") and d.CanCollide then d.CanCollide = false end
                end
            end
        end
        for _, pl in ipairs(Players:GetPlayers()) do
            if pl ~= LP and pl.Character then sweep(pl.Character) end
        end
        for _, cl in ipairs(workspace:GetChildren()) do
            if isClone(cl) then sweep(cl) end
        end
    end)
    task.spawn(function()
        while true do
            task.wait(1)
            if on() and _G.isCloning ~= true then
                for _, pl in ipairs(Players:GetPlayers()) do
                    if pl ~= LP and pl.Character then handle(pl.Character) end
                end
                scanClones()
            end
        end
    end)
end)()
if _G.__LMARK then _G.__LMARK("L24011") end

-- =====================================================================
-- PLOT CLEANER  --  plot_loader_fixed.lua, as a toggle
-- ---------------------------------------------------------------------
-- ON runs the loader: every base is STASHED (moved out of the world, still
-- replicated, never destroyed) unless it is yours, holds a brainrot at
-- $1M/s or more (_G.Skyr0LoaderThreshold), or skyro needs it -- the Base Camp
-- target, the steal target, or a base with a priority pet. A stashed base
-- comes back the moment what is on it changes. Only plots are touched: map,
-- lighting, textures and every other model are left alone.
-- A base you stand on or are inside is never stashed, and a stashed one comes
-- back the frame you enter its box. Every stashed base gets a purple outline.
-- OFF calls _G.Skyr0LoaderStop(), which puts every stashed base back.
-- =====================================================================
;(function()
    if type(_G.Skyr0PlotCleanerRestore) == "function" then pcall(_G.Skyr0PlotCleanerRestore) end
    if type(_G.Skyr0LoaderStop) == "function" then pcall(_G.Skyr0LoaderStop) end
    _G.Skyr0PlotCleaner = false        -- cross-execution: always start off
    local on = false

    -- bases skyro must never hide; recomputed at most twice a second
    local keepSet, keepAt = {}, 0
    _G.Skyr0PlotCleanerKeep = function(plotName)
        if os.clock() - keepAt > 0.5 then
            keepAt = os.clock()
            local k = {}
            local camp = _G.Skyr0Camp
            if camp and camp.active and camp.plotName then k[camp.plotName] = true end
            local st = _G.Skyr0_StealStatus
            if st and st.target and st.target.plot then k[st.target.plot] = true end
            local sel = SharedState and SharedState.SelectedPetData
            if sel and sel.plot then k[sel.plot] = true end
            local cache = SharedState and SharedState.AllAnimalsCache
            if type(cache) == "table" and _G.Skyr0IsPriority then
                for _, a in ipairs(cache) do
                    if a and a.plot and not k[a.plot] then
                        local ok, isP = pcall(_G.Skyr0IsPriority, a.name, a.index, a.mutation)
                        if ok and isP then k[a.plot] = true end
                    end
                end
            end
            keepSet = k
        end
        return keepSet[plotName] == true
    end

    local function runLoader()
        -- Standalone client-side loader (FIXED). Keeps an ENTIRE plot only while a
        -- brainrot in it generates $1M/s or more (or it is yours); every other plot
        -- is taken out of the workspace -- but no longer DESTROYED.
        --
        -- WHAT WAS BREAKING (plots deleted with the brainrot still in them):
        --   1. Traits were never counted. The synchronizer's AnimalList carries no
        --      Traits, so the computed value was base x mutation only, and a traited
        --      brainrot showing $1.4M/s in game computed as $700k -> plot destroyed.
        --      Now the value is the LARGER of the computed one and the $/s the game
        --      itself draws over the brainrot (read from workspace.Debris), and a
        --      brainrot whose label cannot be read keeps its plot.
        --   2. One scan, then permanent Destroy(). Anything that changed afterwards
        --      (a brainrot swapped in, a new owner joining an empty plot) was never
        --      looked at again, and a bad first read could never be undone. Now every
        --      plot is re-read every 2s; a removed plot is only STASHED (moved to a
        --      client-side folder, alive and still replicated) and comes straight back
        --      the moment its brainrots change or it qualifies.
        --   3. A scan that returned nothing looked like "no brainrots". An empty or
        --      unreadable answer keeps the plot, an unowned-looking plot whose sign
        --      says it has an owner keeps the plot, and a plot is only removed after
        --      two identical reads in a row -- and only once YOUR base is found.
        -- Tunables (set before running): _G.Skyr0LoaderThreshold (1000000)
        -- Always on. Stop / restore everything: _G.Skyr0LoaderStop()
        local Workspace = game:GetService("Workspace")
        local Players = game:GetService("Players")
        local LocalPlayer = Players.LocalPlayer or Players.PlayerAdded:Wait()
        local RunService = game:GetService("RunService")
        local ReplicatedStorage = game:GetService("ReplicatedStorage")
        local THRESHOLD = tonumber(_G.Skyr0LoaderThreshold) or 1000000
        -- same cadence as plot_loader_fixed.lua (it was 0.5 here, so a base that
        -- stopped qualifying lingered for seconds and a changed one came back late)
        local EVAL_EVERY = tonumber(_G.Skyr0LoaderScanEvery) or 0.08   -- seconds between full re-reads (was 0.12)
        local VERIFY_AFTER_RESTORE = tonumber(_G.Skyr0LoaderVerifyAfter) or 3.5 -- (was 5) a restored plot stays put this long (its $/s labels need to render)
        if _G.Skyr0LoaderStop then pcall(_G.Skyr0LoaderStop) end

        local running, connections = true, {}

        -- ============================================================== stash, not destroy
        -- Declared FIRST, together with the stop function. _G.Skyr0LoaderStop used
        -- to be defined only after every startup wait (game load, character,
        -- Plots, Datas, the synchronizer -- up to minutes on a slow join), so
        -- turning the toggle OFF in that window did nothing: the loader carried
        -- on, finished waiting and started stashing bases anyway, and turning it
        -- back ON started a second loader on top of it.
        local stash = Instance.new("Folder")     -- parentless: alive, still replicated, not in the world
        stash.Name = "Skyr0Stash"
        local state = {}                          -- plot -> { stashed, sig, parent, notKeep, lastSig, verifyUntil, boxCF, boxSize, outline }

        -- Each base's box, read once while it is still in the world (bases never
        -- move). Used for "you are on / in this base" and for the outline.
        -- (A parentless model still answers GetBoundingBox/GetPivot from its parts'
        -- CFrames, so this also works on a base that is already stashed.)
        local function plotBox(plot, s)
            if not s.pivot then
                local ok, pv = pcall(function() return plot:GetPivot() end)
                if ok and pv then s.pivot = pv.Position end
            end
            if not s.boxCF then
                local ok, cf, size = pcall(function() return plot:GetBoundingBox() end)
                if ok and cf and size and size.X > 1 and size.Z > 1 then s.boxCF, s.boxSize = cf, size end
            end
            return s.boxCF, s.boxSize
        end
        -- Where your body really is. Invisible steal / desync park the
        -- HumanoidRootPart somewhere else, so the head, the character pivot and
        -- what the camera follows are checked too.
        local function bodyPoints()
            local pts = {}
            local char = LocalPlayer.Character
            if char then
                for _, n in ipairs({ "HumanoidRootPart", "Head", "UpperTorso", "Torso", "LowerTorso" }) do
                    local p = char:FindFirstChild(n)
                    if p and p:IsA("BasePart") then pts[#pts + 1] = p.Position end
                end
                local ok, pv = pcall(function() return char:GetPivot() end)
                if ok and pv then pts[#pts + 1] = pv.Position end
            end
            local cam = Workspace.CurrentCamera
            local subj = cam and cam.CameraSubject
            if subj then
                if subj:IsA("Humanoid") then subj = subj.RootPart end
                if subj and subj:IsA("BasePart") then pts[#pts + 1] = subj.Position end
            end
            return pts
        end
        -- true while you are inside a base, or standing on it / where it was
        local function playerInPlot(s)
            if not (s.boxCF or s.pivot) then return false end
            local m = tonumber(_G.Skyr0LoaderInsideMargin) or 6
            local r = tonumber(_G.Skyr0LoaderInsideRadius) or 26   -- the TP's own "in plot" radius
            for _, pos in ipairs(bodyPoints()) do
                if s.boxCF then
                    local lp = s.boxCF:PointToObjectSpace(pos)
                    if math.abs(lp.X) <= s.boxSize.X / 2 + m and math.abs(lp.Z) <= s.boxSize.Z / 2 + m
                        and lp.Y >= -s.boxSize.Y / 2 - 15 and lp.Y <= s.boxSize.Y / 2 + 30 then
                        return true
                    end
                end
                if s.pivot and math.abs(pos.X - s.pivot.X) <= r and math.abs(pos.Z - s.pivot.Z) <= r
                    and pos.Y >= s.pivot.Y - 20 and pos.Y <= s.pivot.Y + 90 then
                    return true
                end
            end
            return false
        end
        -- purple box drawn where a hidden base is, so you can see what was removed
        local function removeOutline(s)
            if s.outline then pcall(function() s.outline:Destroy() end); s.outline = nil end
        end
        local function addOutline(s)
            removeOutline(s)
            if _G.Skyr0LoaderOutline == false or not (s.boxCF and s.boxSize) then return end
            local p = Instance.new("Part")
            p.Name = "Skyr0StashOutline"
            p.Anchored = true; p.CanCollide = false; p.CanQuery = false; p.CanTouch = false
            p.CastShadow = false; p.Transparency = 1
            p.CFrame, p.Size = s.boxCF, s.boxSize
            local box = Instance.new("SelectionBox")
            box.Adornee = p
            box.Color3 = Color3.fromRGB(167, 110, 247)
            box.LineThickness = tonumber(_G.Skyr0LoaderOutlineThickness) or 0.2
            box.SurfaceTransparency = 1
            box.Parent = p
            p.Parent = Workspace
            s.outline = p
        end
        local function restorePlot(plot, s)
            s.stashed = false
            removeOutline(s)
            plot.Parent = s.parent or Workspace:FindFirstChild("Plots")
        end
        _G.Skyr0LoaderStop = function()
            running = false
            for _, connection in ipairs(connections) do pcall(function() connection:Disconnect() end) end
            for plot, s in pairs(state) do
                if s.stashed then pcall(restorePlot, plot, s) end
                removeOutline(s)
            end
            pcall(function() stash:Destroy() end)
        end
        -- A stashed base is gone from YOUR world only: the server still has every
        -- wall of it. The TP router reads this so it keeps flying around them.
        _G.Skyr0StashedPlots = function()
            local out = {}
            for plot, s in pairs(state) do
                if s.stashed and plot.Parent == stash then out[#out + 1] = plot end
            end
            return out
        end

        -- ============================================================ WAIT FOR THE GAME
        -- Nothing below touches the world until the game has loaded, your character and
        -- PlayerGui exist, and the plots have appeared and stopped changing.
        if not game:IsLoaded() then game.Loaded:Wait() end
        if not running then return end
        LocalPlayer:WaitForChild("PlayerGui", 60)
        do
            local t0 = os.clock()
            while running and not LocalPlayer.Character and os.clock() - t0 < 30 do task.wait(0.1) end
        end
        if not running then return end

        local plots = Workspace:WaitForChild("Plots", 90)
        if not plots or not running then return end
        do  -- let them finish streaming in: the count must hold steady for half a second
            local last, since = -1, os.clock()
            local t0 = os.clock()
            while running and os.clock() - t0 < 60 do
                local n = #plots:GetChildren()
                if n ~= last then last, since = n, os.clock() end
                if n > 0 and os.clock() - since >= (tonumber(_G.Skyr0LoaderSettle) or 0.25) then break end
                task.wait(0.1)
            end
        end

        local datas = ReplicatedStorage:WaitForChild("Datas", 90)
        if not datas then return end
        local okAnimals, animalsData = pcall(require, datas:WaitForChild("Animals", 90))
        local okMutations, mutations = pcall(require, datas:WaitForChild("Mutations", 90))
        local okTraits, traitsData = pcall(require, datas:WaitForChild("Traits", 90))
        local okGame, gameData = pcall(require, datas:WaitForChild("Game", 90))
        if not (okAnimals and type(animalsData) == "table" and okMutations and okTraits and okGame) then
            return
        end
        local function generation(index, mutation, traits)
            local animal = animalsData[index]
            if not animal then return nil end
            local base = animal.Generation
            if not base then
                local modifier = gameData.Game and gameData.Game.AnimalGanerationModifier
                if type(modifier) ~= "number" then return nil end
                base = (animal.Price or 0) * modifier
            end
            local mult = 1
            local mutationData = mutation and mutations[mutation]
            if mutationData then mult = mult + (mutationData.Modifier or 0) end
            local sleepy = false
            for _, trait in pairs(traits or {}) do
                if trait == "Sleepy" then sleepy = true
                else
                    local traitData = traitsData[trait]
                    if traitData then mult = mult + (traitData.MultiplierModifier or 0) end
                end
            end
            local result = base * mult
            if sleepy then result = result * 0.5 end
            return math.round(result)
        end
        local packages = ReplicatedStorage:WaitForChild("Packages", 90)
        local syncFolder = packages and packages:WaitForChild("Synchronizer", 90)
        local requestData = syncFolder and syncFolder:WaitForChild("RequestData", 90)
        if not (requestData and requestData:IsA("RemoteFunction")) or not running then
            return
        end

        -- ============================================================ the $/s the game draws
        -- The synchronizer's AnimalList has no Traits, so the computed value above
        -- undercounts any traited brainrot. The game draws the REAL $/s in an overhead
        -- billboard parked in workspace.Debris (tied to the pet by a Motor6D, not a
        -- child of the plot). Read those and match each one to its podium.
        local SUF = { K = 1e3, M = 1e6, B = 1e9, T = 1e12, Qa = 1e15, Qi = 1e18,
                      Sx = 1e21, Sp = 1e24, Oc = 1e27, No = 1e30, Dc = 1e33 }
        local function parseMps(text)
            if type(text) ~= "string" then return nil end
            local num, suf = text:match("%$%s*([%d%.]+)%s*(%a*)%s*/s")
            local v = tonumber(num)
            if not v then return nil end
            if suf and suf ~= "" then
                local m = SUF[suf] or SUF[suf:sub(1, 1):upper() .. suf:sub(2):lower()]
                if not m then return nil end     -- an unknown suffix is "unreadable", not a small number
                v = v * m
            end
            return v
        end
        local function readOverheads()
            local out = {}
            local debris = Workspace:FindFirstChild("Debris")
            if not debris then return out end
            local terra = Workspace:FindFirstChildOfClass("Terrain")
            for _, d in ipairs(debris:GetDescendants()) do
                if (d:IsA("BillboardGui") or d:IsA("SurfaceGui")) and d:FindFirstChild("Traits") then
                    local part = d.Parent
                    if part and part:IsA("BasePart") then
                        local pos = part.Position
                        local m6 = part:FindFirstChild("__foh_transform")
                        if m6 and m6:IsA("Motor6D") and m6.Part0 and m6.Part0 ~= terra and m6.Part0:IsA("BasePart") then
                            pos = m6.Part0.Position
                        end
                        if pos.Y < 9000 then       -- (0,10000,0) is where unused ones are parked
                            local mps
                            for _, t in ipairs(d:GetDescendants()) do
                                if t:IsA("TextLabel") then
                                    mps = parseMps(t.Text)
                                    if mps then break end
                                end
                            end
                            if mps then out[#out + 1] = { pos = pos, mps = mps } end
                        end
                    end
                end
            end
            return out
        end
        local podCache = setmetatable({}, { __mode = "k" })   -- plot -> { at, list }
        local function podiumList(plot)
            local c = podCache[plot]
            if c and os.clock() - c.at < 10 and #c.list > 0 then return c.list end
            local list = {}
            local pods = plot:FindFirstChild("AnimalPodiums")
            if pods then
                for _, p in ipairs(pods:GetChildren()) do
                    local ok, cf = pcall(p.GetPivot, p)
                    if ok then list[#list + 1] = { slot = p.Name, pos = cf.Position } end
                end
            end
            podCache[plot] = { at = os.clock(), list = list }
            return list
        end
        -- plot name -> slot -> the $/s number currently drawn over that podium's brainrot
        local function buildDisplayed(list)
            local disp, pods = {}, {}
            for _, plot in ipairs(list) do
                for _, pd in ipairs(podiumList(plot)) do
                    pods[#pods + 1] = { plot = plot.Name, slot = pd.slot, pos = pd.pos }
                end
            end
            for _, oh in ipairs(readOverheads()) do
                local best, bestD = nil, 9
                for _, pd in ipairs(pods) do
                    local dx, dz = oh.pos.X - pd.pos.X, oh.pos.Z - pd.pos.Z
                    local d = math.sqrt(dx * dx + dz * dz)
                    if d <= bestD then best, bestD = pd, d end
                end
                if best then
                    disp[best.plot] = disp[best.plot] or {}
                    local cur = disp[best.plot][best.slot]
                    if not cur or oh.mps > cur then disp[best.plot][best.slot] = oh.mps end
                end
            end
            return disp
        end

        -- PlotSign owner check plus its YourBase marker.
        -- This only identifies the plot; this loader never creates a Beam or a line.
        local function signText(plot)
            local sign = plot:FindFirstChild("PlotSign")
            local surfaceGui = sign and sign:FindFirstChildWhichIsA("SurfaceGui", true)
            local label = surfaceGui and surfaceGui:FindFirstChildWhichIsA("TextLabel", true)
            return label and label.Text or nil
        end
        local function findMyPlot()
            for _, plot in ipairs(plots:GetChildren()) do
                local sign = plot:FindFirstChild("PlotSign")
                if sign then
                    local marker = sign:FindFirstChild("YourBase")
                    if marker and marker:IsA("BillboardGui") and marker.Enabled then
                        return plot
                    end
                    local text = signText(plot)
                    if text then
                        text = text:lower()
                        if text:find(LocalPlayer.Name:lower(), 1, true)
                            or text:find(LocalPlayer.DisplayName:lower(), 1, true) then
                            return plot
                        end
                    end
                end
            end
        end

        -- ================================================================ read one plot
        -- Returns nil when the answer cannot be trusted (the plot is then KEPT).
        -- Otherwise { top = highest $/s seen, uncertain = a label was unreadable,
        --             sig = a fingerprint of what is on it }, plus the owner.
        local function readPlot(plot, disp)
            local ok, result = pcall(function() return requestData:InvokeServer(plot.Name) end)
            local cache = ok and type(result) == "table" and result or nil
            if type(cache) ~= "table" then return nil end
            local animals = cache.AnimalList or cache.Animals
            if type(animals) ~= "table" then
                -- Unowned plots have no AnimalList. An owned plot without a readable
                -- list is unresolved -- and so is one whose sign names an owner.
                if cache.Owner == nil and next(cache) ~= nil then
                    local text = signText(plot)
                    if text and text ~= "" and text ~= "Empty Base" then return nil end
                    animals = {}
                else
                    return nil
                end
            end
            local info, parts = { top = 0, uncertain = false }, {}
            for slot, animal in pairs(animals) do
                if type(animal) == "table" and animal.Index then
                    local computed = generation(animal.Index, animal.Mutation, animal.Traits)
                    if type(computed) ~= "number" then return nil end
                    local shown = disp and disp[plot.Name] and disp[plot.Name][tostring(slot)]
                    if shown == nil then info.uncertain = true end
                    local v = math.max(computed, shown or 0)
                    if v > info.top then info.top = v end
                    parts[#parts + 1] = tostring(slot) .. "=" .. tostring(animal.Index) .. "/" .. tostring(animal.Mutation)
                end
            end
            table.sort(parts)
            info.sig = table.concat(parts, ",")
            return info, cache.Owner
        end

        local myPlotName, cycles = nil, 0
        local function stateOf(plot)
            local s = state[plot]
            if not s then
                s = { stashed = false, notKeep = 0, verifyUntil = 0 }
                state[plot] = s
                connections[#connections + 1] = plot.Destroying:Connect(function()
                    removeOutline(s)
                    state[plot] = nil
                end)
            end
            return s
        end
        local function stashPlot(plot, s, sig)
            plotBox(plot, s)
            -- never pull a base out from under you
            if playerInPlot(s) then return end
            s.stashed, s.sig, s.parent = true, sig, plot.Parent
            plot.Parent = stash
            addOutline(s)
        end
        -- Every frame: a hidden base you walk into, land in or stand on comes
        -- back at once (the 0.12s cycle waits on server reads, too slow for this).
        -- It goes away again the frame you leave its box -- no 3.5s wait -- as
        -- long as nothing on it changed while you were there (the loop clears
        -- proxRestored if it did, and then the normal two-read rule applies).
        -- If it changes after it is hidden again, the loop brings it back as usual.
        connections[#connections + 1] = RunService.Heartbeat:Connect(function()
            if not running then return end
            for plot, s in pairs(state) do
                if s.stashed and plot.Parent == stash and (s.boxCF or plotBox(plot, s) or s.pivot)
                    and playerInPlot(s) then
                    pcall(restorePlot, plot, s)
                    s.verifyUntil, s.notKeep, s.lastSig = 0, 0, nil
                    s.proxRestored, s.proxSig = true, s.sig
                elseif s.proxRestored and not s.stashed and plot.Parent ~= stash and not playerInPlot(s) then
                    s.proxRestored = false
                    if s.proxSig and plot.Name ~= myPlotName
                        and not (_G.Skyr0PlotCleanerKeep and _G.Skyr0PlotCleanerKeep(plot.Name)) then
                        pcall(stashPlot, plot, s, s.proxSig)
                    end
                end
            end
        end)


        -- ==================================================================== the loop
        local lastDisp, lastDispAt = nil, 0
        local function cycle()
            local visible = plots:GetChildren()
            local all = {}
            for _, plot in ipairs(visible) do all[#all + 1] = plot end
            for plot, s in pairs(state) do
                if s.stashed then
                    if plot.Parent == stash then all[#all + 1] = plot
                    elseif plot.Parent ~= nil then s.stashed = false; removeOutline(s) end   -- something put it back
                end
            end
            myPlotName = (findMyPlot() or {}).Name or myPlotName

            if not lastDisp or os.clock() - lastDispAt > 0.5 then
                lastDisp, lastDispAt = buildDisplayed(visible), os.clock()
            end
            local disp = lastDisp
            local results, pending = {}, #all
            for _, plot in ipairs(all) do
                task.spawn(function()
                    local ok, info, owner = pcall(readPlot, plot, disp)
                    results[plot] = ok and info or nil
                    if ok and info and not myPlotName and owner ~= nil then
                        if owner == LocalPlayer or owner == LocalPlayer.Name or owner == LocalPlayer.UserId
                            or (type(owner) == "table" and
                                (owner.UserId == LocalPlayer.UserId or owner.Name == LocalPlayer.Name)) then
                            myPlotName = plot.Name
                        end
                    end
                    pending = pending - 1
                end)
            end
            local t0 = os.clock()
            while pending > 0 and running and os.clock() - t0 < (tonumber(_G.Skyr0LoaderReadWait) or 0.9) do RunService.Heartbeat:Wait() end
            if not running then return end
            cycles = cycles + 1

            -- nothing is removed until your own base is known and a few full reads have agreed
            local ready = myPlotName ~= nil and cycles >= 2
            local now = os.clock()
            for _, plot in ipairs(all) do
                local s = stateOf(plot)
                local info = results[plot]
                if s.stashed then
                    -- a stashed plot has no rendered labels to re-verify against; it
                    -- only comes back if its contents CHANGED
                    if (info and info.sig ~= s.sig) or (_G.Skyr0PlotCleanerKeep and _G.Skyr0PlotCleanerKeep(plot.Name)) then
                        restorePlot(plot, s)
                        s.verifyUntil, s.notKeep, s.lastSig = now + VERIFY_AFTER_RESTORE, 0, nil
                    end
                else
                    plotBox(plot, s)
                    -- a base brought back because you walked in: if what is on it
                    -- changed, or it now qualifies, it no longer vanishes on exit
                    if s.proxRestored and info and (info.sig ~= s.proxSig
                        or (not info.uncertain and info.top >= THRESHOLD)) then
                        s.proxRestored = false
                    end
                    local keep = plot.Name == myPlotName or info == nil or info.top >= THRESHOLD or info.uncertain
                        or (_G.Skyr0PlotCleanerKeep and _G.Skyr0PlotCleanerKeep(plot.Name))
                        or playerInPlot(s)
                    if keep then
                        s.notKeep, s.lastSig = 0, info and info.sig
                    else
                        if s.lastSig == info.sig then s.notKeep = s.notKeep + 1 else s.notKeep = 1 end
                        s.lastSig = info.sig
                        if ready and s.notKeep >= 2 and now >= s.verifyUntil then
                            stashPlot(plot, s, info.sig)
                            RunService.Heartbeat:Wait()
                        end
                    end
                end
            end
        end

        task.spawn(function()
            while running do
                pcall(cycle)
                task.wait(EVAL_EVERY)
            end
        end)

    end

    _G.Skyr0PlotCleanerRestore = function()
        if _G.Skyr0LoaderStop then pcall(_G.Skyr0LoaderStop) end
    end

    function _G.Skyr0SetPlotCleaner(want)
        want = (want == true)
        if on == want then return end
        on = want
        _G.Skyr0PlotCleaner = want
        Config.PlotCleaner = want
        pcall(saveConfig)
        if want then
            task.spawn(function()
                local ok, err = pcall(runLoader)
                if not ok then warn("[skyr0] Plot Cleaner error: " .. tostring(err)) end
            end)
        else
            if _G.Skyr0LoaderStop then pcall(_G.Skyr0LoaderStop) end
        end
        pcall(setToggle, "Plot Cleaner", want)
    end
    if Config.PlotCleaner == true then
        task.defer(function() _G.Skyr0SetPlotCleaner(true) end)
    end
end)()
if _G.__LMARK then _G.__LMARK("L24582") end

-- =====================================================================
-- BASE CAMP  (auto grab + slot TP)
-- ---------------------------------------------------------------------
-- Pick a player in the Base Camp window and switch it on. Switching it on
-- takes you to their open slot the way rose.lua's camp does: grapple first,
-- then skyro's pathfinding flight TP (switching player mid-flight cancels it
-- and goes to the new one); the TP button does it again on demand.
-- Once you have arrived, the K7 instant grab below (on ONLY while camping) fires every
-- prompt in that player's base within 200 studs (nearest first, whole base), so
-- anything sitting in it -- or that they steal into it -- is grabbed the
-- moment it can be. Debug lines print as "[skyr0 camp] ...".
--
-- ESP: the next open slot (where to stand, cyan) and the slot the grab is
-- going for (nearest occupied one, green), each with a label naming the slot.
--
-- Exposes _G.Skyr0Camp { active, target, plotName, status, start, stop } --
-- read by the nearest grab and the progress bar.
-- =====================================================================
;(function()
    local Players    = game:GetService("Players")
    local RunService = game:GetService("RunService")
    local UIS        = game:GetService("UserInputService")
    local LP = Players.LocalPlayer

    local RC = { active = false, target = nil, plotName = nil, status = "idle",
                 standSlot = nil, grabSlot = nil, grabEntry = nil }
    _G.Skyr0Camp = RC

    -- DEBUG: Base Camp prints "[skyr0 camp] ..." to the executor console.
    -- _G.Skyr0CampDebug = false silences it. key + every rate-limit a line so a
    -- per-frame check prints at most once every `every` seconds.
    if _G.Skyr0CampDebug == nil then _G.Skyr0CampDebug = true end
    local logAt = {}
    _G.Skyr0CampLog = function(key, msg, every)
        if _G.Skyr0CampDebug ~= true then return end
        if key then
            local now = os.clock()
            if logAt[key] and now - logAt[key] < (every or 1.5) then return end
            logAt[key] = now
        end
        print("[skyr0 camp] " .. tostring(msg))
    end
    local clog = _G.Skyr0CampLog

    local function col(key, fallback)
        local t = Theme
        return (t and t[key]) or fallback
    end
    local C_BG     = col("MainBackground", Color3.fromRGB(16, 16, 20))
    local C_ROW    = col("Background", Color3.fromRGB(26, 26, 32))
    local C_ACCENT = col("AccentLight", Color3.fromRGB(170, 85, 255))
    local C_ON     = col("Green", Color3.fromRGB(80, 220, 120))
    local C_TEXT   = Color3.fromRGB(240, 240, 245)
    local C_DIM    = Color3.fromRGB(150, 150, 165)
    local C_STAND  = Color3.fromRGB(80, 200, 255)
    local C_GRAB   = Color3.fromRGB(80, 230, 120)
    local C_STEAL  = Color3.fromRGB(255, 90, 90)
    local C_STEALBG = Color3.fromRGB(70, 22, 26)

    local function notify(text)
        pcall(function()
            game:GetService("StarterGui"):SetCore("SendNotification", { Title = "Base Camp", Text = text, Duration = 4 })
        end)
    end

    -- ------------------------------------------------------------ who is stealing what
    -- The game flags a thief with the player attributes "Stealing" (bool) and
    -- "StealingIndex" (the animal's index). The index maps to a display name
    -- through Datas.Animals; when it is missing, the carried model on their
    -- character is the fallback, and "Brainrot" after that.
    local animalsData
    local function animalsTbl()
        if animalsData == nil then
            local ok, res = pcall(function()
                return require(game:GetService("ReplicatedStorage"):WaitForChild("Datas", 5):WaitForChild("Animals", 5))
            end)
            animalsData = (ok and type(res) == "table") and res or false
        end
        return animalsData or nil
    end
    local function displayNameOf(index)
        local ad = animalsTbl()
        local info = ad and index and ad[index]
        return (type(info) == "table" and info.DisplayName) or (index and tostring(index)) or nil
    end
    local function stealingWhat(plr)
        if not plr or plr:GetAttribute("Stealing") ~= true then return nil end
        local idx = plr:GetAttribute("StealingIndex")
        if idx ~= nil and tostring(idx) ~= "" then return displayNameOf(tostring(idx)) end
        local ad = animalsTbl()
        local ch = plr.Character
        if ad and ch then
            for _, d in ipairs(ch:GetDescendants()) do
                if d:IsA("Model") and ad[d.Name] then return displayNameOf(d.Name) end
            end
        end
        return "Brainrot"
    end
    -- name -> what they are carrying right now (nil = not stealing)
    local stealInfo = {}
    RC.stealInfo = stealInfo

    -- ------------------------------------------------------------ base lookup
    local function plotOwnerName(plot)
        local sign = plot and plot:FindFirstChild("PlotSign")
        local gui  = sign and sign:FindFirstChildWhichIsA("SurfaceGui", true)
        local lbl  = gui and gui:FindFirstChildWhichIsA("TextLabel", true)
        if not (lbl and lbl.Text) then return nil end
        local nick = lbl.Text:match("^(.-)'") or lbl.Text
        nick = nick and nick:gsub("%s+$", "")
        if nick == "" then return nil end
        return nick
    end

    local function findPlotFor(plr)
        local plots = workspace:FindFirstChild("Plots")
        if not (plots and plr) then return nil end
        local n, dn = plr.Name:lower(), (plr.DisplayName or ""):lower()
        for _, plot in ipairs(plots:GetChildren()) do
            local owner = plotOwnerName(plot)
            if owner then
                local ol = owner:lower()
                if ol == n or ol == dn then return plot end
            end
        end
        return nil
    end

    local function slotPrompt(slot)
        local base  = slot:FindFirstChild("Base")
        local spawn = base and base:FindFirstChild("Spawn")
        local att   = spawn and spawn:FindFirstChild("PromptAttachment")
        if att then
            for _, p in ipairs(att:GetChildren()) do
                if p:IsA("ProximityPrompt") and p.Enabled and p.ActionText == "Steal" then return p end
            end
        end
        for _, d in ipairs(slot:GetDescendants()) do
            if d:IsA("ProximityPrompt") and d.Enabled and d.ActionText == "Steal" then return d end
        end
        return nil
    end

    -- podium slots with a Base.Spawn, in numeric order ("2" before "10")
    local function sortedSlots(plot)
        local pods = plot and plot:FindFirstChild("AnimalPodiums")
        local slots = {}
        if not pods then return slots end
        for _, s in ipairs(pods:GetChildren()) do
            local base  = s:FindFirstChild("Base")
            local spawn = base and base:FindFirstChild("Spawn")
            if spawn and spawn:IsA("BasePart") then slots[#slots + 1] = s end
        end
        table.sort(slots, function(a, b)
            local na, nb = tonumber(tostring(a.Name):match("%d+")), tonumber(tostring(b.Name):match("%d+"))
            if na and nb then return na < nb end
            return tostring(a.Name) < tostring(b.Name)
        end)
        return slots
    end

    local function petInSlot(plotName, slotName)
        local cache = SharedState and SharedState.AllAnimalsCache
        if type(cache) ~= "table" then return nil end
        for _, a in ipairs(cache) do
            if a and a.plot == plotName and tostring(a.slot) == tostring(slotName) then return a end
        end
        return nil
    end

    -- stand = first open slot; grab = nearest occupied slot to you
    local function scanCamp(plot)
        local slots = sortedSlots(plot)
        local stand, grab, grabD = nil, nil, math.huge
        local full = #slots > 0
        local c = LP.Character
        local hrp = c and c:FindFirstChild("HumanoidRootPart")
        for _, slot in ipairs(slots) do
            if slotPrompt(slot) then
                local d = hrp and (slot.Base.Spawn.Position - hrp.Position).Magnitude or 0
                if d < grabD then grab, grabD = slot, d end
            else
                full = false
                stand = stand or slot
            end
        end
        return stand, grab, full, grabD
    end

    -- Go to the camped base's open slot (the first podium with nothing on it;
    -- the first podium when the base is full), with the slot handed to skyro's
    -- flight TP as a forced target, so no picker can send it elsewhere.
    -- rose's camp TP: ALWAYS the hub's real teleport -- grapple fired first,
    -- then the pathfinding route, flight and clone-in -- never an instant snap.
    -- Switching target mid-flight cancels the running flight and starts the
    -- new one instead of refusing. The grab stays off (RC.arrived = false)
    -- until the TP has finished, so it never fights the flight.
    local tpGen = 0
    local function tpToCampSlot(plot)
        if not plot then clog(nil, "TP: no base to go to"); return false, "base not found" end
        if _G.Skyr0IsStealing and _G.Skyr0IsStealing() then clog(nil, "TP: refused, you are carrying a brainrot"); return false, "you are stealing" end
        local char = LP.Character
        local root = char and (char.PrimaryPart or char:FindFirstChild("HumanoidRootPart"))
        local hum = char and char:FindFirstChildOfClass("Humanoid")
        if not (root and hum and hum.Health > 0) then return false, "no character" end
        if not _G.Skyr0DoVelocityTP then clog(nil, "TP: engine not loaded"); return false, "TP engine not loaded" end

        local stand = scanCamp(plot)
        local slot = stand or sortedSlots(plot)[1]
        local spawn = slot and slot.Base.Spawn
        if not spawn then return false, "no slots in that base" end
        local dest = spawn.Position + Vector3.new(0, 3, 0)

        clog(nil, ("TP: open slot %s at %.0f, %.0f, %.0f (%.0f studs away, %s)"):format(
            tostring(slot.Name), dest.X, dest.Y, dest.Z, (root.Position - dest).Magnitude,
            stand and "first empty slot" or "base FULL, using first slot"))

        tpGen = tpGen + 1
        local myGen = tpGen
        RC.arrived = false
        local entry = {
            name = "Base Camp", index = "Base Camp", mps = 0, mutation = "None",
            position = spawn.Position, plot = plot.Name, slot = tostring(slot.Name),
            campSlot = true,
        }
        task.spawn(function()
            -- a flight already running (switching target mid-TP): cancel it and
            -- wait for it to let go before starting the new one
            if _G.Skyr0TPActive and _G.Skyr0TPActive() then
                clog(nil, "TP: cancelling the running flight for the new target")
                _G.Skyr0TPCancel = true
                local c0 = os.clock()
                while _G.Skyr0TPActive() and os.clock() - c0 < 2 do task.wait(0.05) end
                if _G.Skyr0TPActive() and _G.Skyr0ForceIdleTP then pcall(_G.Skyr0ForceIdleTP) end
                task.wait(0.1)
            end
            if myGen ~= tpGen then return end
            local s = Config and Config.TpSettings or {}
            _G.TPVelocity   = math.max(tonumber(s.GrabbleTPSpeed) or 400, 400)
            _G.TPCloneDelay = tonumber(s.CloneDelayVal) or 0.1
            _G.LandingDelay = _G.LandingDelay or 0.4
            _G.Skyr0TPCancel = false
            -- doVelocityTP -> run(pet, forceGrapple = true): the grapple goes
            -- out FIRST, aimed at the slot, then the computeRoute pathfinding
            -- flight, clone and walk-in onto the open slot
            clog(nil, "TP: grapple -> pathfinding flight to the slot")
            task.spawn(function() pcall(_G.Skyr0DoVelocityTP, entry) end)
            -- same wait as rose: for the TP to begin, then to finish
            local t0 = os.clock()
            while myGen == tpGen and not _G.Skyr0TPActive() and os.clock() - t0 < 3 do task.wait(0.05) end
            local t1 = os.clock()
            while myGen == tpGen and _G.Skyr0TPActive() and os.clock() - t1 < 15 do task.wait(0.1) end
            if myGen ~= tpGen then return end
            RC.arrivedAt = os.clock()
            RC.arrived = true
            clog(nil, "TP: arrived -> grab armed")
        end)
        return true, "slot " .. (tostring(slot.Name):match("%d+") or slot.Name)
    end
    RC.tp = function()
        local plots = workspace:FindFirstChild("Plots")
        local plot = RC.plotName and plots and plots:FindFirstChild(RC.plotName)
        if not plot and RC.target then
            local plr = Players:FindFirstChild(RC.target)
            plot = plr and findPlotFor(plr)
        end
        return tpToCampSlot(plot)
    end

    -- ------------------------------------------------------------ window
    local guiParent = (gethui and gethui()) or game:GetService("CoreGui")
    pcall(function() local o = guiParent:FindFirstChild("Skyr0_BaseCamp"); if o then o:Destroy() end end)

    local sg = Instance.new("ScreenGui")
    sg.Name = "Skyr0_BaseCamp"
    sg.ResetOnSpawn = false
    sg.ZIndexBehavior = Enum.ZIndexBehavior.Sibling
    sg.DisplayOrder = 997
    sg.Parent = guiParent

    local W, H = 230, 316
    local frame = Instance.new("Frame")
    frame.Size = UDim2.fromOffset(W, H)
    frame.Position = UDim2.new(1, -W - 20, 0.5, -H / 2)
    do
        -- saved position: {xScale, xOffset, yScale, yOffset} in Config.BaseCampPos
        local sp = Config and Config.BaseCampPos
        if type(sp) == "table" and tonumber(sp[1]) and tonumber(sp[2]) and tonumber(sp[3]) and tonumber(sp[4]) then
            frame.Position = UDim2.new(tonumber(sp[1]), tonumber(sp[2]), tonumber(sp[3]), tonumber(sp[4]))
        end
    end
    frame.BackgroundColor3 = C_BG
    frame.BorderSizePixel = 0
    frame.Active = true
    frame.Parent = sg
    Instance.new("UICorner", frame).CornerRadius = UDim.new(0, 14)
    if addOutline then addOutline(frame) end
    if decoratePanel then decoratePanel(frame) end

    local bar = Instance.new("Frame", frame)
    bar.Size = UDim2.new(1, 0, 0, 28)
    bar.BackgroundTransparency = 1

    local title = Instance.new("TextLabel", bar)
    title.Size = UDim2.new(1, -40, 1, 0)
    title.Position = UDim2.fromOffset(20, 0)
    title.BackgroundTransparency = 1
    title.Font = Enum.Font.GothamBlack
    title.TextSize = 12
    title.TextColor3 = C_TEXT
    title.TextXAlignment = Enum.TextXAlignment.Center
    title.Text = "BASE CAMP"

    local minBtn = Instance.new("TextButton", bar)
    minBtn.Size = UDim2.fromOffset(24, 20)
    minBtn.Position = UDim2.new(1, -30, 0, 4)
    minBtn.BackgroundColor3 = C_ROW
    minBtn.BorderSizePixel = 0
    minBtn.Font = Enum.Font.GothamBold
    minBtn.TextSize = 14
    minBtn.TextColor3 = C_TEXT
    minBtn.Text = "-"
    minBtn.AutoButtonColor = false
    Instance.new("UICorner", minBtn).CornerRadius = UDim.new(0, 6)

    local body = Instance.new("Frame", frame)
    body.Size = UDim2.new(1, 0, 1, -28)
    body.Position = UDim2.fromOffset(0, 28)
    body.BackgroundTransparency = 1

    local toggle = Instance.new("TextButton", body)
    toggle.Size = UDim2.new(1, -66, 0, 30)
    toggle.Position = UDim2.fromOffset(8, 2)
    toggle.BorderSizePixel = 0
    toggle.Font = Enum.Font.GothamBold
    toggle.TextSize = 13
    toggle.AutoButtonColor = false
    toggle.TextTruncate = Enum.TextTruncate.AtEnd
    Instance.new("UICorner", toggle).CornerRadius = UDim.new(0, 8)

    -- TP again to the camped (or selected) player's open slot
    local tpBtn = Instance.new("TextButton", body)
    tpBtn.Size = UDim2.fromOffset(46, 30)
    tpBtn.Position = UDim2.new(1, -54, 0, 2)
    tpBtn.BorderSizePixel = 0
    tpBtn.Font = Enum.Font.GothamBold
    tpBtn.TextSize = 13
    tpBtn.Text = "TP"
    tpBtn.TextColor3 = C_TEXT
    tpBtn.BackgroundColor3 = C_ROW
    tpBtn.AutoButtonColor = true
    Instance.new("UICorner", tpBtn).CornerRadius = UDim.new(0, 8)

    local status = Instance.new("TextLabel", body)
    status.Size = UDim2.new(1, -16, 0, 62)
    status.Position = UDim2.fromOffset(8, 36)
    status.BackgroundTransparency = 1
    status.Font = Enum.Font.Gotham
    status.TextSize = 11
    status.TextColor3 = C_DIM
    status.TextXAlignment = Enum.TextXAlignment.Left
    status.TextYAlignment = Enum.TextYAlignment.Top
    status.TextWrapped = true
    status.RichText = true

    local listLbl = Instance.new("TextLabel", body)
    listLbl.Size = UDim2.new(1, -16, 0, 14)
    listLbl.Position = UDim2.fromOffset(8, 100)
    listLbl.BackgroundTransparency = 1
    listLbl.Font = Enum.Font.GothamBold
    listLbl.TextSize = 10
    listLbl.TextColor3 = C_DIM
    listLbl.TextXAlignment = Enum.TextXAlignment.Left
    listLbl.Text = "PICK A PLAYER"

    local list = Instance.new("ScrollingFrame", body)
    list.Size = UDim2.new(1, -16, 1, -120)
    list.Position = UDim2.fromOffset(8, 116)
    list.BackgroundTransparency = 1
    list.BorderSizePixel = 0
    list.ScrollBarThickness = 3
    list.ScrollBarImageColor3 = C_ACCENT
    list.AutomaticCanvasSize = Enum.AutomaticSize.Y
    list.CanvasSize = UDim2.new()
    local layout = Instance.new("UIListLayout", list)
    layout.Padding = UDim.new(0, 4)
    -- thieves float to the top (LayoutOrder 0), everyone else stays alphabetical
    layout.SortOrder = Enum.SortOrder.LayoutOrder

    -- drag by the title bar (mouse + touch)
    do
        local dragging, dStart, fStart
        bar.InputBegan:Connect(function(i)
            if i.UserInputType == Enum.UserInputType.MouseButton1 or i.UserInputType == Enum.UserInputType.Touch then
                dragging, dStart, fStart = true, i.Position, frame.Position
            end
        end)
        UIS.InputChanged:Connect(function(i)
            if dragging and (i.UserInputType == Enum.UserInputType.MouseMovement or i.UserInputType == Enum.UserInputType.Touch) then
                local d = i.Position - dStart
                frame.Position = UDim2.new(fStart.X.Scale, fStart.X.Offset + d.X, fStart.Y.Scale, fStart.Y.Offset + d.Y)
            end
        end)
        UIS.InputEnded:Connect(function(i)
            if i.UserInputType == Enum.UserInputType.MouseButton1 or i.UserInputType == Enum.UserInputType.Touch then
                if dragging and _G.__Skyr0CampSavePos then _G.__Skyr0CampSavePos() end
                dragging = false
            end
        end)
    end

    local minimized = false
    local function savePos()
        if not Config then return end
        local p = frame.Position
        Config.BaseCampPos = { p.X.Scale, math.floor(p.X.Offset + 0.5), p.Y.Scale, math.floor(p.Y.Offset + 0.5) }
        Config.BaseCampMin = minimized == true
        if saveConfig then pcall(saveConfig) end
    end
    _G.__Skyr0CampSavePos = savePos

    local function applyMin()
        body.Visible = not minimized
        frame.Size = minimized and UDim2.fromOffset(W, 28) or UDim2.fromOffset(W, H)
        minBtn.Text = minimized and "+" or "-"
    end
    _G.Skyr0OnTap(minBtn, function()
        minimized = not minimized
        applyMin()
        savePos()
    end)
    if Config and Config.BaseCampMin == true then minimized = true; applyMin() end

    -- a position saved on a bigger screen could leave the window off-screen:
    -- pull it back inside the viewport once layout has run
    task.defer(function()
        task.wait()
        local cam = workspace.CurrentCamera
        local vp = cam and cam.ViewportSize
        if not vp or vp.X < 50 then return end
        local ap, as = frame.AbsolutePosition, frame.AbsoluteSize
        local nx = math.clamp(ap.X, 0, math.max(0, vp.X - as.X))
        local ny = math.clamp(ap.Y, 0, math.max(0, vp.Y - 28))
        if nx ~= ap.X or ny ~= ap.Y then
            frame.Position = UDim2.fromOffset(nx, ny)
        end
    end)

    -- ------------------------------------------------------------ ESP
    local function makeMarker(color)
        local box = Instance.new("SelectionBox")
        box.LineThickness = 0.08
        box.Color3 = color
        box.SurfaceColor3 = color
        box.SurfaceTransparency = 0.75
        box.Visible = false
        box.Parent = sg
        local bb = Instance.new("BillboardGui")
        bb.Size = UDim2.fromOffset(170, 34)
        bb.StudsOffset = Vector3.new(0, 4, 0)
        bb.AlwaysOnTop = true
        bb.Enabled = false
        bb.Parent = sg
        local t = Instance.new("TextLabel", bb)
        t.Size = UDim2.fromScale(1, 1)
        t.BackgroundTransparency = 1
        t.Font = Enum.Font.GothamBlack
        t.TextSize = 13
        t.TextColor3 = color
        t.TextStrokeTransparency = 0.3
        t.TextWrapped = true
        return { box = box, bb = bb, label = t }
    end
    local standMk = makeMarker(C_STAND)
    local grabMk  = makeMarker(C_GRAB)

    local function showMarker(mk, part, text)
        if part then
            mk.box.Adornee = part; mk.box.Visible = true
            mk.bb.Adornee = part;  mk.bb.Enabled = true
            mk.label.Text = text
        else
            mk.box.Visible = false; mk.box.Adornee = nil
            mk.bb.Enabled = false;  mk.bb.Adornee = nil
        end
    end

    -- ------------------------------------------------------------ state
    local selected = nil   -- player name picked in the list
    local rows = {}

    local function refreshToggle()
        toggle.Text = RC.active and ("CAMP: ON  -  " .. tostring(RC.target)) or "CAMP: OFF"
        toggle.BackgroundColor3 = RC.active and C_ON or C_ROW
        toggle.TextColor3 = RC.active and Color3.fromRGB(10, 10, 12) or C_TEXT
    end

    local function rowLabel(plr)
        return plr and ("  " .. plr.DisplayName .. "  (@" .. plr.Name .. ")") or ""
    end

    -- selected = accent fill; stealing = red fill + red outline, a second line
    -- naming the brainrot, and sorted to the top of the list
    local function refreshRows()
        local names = {}
        for name in pairs(rows) do names[#names + 1] = name end
        table.sort(names, function(a, b) return a:lower() < b:lower() end)
        for i, name in ipairs(names) do
            local b = rows[name]
            local on = (name == selected)
            local what = stealInfo[name]
            local plr = Players:FindFirstChild(name)
            b.LayoutOrder = what and (i - 10000) or i
            b.BackgroundColor3 = on and C_ACCENT or (what and C_STEALBG or C_ROW)
            b.TextColor3 = on and Color3.fromRGB(10, 10, 12) or C_TEXT
            b.Size = UDim2.new(1, -4, 0, what and 36 or 24)
            if what then
                b.Text = rowLabel(plr) .. "\n  <font color='" .. (on and "#5a0000" or "#ff6b6b")
                    .. "'><b>STEALING:</b> " .. what .. "</font>"
            else
                b.Text = rowLabel(plr)
            end
            local st = b:FindFirstChild("StealStroke")
            if st then st.Enabled = what ~= nil end
        end
    end

    -- ------------------------------------------------------------ overhead header
    local heads = {}   -- name -> BillboardGui
    local function headerFor(plr)
        local bb = heads[plr.Name]
        if bb and bb.Parent then return bb end
        bb = Instance.new("BillboardGui")
        bb.Name = "Skyr0StealHeader"
        bb.Size = UDim2.fromOffset(220, 26)
        bb.StudsOffset = Vector3.new(0, 3.4, 0)
        bb.AlwaysOnTop = true
        bb.Enabled = false
        bb.Parent = sg
        local pill = Instance.new("TextLabel", bb)
        pill.Name = "Pill"
        pill.AnchorPoint = Vector2.new(0.5, 0.5)
        pill.Position = UDim2.fromScale(0.5, 0.5)
        pill.Size = UDim2.fromScale(1, 1)
        pill.AutomaticSize = Enum.AutomaticSize.None
        pill.BackgroundColor3 = Color3.fromRGB(20, 8, 10)
        pill.BackgroundTransparency = 0.15
        pill.Font = Enum.Font.GothamBlack
        pill.TextSize = 13
        pill.TextColor3 = C_STEAL
        pill.TextStrokeTransparency = 0.4
        pill.TextTruncate = Enum.TextTruncate.AtEnd
        Instance.new("UICorner", pill).CornerRadius = UDim.new(0, 8)
        local s = Instance.new("UIStroke", pill)
        s.Color = C_STEAL
        s.Thickness = 1.5
        s.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
        heads[plr.Name] = bb
        return bb
    end
    local function dropHeader(name)
        local bb = heads[name]
        if bb then pcall(function() bb:Destroy() end); heads[name] = nil end
    end

    RC.start = function(name)
        local plr = name and Players:FindFirstChild(name)
        if not plr or plr == LP then RC.status = "player not found"; return false, RC.status end
        RC.target, RC.active = plr.Name, true
        RC.arrived = false
        local plot = findPlotFor(plr)
        RC.plotName = plot and plot.Name or nil
        RC.status = plot and ("camping " .. plr.Name) or "looking for base..."
        clog(nil, ("START camp on %s -> base %s"):format(plr.Name, tostring(RC.plotName or "not found yet")))
        refreshToggle()
        -- turning the camp on (or moving it to another player) takes you to
        -- their open slot; a base still streaming in gets a few seconds
        local want = plr.Name
        task.spawn(function()
            local t0 = os.clock()
            while RC.active and RC.target == want and not RC.plotName and os.clock() - t0 < 5 do
                task.wait(0.2)
                local p = findPlotFor(plr)
                if p then RC.plotName = p.Name end
            end
            if not (RC.active and RC.target == want) then return end
            local ok, why = RC.tp()
            -- no TP (carrying, no character...): camp from where you stand
            if not ok then RC.arrivedAt = os.clock(); RC.arrived = true end
            notify(ok and ("TP to " .. want .. "'s " .. tostring(why)) or ("TP failed: " .. tostring(why)))
        end)
        return true, RC.status
    end

    RC.stop = function()
        if RC.active then clog(nil, "STOP camp on " .. tostring(RC.target)) end
        RC.active, RC.plotName, RC.arrived = false, nil, false
        RC.standSlot, RC.grabSlot, RC.grabEntry = nil, nil, nil
        RC.status = "stopped"
        showMarker(standMk, nil); showMarker(grabMk, nil)
        refreshToggle()
    end

    _G.Skyr0OnTap(toggle, function()
        if RC.active then
            RC.stop()
        elseif selected then
            local ok, why = RC.start(selected)
            if not ok then notify(why) end
        else
            notify("Pick a player first")
        end
    end)

    _G.Skyr0OnTap(tpBtn, function()
        local name = (RC.active and RC.target) or selected
        if not name then notify("Pick a player first"); return end
        local plr = Players:FindFirstChild(name)
        if RC.active then
            local ok, why = RC.tp()
            notify(ok and ("TP to " .. name .. "'s " .. tostring(why)) or ("TP failed: " .. tostring(why)))
        else
            local ok, why = tpToCampSlot(plr and findPlotFor(plr))
            notify(ok and ("TP to " .. name .. "'s " .. tostring(why)) or ("TP failed: " .. tostring(why)))
        end
    end)

    local function addRow(plr)
        if plr == LP or rows[plr.Name] then return end
        local b = Instance.new("TextButton")
        b.Name = plr.Name:lower()
        b.Size = UDim2.new(1, -4, 0, 24)
        b.BorderSizePixel = 0
        b.Font = Enum.Font.Gotham
        b.TextSize = 11
        b.TextXAlignment = Enum.TextXAlignment.Left
        b.AutoButtonColor = false
        b.RichText = true
        b.Text = rowLabel(plr)
        b.TextTruncate = Enum.TextTruncate.AtEnd
        b.Parent = list
        Instance.new("UICorner", b).CornerRadius = UDim.new(0, 6)
        local st = Instance.new("UIStroke", b)
        st.Name = "StealStroke"
        st.Color = C_STEAL
        st.Thickness = 1.5
        st.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
        st.Enabled = false
        rows[plr.Name] = b
        _G.Skyr0OnTap(b, function()
            selected = plr.Name
            refreshRows()
            -- switching player while camping moves the camp straight over
            if RC.active and RC.target ~= plr.Name then RC.start(plr.Name) end
        end)
        refreshRows()
    end

    for _, p in ipairs(Players:GetPlayers()) do addRow(p) end
    Players.PlayerAdded:Connect(addRow)
    Players.PlayerRemoving:Connect(function(p)
        local b = rows[p.Name]
        if b then b:Destroy(); rows[p.Name] = nil end
        stealInfo[p.Name] = nil
        dropHeader(p.Name)
        if selected == p.Name then selected = nil end
        if RC.active and RC.target == p.Name then
            notify(p.Name .. " left the game - camp off")
            RC.stop()
        end
    end)
    refreshToggle()

    -- ------------------------------------------------------------ steal watcher
    -- 0.2s poll plus the attribute signals, so the header and the row light up
    -- the moment a steal starts and clear the moment it ends.
    local function updateSteal(plr)
        if plr == LP or not rows[plr.Name] then return false end
        local what = stealingWhat(plr)
        local changed = stealInfo[plr.Name] ~= what
        stealInfo[plr.Name] = what
        local ch = plr.Character
        local adornee = ch and (ch:FindFirstChild("Head") or ch:FindFirstChild("HumanoidRootPart"))
        if what and adornee then
            local bb = headerFor(plr)
            bb.Adornee = adornee
            bb.Pill.Text = "STEALING: " .. what
            bb.Enabled = true
        elseif heads[plr.Name] then
            heads[plr.Name].Enabled = false
        end
        return changed
    end
    local function hookSteal(plr)
        if plr == LP then return end
        local function bump() if updateSteal(plr) then refreshRows() end end
        plr:GetAttributeChangedSignal("Stealing"):Connect(bump)
        plr:GetAttributeChangedSignal("StealingIndex"):Connect(bump)
    end
    for _, p in ipairs(Players:GetPlayers()) do hookSteal(p) end
    Players.PlayerAdded:Connect(hookSteal)
    LP:GetAttributeChangedSignal("Stealing"):Connect(function()
        if RC.active then
            clog(nil, LP:GetAttribute("Stealing") == true and "YOU are stealing now (grab worked)"
                or "you stopped carrying (delivered or dropped)")
        end
    end)
    task.spawn(function()
        while sg.Parent do
            local changed = false
            for _, p in ipairs(Players:GetPlayers()) do
                local ok, c = pcall(updateSteal, p)
                if ok and c then changed = true end
            end
            if changed then refreshRows() end
            task.wait(0.2)
        end
    end)

    -- ------------------------------------------------------------ camp loop
    local function slotNum(slot) return slot and (tostring(slot.Name):match("%d+") or slot.Name) or "-" end

    task.spawn(function()
        while sg.Parent do
            task.wait(0.15)
            -- who is stealing right now, for the bottom line of the status
            local thieves = {}
            for n, what in pairs(stealInfo) do
                if what then thieves[#thieves + 1] = n .. ": " .. what end
            end
            table.sort(thieves)
            local stealLine = (#thieves > 0)
                and ("\n<font color='#ff6b6b'><b>STEALING</b> " .. table.concat(thieves, ", ") .. "</font>")
                or ""

            if not RC.active then
                status.Text = (selected and ("Selected: <b>" .. selected .. "</b>\nToggle on to camp their base.")
                    or "Pick a player below, then toggle on.") .. stealLine
                continue
            end
            local plr = Players:FindFirstChild(RC.target or "")
            if not plr then RC.stop(); continue end

            -- the base may not have streamed in yet: keep looking
            local plots = workspace:FindFirstChild("Plots")
            local plot = RC.plotName and plots and plots:FindFirstChild(RC.plotName)
            if not plot then
                plot = findPlotFor(plr)
                RC.plotName = plot and plot.Name or nil
            end
            if not plot then
                clog("nobase", "looking for " .. tostring(RC.target) .. "'s base (PlotSign not found yet)", 3)
                RC.status = "looking for base..."
                showMarker(standMk, nil); showMarker(grabMk, nil)
                status.Text = "Target: <b>" .. RC.target .. "</b>\nlooking for their base..." .. stealLine
                continue
            end

            local stand, grab, full, grabD = scanCamp(plot)
            RC.standSlot, RC.grabSlot = stand and stand.Name or nil, grab and grab.Name or nil
            do
                local k = plot.Name .. "|" .. tostring(RC.standSlot) .. "|" .. tostring(RC.grabSlot)
                if k ~= RC._dbgKey then
                    RC._dbgKey = k
                    clog(nil, ("base %s: open slot %s, nearest brainrot slot %s%s%s"):format(plot.Name,
                        tostring(RC.standSlot), tostring(RC.grabSlot),
                        (grabD and grabD < math.huge) and (" (" .. math.floor(grabD) .. " studs)") or "",
                        full and ", base FULL" or ""))
                end
            end

            local pet = grab and petInSlot(plot.Name, grab.Name)
            RC.grabEntry = grab and {
                name = (pet and pet.name) or "Brainrot",
                mpsValue = pet and pet.genValue or 0,
                plot = plot.Name, slot = grab.Name,
            } or nil

            showMarker(standMk, stand and stand.Base.Spawn,
                "STAND  |  Slot " .. slotNum(stand))
            showMarker(grabMk, grab and grab.Base.Spawn,
                "GRAB  |  Slot " .. slotNum(grab) .. "\n" .. ((pet and pet.name) or "Brainrot")
                .. ((grabD < math.huge) and ("  " .. math.floor(grabD) .. "m") or ""))

            RC.status = full and (RC.target .. "'s base is FULL") or ("camping " .. RC.target)
            status.Text = "Target: <b>" .. RC.target .. "</b>"
                .. (full and "  <font color='#ff7070'>(FULL)</font>" or "")
                .. "\nStand: <font color='#50c8ff'>Slot " .. slotNum(stand) .. "</font>"
                .. "   Grab: <font color='#50e678'>Slot " .. slotNum(grab) .. "</font>"
                .. (grab and ("\n" .. ((pet and pet.name) or "Brainrot")) or "\nbase is empty")
                .. stealLine
        end
    end)
    -- =================================================================
    -- ROSE BASE CAMP STEAL  --  1:1 port of rose.lua
    -- -----------------------------------------------------------------
    -- campTarget / campSteer (rose BASE CAMP block) pick the nearest
    -- stealable brainrot in the camped base every 0.1s once the camp TP
    -- has landed, and rose's autosteal Heartbeat runs rose's executeSteal
    -- on it: hold-began callbacks with the anti-cheat State forced to
    -- "Steal", hold banking/carry, commit only inside JAF_StealCommitRange
    -- (10) of the podium after the entry settle (0.3s) and the server hold
    -- window, then the trigger (fireproximityprompt first, callbacks as the
    -- fallback), recycling until it takes. Same _G.JAF_* tunables and the
    -- same defaults as rose. skyro's own steal engine stands down while
    -- the camp is on, so this is the only thing stealing.
    -- =================================================================
    do
        local Workspace = workspace
        local LocalPlayer = LP
        local Config = { StealRadius = nil, StealDuration = nil }
        if _G.JAF_M2 == nil then
            _G.JAF_M2 = function(ax, az, bx, bz)
                local dx, dz = ax - bx, az - bz
                return math.sqrt(dx * dx + dz * dz)
            end
        end
        local function getChar()
            local c = LocalPlayer.Character
            return c, c and c:FindFirstChild("HumanoidRootPart")
        end

        local isAutoStealing = false
        local StealData      = setmetatable({}, {__mode = "k"})
        local PromptCache    = {}
        local _stealStart    = 0
        local _holdEpoch     = 0
        local function _ragUntil()
            return math.max(tonumber(LocalPlayer:GetAttribute("RagdollEndTime")) or 0, tonumber(_G.JAF_RagdollUntil) or 0)
        end
        local function _ragBlockedNow()
            return (_ragUntil() - workspace:GetServerTimeNow() + (tonumber(_G.JAF_RagdollLatePad) or 0.1)) > 0
                or (tick() - (tonumber(_G.JAF_RagdollPhysLastT) or 0)) < (tonumber(_G.JAF_RagdollPhysWindow) or 0.4)
        end
        local function _podOf(uid)
            if not uid then return nil end
            local pn, sl = tostring(uid):match("^(.*)_([^_]+)$")
            if not (pn and sl) then return nil end
            local pl = Workspace:FindFirstChild("Plots")
            pl = pl and pl:FindFirstChild(pn)
            pl = pl and pl:FindFirstChild("AnimalPodiums")
            return pl and pl:FindFirstChild(sl)
        end
        local function _grabCB(p)
            local d = { hold = {}, trigger = {} }
            if type(getconnections) ~= "function" then return d end
            local ok, cs = pcall(getconnections, p.PromptButtonHoldBegan)
            if ok and type(cs) == "table" then
                for _, c in ipairs(cs) do if type(c.Function) == "function" then d.hold[#d.hold + 1] = c.Function end end
            end
            ok, cs = pcall(getconnections, p.Triggered)
            if ok and type(cs) == "table" then
                for _, c in ipairs(cs) do if type(c.Function) == "function" then d.trigger[#d.trigger + 1] = c.Function end end
            end
            return d
        end
        local function _fireTrigger(p, d)
            if fireproximityprompt and _G.JAF_StealUseFPP ~= false then pcall(fireproximityprompt, p); return end
            if d then for _, f in ipairs(d.trigger) do task.spawn(f) end
                if #d.trigger == 0 and fireproximityprompt then pcall(fireproximityprompt, p) end end
        end
        local _apCache = setmetatable({}, {__mode = "k"})
        local function _apFromHold(p, d)
            local ap = _apCache[p]
            if ap ~= nil then return ap or nil end
            if debug and debug.getupvalues and d then
                for _, f in ipairs(d.hold) do
                    local ok, ups = pcall(debug.getupvalues, f)
                    if ok then for _, v in pairs(ups) do
                        if type(v) == "table" and rawget(v, "State") ~= nil and rawget(v, "ProximityPrompt") ~= nil then
                            _apCache[p] = v
                            return v
                        end
                    end end
                end
            end
            _apCache[p] = false
            return nil
        end
        local function _fireHoldForced(p, d)
            if not d or #d.hold == 0 then return false end
            local ap = _apFromHold(p, d)
            if ap and ap.State ~= "Steal" then
                local _os = ap.State
                ap.State = "Steal"
                for _, f in ipairs(d.hold) do pcall(f) end
                ap.State = _os
                return true
            end
            if not ap and p and p.Enabled == false then return false end
            for _, f in ipairs(d.hold) do task.spawn(f) end
            return true
        end
        local function isMyPlot(plotName)
            local plots = Workspace:FindFirstChild("Plots")
            local plot  = plots and plots:FindFirstChild(plotName)
            local sign  = plot and plot:FindFirstChild("PlotSign")
            local yb    = sign and sign:FindFirstChild("YourBase")
            return (yb and yb:IsA("BillboardGui") and yb.Enabled == true) or false
        end
        local function findPrompt(a)
            if not a then return nil end
            local cp = PromptCache[a.uid]
            if cp and cp.Parent and cp.Enabled and cp.ActionText == "Steal" then return cp end
            local pod = _podOf(a.uid)
            local base = pod and pod:FindFirstChild("Base")
            local sp = base and base:FindFirstChild("Spawn")
            if not sp then return nil end
            local att = sp:FindFirstChild("PromptAttachment")
            if att then
                for _, p in ipairs(att:GetChildren()) do
                    if p:IsA("ProximityPrompt") and p.Enabled and p.ActionText == "Steal" then PromptCache[a.uid] = p; return p end
                end end
            return nil
        end
        local _ownerPresent = {}
        for _, pl in ipairs(Players:GetPlayers()) do _ownerPresent[pl.Name] = true end
        Players.PlayerAdded:Connect(function(pl) _ownerPresent[pl.Name] = true end)
        Players.PlayerRemoving:Connect(function(pl) _ownerPresent[pl.Name] = nil end)
        local function _stealable(a, me)
            if not a or a.owner == me then return false end
            if _G.JAF_SkipLeftOwners == false then return true end
            return a.owner ~= nil and _ownerPresent[a.owner] == true
        end
        local function findNearestPrompt(priorityTarget)
            local _, hrp = getChar()
            if not hrp then return end
            local plots = Workspace:FindFirstChild("Plots")
            if not plots then return end
            if not priorityTarget then return end
            local _hrpPos = hrp.Position
            local _radius = Config.StealRadius or 95
            local plot = plots:FindFirstChild(priorityTarget.plot)
            if not plot or isMyPlot(plot.Name) then return nil end
            local pods = plot:FindFirstChild("AnimalPodiums")
            local pod  = pods and pods:FindFirstChild(priorityTarget.slot)
            local base = pod and pod:FindFirstChild("Base")
            local spawn = base and base:FindFirstChild("Spawn")
            if not spawn then return nil end
            local sp = spawn.Position
            if _G.JAF_M2(sp.X, sp.Z, _hrpPos.X, _hrpPos.Z) > _radius then return nil end
            local att = spawn:FindFirstChild("PromptAttachment")
            if not att then return nil end
            local nearest
            for _, p in ipairs(att:GetChildren()) do if p:IsA("ProximityPrompt") and p.Enabled and p.ActionText:find("Steal") then nearest = p end end
            return nearest
        end
        local function promptDistXZ(prompt)
            local c = LocalPlayer.Character
            local hrp = c and c:FindFirstChild("HumanoidRootPart")
            if not hrp then return nil end
            local par = prompt and prompt.Parent
            local pos
            if par then
                if par:IsA("Attachment") then pos = par.WorldPosition
                elseif par:IsA("BasePart") then pos = par.Position
                else
                    local bp = par:FindFirstAncestorWhichIsA("BasePart")
                    if bp then pos = bp.Position end
                end end
            if not pos then return nil end
            local hp = hrp.Position
            return _G.JAF_M2(pos.X, pos.Z, hp.X, hp.Z), (pos - hp).Magnitude
        end
        local function _pivotPos(m) return m:GetPivot().Position end
        local function _cache() return (SharedState and SharedState.AllAnimalsCache) or {} end

        -- rose _animalSlotEntry: the slot's LIVE entry in the plot's channel
        -- AnimalList (skyro reads the same list via Skyr0_GetPlotAnimalList)
        local function _animalSlotEntry(a, memo)
            local al = memo and memo[a.plot]
            if al == nil then
                local ok, list = pcall(function()
                    return _G.Skyr0_GetPlotAnimalList and _G.Skyr0_GetPlotAnimalList(tostring(a.plot))
                end)
                al = (ok and type(list) == "table") and list or false
                if memo then memo[a.plot] = al end
            end
            if al == false then return nil, "noChan" end
            local e = al[a.slot]
            if e == nil then local n = tonumber(a.slot); if n ~= nil then e = al[n] end end
            return e
        end
        -- rose JAF_StealSpeciesSet: what every other player is carrying right now
        local _stealSpecies, _stealSpeciesAt = {}, 0
        local function _stealSpeciesSet()
            local ttl = tonumber(_G.JAF_StealSetTTL) or 0.25
            if (tick() - _stealSpeciesAt) < ttl then return _stealSpecies end
            _stealSpeciesAt = tick()
            for k in pairs(_stealSpecies) do _stealSpecies[k] = nil end
            for _, pl in ipairs(Players:GetPlayers()) do
                if pl ~= LocalPlayer then
                    local idx = pl:GetAttribute("StealingIndex")
                    if idx ~= nil and idx ~= "" then
                        local s2 = tostring(idx):lower()
                        _stealSpecies[s2] = true
                        _stealSpecies[(s2:gsub("%s+", ""))] = true
                        local dn = displayNameOf and displayNameOf(tostring(idx))
                        if dn then local d = tostring(dn):lower() _stealSpecies[d] = true _stealSpecies[(d:gsub("%s+", ""))] = true end
                    end end end
            return _stealSpecies
        end
        -- rose JAF_IsBeingStolen: the slot's entry names a thief (Steal = their
        -- UserId) who is carrying right now, or the species is being carried
        local function _isBeingStolen(a, memo)
            if _G.JAF_StolenDetect == false then return false end
            if type(a) ~= "table" or a.isWalking then return false end
            if type(a.plot) ~= "string" or a.slot == nil then return false end
            local e, why = _animalSlotEntry(a, memo)
            if why then return false end
            if type(e) == "table" then
                local st = e.Steal
                if type(st) ~= "number" then return false end
                if st == LocalPlayer.UserId then return false end
                for _, pl in ipairs(Players:GetPlayers()) do if pl.UserId == st then return pl:GetAttribute("Stealing") == true end end
                return false
            end
            local nm = a.nameLower or (a.name and tostring(a.name):lower())
            if not nm then return false end
            local set = _stealSpeciesSet()
            if set[nm] or set[(nm:gsub("%s+", ""))] then return true end
            return false
        end

        -- skyro's progress bar reads _G.Skyr0_StealStatus. Like rose's bar it
        -- follows _stealStart while a hold runs, and only reads idle after
        -- JAF_StealReadyDebounce (0.12s) with no hold -- so a hold that carries
        -- straight into the next one (rose's 1.25s carry / bank) keeps filling
        -- instead of flashing back to 0.
        local _barGen = 0
        local function _bar(active, start, dur, tgt)
            _G.Skyr0_StealStatus = _G.Skyr0_StealStatus or {}
            local st = _G.Skyr0_StealStatus
            if start then st.start = start end
            if dur then st.duration = dur end
            if tgt ~= nil then st.target = tgt or nil end
            if active == true then
                _barGen = _barGen + 1
                st.active = true
            elseif active == false then
                _barGen = _barGen + 1
                local g = _barGen
                task.delay(tonumber(_G.JAF_StealReadyDebounce) or 0.12, function()
                    if g == _barGen and not isAutoStealing then st.active = false end
                end)
            end
        end
        -- keep the bar on rose's live _stealStart (rose's bar reads it every frame)
        RunService.Heartbeat:Connect(function()
            if isAutoStealing and RC.active then
                local st = _G.Skyr0_StealStatus
                if st and st.start ~= _stealStart then st.start = _stealStart end
            end
        end)

        local function executeSteal(prompt, heldUid, preHold)
            if isAutoStealing then return end
            local function _tpBanking() return false end
            local _d = promptDistXZ(prompt)
            if _d and _d > (Config.StealRadius or 95) and not _tpBanking() then return end
            local data = StealData[prompt]
            if not data then data = _grabCB(prompt); data.ready = true if #data.hold > 0 and (#data.trigger > 0 or _G.JAF_StealUseFPP ~= false) then StealData[prompt] = data end end
            if not data.ready then return end
            data.ready = false
            isAutoStealing = true
            _stealStart = tick()
            task.spawn(function()
                local oldDuration = prompt.HoldDuration
                prompt.HoldDuration = 0
                local _beginT, _inherited = 0, false
                local _hAge = _holdEpoch > 0 and (tick() - _holdEpoch) or math.huge
                if _G.JAF_StealHoldCarry ~= false and prompt.Enabled and _hAge <= (tonumber(_G.JAF_StealCarryMax) or 1.25) then
                    _beginT, _inherited = _holdEpoch, true
                else
                    for _, f in ipairs(data.hold) do task.spawn(f) end
                    _beginT = prompt.Enabled and tick() or 0
                    if _beginT > 0 and #data.hold > 0 then _holdEpoch = _beginT end
                end
                local _beganOk, _recapN = (_inherited or #data.hold > 0), 0
                local _dur = Config.StealDuration
                if not _dur then
                    local _srv = (_G.JAF_StealUsePromptHold == true) and tonumber(oldDuration) or nil
                    _dur = ((_srv and _srv > 0.1 and _srv) or 1.3) + (tonumber(_G.JAF_StealHoldPad) or 0)
                end
                local _maxHold = tonumber(_G.JAF_StealMaxHold) or (_dur + (tonumber(_G.JAF_StealExtendWindow) or 1.3))
                local _t0 = _inherited and _beginT or tick(); local _holdAbsStart = tick()
                if _inherited then _stealStart = _beginT end
                local _ragRet0 = _ragUntil()
                local _postGrace = (tonumber(_G.JAF_StealPostGrace) or 0) + ((_ragRet0 > 0) and (tonumber(_G.JAF_RagdollPostGrace) or 0) or 0)
                local _abort, _grabbed, _recycle, _didEnter = false, false, false, false
                local _clearFireUntil, _lastCommitT, _commitN = 0, 0, 0
                local _eligSince, _commitGraceUntil = 0, 0
                local _wasDis, _disAt = false, nil
                local _bankT, _campChkT = 0, 0
                local _carryChkT, _carryFlag, _carryLastT = 0, false, 0
                local _promptGone, _goneAt, _goneConn = false, nil, nil
                local activePrompt, activeData = prompt, data
                local _podiumForDist = _podOf(heldUid)
                local function _petDistNow()
                    local _, _h = getChar()
                    if not _h then return nil end
                    if _podiumForDist and _podiumForDist.Parent then
                        local ok, piv = pcall(_pivotPos, _podiumForDist)
                        if ok and piv then return (piv - _h.Position).Magnitude end
                    end
                    local _, d3 = promptDistXZ(activePrompt); return d3
                end
                _bar(true, _stealStart, _dur)
                if _G.JAF_StealReacquire ~= false and heldUid and _podiumForDist then
                    _goneConn = _podiumForDist.DescendantAdded:Connect(function(desc)
                        if _promptGone and desc:IsA("ProximityPrompt") and tostring(desc.ActionText or ""):find("Steal") then
                            activePrompt, activeData = desc, _grabCB(desc)
                            pcall(function() desc.HoldDuration = 0 end)
                            for _, f in ipairs(activeData.hold) do task.spawn(f) end
                            _beginT = desc.Enabled and tick() or 0
                            if _beginT > 0 and #activeData.hold > 0 then _holdEpoch = _beginT end
                            _beganOk = #activeData.hold > 0
                            _wasDis, _disAt, _bankT = false, nil, 0
                            _promptGone, _goneAt = false, nil
                            _stealStart = tick()
                            _t0, _commitN, _lastCommitT, _recycle = tick(), 0, 0, false
                        end end) end
                repeat
                    local _mt = RC._mt
                    if _mt ~= nil and heldUid ~= nil and _mt.uid ~= heldUid then _abort = true; break end
                    if not RC.active then _abort = true; break end
                    if LocalPlayer:GetAttribute("Stealing") then _grabbed = true; break end
                    if _goneConn and not activePrompt.Parent and not _promptGone then _promptGone = true; _goneAt = tick() end
                    if _promptGone then
                        if _bankT == 0 or (tick() - _bankT) > (tonumber(_G.JAF_StealBankRefresh) or 2.5) then
                            if _fireHoldForced(activePrompt, activeData) then _bankT = tick() _holdEpoch = _bankT end
                        end
                        if (tick() - _goneAt) > (tonumber(_G.JAF_StealPromptGoneWait) or 6.5) then break end
                        _t0 = _t0 + (_G.JAF_StealFireInterval or 0.12)
                        task.wait(_G.JAF_StealFireInterval or 0.12)
                        continue
                    end
                    if activePrompt.Parent and not activePrompt.Enabled then
                        if not _disAt then _disAt = tick() end
                        if (tick() - _carryChkT) > 0.25 then
                            _carryChkT = tick()
                            if #activeData.hold == 0 then activeData = _grabCB(activePrompt) end
                            local _cnow = false
                            for _, _sa in ipairs(_cache()) do if _sa and _sa.uid == heldUid then
                                local _cok, _cv = pcall(_isBeingStolen, _sa)
                                _cnow = _cok and _cv == true
                                break
                            end end
                            if _cnow then _carryLastT = tick() end
                            _carryFlag = _cnow or (tick() - _carryLastT) < 1.0
                        end
                        if _bankT > 0 and (tick() - _bankT) > (tonumber(_G.JAF_StealBankRefresh) or 2.5) then _bankT = 0 end
                        if _bankT == 0 and _G.JAF_StealPreBank ~= false then
                            if _fireHoldForced(activePrompt, activeData) then _bankT = tick() _holdEpoch = _bankT end
                        end
                        if (tick() - _campChkT) > 0.25 then
                            _campChkT = tick()
                            if _bankT == 0 and _G.JAF_StealPreBank ~= false then
                                for _, _sa in ipairs(_cache()) do
                                    if _sa and _sa.uid ~= heldUid and _stealable(_sa, LocalPlayer.Name) then
                                        local _bp = findPrompt(_sa)
                                        if _bp and _bp.Enabled and _bp:GetAttribute("State") == "Steal" then
                                            local _bd = _grabCB(_bp)
                                            if #_bd.hold > 0 then for _, f in ipairs(_bd.hold) do task.spawn(f) end _bankT = tick() _holdEpoch = _bankT break end
                                        end
                                    end
                                end
                            end
                        end
                        if (not _carryFlag) and (tick() - math.max(_disAt, _carryLastT)) > (tonumber(_G.JAF_StealDisabledGrace) or 3) then break end
                        _wasDis = true
                        local _dt = tonumber(_G.JAF_StealPoll) or 0.03
                        _stealStart = _bankT > 0 and _bankT or tick()
                        _t0, _commitN, _lastCommitT, _recycle = tick(), 0, 0, false
                        _bar(true, _stealStart, _dur)
                        _holdAbsStart = _holdAbsStart + (task.wait(_dt) or _dt)
                        continue
                    end
                    if _wasDis then
                        _wasDis, _disAt = false, nil
                        activeData = _grabCB(activePrompt)
                        local _bAge = _bankT > 0 and (tick() - _bankT) or math.huge
                        if _bAge <= (tonumber(_G.JAF_StealBankUseMax) or 2.3) then
                            _beginT = _bankT
                            _t0 = _bankT
                            _stealStart = _bankT
                            _beganOk = true
                        else
                            for _, f in ipairs(activeData.hold) do task.spawn(f) end
                            _beginT = tick()
                            _beganOk = #activeData.hold > 0
                            if _beganOk then _holdEpoch = _beginT end
                            _t0 = tick()
                            _stealStart = tick()
                        end
                        _bankT = 0
                        _commitN, _lastCommitT, _recycle = 0, 0, false
                        _eligSince = tick() - (tonumber(_G.JAF_StealEntryDelay) or 0.3)
                        _clearFireUntil = math.max(_clearFireUntil, tick() + (tonumber(_G.JAF_StealDropSettle) or 0.5))
                        _bar(true, _stealStart, _dur)
                    end
                    if not _beganOk then _stealStart = tick() end
                    local _needTrig = _G.JAF_StealUseFPP == false
                    if (#activeData.hold == 0 or (_needTrig and #activeData.trigger == 0)) and _recapN < (tonumber(_G.JAF_StealRecapMax) or 40) then
                        _recapN = _recapN + 1
                        local _rd = _grabCB(activePrompt)
                        if #_rd.hold > 0 and (not _needTrig or #_rd.trigger > 0) then
                            activeData = _rd
                            if not _beganOk then
                                for _, f in ipairs(_rd.hold) do task.spawn(f) end
                                if activePrompt.Enabled then _beginT = tick() _holdEpoch = _beginT end
                                _beganOk = true
                                _stealStart = tick()
                                _t0, _commitN, _lastCommitT, _recycle = tick(), 0, 0, false
                                _bar(true, _stealStart, _dur)
                            end end end
                    local _hrDist = promptDistXZ(activePrompt)
                    if _hrDist and _hrDist > (Config.StealRadius or 95) then _abort = true; break end
                    local _ragSync = _G.JAF_RagdollStealSync ~= false
                    local _now = tick()
                    if _ragSync then
                        local _nr = _ragUntil(); local _remNow = _nr - workspace:GetServerTimeNow()
                        if _nr > _ragRet0 + 0.3 and _remNow > 0.1 then
                            _ragRet0 = _nr
                            _t0 = math.max(_t0, _now + _remNow - _dur + (tonumber(_G.JAF_RagdollLatePad) or 0.1))
                            _stealStart = math.max(_stealStart, _t0)
                            _postGrace = (tonumber(_G.JAF_StealPostGrace) or 0) + (tonumber(_G.JAF_RagdollPostGrace) or 0)
                        end end
                    local _holdDone = (_now - _t0) >= (_dur + _postGrace)
                    local _ragBlocked = _ragSync and _ragBlockedNow()
                    if _ragSync and _G.JAF_RagdollHoldUntilClear ~= false and _holdDone and _ragBlocked then
                        _clearFireUntil = _now + (tonumber(_G.JAF_RagdollClearWindow) or 0.35)
                    end
                    if _commitN == 0 and not _ragBlocked and (_beginT == 0 or (_now - _beginT) > (tonumber(_G.JAF_StealSrvHoldMax) or 2.5)) and activePrompt.Parent and activePrompt.Enabled then
                        local _rhOk = _fireHoldForced(activePrompt, activeData)
                        _beginT = tick()
                        _holdEpoch = _rhOk and _beginT or 0
                        _beganOk = #activeData.hold > 0
                        _stealStart = tick()
                        _t0 = math.max(_t0, tick())
                        _bar(true, _stealStart, _dur)
                    end
                    local _petDist = _petDistNow()
                    local _petInRange = _petDist and _petDist <= (tonumber(_G.JAF_StealCommitRange) or 10)
                    if _petInRange then if _eligSince == 0 then _eligSince = _now end else _eligSince = 0 end
                    local _settleAnchor = _eligSince
                    local _effDelay = tonumber(_G.JAF_StealEntryDelay) or 0.3
                    local _settled = (_eligSince > 0) and ((_now - _settleAnchor) >= _effDelay)
                    local _inCommit = _holdDone and not _grabbed and not _ragBlocked and _petInRange and _settled
                                      and _beginT > 0 and (_now - _beginT) >= (tonumber(_G.JAF_StealSrvHold) or _dur)
                                      and (_now - _beginT) <= (tonumber(_G.JAF_StealSrvHoldMax) or 2.5)
                    if _inCommit and _commitN == 0 then
                        _lastCommitT, _commitN = _now, 1
                        _fireTrigger(activePrompt, activeData)
                        clog(nil, ("rose steal: commit on slot %s (%.1f studs, %.2fs hold)")
                            :format(tostring(heldUid and heldUid:match("_([^_]+)$")), _petDist or -1, _now - _beginT))
                    end
                    if _inCommit and not _didEnter then
                        _didEnter = true
                        if _G.JAF_StealCommitSettle == true then
                            local _, _shrp = getChar()
                            local _v = _shrp and _shrp.AssemblyLinearVelocity
                            local _minSpd = tonumber(_G.JAF_StealCommitSettleSpeed) or 30
                            if _v and (_v.X * _v.X + _v.Z * _v.Z) > (_minSpd * _minSpd) then
                                pcall(function() _shrp.AssemblyLinearVelocity = Vector3.new(0, _v.Y, 0) end)
                            end end end
                    if _commitN > 0 and not _grabbed and (_now - _lastCommitT) >= (tonumber(_G.JAF_StealCommitWait) or 0.4) then _recycle = true end
                    _commitGraceUntil = 0
                    if _G.JAF_StealHoldForSettle ~= false and not _grabbed and (_eligSince > 0 or _ragBlocked) then
                        local _fm = tonumber(_G.JAF_StealCommitFireMargin) or 0.06
                        local _due = 0
                        if _commitN == 0 then
                            if _eligSince > 0 and not _settled then _due = _settleAnchor + _effDelay + _fm end
                            if _beginT > 0 then
                                local _srvDue = _beginT + (tonumber(_G.JAF_StealSrvHold) or _dur) + _fm
                                if _srvDue > _due then _due = _srvDue end
                            end
                            local _hdDue = _t0 + _dur + _postGrace + _fm
                            if _hdDue > _due then _due = _hdDue end
                        else _due = _lastCommitT + (tonumber(_G.JAF_StealCommitWait) or 0.4) end
                        if _due > 0 then _commitGraceUntil = _due end
                    end
                    task.wait(tonumber(_G.JAF_StealPoll) or 0.03)
                until (not _promptGone and not _disAt and ((tick() - _t0) >= _maxHold or _recycle) and tick() >= _clearFireUntil and tick() >= _commitGraceUntil)
                      or (not _goneConn and not activePrompt.Parent)
                      or (tick() - _holdAbsStart > (tonumber(_G.JAF_StealHoldMaxTotal) or 20))
                if _commitN > 0 or not _abort then _holdEpoch = 0 end
                if _goneConn then pcall(function() _goneConn:Disconnect() end) end
                if activePrompt.Parent and not _abort and not _grabbed and _commitN == 0 then
                    local _fd = _petDistNow()
                    if _fd and _fd <= (tonumber(_G.JAF_StealCommitRange) or 10) and activePrompt.Enabled and _beginT > 0 and (tick() - _beginT) >= (tonumber(_G.JAF_StealSrvHold) or _dur) and (tick() - _beginT) <= (tonumber(_G.JAF_StealSrvHoldMax) or 2.5) then _fireTrigger(activePrompt, activeData) end
                end
                if activePrompt.Parent then activePrompt.HoldDuration = oldDuration end
                local _why = _grabbed and "grab" or (_abort and "abort") or (_disAt and "carry") or (_promptGone and "gone") or (_commitN > 0 and "fired") or "expire"
                clog(nil, ("rose steal: hold ended (%s)"):format(_why))
                _bar(false)
                data.ready = true
                isAutoStealing = false
            end)
        end

        -- rose campTarget: nearest stealable brainrot sitting in the camped
        -- base, from the panel cache, measured from where you stand
        local function campTarget()
            local cache = _cache()
            local me = LocalPlayer.Name
            local _, hrp = getChar()
            local myPos = hrp and hrp.Position
            local best, bestD, firstAny = nil, math.huge, nil
            for _, a in ipairs(cache) do
                if a and a.plot == RC.plotName and not a.isWalking and a.owner ~= me then
                    firstAny = firstAny or a
                    if myPos and type(findAdorneeGlobal) == "function" then
                        local ok, part = pcall(findAdorneeGlobal, a)
                        local pos = ok and part and part.Position
                        if pos then
                            local d = (pos - myPos).Magnitude
                            if d < bestD then bestD = d; best = a end
                        end
                    end
                end
            end
            return best or firstAny
        end
        -- STAND ON THE NEXT SLOT. The camp holds you on the base's first OPEN
        -- slot (RC.standSlot, refreshed by the camp loop) -- that is where the
        -- owner's next brainrot lands, inside the commit range, so the steal
        -- fires the moment it does. When that slot fills up and the steal is
        -- done, you are CFramed onto the new next open slot.
        -- It never chases the brainrots themselves (that fought the slot TP and
        -- looped between the two), and it stays put while a hold is running,
        -- while you carry one, or while a stealable brainrot is already in range.
        local _campMoveAt = 0
        local function campHold()
            if not RC.standSlot or not RC.plotName then return end
            if LocalPlayer:GetAttribute("Stealing") or isAutoStealing then return end
            if _G.Skyr0TPActive and _G.Skyr0TPActive() then return end
            if os.clock() - _campMoveAt < (tonumber(_G.Skyr0CampMoveCooldown) or 0.6) then return end
            local _, hrp = getChar()
            if not hrp then return end
            local plots = Workspace:FindFirstChild("Plots")
            local plot = plots and plots:FindFirstChild(RC.plotName)
            local pods = plot and plot:FindFirstChild("AnimalPodiums")
            local pod = pods and pods:FindFirstChild(tostring(RC.standSlot))
            local base = pod and pod:FindFirstChild("Base")
            local sp = base and base:FindFirstChild("Spawn")
            if not sp then return end
            local stand = sp.Position + Vector3.new(0, 3, 0)
            if (stand - hrp.Position).Magnitude <= 5 then return end
            -- a brainrot already within commit range of where we are: stay and take it
            local range = tonumber(_G.JAF_StealCommitRange) or 10
            local tgt = RC._mt
            if tgt and tgt.uid then
                local tp = _podOf(tgt.uid)
                local okP, piv = tp and pcall(_pivotPos, tp)
                if okP and piv and (piv - hrp.Position).Magnitude <= range then return end
            end
            _campMoveAt = os.clock()
            pcall(function()
                hrp.AssemblyLinearVelocity = Vector3.zero
                hrp.AssemblyAngularVelocity = Vector3.zero
                hrp.CFrame = CFrame.new(stand)
            end)
            clog("campmove", ("move -> next open slot %s"):format(tostring(RC.standSlot)), 1)
        end

        -- rose campSteer: point the steal at whatever is in the camped base
        -- (or release it when the base is empty); only once we have arrived
        local function campSteer()
            if not RC.arrived then return end
            -- rose never moves you after the camp TP; _G.Skyr0CampMove = true
            -- brings back the hold-on-next-open-slot snap
            if _G.Skyr0CampMove == true then campHold() end
            local tgt = campTarget()
            if tgt then
                if RC._mt ~= tgt then
                    if not (RC._mt and RC._mt.uid == tgt.uid) then
                        clog(nil, ("steer -> %s [slot %s]"):format(tostring(tgt.name), tostring(tgt.slot)))
                    end
                    RC._mt = tgt
                    _bar(nil, nil, nil, { name = tgt.name, mps = tgt.genValue, plot = tgt.plot, slot = tgt.slot })
                end
            elseif RC._mt ~= nil then
                RC._mt = nil
                _bar(nil, nil, nil, false)
            end
        end
        task.spawn(function()
            while sg.Parent do
                task.wait(0.1)
                if RC.active then
                    pcall(campSteer)
                elseif RC._mt ~= nil then
                    RC._mt = nil
                end
            end
        end)

        -- rose's autosteal Heartbeat, camp branch: while camping, only the
        -- camp target; no camp target = no steal
        local _asAcc, _asResolveDt = 1, 0.03
        local _asP, _asUid = nil, nil
        RunService.Heartbeat:Connect(function(dt)
            if _G.SKYR0_GRAB_OWNS_STEAL == true then return end   -- rose: K7 owns the steal
            if not RC.active then _asP, _asUid = nil, nil; return end
            if RC._mt == nil then return end
            if isAutoStealing then return end
            if _G.JAF_StealCarryGate ~= false and LocalPlayer:GetAttribute("Stealing") then return end
            _asAcc = _asAcc + dt
            if _asAcc >= _asResolveDt or (_asP and not _asP.Parent) then
                _asAcc = 0
                local tgt = RC._mt
                _asP = tgt and findNearestPrompt(tgt) or nil
